 WHERE r55_project_id IS NOT NULL AND invalidated_at IS NULL;
CREATE FUNCTION company_private.r55_cp_clock_epoch_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'CLOCK_EPOCH_HISTORY_IMMUTABLE'; END IF;
 IF (to_jsonb(NEW)-'invalidated_at') IS DISTINCT FROM (to_jsonb(OLD)-'invalidated_at')
 OR (OLD.invalidated_at IS NOT NULL AND NEW IS DISTINCT FROM OLD)
 THEN RAISE EXCEPTION 'CLOCK_EPOCH_IDENTITY_OR_INVALIDATION_IMMUTABLE'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION company_private.r55_cp_clock_epoch_immutable() FROM PUBLIC;
CREATE TRIGGER r55_clock_epoch_immutable BEFORE UPDATE OR DELETE ON company.clock_epochs FOR EACH ROW EXECUTE FUNCTION company_private.r55_cp_clock_epoch_immutable();
ALTER TABLE company.clock_samples ADD COLUMN r55_raw_proof_digest text;
ALTER TABLE company.clock_samples ADD COLUMN r55_source_sequence bigint;
ALTER TABLE company.clock_samples ADD COLUMN r55_source_enrollment_revision bigint;
ALTER TABLE company.clock_samples ADD COLUMN r55_source_issuer uuid;
ALTER TABLE company.clock_samples ADD COLUMN r55_source_key uuid;
ALTER TABLE company.clock_samples ADD COLUMN r55_frequency_error_ppm_bound numeric;
ALTER TABLE company.clock_samples ADD COLUMN r55_sampling_error_margin_ns numeric(20,0);
CREATE UNIQUE INDEX r55_clock_source_sequence ON company.clock_samples(tenant_id,epoch_id,r55_source_sequence);

-- DB-local trusted observer source is r55_clock_observer.c. The library must
-- be compiled from the pinned source and independently enrolled before install.
-- No compile/load is performed in this task; unsupported platforms fail closed.
CREATE FUNCTION company_private.r55_cp_clock_observe_local()
RETURNS jsonb AS '$libdir/r55_clock_observer','r55_cp_clock_observe_local'
LANGUAGE C VOLATILE SECURITY INVOKER;
REVOKE ALL ON FUNCTION company_private.r55_cp_clock_observe_local() FROM PUBLIC;

-- Exact raw-byte HMAC verification, not caller-supplied verified=true. The
-- exclusive trusted verifier login receives the key from its enrolled adapter;
-- no runtime role membership/EXECUTE is installed here.
CREATE FUNCTION company_private.r55_cp_verify_clock_statement(
 p_issuer uuid,p_key_id uuid,p_revision bigint,p_raw bytea,p_tag bytea,p_secret bytea)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE j jsonb; e company.signer_enrollments%ROWTYPE; message bytea; item bytea;
 values bytea[]; tenant uuid;
BEGIN
 IF session_user<>'company_clock_runtime_r55' THEN RAISE EXCEPTION 'TRUSTED_CLOCK_VERIFIER_LOGIN_REQUIRED'; END IF;
 IF p_issuer IS NULL OR p_key_id IS NULL OR p_revision IS NULL OR p_revision<0
 OR p_raw IS NULL OR octet_length(p_raw)>65536 OR octet_length(p_raw)=0
 OR p_tag IS NULL OR octet_length(p_tag)<>32 OR p_secret IS NULL OR octet_length(p_secret)<>32
 THEN RAISE EXCEPTION 'INVALID_CLOCK_PROOF'; END IF;
 j=convert_from(p_raw,'UTF8')::jsonb;
 IF jsonb_typeof(j)<>'object' OR EXISTS(SELECT key FROM json_each(convert_from(p_raw,'UTF8')::json) GROUP BY key HAVING count(*)>1)
 THEN RAISE EXCEPTION 'AMBIGUOUS_CLOCK_JSON'; END IF;
 IF NOT ((j ?& ARRAY['tenant_id','project_id','epoch_id','sample_id','host_boot_id','backend_pid','transaction_id','db_login','phase','current_boottime_ns','valid_until_boottime_ns','utc_lower_bound','utc_upper_bound']) IS TRUE)
 OR EXISTS(SELECT 1 FROM jsonb_each(j) z WHERE z.key IN ('tenant_id','project_id','epoch_id','sample_id','host_boot_id','transaction_id','db_login','phase','utc_lower_bound','utc_upper_bound')
  AND jsonb_typeof(z.value) IS DISTINCT FROM 'string')
 OR EXISTS(SELECT 1 FROM jsonb_each(j) z WHERE z.key IN ('backend_pid','current_boottime_ns','valid_until_boottime_ns')
  AND (jsonb_typeof(z.value) IS DISTINCT FROM 'number' OR z.value::text !~ '^[0-9]+$'))
 THEN RAISE EXCEPTION 'CLOCK_REQUIRED_TYPED_FIELDS'; END IF;
 tenant=(j->>'tenant_id')::uuid;
 SELECT * INTO STRICT e FROM company.signer_enrollments
 WHERE tenant_id=tenant AND issuer_id=p_issuer AND key_id=p_key_id
 AND purpose='CLOCK_OBSERVATION' AND enrollment_revision=p_revision FOR SHARE;
 IF e.profile_id IS DISTINCT FROM 'R55_CLOCK_V1_RAW_JSON'
 OR e.revoked_at IS NOT NULL OR e.compromised_since IS NOT NULL
 OR e.key_fingerprint IS DISTINCT FROM encode(sha256(p_secret),'hex')
 OR e.approved_by IS NULL OR e.approved_by=e.issuer_id
 OR NOT isfinite(e.valid_from) OR NOT isfinite(e.valid_until)
 OR NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=e.tenant_id AND id=e.approved_by AND kind='HUMAN')
 THEN RAISE EXCEPTION 'CLOCK_ENROLLMENT_NOT_TRUSTED'; END IF;
 IF NOT ((j ?& ARRAY['tenant_id','project_id','epoch_id','sample_id','host_boot_id','backend_pid','transaction_id','db_login','phase','current_boottime_ns','valid_until_boottime_ns','utc_lower_bound','utc_upper_bound']) IS TRUE)
 OR j->>'phase' IS DISTINCT FROM 'FINAL_AFTER_LOCKS'
 OR j->>'backend_pid' IS DISTINCT FROM pg_backend_pid()::text
 OR j->>'transaction_id' IS DISTINCT FROM pg_current_xact_id()::text
 OR j->>'db_login' IS DISTINCT FROM session_user::text
 OR e.r55_project_id IS NULL OR e.r55_host_id IS NULL OR e.r55_host_revision IS NULL OR e.r55_host_generation IS NULL OR e.r55_host_boot_id IS NULL
 OR j->>'project_id' IS DISTINCT FROM e.r55_project_id::text OR j->>'host_registration_id' IS DISTINCT FROM e.r55_host_id::text
 OR j->>'host_registration_revision' IS DISTINCT FROM e.r55_host_revision::text OR j->>'host_generation' IS DISTINCT FROM e.r55_host_generation::text
 OR j->>'host_boot_id' IS DISTINCT FROM e.r55_host_boot_id::text
 OR j->>'utc_lower_bound' IS NULL OR j->>'utc_upper_bound' IS NULL
 OR NOT ((isfinite((j->>'utc_lower_bound')::timestamptz) AND isfinite((j->>'utc_upper_bound')::timestamptz)
 AND e.valid_from<=(j->>'utc_lower_bound')::timestamptz
 AND (j->>'utc_lower_bound')::timestamptz<=(j->>'utc_upper_bound')::timestamptz
 AND (j->>'utc_upper_bound')::timestamptz<e.valid_until) IS TRUE)
 THEN RAISE EXCEPTION 'CLOCK_STATEMENT_NOT_CURRENT_BINDING'; END IF;
 message=convert_to('R55-CP-PROOF-v1','UTF8')||decode('00','hex');
 values=ARRAY[convert_to('CLOCK_OBSERVATION','UTF8'),convert_to(p_issuer::text,'UTF8'),convert_to(p_key_id::text,'UTF8'),convert_to(p_revision::text,'UTF8'),p_raw];
 FOREACH item IN ARRAY values LOOP message=message||convert_to(octet_length(item)::text||':','UTF8')||item; END LOOP;
 IF company_private.r55_cp_hmac_sha256(p_secret,message) IS DISTINCT FROM p_tag THEN RAISE EXCEPTION 'INVALID_CLOCK_HMAC'; END IF;
 RETURN j;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'CLOCK_SIGNER_NOT_ENROLLED';
END $$;
ALTER FUNCTION company_private.r55_cp_verify_clock_statement(uuid,uuid,bigint,bytea,bytea,bytea) OWNER TO company_context_owner;
REVOKE ALL ON FUNCTION company_private.r55_cp_verify_clock_statement(uuid,uuid,bigint,bytea,bytea,bytea) FROM PUBLIC;

CREATE FUNCTION company_private.r55_cp_clock_epoch_register(
 p_issuer uuid,p_key_id uuid,p_revision bigint,p_raw bytea,p_tag bytea,p_secret bytea,
 p_host uuid,p_host_revision bigint,p_host_generation bigint,p_policy jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE j jsonb;obs jsonb;t uuid;project uuid;epoch uuid;d text;
BEGIN
 j=company_private.r55_cp_verify_clock_statement(p_issuer,p_key_id,p_revision,p_raw,p_tag,p_secret);
 t=(j->>'tenant_id')::uuid;project=(j->>'project_id')::uuid;epoch=(j->>'epoch_id')::uuid;
 IF p_host IS NULL OR p_host_revision IS NULL OR p_host_generation IS NULL OR p_policy IS NULL
 OR jsonb_typeof(p_policy)<>'object' OR NOT ((p_policy ?& ARRAY['max_sample_age_ms','max_uncertainty_ms','max_drift_ms','max_clock_jump_ms']) IS TRUE)
 OR EXISTS(SELECT 1 FROM jsonb_each(p_policy) z WHERE z.key IN ('max_sample_age_ms','max_uncertainty_ms','max_drift_ms','max_clock_jump_ms')
 AND (jsonb_typeof(z.value)<>'number' OR z.value::text !~ '^[0-9]+$')) THEN RAISE EXCEPTION 'INVALID_CLOCK_EPOCH_PROFILE'; END IF;
 d=encode(sha256(convert_to(p_policy::text,'UTF8')),'hex');
 IF j->>'host_registration_id' IS DISTINCT FROM p_host::text OR j->>'host_registration_revision' IS DISTINCT FROM p_host_revision::text
 OR j->>'host_generation' IS DISTINCT FROM p_host_generation::text OR j->>'policy_digest' IS DISTINCT FROM d
 THEN RAISE EXCEPTION 'CLOCK_SIGNED_HOST_POLICY_MISMATCH'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company_private.operation_permissions WHERE operation_id='clock.policy.activate' AND approved_policy_digest=d)
 THEN RAISE EXCEPTION 'CLOCK_POLICY_NOT_APPROVED'; END IF;
 PERFORM 1 FROM company.host_registrations h JOIN company.projects p ON p.tenant_id=h.tenant_id AND p.id=h.project_id
 WHERE h.tenant_id=t AND h.project_id=project AND h.id=p_host AND h.revision=p_host_revision AND h.bound_generation=p_host_generation
 AND h.state='BOUND_NOT_LEASED' AND p.host_registration_id=h.id AND p.host_registration_revision=h.revision AND p.instance_generation=h.bound_generation;
 IF NOT FOUND THEN RAISE EXCEPTION 'CLOCK_HOST_GENERATION_STALE'; END IF;
 obs=company_private.r55_cp_clock_observe_local();
 IF obs->>'source_sync_state' IS DISTINCT FROM 'SYNC' OR obs->>'host_boot_id' IS DISTINCT FROM j->>'host_boot_id'
 THEN RAISE EXCEPTION 'BLOCKED_DB_LOCAL_CLOCK_SOURCE'; END IF;
 INSERT INTO company.clock_epochs(tenant_id,epoch_id,supervisor_id,host_boot_id,writer_generation,policy_digest,registered_at,
 r55_project_id,r55_host_registration_id,r55_host_registration_revision,r55_host_generation,r55_policy)
 VALUES(t,epoch,p_issuer,(j->>'host_boot_id')::uuid,54,d,clock_timestamp(),project,p_host,p_host_revision,p_host_generation,p_policy);
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(t,epoch,p_issuer,'ClockEpochRegistered');
 RETURN epoch;
END $$;
ALTER FUNCTION company_private.r55_cp_clock_epoch_register(uuid,uuid,bigint,bytea,bytea,bytea,uuid,bigint,bigint,jsonb) OWNER TO company_context_owner;
REVOKE ALL ON FUNCTION company_private.r55_cp_clock_epoch_register(uuid,uuid,bigint,bytea,bytea,bytea,uuid,bigint,bigint,jsonb) FROM PUBLIC;

CREATE FUNCTION company_private.r55_cp_clock_sample_persist(
 p_issuer uuid,p_key_id uuid,p_revision bigint,p_raw bytea,p_tag bytea,p_secret bytea)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE j jsonb;e company.clock_epochs%ROWTYPE;s company.clock_samples%ROWTYPE;
 t uuid;project uuid;epoch uuid;sample uuid;seq bigint;bt numeric;age_ns numeric;d text;reason text;
 lo timestamptz;hi timestamptz;u bigint;freq numeric;margin numeric;
BEGIN
 j=company_private.r55_cp_verify_clock_statement(p_issuer,p_key_id,p_revision,p_raw,p_tag,p_secret);
 IF NOT ((j ?& ARRAY['cut_nonce','source_sequence','sampled_at','utc_lower_bound','utc_upper_bound','sample_boottime_ns','sample_uncertainty_ms','frequency_error_ppm_bound','sampling_error_margin_ns','source_sync_state']) IS TRUE)
 THEN RAISE EXCEPTION 'CLOCK_SAMPLE_FIELDS_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(j) z WHERE z.key IN ('source_sequence','sample_boottime_ns','sample_uncertainty_ms','frequency_error_ppm_bound','sampling_error_margin_ns','current_boottime_ns','valid_until_boottime_ns')
 AND (jsonb_typeof(z.value)<>'number' OR z.value::text !~ '^[0-9]+$')) THEN RAISE EXCEPTION 'CLOCK_INTEGER_REQUIRED'; END IF;
 t=(j->>'tenant_id')::uuid;project=(j->>'project_id')::uuid;epoch=(j->>'epoch_id')::uuid;sample=(j->>'sample_id')::uuid;
 seq=(j->>'source_sequence')::bigint;bt=(j->>'sample_boottime_ns')::numeric;
 lo=(j->>'utc_lower_bound')::timestamptz;hi=(j->>'utc_upper_bound')::timestamptz;
 u=(j->>'sample_uncertainty_ms')::bigint;freq=(j->>'frequency_error_ppm_bound')::numeric;margin=(j->>'sampling_error_margin_ns')::numeric;
 IF seq<1 OR hi<lo OR u<0 OR bt<0 OR freq<0 OR margin<0
 OR extract(epoch FROM (hi-lo))*1000000000>2*u::numeric*1000000
 OR (j->>'sampled_at')::timestamptz<lo OR (j->>'sampled_at')::timestamptz>hi
 OR (j->>'current_boottime_ns')::numeric<bt
 OR (j->>'valid_until_boottime_ns')::numeric<=(j->>'current_boottime_ns')::numeric
 THEN RAISE EXCEPTION 'INVALID_CLOCK_SAMPLE_BOUNDS'; END IF;
 SELECT * INTO STRICT e FROM company.clock_epochs WHERE tenant_id=t AND epoch_id=epoch FOR UPDATE;
 IF e.invalidated_at IS NOT NULL OR e.supervisor_id IS DISTINCT FROM p_issuer OR e.writer_generation IS DISTINCT FROM 54
 OR e.r55_project_id IS DISTINCT FROM project OR e.host_boot_id IS DISTINCT FROM (j->>'host_boot_id')::uuid
 OR e.r55_policy IS NULL OR e.r55_host_registration_id IS NULL OR e.r55_host_generation IS NULL
 THEN RAISE EXCEPTION 'CLOCK_EPOCH_BINDING_MISMATCH'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company.host_registrations h JOIN company.projects p ON p.tenant_id=h.tenant_id AND p.id=h.project_id
 WHERE h.tenant_id=t AND h.project_id=project AND h.id=e.r55_host_registration_id AND h.revision=e.r55_host_registration_revision
 AND h.bound_generation=e.r55_host_generation AND h.state='BOUND_NOT_LEASED'
 AND p.host_registration_id=h.id AND p.host_registration_revision=h.revision AND p.instance_generation=h.bound_generation)
 THEN RAISE EXCEPTION 'CLOCK_HOST_GENERATION_STALE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company_private.operation_permissions op WHERE op.operation_id='clock.policy.activate'
 AND op.approved_policy_digest=e.policy_digest AND op.approved_policy_digest=encode(sha256(convert_to(e.r55_policy::text,'UTF8')),'hex'))
 THEN RAISE EXCEPTION 'CLOCK_POLICY_NOT_APPROVED'; END IF;
 IF NOT ((e.r55_policy ?& ARRAY['max_clock_jump_ms','max_uncertainty_ms','max_drift_ms','max_sample_age_ms']) IS TRUE)
 OR EXISTS(SELECT 1 FROM jsonb_each(e.r55_policy) z WHERE z.key IN ('max_clock_jump_ms','max_uncertainty_ms','max_drift_ms','max_sample_age_ms')
 AND (jsonb_typeof(z.value)<>'number' OR z.value::text !~ '^[0-9]+$')) THEN RAISE EXCEPTION 'CLOCK_POLICY_INVALID'; END IF;
 d=encode(sha256(p_raw),'hex');
 SELECT * INTO s FROM company.clock_samples WHERE tenant_id=t AND epoch_id=epoch AND sample_id=sample;
 IF FOUND THEN
  IF s.r55_raw_proof_digest IS DISTINCT FROM d THEN RAISE EXCEPTION 'CLOCK_SAMPLE_DIGEST_CONFLICT'; END IF;
  RETURN jsonb_build_object('status','REPLAY_NO_NEW_CUT','sample_id',sample);
 END IF;
 SELECT * INTO s FROM company.clock_samples WHERE tenant_id=t AND epoch_id=epoch ORDER BY boottime_ns DESC,sample_id DESC LIMIT 1;
 IF FOUND THEN
  IF s.r55_source_sequence IS NULL OR seq<=s.r55_source_sequence OR bt<=s.boottime_ns THEN RAISE EXCEPTION 'CLOCK_REPLAY_OR_REORDER'; END IF;
  age_ns=bt-s.boottime_ns;
  IF greatest(abs(extract(epoch FROM (lo-s.utc_upper_bound))*1000000000-age_ns),abs(extract(epoch FROM (hi-s.utc_lower_bound))*1000000000-age_ns))
  >(e.r55_policy->>'max_clock_jump_ms')::numeric*1000000 THEN reason='CLOCK_JUMP'; END IF;
 ELSIF seq<>1 THEN RAISE EXCEPTION 'CLOCK_FIRST_SEQUENCE_REQUIRED'; END IF;
 IF j->>'source_sync_state' IS DISTINCT FROM 'SYNC' THEN reason='CLOCK_SOURCE_UNSYNCHRONIZED'; END IF;
 IF reason IS NOT NULL THEN
  UPDATE company.clock_epochs SET invalidated_at=clock_timestamp() WHERE tenant_id=t AND epoch_id=epoch AND invalidated_at IS NULL;
  INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(t,(j->>'cut_nonce')::uuid,p_issuer,reason);
  -- Commit this BLOCKED result to preserve invalidation. A caller must not turn
  -- it into a success exception handler or silently rollback and reuse the epoch.
  RETURN jsonb_build_object('status','BLOCKED','reason',reason,'epoch_invalidated',true);
 END IF;
 INSERT INTO company.clock_samples(tenant_id,epoch_id,sample_id,sampled_at,utc_lower_bound,utc_upper_bound,boottime_ns,uncertainty_ms,sample_digest,
 r55_raw_proof_digest,r55_source_sequence,r55_source_enrollment_revision,r55_source_issuer,r55_source_key,r55_frequency_error_ppm_bound,r55_sampling_error_margin_ns)
 VALUES(t,epoch,sample,(j->>'sampled_at')::timestamptz,lo,hi,bt,u,d,d,seq,p_revision,p_issuer,p_key_id,freq,margin);
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(t,(j->>'cut_nonce')::uuid,p_issuer,'ClockObservationPersisted');
 -- Cut persistence is intentionally separate from sample persistence until the
 -- live after-lock BOOTTIME adapter is implemented. No durable sample is HEALTHY.
 RETURN jsonb_build_object('status','SAMPLE_PERSISTED_NO_LIVE_CUT','sample_id',sample,'source_sequence',seq);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'CLOCK_SOURCE_UNRESOLVED';
END $$;
ALTER FUNCTION company_private.r55_cp_clock_sample_persist(uuid,uuid,bigint,bytea,bytea,bytea) OWNER TO company_context_owner;
REVOKE ALL ON FUNCTION company_private.r55_cp_clock_sample_persist(uuid,uuid,bigint,bytea,bytea,bytea) FROM PUBLIC;

CREATE FUNCTION company_private.r55_cp_clock_current_bounds_at(p_tenant uuid,p_project uuid,p_epoch uuid,p_sample uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE e company.clock_epochs%ROWTYPE;s company.clock_samples%ROWTYPE;
 obs jsonb;age_ns numeric;age_lower_ns numeric;drift_ns numeric;uncertainty_ns numeric;
 utc_lo timestamptz;utc_hi timestamptz;capture_ns numeric;
BEGIN
 IF p_tenant IS NULL OR p_project IS NULL OR p_epoch IS NULL OR p_sample IS NULL THEN RAISE EXCEPTION 'BLOCKED_TIME_DEPENDENCY'; END IF;
 SELECT * INTO STRICT e FROM company.clock_epochs WHERE tenant_id=p_tenant AND epoch_id=p_epoch FOR SHARE;
 SELECT * INTO STRICT s FROM company.clock_samples WHERE tenant_id=p_tenant AND epoch_id=p_epoch AND sample_id=p_sample;
 IF e.invalidated_at IS NOT NULL OR e.writer_generation IS DISTINCT FROM 54 OR e.r55_project_id IS DISTINCT FROM p_project
 OR e.r55_host_registration_id IS NULL OR e.r55_host_registration_revision IS NULL OR e.r55_host_generation IS NULL
 OR e.r55_policy IS NULL OR s.r55_raw_proof_digest IS NULL OR s.r55_source_sequence IS NULL OR s.r55_source_sequence<2
 OR s.r55_source_issuer IS DISTINCT FROM e.supervisor_id OR s.r55_source_key IS NULL OR s.r55_source_enrollment_revision IS NULL
 OR s.r55_frequency_error_ppm_bound IS NULL OR s.r55_frequency_error_ppm_bound<0
 OR s.r55_sampling_error_margin_ns IS NULL OR s.r55_sampling_error_margin_ns<0
 THEN RAISE EXCEPTION 'CLOCK_EPOCH_SAMPLE_NOT_CURRENT'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company.host_registrations h JOIN company.projects p ON p.tenant_id=h.tenant_id AND p.id=h.project_id
 WHERE h.tenant_id=p_tenant AND h.project_id=p_project AND h.id=e.r55_host_registration_id AND h.revision=e.r55_host_registration_revision
 AND h.bound_generation=e.r55_host_generation AND h.state='BOUND_NOT_LEASED'
 AND p.host_registration_id=h.id AND p.host_registration_revision=h.revision AND p.instance_generation=h.bound_generation)
 THEN RAISE EXCEPTION 'CLOCK_HOST_GENERATION_STALE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company_private.operation_permissions op WHERE op.operation_id='clock.policy.activate'
 AND op.approved_policy_digest=e.policy_digest AND op.approved_policy_digest=encode(sha256(convert_to(e.r55_policy::text,'UTF8')),'hex'))
 THEN RAISE EXCEPTION 'CLOCK_POLICY_NOT_APPROVED'; END IF;
 IF NOT ((jsonb_typeof(e.r55_policy)='object' AND e.r55_policy ?& ARRAY['max_sample_age_ms','max_uncertainty_ms','max_drift_ms','max_clock_jump_ms']) IS TRUE)
 OR EXISTS(SELECT 1 FROM jsonb_each(e.r55_policy) z WHERE z.key IN ('max_sample_age_ms','max_uncertainty_ms','max_drift_ms','max_clock_jump_ms')
 AND (jsonb_typeof(z.value)<>'number' OR z.value::text !~ '^[0-9]+$')) THEN RAISE EXCEPTION 'CLOCK_POLICY_INVALID'; END IF;
 -- Fresh native BOOTTIME read occurs AFTER SQL row locks, every guard call.
 -- A remote producer whose boot/host differs cannot authorize this DB-local path.
 obs=company_private.r55_cp_clock_observe_local();
 IF obs->>'profile' IS DISTINCT FROM 'LINUX_ADJTIMEX_DB_LOCAL_V1' OR obs->>'source_sync_state' IS DISTINCT FROM 'SYNC'
 OR (obs->>'host_boot_id')::uuid IS DISTINCT FROM e.host_boot_id OR (obs->>'backend_pid')::integer IS DISTINCT FROM pg_backend_pid()
 THEN RAISE EXCEPTION 'BLOCKED_LOCAL_CLOCK_SOURCE'; END IF;
 age_ns=(obs->>'boottime_after_ns')::numeric-s.boottime_ns;
 age_lower_ns=(obs->>'boottime_before_ns')::numeric-s.boottime_ns;
 capture_ns=(obs->>'boottime_after_ns')::numeric-(obs->>'boottime_before_ns')::numeric;
 IF age_lower_ns<0 OR capture_ns<0 OR age_ns>(e.r55_policy->>'max_sample_age_ms')::numeric*1000000 THEN RAISE EXCEPTION 'CLOCK_SAMPLE_STALE'; END IF;
 drift_ns=ceil(age_ns*s.r55_frequency_error_ppm_bound/1000000)+s.r55_sampling_error_margin_ns;
 IF drift_ns>(e.r55_policy->>'max_drift_ms')::numeric*1000000 THEN RAISE EXCEPTION 'CLOCK_DRIFT_EXCEEDED'; END IF;
 uncertainty_ns=greatest(s.uncertainty_ms::numeric*1000000+drift_ns+capture_ns,(obs->>'maxerror_us')::numeric*1000,(obs->>'esterror_us')::numeric*1000);
 IF uncertainty_ns>(e.r55_policy->>'max_uncertainty_ms')::numeric*1000000 THEN RAISE EXCEPTION 'CLOCK_UNCERTAINTY_EXCEEDED'; END IF;
 IF greatest(abs((obs->>'utc_ns')::numeric-extract(epoch FROM s.utc_lower_bound)*1000000000-age_ns),
             abs((obs->>'utc_ns')::numeric-extract(epoch FROM s.utc_upper_bound)*1000000000-age_lower_ns))
 >(e.r55_policy->>'max_clock_jump_ms')::numeric*1000000 THEN RAISE EXCEPTION 'CLOCK_JUMP'; END IF;
 -- Trusted current UTC is projected from the signed source interval and fresh
 -- BOOTTIME; local realtime is only a jump rejection, not an expiry authority.
 utc_lo=s.utc_lower_bound+floor((age_lower_ns-drift_ns)/1000)*interval '1 microsecond';
 utc_hi=s.utc_upper_bound+ceil((age_ns+drift_ns)/1000)*interval '1 microsecond';
 IF NOT EXISTS(SELECT 1 FROM company.signer_enrollments k WHERE k.tenant_id=p_tenant AND k.issuer_id=s.r55_source_issuer
 AND k.key_id=s.r55_source_key AND k.enrollment_revision=s.r55_source_enrollment_revision AND k.purpose='CLOCK_OBSERVATION'
 AND k.profile_id='R55_CLOCK_V1_RAW_JSON' AND k.revoked_at IS NULL AND k.compromised_since IS NULL
 AND k.r55_project_id=p_project AND k.r55_host_id=e.r55_host_registration_id AND k.r55_host_revision=e.r55_host_registration_revision
 AND k.r55_host_generation=e.r55_host_generation AND k.r55_host_boot_id=e.host_boot_id
 AND k.valid_from<=utc_lo AND k.valid_until>utc_hi)
 THEN RAISE EXCEPTION 'CLOCK_SAMPLE_ENROLLMENT_REVOKED_OR_AMBIGUOUS'; END IF;
 RETURN jsonb_build_object('utc_lower_bound',utc_lo,'utc_upper_bound',utc_hi,'epoch_id',p_epoch,'sample_id',p_sample,
 'host_boot_id',e.host_boot_id,'host_registration_id',e.r55_host_registration_id,'host_registration_revision',e.r55_host_registration_revision,
 'host_generation',e.r55_host_generation,'writer_generation',e.writer_generation,'boottime_after_ns',obs->'boottime_after_ns');
END $$;
ALTER FUNCTION company_private.r55_cp_clock_current_bounds_at(uuid,uuid,uuid,uuid) OWNER TO company_context_owner;
REVOKE ALL ON FUNCTION company_private.r55_cp_clock_current_bounds_at(uuid,uuid,uuid,uuid) FROM PUBLIC;

CREATE FUNCTION company_private.r55_cp_clock_assert_current(p_tenant uuid,p_project uuid,p_epoch uuid,p_sample uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN PERFORM company_private.r55_cp_clock_current_bounds_at(p_tenant,p_project,p_epoch,p_sample); END $$;
ALTER FUNCTION company_private.r55_cp_clock_assert_current(uuid,uuid,uuid,uuid) OWNER TO company_context_owner;
REVOKE ALL ON FUNCTION company_private.r55_cp_clock_assert_current(uuid,uuid,uuid,uuid) FROM PUBLIC;

CREATE FUNCTION company_private.r55_cp_require_clock_health(p_tenant uuid,p_project uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE e uuid;s uuid;
BEGIN
 SELECT ce.epoch_id,cs.sample_id INTO STRICT e,s FROM company.clock_epochs ce JOIN company.clock_samples cs
 ON cs.tenant_id=ce.tenant_id AND cs.epoch_id=ce.epoch_id
 WHERE ce.tenant_id=p_tenant AND ce.r55_project_id=p_project AND ce.invalidated_at IS NULL
 ORDER BY ce.registered_at DESC,ce.epoch_id DESC,cs.boottime_ns DESC,cs.sample_id DESC LIMIT 1;
 PERFORM company_private.r55_cp_clock_assert_current(p_tenant,p_project,e,s);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'BLOCKED_TIME_DEPENDENCY';
END $$;
ALTER FUNCTION company_private.r55_cp_require_clock_health(uuid,uuid) OWNER TO company_context_owner;
REVOKE ALL ON FUNCTION company_private.r55_cp_require_clock_health(uuid,uuid) FROM PUBLIC;
CREATE FUNCTION company_private.r55_cp_clock_current_bounds(p_tenant uuid,p_project uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE e uuid;s uuid;
BEGIN
 SELECT ce.epoch_id,cs.sample_id INTO STRICT e,s FROM company.clock_epochs ce JOIN company.clock_samples cs
 ON cs.tenant_id=ce.tenant_id AND cs.epoch_id=ce.epoch_id
 WHERE ce.tenant_id=p_tenant AND ce.r55_project_id=p_project AND ce.invalidated_at IS NULL
 ORDER BY ce.registered_at DESC,ce.epoch_id DESC,cs.boottime_ns DESC,cs.sample_id DESC LIMIT 1;
 RETURN company_private.r55_cp_clock_current_bounds_at(p_tenant,p_project,e,s);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'BLOCKED_TIME_DEPENDENCY';
END $$;
ALTER FUNCTION company_private.r55_cp_clock_current_bounds(uuid,uuid) OWNER TO company_context_owner;
REVOKE ALL ON FUNCTION company_private.r55_cp_clock_current_bounds(uuid,uuid) FROM PUBLIC;

CREATE FUNCTION company_private.r55_cp_time_window_current(p_tenant uuid,p_project uuid,p_valid_from timestamptz,p_valid_until timestamptz)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE b jsonb;
BEGIN
 IF p_valid_from IS NULL OR p_valid_until IS NULL OR p_valid_until<=p_valid_from THEN RETURN false; END IF;
 b=company_private.r55_cp_clock_current_bounds(p_tenant,p_project);
 RETURN ((p_valid_from<=(b->>'utc_lower_bound')::timestamptz AND (b->>'utc_upper_bound')::timestamptz<p_valid_until) IS TRUE);
END $$;
ALTER FUNCTION company_private.r55_cp_time_window_current(uuid,uuid,timestamptz,timestamptz) OWNER TO company_context_owner;
REVOKE ALL ON FUNCTION company_private.r55_cp_time_window_current(uuid,uuid,timestamptz,timestamptz) FROM PUBLIC;

CREATE FUNCTION company_private.r55_cp_require_not_expired(p_tenant uuid,p_project uuid,p_expiry timestamptz)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE b jsonb;
BEGIN
 IF p_expiry IS NULL THEN RAISE EXCEPTION 'TIME_EXPIRY_REQUIRED'; END IF;
 b=company_private.r55_cp_clock_current_bounds(p_tenant,p_project);
 IF NOT (((b->>'utc_upper_bound')::timestamptz<p_expiry) IS TRUE) THEN RAISE EXCEPTION 'TIME_EXPIRED_OR_AMBIGUOUS'; END IF;
END $$;
ALTER FUNCTION company_private.r55_cp_require_not_expired(uuid,uuid,timestamptz) OWNER TO company_context_owner;
REVOKE ALL ON FUNCTION company_private.r55_cp_require_not_expired(uuid,uuid,timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_time_window_current(uuid,uuid,timestamptz,timestamptz),company_private.r55_cp_require_not_expired(uuid,uuid,timestamptz),company_private.r55_cp_clock_current_bounds(uuid,uuid) TO company_first_run_functions_r53,company_revoke_functions_r53;

-- Source-exact replacement of the historical unconditional stub. CREATE OR
-- REPLACE keeps its signature and existing object grants; no new transport role.
CREATE OR REPLACE FUNCTION company_private.r54_require_clock_health(p_tenant uuid,p_project uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM company_private.r55_cp_require_clock_health(p_tenant,p_project);
END $$;
ALTER FUNCTION company_private.r54_require_clock_health(uuid,uuid) OWNER TO company_context_owner;
REVOKE ALL ON FUNCTION company_private.r54_require_clock_health(uuid,uuid) FROM PUBLIC;
-- Finite owner metadata reads; normal roles get no table DML or source key.
GRANT SELECT ON company.clock_epochs,company.clock_samples,company.signer_enrollments,company.host_registrations,company.projects,company.principals,company_private.operation_permissions TO company_context_owner;
GRANT INSERT ON company.clock_epochs,company.clock_samples,company.audit_events TO company_context_owner;
GRANT UPDATE(invalidated_at) ON company.clock_epochs TO company_context_owner;
GRANT UPDATE(revoked_at) ON company.signer_enrollments TO company_context_owner;
GRANT USAGE ON SEQUENCE company.audit_events_id_seq TO company_context_owner;
CREATE POLICY r55_clock_epoch_read ON company.clock_epochs FOR SELECT TO company_context_owner USING(true);
CREATE POLICY r55_clock_epoch_insert ON company.clock_epochs FOR INSERT TO company_context_owner WITH CHECK(session_user='company_clock_runtime_r55');
CREATE POLICY r55_clock_epoch_lock ON company.clock_epochs FOR UPDATE TO company_context_owner USING(true) WITH CHECK(true);
CREATE POLICY r55_clock_sample_read ON company.clock_samples FOR SELECT TO company_context_owner USING(true);
CREATE POLICY r55_clock_sample_insert ON company.clock_samples FOR INSERT TO company_context_owner WITH CHECK(session_user='company_clock_runtime_r55');
CREATE POLICY r55_clock_signer_read ON company.signer_enrollments FOR SELECT TO company_context_owner USING(purpose='CLOCK_OBSERVATION');
CREATE POLICY r55_clock_signer_lock ON company.signer_enrollments FOR UPDATE TO company_context_owner USING(purpose='CLOCK_OBSERVATION') WITH CHECK(false);
CREATE POLICY r55_clock_host_read ON company.host_registrations FOR SELECT TO company_context_owner USING(true);
CREATE POLICY r55_clock_audit ON company.audit_events FOR INSERT TO company_context_owner WITH CHECK(session_user='company_clock_runtime_r55');
GRANT EXECUTE ON FUNCTION company_private.r55_cp_hmac_sha256(bytea,bytea),company_private.r55_cp_clock_observe_local() TO company_context_owner;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_verify_clock_statement(uuid,uuid,bigint,bytea,bytea,bytea),company_private.r55_cp_clock_sample_persist(uuid,uuid,bigint,bytea,bytea,bytea),company_private.r55_cp_clock_epoch_register(uuid,uuid,bigint,bytea,bytea,bytea,uuid,bigint,bigint,jsonb) TO company_clock_runtime_r55;
-- NO caller EXECUTE before exact verifier login/DB-local host/profile/compiled
-- source enrollment; actual identity/policy rows are not generated here.

-- SOURCE sql/018_R55_TRUSTED_TIME_CONSUMER_OVERLAY.sql
-- Apply after A clock helpers and r54 baseline. Does NOT replace C Objective/Plan/Task finality or B worker admission.

CREATE OR REPLACE FUNCTION company_private.r54_grant_chain(p_tenant uuid,p_project uuid,p_principal uuid,p_permission text,p_task uuid,p_leaf uuid)
RETURNS uuid[] LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE g company.project_grants%ROWTYPE; child company.project_grants%ROWTYPE;
 ids uuid[]='{}'; next_id uuid=p_leaf; first_row boolean=true;
BEGIN
 IF p_leaf IS NULL OR p_permission IS NULL OR p_permission='' OR position('*' IN p_permission)>0 THEN RAISE EXCEPTION 'GRANT_ID_REQUIRED'; END IF;
 LOOP
  IF next_id=ANY(ids) THEN RAISE EXCEPTION 'DELEGATION_CYCLE'; END IF;
  SELECT * INTO STRICT g FROM company.project_grants WHERE tenant_id=p_tenant AND project_id=p_project AND grant_id=next_id;
  IF NOT EXISTS(SELECT 1 FROM company.memberships WHERE tenant_id=p_tenant AND principal_id=g.principal_id) THEN RAISE EXCEPTION 'ANCESTOR_MEMBERSHIP_REVOKED'; END IF;
  IF g.revoked_at IS NOT NULL OR g.valid_from>((company_private.r55_cp_clock_current_bounds(p_tenant,p_project)->>'utc_lower_bound')::timestamptz) OR g.valid_until<=((company_private.r55_cp_clock_current_bounds(p_tenant,p_project)->>'utc_upper_bound')::timestamptz)
     OR COALESCE(g.base_permission,g.permission)<>p_permission THEN RAISE EXCEPTION 'GRANT_NOT_CURRENT'; END IF;
  IF g.task_scope_id IS NOT NULL AND g.task_scope_id IS DISTINCT FROM p_task THEN RAISE EXCEPTION 'GRANT_WRONG_TASK'; END IF;
  IF first_row THEN
   IF g.principal_id<>p_principal THEN RAISE EXCEPTION 'GRANT_WRONG_PRINCIPAL'; END IF;
  ELSE
   IF child.granted_by<>g.principal_id OR child.valid_from<g.valid_from OR child.valid_until>g.valid_until
      OR (g.task_scope_id IS NOT NULL AND child.task_scope_id IS DISTINCT FROM g.task_scope_id)
      THEN RAISE EXCEPTION 'CHILD_EXCEEDS_PARENT'; END IF;
  END IF;
  ids=array_append(ids,g.grant_id);
  IF g.parent_grant_id IS NULL THEN RETURN ids; END IF;
  child=g; first_row=false; next_id=g.parent_grant_id;
 END LOOP;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'GRANT_CHAIN_UNRESOLVED';
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_context_enter(p_token text,p_operation text,p_project uuid,p_kind text,p_resource uuid,p_task uuid,p_attempt uuid,p_fence bigint,p_grant uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE s company.sessions%ROWTYPE; op company_private.operation_permissions%ROWTYPE;
 t company.tasks%ROWTYPE; a company.attempts%ROWTYPE; h record; ids uuid[]; nonce uuid; pk text; te bigint; pe bigint; se bigint;
BEGIN
 IF NOT pg_has_role(session_user,'company_transport_r54','MEMBER') THEN RAISE EXCEPTION 'TRANSPORT_REQUIRED'; END IF;
 IF p_token IS NULL OR octet_length(p_token)<32 OR octet_length(p_token)>4096 THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id()) THEN RAISE EXCEPTION 'CONTEXT_ALREADY_BOUND'; END IF;
 SELECT * INTO STRICT s FROM company.sessions WHERE token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex');
 -- Tek authority lock sırası: rank,lock_id. Revoke da aynı üç scope kilidini alır.
 FOR h IN SELECT l.lock_id,l.rank FROM company.authority_scope_heads ah JOIN company_private.scope_lock_registry l ON l.lock_id=ah.lock_id
 WHERE ah.tenant_id=s.tenant_id AND ((ah.scope_kind='TENANT' AND ah.scope_ref=s.tenant_id)
 OR (ah.scope_kind='PROJECT' AND ah.scope_ref=p_project) OR (ah.scope_kind='SESSION' AND ah.scope_ref=s.id)) ORDER BY l.rank,l.lock_id LOOP
  PERFORM pg_advisory_xact_lock(h.lock_id);
 END LOOP;
 SELECT * INTO STRICT s FROM company.sessions WHERE tenant_id=s.tenant_id AND id=s.id AND token_hash=s.token_hash;
 IF s.revoked_at IS NOT NULL OR s.expires_at<=((company_private.r55_cp_clock_current_bounds(s.tenant_id,p_project)->>'utc_upper_bound')::timestamptz) THEN RAISE EXCEPTION 'AUTH_REVOKED'; END IF;
 SELECT pr.kind INTO STRICT pk FROM company.principals pr JOIN company.memberships m ON m.tenant_id=pr.tenant_id AND m.principal_id=pr.id
 WHERE pr.tenant_id=s.tenant_id AND pr.id=s.principal_id;
 SELECT * INTO STRICT op FROM company_private.operation_permissions WHERE operation_id=p_operation;
 -- Yeni DIRECT/TASK/RESOURCE scope enum yaratılmaz. Bunlar PROJECT altındaki exact binding biçimleridir.
 IF op.scope_kind<>'PROJECT' THEN RAISE EXCEPTION 'SEPARATE_SCOPE_RESOLVER_REQUIRED'; END IF;
 IF op.approved_policy_digest IS NULL AND op.execution_class NOT IN ('QUERY','STREAM') THEN RAISE EXCEPTION 'POLICY_NOT_APPROVED'; END IF;
 IF p_project IS NULL OR p_kind IS NULL OR p_resource IS NULL OR p_kind NOT IN ('PROJECT','TASK','ATTEMPT') THEN RAISE EXCEPTION 'RESOURCE_RESOLVER_UNSUPPORTED'; END IF;
 IF p_kind='PROJECT' THEN
  IF p_resource IS DISTINCT FROM p_project OR p_task IS NOT NULL OR p_attempt IS NOT NULL OR p_fence IS NOT NULL THEN RAISE EXCEPTION 'PROJECT_BINDING_INVALID'; END IF;
  PERFORM 1 FROM company.projects WHERE tenant_id=s.tenant_id AND id=p_project;
  IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 ELSE
  SELECT * INTO STRICT t FROM company.tasks WHERE tenant_id=s.tenant_id AND project_id=p_project AND id=p_task;
  IF p_kind='TASK' AND (p_resource IS DISTINCT FROM p_task OR p_attempt IS NOT NULL OR p_fence IS NOT NULL) THEN RAISE EXCEPTION 'TASK_BINDING_INVALID'; END IF;
  IF p_kind='ATTEMPT' THEN
   IF p_task IS NULL OR p_attempt IS NULL OR p_fence IS NULL OR p_fence<=0 THEN RAISE EXCEPTION 'ATTEMPT_BINDING_INVALID'; END IF;
   SELECT * INTO STRICT a FROM company.attempts WHERE tenant_id=s.tenant_id AND project_id=p_project AND task_id=p_task AND id=p_attempt;
   IF p_resource IS DISTINCT FROM p_attempt OR t.active_attempt_id IS DISTINCT FROM a.id OR t.fencing_epoch<>p_fence
      OR a.fencing_epoch<>p_fence OR a.worker_id<>s.principal_id OR a.lease_expires_at<=((company_private.r55_cp_clock_current_bounds(s.tenant_id,p_project)->>'utc_upper_bound')::timestamptz)
      OR a.state NOT IN ('CLAIMED','RUNNING') OR a.ended_at IS NOT NULL THEN RAISE EXCEPTION 'STALE_ATTEMPT'; END IF;
  END IF;
 END IF;
 ids=company_private.r54_grant_chain(s.tenant_id,p_project,s.principal_id,op.permission,p_task,p_grant);
 SELECT epoch INTO STRICT te FROM company.authority_scope_heads WHERE tenant_id=s.tenant_id AND scope_kind='TENANT' AND scope_ref=s.tenant_id;
 SELECT epoch INTO STRICT pe FROM company.authority_scope_heads WHERE tenant_id=s.tenant_id AND scope_kind='PROJECT' AND scope_ref=p_project;
 SELECT epoch INTO STRICT se FROM company.authority_scope_heads WHERE tenant_id=s.tenant_id AND scope_kind='SESSION' AND scope_ref=s.id;
 PERFORM company_private.r54_require_clock_health(s.tenant_id,p_project);
 nonce=gen_random_uuid();
 INSERT INTO company_private.request_contexts(backend_pid,transaction_id,request_nonce,db_login,tenant_id,project_id,principal_id,session_id,operation_id,tenant_epoch,project_epoch,session_epoch,writer_generation,authenticated_at,expires_at,grant_id,grant_chain_ids,principal_kind,resource_kind,resource_id,task_id,attempt_id,fencing_epoch,policy_revision)
 VALUES(pg_backend_pid(),pg_current_xact_id(),nonce,session_user,s.tenant_id,p_project,s.principal_id,s.id,p_operation,te,pe,se,54,clock_timestamp(),s.expires_at,p_grant,ids,pk,p_kind,p_resource,p_task,p_attempt,p_fence,op.policy_revision);
 RETURN nonce;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'AUTH_OR_RESOURCE_UNRESOLVED';
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_allowed(p_tenant uuid,p_project uuid,p_permission text,p_task uuid,p_write boolean)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; op company_private.operation_permissions%ROWTYPE; ids uuid[];
BEGIN
 PERFORM company_private.r54_require_clock_health(p_tenant,p_project);
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user;
 SELECT * INTO STRICT op FROM company_private.operation_permissions WHERE operation_id=x.operation_id AND permission=p_permission AND scope_kind='PROJECT';
 IF x.writer_generation<>54 OR x.tenant_id<>p_tenant OR x.project_id IS DISTINCT FROM p_project
 OR x.policy_revision IS DISTINCT FROM op.policy_revision OR x.expires_at<=((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz) OR (p_write AND op.approved_policy_digest IS NULL)
 OR (x.task_id IS NOT NULL AND x.task_id IS DISTINCT FROM p_task) THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM company.sessions s JOIN company.memberships m ON m.tenant_id=s.tenant_id AND m.principal_id=s.principal_id WHERE s.tenant_id=x.tenant_id AND s.id=x.session_id AND s.principal_id=x.principal_id AND s.revoked_at IS NULL AND s.expires_at>((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz)) THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM company.authority_scope_heads WHERE tenant_id=x.tenant_id AND scope_kind='TENANT' AND scope_ref=x.tenant_id AND epoch=x.tenant_epoch)
 OR NOT EXISTS(SELECT 1 FROM company.authority_scope_heads WHERE tenant_id=x.tenant_id AND scope_kind='PROJECT' AND scope_ref=x.project_id AND epoch=x.project_epoch)
 OR NOT EXISTS(SELECT 1 FROM company.authority_scope_heads WHERE tenant_id=x.tenant_id AND scope_kind='SESSION' AND scope_ref=x.session_id AND epoch=x.session_epoch) THEN RETURN false; END IF;
 ids=company_private.r54_grant_chain(x.tenant_id,x.project_id,x.principal_id,p_permission,x.task_id,x.grant_id);
 IF ids IS DISTINCT FROM x.grant_chain_ids THEN RETURN false; END IF;
 IF x.attempt_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM company.attempts a JOIN company.tasks t ON t.tenant_id=a.tenant_id AND t.project_id=a.project_id AND t.id=a.task_id AND t.active_attempt_id=a.id
 WHERE a.tenant_id=x.tenant_id AND a.project_id=x.project_id AND a.task_id=x.task_id AND a.id=x.attempt_id AND a.worker_id=x.principal_id AND a.fencing_epoch=x.fencing_epoch AND t.fencing_epoch=x.fencing_epoch AND a.lease_expires_at>((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz) AND a.ended_at IS NULL AND a.state IN ('CLAIMED','RUNNING')) THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS OR RAISE_EXCEPTION THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_resource_process_context(p_token text,p_operation text,p_project uuid,p_task uuid,p_attempt uuid,p_fence bigint,p_grant uuid,p_process uuid,p_slot uuid,p_process_revision bigint,p_claim_revision bigint)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE n uuid; x company_private.request_contexts%ROWTYPE; r company.process_runs%ROWTYPE;
BEGIN
 IF p_process IS NULL OR p_process_revision IS NULL OR p_process_revision<0 THEN RAISE EXCEPTION 'PROCESS_BINDING_REQUIRED'; END IF;
 n=company_private.r54_context_enter(p_token,p_operation,p_project,'ATTEMPT',p_attempt,p_task,p_attempt,p_fence,p_grant);
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND request_nonce=n;
 PERFORM company_private.r54_require_clock_health(x.tenant_id,x.project_id);
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process FOR SHARE;
 IF r.task_id IS DISTINCT FROM p_task OR r.attempt_id IS DISTINCT FROM p_attempt OR r.attempt_fencing_epoch IS DISTINCT FROM p_fence OR r.worker_id IS DISTINCT FROM x.principal_id OR r.revision IS DISTINCT FROM p_process_revision
 OR r.lease_expires_at<=((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz) OR r.state NOT IN ('LEASED','REQUESTED','STARTING','RUNNING','STOP_REQUESTED') THEN RAISE EXCEPTION 'STALE_PROCESS_BINDING'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company.tasks t JOIN company.attempts a ON a.tenant_id=t.tenant_id AND a.project_id=t.project_id AND a.task_id=t.id AND a.id=t.active_attempt_id WHERE t.tenant_id=x.tenant_id AND t.project_id=x.project_id AND t.id=r.task_id AND a.id=r.attempt_id AND a.fencing_epoch=r.attempt_fencing_epoch AND a.worker_id=r.worker_id AND a.lease_expires_at=r.lease_expires_at AND EXISTS(SELECT 1 FROM company.projects pp WHERE pp.tenant_id=r.tenant_id AND pp.id=r.project_id AND pp.workspace_id=r.workspace_id))
 THEN RAISE EXCEPTION 'PROCESS_ATTEMPT_TUPLE_MISMATCH'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company.budget_reservations b WHERE b.tenant_id=r.tenant_id AND b.project_id=r.project_id AND b.id=r.reservation_id AND b.task_id=r.task_id AND b.attempt_id=r.attempt_id AND b.attempt_fencing_epoch=r.attempt_fencing_epoch AND b.state='RESERVED') THEN RAISE EXCEPTION 'BUDGET_BINDING_NOT_CURRENT'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company.host_registrations h JOIN company.projects p ON p.tenant_id=h.tenant_id AND p.id=h.project_id WHERE h.tenant_id=r.tenant_id AND h.project_id=r.project_id AND h.id=r.host_registration_id AND h.revision=r.host_registration_revision AND h.state='BOUND_NOT_LEASED' AND h.bound_generation=r.host_generation AND p.instance_generation=r.host_generation AND p.host_registration_id=r.host_registration_id AND p.host_registration_revision=r.host_registration_revision) THEN RAISE EXCEPTION 'HOST_GENERATION_STALE'; END IF;
 IF p_slot IS NOT NULL THEN
  IF p_claim_revision IS NULL OR NOT EXISTS(SELECT 1 FROM company.resource_claims c JOIN company.resource_slots s ON s.tenant_id=c.tenant_id AND s.id=c.slot_id WHERE c.tenant_id=r.tenant_id AND c.project_id=r.project_id AND c.process_run_id=r.id AND c.slot_id=p_slot AND c.revision=p_claim_revision AND c.state='HELD' AND c.units>0 AND s.reserved>=c.units AND s.reserved<=s.capacity) THEN RAISE EXCEPTION 'RESOURCE_CLAIM_NOT_CURRENT'; END IF;
 ELSIF p_claim_revision IS NOT NULL THEN RAISE EXCEPTION 'RESOURCE_SLOT_REQUIRED'; END IF;
 UPDATE company_private.request_contexts SET resource_kind=CASE WHEN p_slot IS NULL THEN 'PROCESS' ELSE 'RESOURCE' END,resource_id=COALESCE(p_slot,p_process) WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND request_nonce=n;
 RETURN n;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'PROCESS_RESOURCE_UNRESOLVED'; END $$;

CREATE OR REPLACE FUNCTION company_private.r54_e0_setup_mandate_consume(p_installation uuid,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; b company_private.bootstrap_receipts%ROWTYPE; e company.evaluation_runs%ROWTYPE;
 v_command uuid; v_id uuid; v_digest text; v_key text;
BEGIN
 x=company_private.r54_b_context('e0.setup_mandate_consume',true);
 SELECT * INTO STRICT b FROM company_private.bootstrap_receipts WHERE installation_id=p_installation AND tenant_id=x.tenant_id AND project_id=x.project_id FOR UPDATE;
 IF b.accepted_human_id IS DISTINCT FROM x.principal_id OR b.e0_mandate IS NULL OR b.e0_valid_until IS NULL OR b.e0_valid_until<=((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz)
 THEN RAISE EXCEPTION 'BLOCKED_SETUP_MANDATE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company_private.installation_bootstrap_control z WHERE z.installation_id=b.installation_id AND z.state='CONSUMED' AND z.generation=b.generation AND z.consumed_command_id=b.command_id AND z.setup_manifest_digest=b.setup_manifest_digest) THEN RAISE EXCEPTION 'BLOCKED_SETUP_PROVENANCE'; END IF;
 v_digest=encode(sha256(convert_to(b.e0_mandate::text,'UTF8')),'hex');v_key='e0:'||p_installation::text;
 SELECT * INTO e FROM company.evaluation_runs WHERE e0_installation_id=p_installation;
 IF FOUND THEN RETURN jsonb_build_object('evaluation_run_id',e.id,'command_id',e.authorization_id,'outcome','REPLAY_NO_NEW_ATTEMPT'); END IF;
 v_command=gen_random_uuid();v_id=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,v_command,x.principal_id,x.operation_id,v_key,v_digest,p_correlation,'RUNNING',NULL);
 INSERT INTO company.evaluation_runs(tenant_id,project_id,id,authorization_id,role_id,fixture_digest,model_digest,source_kind,state,subject_principal_id,e0_installation_id)
 VALUES(x.tenant_id,x.project_id,v_id,v_command,b.e0_mandate->>'role_id',b.e0_mandate->>'fixture_digest',b.e0_mandate->>'model_digest','DISPOSABLE_TEST','AUTHORIZED',(b.e0_mandate->>'subject_principal_id')::uuid,p_installation);
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(x.tenant_id,p_correlation,x.principal_id,'E0MandateConsumed');
 PERFORM company_private.r54_emit_event(x.tenant_id,x.project_id,v_id,0,'E0MandateConsumed',jsonb_build_object('evaluation_run_id',v_id,'command_id',v_command));
 UPDATE company.commands SET state='SUCCEEDED',result_ref=v_id WHERE tenant_id=x.tenant_id AND id=v_command;
 PERFORM company_private.r54_b_context(x.operation_id,true);
 RETURN jsonb_build_object('evaluation_run_id',v_id,'command_id',v_command,'outcome','EVALUATION_AUTHORIZED_NOT_STARTED');
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_e0_evaluation_attempt_create(p_evaluation uuid,p_lease_until timestamptz)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;e company.evaluation_runs%ROWTYPE;b company_private.bootstrap_receipts%ROWTYPE;t uuid;a uuid;v_plan uuid;
BEGIN
 x=company_private.r54_b_context('e0.evaluation_attempt_create',true);
 SELECT * INTO STRICT e FROM company.evaluation_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_evaluation FOR UPDATE;
 SELECT * INTO STRICT b FROM company_private.bootstrap_receipts WHERE installation_id=e.e0_installation_id;
 IF b.accepted_human_id IS DISTINCT FROM x.principal_id OR b.e0_valid_until IS NULL OR b.e0_valid_until<=((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz) OR p_lease_until IS NULL OR p_lease_until<=((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz) OR p_lease_until>b.e0_valid_until THEN RAISE EXCEPTION 'BLOCKED_SETUP_MANDATE'; END IF;
 IF e.evaluation_attempt_id IS NOT NULL THEN RETURN jsonb_build_object('task_id',e.evaluation_task_id,'attempt_id',e.evaluation_attempt_id,'outcome','REPLAY_NO_NEW_ATTEMPT'); END IF;
 IF e.state<>'AUTHORIZED' THEN RAISE EXCEPTION 'CONFLICT_EVALUATION_STATE'; END IF;
 v_plan=(b.e0_mandate->>'plan_id')::uuid;
 PERFORM 1 FROM company.plans WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=v_plan FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BLOCKED_EVALUATION_PLAN'; END IF;
 t=gen_random_uuid();a=gen_random_uuid();
 INSERT INTO company.tasks(tenant_id,project_id,id,plan_id,title,role_id,state,revision,fencing_epoch,acceptance_criteria,execution_kind)
 VALUES(x.tenant_id,x.project_id,t,v_plan,'E0 disposable evaluation',e.role_id,'READY',0,1,jsonb_build_array('negative suite and independent evidence required'),'EVALUATION');
 INSERT INTO company.attempts(tenant_id,project_id,task_id,id,attempt_no,fencing_epoch,worker_id,state,lease_expires_at,e0_evaluation_run_id)
 VALUES(x.tenant_id,x.project_id,t,a,1,1,e.subject_principal_id,'CLAIMED',p_lease_until,e.id);
 UPDATE company.tasks SET active_attempt_id=a WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=t;
 UPDATE company.evaluation_runs SET evaluation_task_id=t,evaluation_attempt_id=a WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=e.id;
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) SELECT x.tenant_id,c.correlation_id,x.principal_id,'E0AttemptCreated' FROM company.commands c WHERE c.tenant_id=x.tenant_id AND c.id=e.authorization_id;
 PERFORM company_private.r54_emit_event(x.tenant_id,x.project_id,t,0,'E0AttemptCreated',jsonb_build_object('task_id',t,'attempt_id',a,'evaluation_run_id',e.id,'ordinary_admission',false));
 PERFORM company_private.r54_b_context(x.operation_id,true);
 RETURN jsonb_build_object('task_id',t,'attempt_id',a,'outcome','EVALUATION_CLAIMED_PROCESS_NOT_STARTED');
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_qualification_current(p_qualification uuid,p_subject uuid,p_binding_digest text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;q company.agent_qualifications%ROWTYPE;h company.governance_decision_heads%ROWTYPE;
BEGIN
 x=company_private.r54_b_context('qualification.admission',false,false);
 SELECT * INTO STRICT q FROM company.agent_qualifications WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_qualification;
 IF p_subject IS NULL OR p_binding_digest IS NULL OR q.subject_principal_id IS DISTINCT FROM p_subject OR q.execution_binding_digest IS DISTINCT FROM p_binding_digest OR q.valid_until<=((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz) THEN RAISE EXCEPTION 'DENIED_QUALIFICATION_BINDING'; END IF;
 SELECT * INTO STRICT h FROM company.governance_decision_heads WHERE tenant_id=x.tenant_id AND scope_kind='PROJECT' AND scope_ref=x.project_id AND decision_kind='QUALIFICATION' AND operation='qualification.activate' AND logical_target_digest=encode(sha256(convert_to(q.id::text,'UTF8')),'hex');
 IF h.decision_state<>'APPROVED' THEN RAISE EXCEPTION 'DENIED_QUALIFICATION_CURRENT_HEAD'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company.artifacts a JOIN company.principals p ON p.tenant_id=a.tenant_id AND p.id=(a.r54_human_decision->>'human_id')::uuid
 WHERE a.tenant_id=x.tenant_id AND a.project_id=h.decision_project_id AND a.task_id=h.decision_task_id AND a.attempt_id=h.decision_attempt_id AND a.id=h.decision_artifact_id AND a.state='AVAILABLE' AND p.kind='HUMAN'
 AND a.r54_human_decision->>'kind'='QUALIFICATION_ACTIVATE' AND a.r54_human_decision->>'qualification_id'=q.id::text AND a.r54_human_decision->>'binding_digest'=p_binding_digest
 AND (a.r54_human_decision->>'valid_until')::timestamptz>((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz)) THEN RAISE EXCEPTION 'DENIED_QUALIFICATION_HUMAN_PROVENANCE'; END IF;
 RETURN jsonb_build_object('qualification_id',q.id,'subject_principal_id',q.subject_principal_id,'execution_binding_digest',q.execution_binding_digest,'head_revision',h.revision,'eligible',true,'grant_created',false,'command_receipt',NULL);
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_qualification_decide(p_qualification uuid,p_expected_revision bigint,p_decision_task uuid,p_decision_attempt uuid,p_decision_artifact uuid,p_revoke boolean,p_key text,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;q company.agent_qualifications%ROWTYPE;a company.artifacts%ROWTYPE;h company.governance_decision_heads%ROWTYPE;c company.commands%ROWTYPE;
 v_op text;v_target text;v_digest text;v_cmd uuid;v_revision bigint;v_kind text;
BEGIN
 IF p_revoke IS NULL THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 v_op=CASE WHEN p_revoke THEN 'qualification.revoke' ELSE 'qualification.activate' END;
 v_kind=CASE WHEN p_revoke THEN 'QUALIFICATION_REVOKE' ELSE 'QUALIFICATION_ACTIVATE' END;
 x=company_private.r54_b_context(v_op,true);
 IF p_key IS NULL OR length(p_key) NOT BETWEEN 16 AND 128 OR p_expected_revision IS NULL OR p_expected_revision<0 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 SELECT * INTO STRICT q FROM company.agent_qualifications WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_qualification;
 IF q.execution_binding_digest IS NULL OR q.subject_principal_id IS NULL THEN RAISE EXCEPTION 'BLOCKED_LEGACY_QUALIFICATION'; END IF;
 SELECT * INTO STRICT a FROM company.artifacts WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_decision_task AND attempt_id=p_decision_attempt AND id=p_decision_artifact AND state='AVAILABLE';
 IF NOT ((a.r54_human_decision->>'kind'=v_kind AND a.r54_human_decision->>'human_id'=x.principal_id::text
 AND a.r54_human_decision->>'qualification_id'=q.id::text AND a.r54_human_decision->>'binding_digest'=q.execution_binding_digest
 AND (a.r54_human_decision->>'valid_until')::timestamptz>((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz)) IS TRUE)
 OR NOT EXISTS(SELECT 1 FROM company.commands z WHERE z.tenant_id=x.tenant_id AND z.id=(a.r54_human_decision->>'command_id')::uuid AND z.principal_id=x.principal_id AND z.operation='qualification.human_decision' AND z.state='SUCCEEDED' AND z.result_ref=a.id)
 THEN RAISE EXCEPTION 'BLOCKED_EXACT_HUMAN_DECISION'; END IF;
 IF NOT p_revoke AND (q.valid_until<=((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz) OR NOT EXISTS(SELECT 1 FROM company.evaluation_runs e JOIN company.evidence ev ON ev.tenant_id=e.tenant_id AND ev.project_id=e.project_id AND ev.task_id=e.evaluation_task_id AND ev.attempt_id=e.evaluation_attempt_id AND ev.id=e.sealed_evidence_id JOIN company.verification_runs vr ON vr.tenant_id=ev.tenant_id AND vr.project_id=ev.project_id AND vr.task_id=ev.task_id AND vr.attempt_id=ev.attempt_id AND vr.id=ev.verification_run_id
 WHERE e.tenant_id=q.tenant_id AND e.project_id=q.project_id AND e.id=q.evaluation_run_id AND e.execution_binding_digest=q.execution_binding_digest AND e.state='REVIEWED' AND vr.result='PASS' AND vr.exit_code=0 AND vr.producer_id<>vr.verifier_id)) THEN RAISE EXCEPTION 'BLOCKED_INDEPENDENT_EVALUATION'; END IF;
 v_target=encode(sha256(convert_to(q.id::text,'UTF8')),'hex');
 v_digest=encode(sha256(convert_to(jsonb_build_array(q.id,p_expected_revision,p_decision_task,p_decision_attempt,p_decision_artifact,p_revoke)::text,'UTF8')),'hex');
 -- Project authority lock is already held by protected context; serialize absent and present head.
 PERFORM 1 FROM company.projects WHERE tenant_id=x.tenant_id AND id=x.project_id FOR UPDATE;
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation=v_op AND idempotency_key=p_key;
 IF FOUND THEN
  IF c.payload_digest IS DISTINCT FROM v_digest THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  RETURN jsonb_build_object('command_id',c.id,'qualification_id',q.id,'outcome','REPLAY_NO_NEW_HEAD');
 END IF;
 SELECT * INTO h FROM company.governance_decision_heads WHERE tenant_id=x.tenant_id AND scope_kind='PROJECT' AND scope_ref=x.project_id AND decision_kind='QUALIFICATION' AND operation='qualification.activate' AND logical_target_digest=v_target FOR UPDATE;
 IF COALESCE(h.revision,0)<>p_expected_revision OR (p_revoke AND h.revision IS NULL) THEN RAISE EXCEPTION 'STALE_QUALIFICATION_HEAD'; END IF;
 v_revision=p_expected_revision+1;v_cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref) VALUES(x.tenant_id,v_cmd,x.principal_id,v_op,p_key,v_digest,p_correlation,'RUNNING',NULL);
 INSERT INTO company.governance_decision_heads(tenant_id,scope_kind,scope_ref,target_project_id,decision_kind,operation,logical_target_digest,revision,decision_state,decision_project_id,decision_task_id,decision_attempt_id,decision_artifact_id,command_id,decision_digest)
 VALUES(x.tenant_id,'PROJECT',x.project_id,x.project_id,'QUALIFICATION','qualification.activate',v_target,v_revision,CASE WHEN p_revoke THEN 'REVOKED' ELSE 'APPROVED' END,x.project_id,p_decision_task,p_decision_attempt,p_decision_artifact,v_cmd,a.sha256)
 ON CONFLICT(tenant_id,scope_kind,scope_ref,decision_kind,operation,logical_target_digest) DO UPDATE SET revision=EXCLUDED.revision,decision_state=EXCLUDED.decision_state,decision_project_id=EXCLUDED.decision_project_id,decision_task_id=EXCLUDED.decision_task_id,decision_attempt_id=EXCLUDED.decision_attempt_id,decision_artifact_id=EXCLUDED.decision_artifact_id,command_id=EXCLUDED.command_id,decision_digest=EXCLUDED.decision_digest WHERE company.governance_decision_heads.revision=p_expected_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_QUALIFICATION_HEAD'; END IF;
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(x.tenant_id,p_correlation,x.principal_id,v_kind);
 PERFORM company_private.r54_emit_event(x.tenant_id,x.project_id,q.id,v_revision,v_kind,jsonb_build_object('qualification_id',q.id,'head_revision',v_revision,'command_id',v_cmd));
 UPDATE company.commands SET state='SUCCEEDED',result_ref=q.id WHERE tenant_id=x.tenant_id AND id=v_cmd;
 PERFORM company_private.r54_b_context(v_op,true);
 RETURN jsonb_build_object('qualification_id',q.id,'command_id',v_cmd,'head_revision',v_revision,'outcome',CASE WHEN p_revoke THEN 'REVOKED' ELSE 'ACTIVATED_NO_GRANT' END);
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_evaluation_verification_seal(p_evaluation uuid,p_binding jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;e company.evaluation_runs%ROWTYPE;v company.verification_runs%ROWTYPE;ev company.evidence%ROWTYPE;a company.artifacts%ROWTYPE;d text; r company.verifier_receipts%ROWTYPE; env company.internal_receipt_envelopes%ROWTYPE; rep jsonb;
BEGIN
 x=company_private.r54_b_context('e0.evaluation_verification_seal',false);
 PERFORM company_private.r54_schema_check(p_binding,'{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"schema_version":{"const":"r53.execution-binding.v1"},"subject_principal_id":{"type":"string","format":"uuid"},"role_definition":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"agent_profile":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"model":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"engine":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"tools":{"type":"array","items":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"minItems":1,"uniqueItems":true},"suite":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"policy":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"resource_scope":{"type":"object","properties":{"tenant_id":{"type":"string","format":"uuid"},"project_id":{"type":"string","format":"uuid"},"workspace_id":{"type":"string","format":"uuid"}},"required":["tenant_id","project_id","workspace_id"],"additionalProperties":false},"independent_evidence":{"type":"object","properties":{"task_id":{"type":"string","format":"uuid"},"attempt_id":{"type":"string","format":"uuid"},"evidence_id":{"type":"string","format":"uuid"},"verification_run_id":{"type":"string","format":"uuid"},"producer_id":{"type":"string","format":"uuid"},"verifier_id":{"type":"string","format":"uuid"},"artifact_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["task_id","attempt_id","evidence_id","verification_run_id","producer_id","verifier_id","artifact_sha256"],"additionalProperties":false},"source_revision":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["schema_version","subject_principal_id","role_definition","agent_profile","model","engine","tools","suite","policy","resource_scope","independent_evidence","source_revision"],"additionalProperties":false}'::jsonb);
 SELECT * INTO STRICT e FROM company.evaluation_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_evaluation FOR UPDATE;
 IF p_binding IS NULL OR jsonb_typeof(p_binding)<>'object' OR NOT(p_binding ?& ARRAY['schema_version','subject_principal_id','role_definition','agent_profile','model','engine','tools','suite','policy','resource_scope','independent_evidence','source_revision']) THEN RAISE EXCEPTION 'INVALID_SEALED_BINDING'; END IF;
 IF NOT((p_binding->>'schema_version'='r53.execution-binding.v1' AND p_binding->>'subject_principal_id'=e.subject_principal_id::text AND p_binding#>>'{role_definition,identity}'=e.role_id AND p_binding#>>'{model,sha256}'=e.model_digest AND p_binding#>>'{suite,sha256}'=e.fixture_digest AND p_binding#>>'{resource_scope,tenant_id}'=x.tenant_id::text AND p_binding#>>'{resource_scope,project_id}'=x.project_id::text AND p_binding#>>'{resource_scope,workspace_id}'=(SELECT br.e0_mandate->>'workspace_id' FROM company_private.bootstrap_receipts br WHERE br.installation_id=e.e0_installation_id) AND p_binding#>>'{agent_profile,sha256}'=(SELECT br.e0_mandate->>'profile_digest' FROM company_private.bootstrap_receipts br WHERE br.installation_id=e.e0_installation_id)) IS TRUE) THEN RAISE EXCEPTION 'INVALID_SEALED_BINDING'; END IF;
 SELECT * INTO STRICT ev FROM company.evidence WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=e.evaluation_task_id AND attempt_id=e.evaluation_attempt_id AND id=(p_binding#>>'{independent_evidence,evidence_id}')::uuid;
 SELECT * INTO STRICT v FROM company.verification_runs WHERE tenant_id=ev.tenant_id AND project_id=ev.project_id AND task_id=ev.task_id AND attempt_id=ev.attempt_id AND id=ev.verification_run_id;
 SELECT * INTO STRICT a FROM company.artifacts WHERE tenant_id=ev.tenant_id AND project_id=ev.project_id AND task_id=ev.task_id AND attempt_id=ev.attempt_id AND id=ev.artifact_id;
 IF NOT((v.result='PASS' AND v.exit_code=0 AND v.producer_id<>v.verifier_id AND v.verifier_id=x.principal_id AND v.producer_id=e.subject_principal_id
 AND a.state='AVAILABLE' AND a.sha256=p_binding#>>'{independent_evidence,artifact_sha256}'
 AND v.id::text=p_binding#>>'{independent_evidence,verification_run_id}' AND v.producer_id::text=p_binding#>>'{independent_evidence,producer_id}' AND v.verifier_id::text=p_binding#>>'{independent_evidence,verifier_id}'
 AND ev.task_id::text=p_binding#>>'{independent_evidence,task_id}' AND ev.attempt_id::text=p_binding#>>'{independent_evidence,attempt_id}') IS TRUE) THEN RAISE EXCEPTION 'DENIED_INDEPENDENT_EVIDENCE'; END IF;
 rep=a.r54_evaluation_report;
 PERFORM company_private.r54_schema_check(rep,'{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"profile":{"const":"r54.evaluation-report.pg-jsonb.v1"},"receipt_id":{"type":"string","format":"uuid"},"subject_principal_id":{"type":"string","format":"uuid"},"model_digest":{"type":"string","pattern":"^[a-f0-9]{64}$"},"fixture_digest":{"type":"string","pattern":"^[a-f0-9]{64}$"},"negative_suite_digest":{"type":"string","pattern":"^[a-f0-9]{64}$"},"positive_cases":{"type":"array","minItems":1,"items":{"type":"object","properties":{"oracle_id":{"type":"string","minLength":1},"result":{"const":"PASS"},"observed_digest":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["oracle_id","result","observed_digest"],"additionalProperties":false}},"negative_cases":{"type":"array","minItems":1,"items":{"type":"object","properties":{"oracle_id":{"type":"string","minLength":1},"result":{"const":"PASS"},"observed_digest":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["oracle_id","result","observed_digest"],"additionalProperties":false}}},"required":["profile","receipt_id","subject_principal_id","model_digest","fixture_digest","negative_suite_digest","positive_cases","negative_cases"],"additionalProperties":false}'::jsonb);
 IF NOT((jsonb_typeof(rep)='object' AND rep->>'profile'='r54.evaluation-report.pg-jsonb.v1'
 AND rep->>'model_digest'=e.model_digest AND rep->>'fixture_digest'=e.fixture_digest
 AND rep->>'subject_principal_id'=e.subject_principal_id::text
 AND rep->>'negative_suite_digest'=(SELECT b.e0_mandate->>'negative_suite_digest' FROM company_private.bootstrap_receipts b WHERE b.installation_id=e.e0_installation_id)
 AND jsonb_typeof(rep->'positive_cases')='array' AND jsonb_array_length(rep->'positive_cases')>0
 AND jsonb_typeof(rep->'negative_cases')='array' AND jsonb_array_length(rep->'negative_cases')>0
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements((rep->'positive_cases')||(rep->'negative_cases')) c WHERE NOT((jsonb_typeof(c)='object' AND c->>'oracle_id'<>'' AND c->>'result'='PASS' AND c->>'observed_digest' ~ '^[a-f0-9]{64}$') IS TRUE))
 AND (SELECT jsonb_agg(z->>'oracle_id' ORDER BY z->>'oracle_id') FROM jsonb_array_elements(rep->'positive_cases') z)=(SELECT jsonb_agg(z ORDER BY z) FROM company_private.bootstrap_receipts br,jsonb_array_elements(br.e0_mandate->'required_positive_oracle_ids') z WHERE br.installation_id=e.e0_installation_id)
 AND (SELECT jsonb_agg(z->>'oracle_id' ORDER BY z->>'oracle_id') FROM jsonb_array_elements(rep->'negative_cases') z)=(SELECT jsonb_agg(z ORDER BY z) FROM company_private.bootstrap_receipts br,jsonb_array_elements(br.e0_mandate->'required_negative_oracle_ids') z WHERE br.installation_id=e.e0_installation_id)
 AND (SELECT count(*)=count(DISTINCT z->>'oracle_id') FROM jsonb_array_elements((rep->'positive_cases')||(rep->'negative_cases')) z)
 AND encode(sha256(convert_to(rep::text,'UTF8')),'hex')=a.sha256) IS TRUE) THEN RAISE EXCEPTION 'DENIED_EVALUATION_SUITE_REPORT'; END IF;
 SELECT * INTO STRICT r FROM company.verifier_receipts WHERE tenant_id=e.tenant_id AND project_id=e.project_id AND task_id=e.evaluation_task_id AND attempt_id=e.evaluation_attempt_id AND id=(rep->>'receipt_id')::uuid AND purpose='EVALUATION' AND signer_id=v.verifier_id;
 SELECT * INTO STRICT env FROM company.internal_receipt_envelopes WHERE tenant_id=r.tenant_id AND receipt_id=r.id AND purpose='EVALUATION' AND issuer_id=r.signer_id AND key_id=r.key_id;
 d=encode(sha256(convert_to(p_binding::text,'UTF8')),'hex');
 IF env.expected_binding_digest IS DISTINCT FROM d OR env.canonical_artifact_digest IS DISTINCT FROM a.sha256 OR env.profile_id<>'r54.evaluation-report.pg-jsonb.v1'
 OR env.auth_tag IS DISTINCT FROM r.signature OR env.envelope_digest IS DISTINCT FROM r.receipt_digest
 OR NOT EXISTS(SELECT 1 FROM company.signer_enrollments en JOIN company.principals hp ON hp.tenant_id=en.tenant_id AND hp.id=en.approved_by AND hp.kind='HUMAN'
 WHERE en.tenant_id=env.tenant_id AND en.issuer_id=env.issuer_id AND en.key_id=env.key_id AND en.purpose='EVALUATION' AND en.profile_id=env.profile_id AND en.enrollment_revision=env.enrollment_revision
 AND en.valid_from<=env.verified_at AND en.valid_until>((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz) AND company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,en.valid_from,en.valid_until) IS TRUE AND en.revoked_at IS NULL AND en.compromised_since IS NULL AND en.secret_ref<>'' AND en.key_fingerprint ~ '^[a-f0-9]{64}$') THEN RAISE EXCEPTION 'DENIED_EVALUATION_SIGNER_PROVENANCE'; END IF;
 IF e.execution_binding_digest IS NOT NULL THEN
  IF e.execution_binding_digest IS DISTINCT FROM d THEN RAISE EXCEPTION 'CONFLICT_IMMUTABLE_EVALUATION_SEAL'; END IF;
  RETURN jsonb_build_object('evaluation_run_id',e.id,'outcome','REPLAY_SEAL_NO_QUALIFICATION');
 END IF;
 IF e.state NOT IN ('AUTHORIZED','RUNNING','MEASURED') THEN RAISE EXCEPTION 'CONFLICT_EVALUATION_STATE'; END IF;
 UPDATE company.evaluation_runs SET execution_binding=p_binding,execution_binding_digest=d,sealed_evidence_id=ev.id,sealed_verification_id=v.id,sealed_artifact_id=a.id,state='REVIEWED' WHERE tenant_id=e.tenant_id AND project_id=e.project_id AND id=e.id AND execution_binding_digest IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'CONFLICT_IMMUTABLE_EVALUATION_SEAL'; END IF;
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) SELECT x.tenant_id,c.correlation_id,x.principal_id,'E0EvaluationSealed' FROM company.commands c WHERE c.tenant_id=e.tenant_id AND c.id=e.authorization_id;
 PERFORM company_private.r54_emit_event(x.tenant_id,x.project_id,e.id,1,'E0EvaluationSealed',jsonb_build_object('evaluation_run_id',e.id,'binding_digest',d,'evidence_id',ev.id,'qualification_created',false));
 PERFORM company_private.r54_b_context(x.operation_id,false);
 RETURN jsonb_build_object('evaluation_run_id',e.id,'binding_digest',d,'outcome','SEALED_NOT_QUALIFIED');
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_qualification_candidate_issue(p_evaluation uuid,p_valid_until timestamptz,p_key text,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;e company.evaluation_runs%ROWTYPE;c company.commands%ROWTYPE;v uuid;cmd uuid;d text;
BEGIN
 x=company_private.r54_b_context('e0.qualification_candidate_issue',true);
 SELECT * INTO STRICT e FROM company.evaluation_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_evaluation FOR UPDATE;
 IF e.state<>'REVIEWED' OR e.execution_binding IS NULL OR e.execution_binding_digest IS NULL OR e.sealed_evidence_id IS NULL OR p_valid_until IS NULL OR p_valid_until<=((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz) THEN RAISE EXCEPTION 'BLOCKED_REVIEWED_EVALUATION'; END IF;
 IF p_key IS NULL OR length(p_key) NOT BETWEEN 16 AND 128 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company_private.bootstrap_receipts b WHERE b.installation_id=e.e0_installation_id AND b.e0_valid_until>=p_valid_until AND b.accepted_human_id=x.principal_id) THEN RAISE EXCEPTION 'BLOCKED_QUALIFICATION_VALIDITY_CEILING'; END IF;
 d=encode(sha256(convert_to(jsonb_build_array(e.id,e.execution_binding_digest,p_valid_until)::text,'UTF8')),'hex');
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation=x.operation_id AND idempotency_key=p_key;
 IF FOUND THEN
  IF c.payload_digest IS DISTINCT FROM d THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  RETURN jsonb_build_object('qualification_id',c.result_ref,'command_id',c.id,'outcome','REPLAY_NO_ACTIVATION');
 END IF;
 v=gen_random_uuid();cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref) VALUES(x.tenant_id,cmd,x.principal_id,x.operation_id,p_key,d,p_correlation,'RUNNING',NULL);
 INSERT INTO company.agent_qualifications(tenant_id,project_id,id,evaluation_run_id,role_id,version_binding,approved_by,valid_until,subject_principal_id,execution_binding_digest,evaluation_task_id,evaluation_attempt_id,evaluation_evidence_id)
 VALUES(x.tenant_id,x.project_id,v,e.id,e.role_id,e.execution_binding,x.principal_id,p_valid_until,e.subject_principal_id,e.execution_binding_digest,e.evaluation_task_id,e.evaluation_attempt_id,e.sealed_evidence_id);
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(x.tenant_id,p_correlation,x.principal_id,'QualificationCandidateIssued');
 PERFORM company_private.r54_emit_event(x.tenant_id,x.project_id,v,0,'QualificationCandidateIssued',jsonb_build_object('qualification_id',v,'command_id',cmd,'active',false));
 UPDATE company.commands SET state='SUCCEEDED',result_ref=v WHERE tenant_id=x.tenant_id AND id=cmd;
 PERFORM company_private.r54_b_context(x.operation_id,true);
 RETURN jsonb_build_object('qualification_id',v,'command_id',cmd,'outcome','CANDIDATE_NOT_ACTIVE','grant_created',false);
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_e0_evaluation_artifact_record(p_evaluation uuid,p_report jsonb,p_key text,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;e company.evaluation_runs%ROWTYPE; c company.commands%ROWTYPE; a uuid; cmd uuid;d text;n bigint;
BEGIN
 x=company_private.r54_b_context('e0.evaluation_artifact_record',false);
 PERFORM company_private.r54_schema_check(p_report,'{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"profile":{"const":"r54.evaluation-report.pg-jsonb.v1"},"receipt_id":{"type":"string","format":"uuid"},"subject_principal_id":{"type":"string","format":"uuid"},"model_digest":{"type":"string","pattern":"^[a-f0-9]{64}$"},"fixture_digest":{"type":"string","pattern":"^[a-f0-9]{64}$"},"negative_suite_digest":{"type":"string","pattern":"^[a-f0-9]{64}$"},"positive_cases":{"type":"array","minItems":1,"items":{"type":"object","properties":{"oracle_id":{"type":"string","minLength":1},"result":{"const":"PASS"},"observed_digest":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["oracle_id","result","observed_digest"],"additionalProperties":false}},"negative_cases":{"type":"array","minItems":1,"items":{"type":"object","properties":{"oracle_id":{"type":"string","minLength":1},"result":{"const":"PASS"},"observed_digest":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["oracle_id","result","observed_digest"],"additionalProperties":false}}},"required":["profile","receipt_id","subject_principal_id","model_digest","fixture_digest","negative_suite_digest","positive_cases","negative_cases"],"additionalProperties":false}'::jsonb);
 SELECT * INTO STRICT e FROM company.evaluation_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_evaluation FOR UPDATE;
 IF e.subject_principal_id IS DISTINCT FROM x.principal_id OR e.state NOT IN ('AUTHORIZED','RUNNING','MEASURED') OR NOT EXISTS(SELECT 1 FROM company.attempts at JOIN company.tasks t ON t.tenant_id=at.tenant_id AND t.project_id=at.project_id AND t.id=at.task_id WHERE at.tenant_id=e.tenant_id AND at.project_id=e.project_id AND at.task_id=e.evaluation_task_id AND at.id=e.evaluation_attempt_id AND at.worker_id=x.principal_id AND at.lease_expires_at>((company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'utc_upper_bound')::timestamptz) AND at.ended_at IS NULL AND t.execution_kind='EVALUATION' AND t.active_attempt_id=at.id AND t.fencing_epoch=at.fencing_epoch) THEN RAISE EXCEPTION 'DENIED_EVALUATION_ATTEMPT'; END IF;
 IF p_report IS NULL OR jsonb_typeof(p_report)<>'object' OR p_report->>'profile' IS DISTINCT FROM 'r54.evaluation-report.pg-jsonb.v1' OR p_key IS NULL OR length(p_key) NOT BETWEEN 16 AND 128 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 n=octet_length(convert_to(p_report::text,'UTF8'));IF n>65536 THEN RAISE EXCEPTION 'EVALUATION_REPORT_TOO_LARGE'; END IF;
 d=encode(sha256(convert_to(p_report::text,'UTF8')),'hex');
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation=x.operation_id AND idempotency_key=p_key;
 IF FOUND THEN IF c.payload_digest IS DISTINCT FROM d THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;RETURN jsonb_build_object('artifact_id',c.result_ref,'command_id',c.id,'outcome','REPLAY_STORED_REPORT');END IF;
 a=gen_random_uuid();cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref) VALUES(x.tenant_id,cmd,x.principal_id,x.operation_id,p_key,d,p_correlation,'RUNNING',NULL);
 -- JSONB is the persisted payload; this bounded report is not an external blob-store availability assertion.
 INSERT INTO company.artifacts(tenant_id,project_id,task_id,attempt_id,id,storage_key,sha256,size_bytes,state,r54_evaluation_report) VALUES(x.tenant_id,x.project_id,e.evaluation_task_id,e.evaluation_attempt_id,a,gen_random_uuid(),d,n,'AVAILABLE',p_report);
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(x.tenant_id,p_correlation,x.principal_id,'E0ReportRecorded');
 PERFORM company_private.r54_emit_event(x.tenant_id,x.project_id,a,0,'E0ReportRecorded',jsonb_build_object('artifact_id',a,'sha256',d,'command_id',cmd));
 UPDATE company.commands SET state='SUCCEEDED',result_ref=a WHERE tenant_id=x.tenant_id AND id=cmd;
 PERFORM company_private.r54_b_context(x.operation_id,false);
 RETURN jsonb_build_object('artifact_id',a,'sha256',d,'command_id',cmd,'outcome','REPORT_RECORDED_NOT_VERIFIED');
END $$;


-- SOURCE sql/019_R55_POST_LOCK_RETURN_CUT_PATCH.sql
CREATE OR REPLACE FUNCTION company_private.r53_objectives_create(p_request jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; v_project uuid; v_correlation uuid;
 v_key text; v_digest text; v_id uuid; v_command uuid; v_revision bigint; element jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND operation_id='objectives.create';
 IF p_request IS NULL OR jsonb_typeof(p_request)<>'object' OR NOT (p_request ?& ARRAY['idempotency_key','correlation_id','project_id','goal','constraints','expected_outputs'])
 OR (SELECT count(*) FROM jsonb_object_keys(p_request))<>6 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 IF jsonb_typeof(p_request->'idempotency_key')<>'string' OR jsonb_typeof(p_request->'correlation_id')<>'string' OR jsonb_typeof(p_request->'project_id')<>'string'
 OR jsonb_typeof(p_request->'goal')<>'string' OR jsonb_typeof(p_request->'constraints')<>'array' OR jsonb_typeof(p_request->'expected_outputs')<>'array' THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 v_project=(p_request->>'project_id')::uuid; v_correlation=(p_request->>'correlation_id')::uuid; v_key=p_request->>'idempotency_key';
 IF v_project IS DISTINCT FROM x.project_id OR x.resource_kind<>'PROJECT' OR NOT company_private.r54_allowed(x.tenant_id,v_project,'objectives.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_CURRENT_AUTHORITY'; END IF;
 IF length(v_key) NOT BETWEEN 16 AND 128 OR v_key !~ '^[A-Za-z0-9_.:-]+$' OR length(p_request->>'goal') NOT BETWEEN 10 AND 4000
 OR jsonb_array_length(p_request->'constraints') NOT BETWEEN 1 AND 20 OR jsonb_array_length(p_request->'expected_outputs') NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 FOR element IN SELECT value FROM jsonb_array_elements((p_request->'constraints')||(p_request->'expected_outputs')) LOOP
  IF jsonb_typeof(element)<>'string' OR length(element#>>'{}') NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 END LOOP;
 -- Server-owned profile PG_JSONB_TEXT_UTF8_R53; JCS veya caller digest iddiası yok.
 -- correlation_id semantik payload dışıdır: replay ilk correlation id'yi döndürür.
 v_digest=encode(sha256(convert_to((p_request-'correlation_id'-'idempotency_key')::text,'UTF8')),'hex');
 -- Project authority advisory lock context enter'da alınmıştır; row lock bundan sonra.
 SELECT revision INTO STRICT v_revision FROM company.projects WHERE tenant_id=x.tenant_id AND id=v_project FOR UPDATE;
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation='objectives.create' AND idempotency_key=v_key;
 IF FOUND THEN
  IF c.payload_digest<>v_digest THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  IF company_private.r54_allowed(x.tenant_id,x.project_id,
 (SELECT permission FROM company_private.operation_permissions WHERE operation_id=x.operation_id),
 x.task_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'DENIED_POST_LOCK_RETURN_CUT'; END IF;
 RETURN jsonb_build_object('command_id',c.id,'correlation_id',c.correlation_id,'state',c.state,'result_ref',c.result_ref);
 END IF;
 v_id=gen_random_uuid(); v_command=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,v_command,x.principal_id,'objectives.create',v_key,v_digest,v_correlation,'RUNNING',NULL);
 INSERT INTO company.objectives(tenant_id,project_id,id,goal,constraints,expected_outputs,created_by)
 VALUES(x.tenant_id,v_project,v_id,p_request->>'goal',p_request->'constraints',p_request->'expected_outputs',x.principal_id);
 UPDATE company.projects SET revision=revision+1 WHERE tenant_id=x.tenant_id AND id=v_project AND revision=v_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_PROJECT'; END IF;
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(x.tenant_id,v_correlation,x.principal_id,'ObjectiveCreated');
 PERFORM company_private.r54_emit_event(x.tenant_id,v_project,v_id,v_revision+1,'ObjectiveCreated',jsonb_build_object('objective_id',v_id,'command_id',v_command,'project_revision',v_revision+1));
 UPDATE company.commands SET state='SUCCEEDED',result_ref=v_id WHERE tenant_id=x.tenant_id AND id=v_command;
 IF NOT company_private.r54_allowed(x.tenant_id,v_project,'objectives.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_COMMIT_CUT'; END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,
 (SELECT permission FROM company_private.operation_permissions WHERE operation_id=x.operation_id),
 x.task_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'DENIED_POST_LOCK_RETURN_CUT'; END IF;
 RETURN jsonb_build_object('command_id',v_command,'correlation_id',v_correlation,'state','SUCCEEDED','result_ref',v_id);
EXCEPTION WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST';
WHEN INVALID_TEXT_REPRESENTATION THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING';
END $$;

CREATE OR REPLACE FUNCTION company_private.r53_revoke_project_grant(p_request jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; g company.project_grants%ROWTYPE; c company.commands%ROWTYPE;
 q jsonb; ids uuid[]; scope_body jsonb; scope_digest text; payload_digest text; cid uuid; correlation uuid; target uuid; expected bigint; k text;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND operation_id='CAP-017.revoke';
 IF NOT company_private.r53_revoke_scope(x.tenant_id,x.project_id) OR NOT company_private.r54_allowed(x.tenant_id,x.project_id,'cap-017.revoke',NULL,true) THEN RAISE EXCEPTION 'DENIED_CURRENT_HUMAN_REVOKER'; END IF;
 IF p_request IS NULL OR jsonb_typeof(p_request)<>'object' OR NOT(p_request ?& ARRAY['schema_version','operation','correlation_id','tenant_id','project_id','resource_id','payload','expected_revision','idempotency_key']) OR (SELECT count(*) FROM jsonb_object_keys(p_request))<>9 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 IF p_request->>'schema_version' IS DISTINCT FROM 'PK04-r1' OR p_request->>'operation' IS DISTINCT FROM 'CAP-017.revoke' OR jsonb_typeof(p_request->'payload')<>'object' THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 q=p_request->'payload';
 IF NOT(q ?& ARRAY['grant_id','grant_revision','reason_code','revocation_scope_digest']) OR (SELECT count(*) FROM jsonb_object_keys(q))<>4 OR q->>'reason_code' NOT IN ('OWNER_REQUEST','POLICY_CHANGED','INCIDENT') OR q->>'revocation_scope_digest' !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 IF jsonb_typeof(p_request->'schema_version') IS DISTINCT FROM 'string' OR jsonb_typeof(p_request->'operation') IS DISTINCT FROM 'string' OR jsonb_typeof(p_request->'correlation_id') IS DISTINCT FROM 'string' OR jsonb_typeof(p_request->'tenant_id') IS DISTINCT FROM 'string' OR jsonb_typeof(p_request->'project_id') IS DISTINCT FROM 'string' OR jsonb_typeof(p_request->'resource_id') IS DISTINCT FROM 'string' OR jsonb_typeof(p_request->'expected_revision') IS DISTINCT FROM 'number' OR jsonb_typeof(p_request->'idempotency_key') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 IF jsonb_typeof(q->'grant_id') IS DISTINCT FROM 'string' OR jsonb_typeof(q->'grant_revision') IS DISTINCT FROM 'number' OR jsonb_typeof(q->'reason_code') IS DISTINCT FROM 'string' OR jsonb_typeof(q->'revocation_scope_digest') IS DISTINCT FROM 'string' OR q->>'grant_revision' !~ '^[0-9]+$' OR p_request->>'expected_revision' !~ '^[0-9]+$' THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 target=(q->>'grant_id')::uuid; expected=(q->>'grant_revision')::bigint; correlation=(p_request->>'correlation_id')::uuid; k=p_request->>'idempotency_key';
 IF (p_request->>'tenant_id')::uuid IS DISTINCT FROM x.tenant_id OR (p_request->>'project_id')::uuid IS DISTINCT FROM x.project_id OR (p_request->>'resource_id')::uuid IS DISTINCT FROM target OR (p_request->>'expected_revision')::bigint IS DISTINCT FROM expected THEN RAISE EXCEPTION 'INVALID_SCOPE_OR_REVISION'; END IF;
 IF expected<0 OR expected>9007199254740991 OR length(k) NOT BETWEEN 16 AND 128 OR k !~ '^[A-Za-z0-9_.:-]+$' THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 payload_digest=encode(sha256(convert_to((p_request-'correlation_id'-'idempotency_key')::text,'UTF8')),'hex');
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation='CAP-017.revoke' AND idempotency_key=k;
 IF FOUND THEN
  IF c.payload_digest<>payload_digest THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  IF company_private.r54_allowed(x.tenant_id,x.project_id,
 (SELECT permission FROM company_private.operation_permissions WHERE operation_id=x.operation_id),
 x.task_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'DENIED_POST_LOCK_RETURN_CUT'; END IF;
 RETURN jsonb_build_object('operation','CAP-017.revoke','status','RECORDED','resource_id',target,'revision',expected+1,'command_receipt_ref',c.id,'result',jsonb_build_object('revocation_receipt_ref',c.id));
 END IF;
 SELECT * INTO STRICT g FROM company.project_grants WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND grant_id=target FOR UPDATE;
 IF g.revision<>expected OR g.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'STALE_GRANT'; END IF;
 WITH RECURSIVE descendants AS (
 SELECT grant_id FROM company.project_grants WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND grant_id=target
 UNION SELECT ch.grant_id FROM company.project_grants ch JOIN descendants p ON ch.parent_grant_id=p.grant_id WHERE ch.tenant_id=x.tenant_id AND ch.project_id=x.project_id
 ) SELECT array_agg(pg.grant_id ORDER BY pg.grant_id),jsonb_agg(jsonb_build_object('grant_id',pg.grant_id,'revision',pg.revision,'task_scope_id',pg.task_scope_id,'permission',pg.permission,'parent_grant_id',pg.parent_grant_id) ORDER BY pg.grant_id)
 INTO ids,scope_body FROM descendants d JOIN company.project_grants pg ON pg.tenant_id=x.tenant_id AND pg.project_id=x.project_id AND pg.grant_id=d.grant_id;
 scope_digest=encode(sha256(convert_to(scope_body::text,'UTF8')),'hex');
 IF scope_digest IS DISTINCT FROM q->>'revocation_scope_digest' THEN RAISE EXCEPTION 'STALE_REVOCATION_SCOPE'; END IF;
 -- Ancestor currentness r53_grant_chain'de her kullanımda zorunlu; descendant kayıtları silinmez.
 UPDATE company.project_grants SET revoked_at=clock_timestamp(),revision=revision+1 WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND grant_id=target AND revision=expected AND revoked_at IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_GRANT'; END IF;
 cid=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref) VALUES(x.tenant_id,cid,x.principal_id,'CAP-017.revoke',k,payload_digest,correlation,'SUCCEEDED',target);
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(x.tenant_id,correlation,x.principal_id,'GrantRevoked');
 PERFORM company_private.r54_emit_event(x.tenant_id,x.project_id,target,expected+1,'GrantRevoked',jsonb_build_object('grant_id',target,'descendant_ids',ids,'command_id',cid,'scope_digest',scope_digest));
 -- Son authority write: eski context bu noktadan sonra geçersiz; self-revoke meşrudur.
 UPDATE company.authority_scope_heads SET epoch=epoch+1 WHERE tenant_id=x.tenant_id AND scope_kind='PROJECT' AND scope_ref=x.project_id AND epoch=x.project_epoch;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_AUTHORITY_EPOCH'; END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,
 (SELECT permission FROM company_private.operation_permissions WHERE operation_id=x.operation_id),
 x.task_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'DENIED_POST_LOCK_RETURN_CUT'; END IF;
 RETURN jsonb_build_object('operation','CAP-017.revoke','status','RECORDED','resource_id',target,'revision',expected+1,'command_receipt_ref',cid,'result',jsonb_build_object('revocation_receipt_ref',cid));
EXCEPTION WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING';
 WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST';
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_plans_create(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; pid uuid; parent_id uuid; rid uuid; cid uuid; correlation uuid; k text; d text; rev bigint; dep uuid;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND operation_id='plans.create';
 IF q IS NULL OR jsonb_typeof(q)<>'object' OR NOT(q ?& ARRAY['idempotency_key','correlation_id','project_id','objective_id','expected_revision','assumptions','acceptance_criteria']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(q) key WHERE key<>ALL(ARRAY['idempotency_key','correlation_id','project_id','objective_id','expected_revision','assumptions','acceptance_criteria'])) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 pid=(q->>'project_id')::uuid; parent_id=(q->>'objective_id')::uuid; correlation=(q->>'correlation_id')::uuid; k=q->>'idempotency_key';
 IF pid IS DISTINCT FROM x.project_id OR x.task_id IS NOT NULL OR k IS NULL OR k !~ '^[A-Za-z0-9_.:-]{16,128}$' OR NOT company_private.r54_allowed(x.tenant_id,pid,'plans.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_CURRENT_AUTHORITY'; END IF;
 IF jsonb_typeof(q->'acceptance_criteria') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF jsonb_array_length(q->'acceptance_criteria') NOT BETWEEN 1 AND 20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'acceptance_criteria') e WHERE jsonb_typeof(e)<>'string' OR length(e#>>'{}') NOT BETWEEN 1 AND 2000) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 d=encode(sha256(convert_to((q-'correlation_id'-'idempotency_key')::text,'UTF8')),'hex');
 SELECT revision INTO STRICT rev FROM company.projects WHERE tenant_id=x.tenant_id AND id=pid FOR UPDATE;
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation='plans.create' AND idempotency_key=k;
 IF FOUND THEN
  IF c.payload_digest<>d THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  IF company_private.r54_allowed(x.tenant_id,x.project_id,
 (SELECT permission FROM company_private.operation_permissions WHERE operation_id=x.operation_id),
 x.task_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'DENIED_POST_LOCK_RETURN_CUT'; END IF;
 RETURN jsonb_build_object('command_id',c.id,'correlation_id',c.correlation_id,'state',c.state,'result_ref',c.result_ref);
 END IF;
 PERFORM 1 FROM company.objectives WHERE tenant_id=x.tenant_id AND project_id=pid AND id=parent_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PARENT_NOT_FOUND_OR_DENIED'; END IF;
 IF jsonb_typeof(q->'expected_revision') IS DISTINCT FROM 'number' OR (q->>'expected_revision') !~ '^[0-9]+$' OR (q->>'expected_revision')::bigint<>rev THEN RAISE EXCEPTION 'STALE_PROJECT_REVISION'; END IF;
 IF jsonb_typeof(q->'assumptions') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF jsonb_array_length(q->'assumptions')>20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'assumptions') e WHERE jsonb_typeof(e)<>'string' OR length(e#>>'{}') NOT BETWEEN 1 AND 2000) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 rid=gen_random_uuid(); cid=gen_random_uuid();
 INSERT INTO company.plans(tenant_id,project_id,id,objective_id,revision,assumptions,acceptance_criteria) VALUES(x.tenant_id,pid,rid,parent_id,0,q->'assumptions',q->'acceptance_criteria');
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref) VALUES(x.tenant_id,cid,x.principal_id,'plans.create',k,d,correlation,'SUCCEEDED',rid);
 UPDATE company.projects SET revision=revision+1 WHERE tenant_id=x.tenant_id AND id=pid AND revision=rev;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_PROJECT_REVISION'; END IF;
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(x.tenant_id,correlation,x.principal_id,'PlanCreated');
 PERFORM company_private.r54_emit_event(x.tenant_id,pid,rid,0,'PlanCreated',jsonb_build_object('resource_id',rid,'command_id',cid,'project_revision',rev+1));
 IF NOT company_private.r54_allowed(x.tenant_id,pid,'plans.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_COMMIT_CUT'; END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,
 (SELECT permission FROM company_private.operation_permissions WHERE operation_id=x.operation_id),
 x.task_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'DENIED_POST_LOCK_RETURN_CUT'; END IF;
 RETURN jsonb_build_object('command_id',cid,'correlation_id',correlation,'state','SUCCEEDED','result_ref',rid);
EXCEPTION WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING';
 WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST';
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_tasks_create(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; pid uuid; parent_id uuid; rid uuid; cid uuid; correlation uuid; k text; d text; rev bigint; dep uuid;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND operation_id='tasks.create';
 IF q IS NULL OR jsonb_typeof(q)<>'object' OR NOT(q ?& ARRAY['idempotency_key','correlation_id','project_id','plan_id','title','role_id','acceptance_criteria']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(q) key WHERE key<>ALL(ARRAY['idempotency_key','correlation_id','project_id','plan_id','title','role_id','acceptance_criteria','depends_on'])) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 pid=(q->>'project_id')::uuid; parent_id=(q->>'plan_id')::uuid; correlation=(q->>'correlation_id')::uuid; k=q->>'idempotency_key';
 IF pid IS DISTINCT FROM x.project_id OR x.task_id IS NOT NULL OR k IS NULL OR k !~ '^[A-Za-z0-9_.:-]{16,128}$' OR NOT company_private.r54_allowed(x.tenant_id,pid,'tasks.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_CURRENT_AUTHORITY'; END IF;
 IF jsonb_typeof(q->'acceptance_criteria') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF jsonb_array_length(q->'acceptance_criteria') NOT BETWEEN 1 AND 20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'acceptance_criteria') e WHERE jsonb_typeof(e)<>'string' OR length(e#>>'{}') NOT BETWEEN 1 AND 2000) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 d=encode(sha256(convert_to((q-'correlation_id'-'idempotency_key')::text,'UTF8')),'hex');
 SELECT revision INTO STRICT rev FROM company.projects WHERE tenant_id=x.tenant_id AND id=pid FOR UPDATE;
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation='tasks.create' AND idempotency_key=k;
 IF FOUND THEN
  IF c.payload_digest<>d THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  IF company_private.r54_allowed(x.tenant_id,x.project_id,
 (SELECT permission FROM company_private.operation_permissions WHERE operation_id=x.operation_id),
 x.task_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'DENIED_POST_LOCK_RETURN_CUT'; END IF;
 RETURN jsonb_build_object('command_id',c.id,'correlation_id',c.correlation_id,'state',c.state,'result_ref',c.result_ref);
 END IF;
 PERFORM 1 FROM company.plans WHERE tenant_id=x.tenant_id AND project_id=pid AND id=parent_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PARENT_NOT_FOUND_OR_DENIED'; END IF;
 IF jsonb_typeof(q->'title') IS DISTINCT FROM 'string' OR length(q->>'title') NOT BETWEEN 3 AND 200 OR jsonb_typeof(q->'role_id') IS DISTINCT FROM 'string' OR (q->>'role_id') !~ '^(MGR|EXP)-[0-9]{2,3}$' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF q ? 'depends_on' THEN
  IF jsonb_typeof(q->'depends_on') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
  IF jsonb_array_length(q->'depends_on')>32 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'depends_on') e WHERE jsonb_typeof(e)<>'string') OR (SELECT count(*)<>count(DISTINCT value) FROM jsonb_array_elements_text(q->'depends_on')) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 END IF;
 rid=gen_random_uuid(); cid=gen_random_uuid();
 INSERT INTO company.tasks(tenant_id,project_id,id,plan_id,title,role_id,state,revision,fencing_epoch,acceptance_criteria) VALUES(x.tenant_id,pid,rid,parent_id,q->>'title',q->>'role_id','DRAFT',0,0,q->'acceptance_criteria');
 -- Existing dependency rows cannot point to a not-yet-created rid; only outgoing edges added => no cycle introduced.
 FOR dep IN SELECT value::uuid FROM jsonb_array_elements_text(COALESCE(q->'depends_on','[]'::jsonb)) ORDER BY value LOOP
  PERFORM 1 FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=pid AND id=dep;
  IF NOT FOUND THEN RAISE EXCEPTION 'DEPENDENCY_NOT_FOUND_OR_DENIED'; END IF;
  INSERT INTO company.task_dependencies(tenant_id,project_id,task_id,depends_on_task_id) VALUES(x.tenant_id,pid,rid,dep);
 END LOOP;
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref) VALUES(x.tenant_id,cid,x.principal_id,'tasks.create',k,d,correlation,'SUCCEEDED',rid);
 UPDATE company.projects SET revision=revision+1 WHERE tenant_id=x.tenant_id AND id=pid AND revision=rev;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_PROJECT_REVISION'; END IF;
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(x.tenant_id,correlation,x.principal_id,'TaskCreated');
 PERFORM company_private.r54_emit_event(x.tenant_id,pid,rid,0,'TaskCreated',jsonb_build_object('resource_id',rid,'command_id',cid,'project_revision',rev+1));
 IF NOT company_private.r54_allowed(x.tenant_id,pid,'tasks.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_COMMIT_CUT'; END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,
 (SELECT permission FROM company_private.operation_permissions WHERE operation_id=x.operation_id),
 x.task_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'DENIED_POST_LOCK_RETURN_CUT'; END IF;
 RETURN jsonb_build_object('command_id',cid,'correlation_id',correlation,'state','SUCCEEDED','result_ref',rid);
EXCEPTION WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING';
 WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST';
END $$;


-- SOURCE sql/020_R55_RECEIPT_EVENT_NATIVE_CANDIDATES.sql
-- Overlay after r54 assembly. Existing canonical commands/audit_events/outbox;
-- no second ledger, dispatcher, or fabricated cryptographic receipt.
CREATE ROLE company_atomic_functions_r55 NOLOGIN NOSUPERUSER NOBYPASSRLS NOINHERIT;
GRANT USAGE ON SCHEMA company,company_private TO company_atomic_functions_r55;
ALTER TABLE company.commands ADD COLUMN r55_project_id uuid;
ALTER TABLE company.commands ADD COLUMN r55_result_payload jsonb;
ALTER TABLE company.commands ADD COLUMN r55_result_digest text;
ALTER TABLE company.commands ADD COLUMN r55_event_sequence bigint;
ALTER TABLE company.commands ADD COLUMN r55_audit_id bigint;
ALTER TABLE company.commands ADD COLUMN r55_source_revision text;
ALTER TABLE company.commands ADD CONSTRAINT r55_command_project_fk FOREIGN KEY(tenant_id,r55_project_id) REFERENCES company.projects(tenant_id,id);
ALTER TABLE company.commands ADD CONSTRAINT r55_command_finality_shape CHECK((
 (r55_project_id IS NULL AND r55_result_payload IS NULL AND r55_result_digest IS NULL AND r55_event_sequence IS NULL AND r55_audit_id IS NULL AND r55_source_revision IS NULL)
 OR (state='SUCCEEDED' AND r55_project_id IS NOT NULL AND r55_result_payload IS NOT NULL AND jsonb_typeof(r55_result_payload)='object'
 AND r55_result_digest IS NOT NULL AND r55_result_digest ~ '^[a-f0-9]{64}$' AND r55_event_sequence>0
 AND r55_event_sequence IS NOT NULL AND r55_audit_id IS NOT NULL AND r55_audit_id>0 AND r55_source_revision IS NOT NULL AND r55_source_revision='r55-cp1')) IS TRUE);
GRANT SELECT,UPDATE(r55_project_id,r55_result_payload,r55_result_digest,r55_event_sequence,r55_audit_id,r55_source_revision) ON company.commands TO company_atomic_functions_r55;
GRANT SELECT,INSERT ON company.outbox TO company_atomic_functions_r55;
GRANT SELECT,UPDATE ON company.project_event_heads TO company_atomic_functions_r55;
GRANT SELECT,INSERT ON company.audit_events TO company_atomic_functions_r55;
GRANT SELECT ON company_private.request_contexts,company_private.operation_permissions TO company_atomic_functions_r55;
GRANT USAGE ON SEQUENCE company.outbox_event_id_seq,company.audit_events_id_seq TO company_atomic_functions_r55;
GRANT EXECUTE ON FUNCTION company_private.r54_allowed(uuid,uuid,text,uuid,boolean) TO company_atomic_functions_r55;
CREATE POLICY r55_atomic_context ON company_private.request_contexts FOR SELECT TO company_atomic_functions_r55
 USING(backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54);
CREATE POLICY r55_atomic_registry ON company_private.operation_permissions FOR SELECT TO company_atomic_functions_r55 USING(true);
CREATE POLICY r55_atomic_commands ON company.commands TO company_atomic_functions_r55
 USING(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=commands.tenant_id AND x.principal_id=commands.principal_id AND x.operation_id=commands.operation AND x.writer_generation=54))
 WITH CHECK(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=commands.tenant_id AND x.project_id=commands.r55_project_id AND x.principal_id=commands.principal_id AND x.operation_id=commands.operation AND x.writer_generation=54));
CREATE POLICY r55_atomic_outbox ON company.outbox TO company_atomic_functions_r55
 USING(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=outbox.tenant_id AND x.project_id=outbox.project_id AND x.writer_generation=54))
 WITH CHECK(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=outbox.tenant_id AND x.project_id=outbox.project_id AND x.writer_generation=54));
CREATE POLICY r55_atomic_head ON company.project_event_heads TO company_atomic_functions_r55
 USING(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=project_event_heads.tenant_id AND x.project_id=project_event_heads.project_id AND x.writer_generation=54))
 WITH CHECK(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=project_event_heads.tenant_id AND x.project_id=project_event_heads.project_id AND x.writer_generation=54));
CREATE POLICY r55_atomic_audit ON company.audit_events TO company_atomic_functions_r55
 USING(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=audit_events.tenant_id AND x.principal_id=audit_events.actor_id AND x.writer_generation=54))
 WITH CHECK(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=audit_events.tenant_id AND x.principal_id=audit_events.actor_id AND x.writer_generation=54));

CREATE FUNCTION company_private.r55_cp_event_kind(p_operation text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT CASE p_operation
 WHEN 'e0.process_admit' THEN 'E0ProcessAdmitted'
 WHEN 'e0.process_stop_confirm' THEN 'E0ProcessStopConfirmed'
 WHEN 'e0.process_release' THEN 'E0ProcessReleased'
 WHEN 'e0.process_reconcile' THEN 'E0ProcessReconciled'
 WHEN 'e0.evaluation_envelope_persist' THEN 'E0EnvelopePersisted'
 WHEN 'e0.process_proof_persist' THEN 'E0ProcessProofPersisted'
 WHEN 'plans.create' THEN 'PlanCreated'
 WHEN 'tasks.create' THEN 'TaskCreated'
 WHEN 'objectives.create' THEN 'ObjectiveCreated'
 END;
$$;
REVOKE ALL ON FUNCTION company_private.r55_cp_event_kind(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_event_kind(text) TO company_atomic_functions_r55,company_first_run_functions_r53;

CREATE FUNCTION company_private.r55_cp_emit_event(p_tenant uuid,p_project uuid,p_event uuid,p_aggregate uuid,p_revision bigint,p_kind text,p_payload jsonb)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; h company.project_event_heads%ROWTYPE; e company.outbox%ROWTYPE; d text; n bigint; perm text; expected_kind text;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 IF x.tenant_id IS DISTINCT FROM p_tenant OR x.project_id IS DISTINCT FROM p_project OR p_event IS NULL OR p_aggregate IS NULL OR p_revision IS NULL OR p_revision<0 OR p_payload IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'INVALID_EVENT_BINDING'; END IF;
 expected_kind=company_private.r55_cp_event_kind(x.operation_id);
 IF expected_kind IS NULL OR p_kind IS DISTINCT FROM expected_kind THEN RAISE EXCEPTION 'EVENT_PRODUCER_KIND_MISMATCH'; END IF;
 SELECT permission INTO STRICT perm FROM company_private.operation_permissions WHERE operation_id=x.operation_id AND execution_class NOT IN ('QUERY','STREAM');
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_EVENT_COMMIT'; END IF;
 SELECT * INTO STRICT h FROM company.project_event_heads WHERE tenant_id=p_tenant AND project_id=p_project FOR UPDATE;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_EVENT_AFTER_LOCK_WAIT'; END IF;
 IF h.writer_generation IS DISTINCT FROM 54 THEN RAISE EXCEPTION 'OLD_EVENT_WRITER_FENCED'; END IF;
 d=encode(sha256(convert_to(jsonb_build_array(p_aggregate,p_revision,p_kind,p_payload)::text,'UTF8')),'hex');
 SELECT * INTO e FROM company.outbox WHERE tenant_id=p_tenant AND project_id=p_project AND event_instance_id=p_event;
 IF FOUND THEN
  IF e.event_digest IS DISTINCT FROM d OR e.event_writer_generation IS DISTINCT FROM 54 OR e.project_sequence IS NULL OR e.project_sequence>h.committed_sequence THEN RAISE EXCEPTION 'CONFLICT_EVENT_DIGEST'; END IF;
  RETURN e.project_sequence;
 END IF;
 n=h.committed_sequence+1;
 INSERT INTO company.outbox(tenant_id,project_id,aggregate_id,aggregate_revision,kind,payload,project_sequence,event_writer_generation,event_instance_id,event_digest)
 VALUES(p_tenant,p_project,p_aggregate,p_revision,p_kind,p_payload,n,54,p_event,d);
 UPDATE company.project_event_heads SET committed_sequence=n WHERE tenant_id=p_tenant AND project_id=p_project AND committed_sequence=h.committed_sequence AND writer_generation=54;
 IF NOT FOUND THEN RAISE EXCEPTION 'CONFLICT_EVENT_HEAD'; END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_EVENT_RETURN_CUT'; END IF;
 RETURN n;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'EVENT_HEAD_OR_CONTEXT_NOT_MIGRATED';
END $$;
ALTER FUNCTION company_private.r55_cp_emit_event(uuid,uuid,uuid,uuid,bigint,text,jsonb) OWNER TO company_atomic_functions_r55;
REVOKE ALL ON FUNCTION company_private.r55_cp_emit_event(uuid,uuid,uuid,uuid,bigint,text,jsonb) FROM PUBLIC;
-- Only canonical domain owner may call. No transport/client direct EXECUTE.
GRANT EXECUTE ON FUNCTION company_private.r55_cp_emit_event(uuid,uuid,uuid,uuid,bigint,text,jsonb) TO company_first_run_functions_r53;

CREATE FUNCTION company_private.r55_cp_finalize_command(p_command uuid,p_aggregate uuid,p_revision bigint,p_event_kind text,p_result_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; d text; seq bigint; aid bigint; perm text; event_payload jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 IF p_command IS NULL OR p_aggregate IS NULL OR p_revision IS NULL OR p_revision<0 OR p_result_payload IS NULL OR jsonb_typeof(p_result_payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'INVALID_RESULT_BINDING'; END IF;
 IF p_event_kind IS DISTINCT FROM company_private.r55_cp_event_kind(x.operation_id) OR company_private.r55_cp_event_kind(x.operation_id) IS NULL THEN RAISE EXCEPTION 'UNREGISTERED_FINALIZER_OPERATION'; END IF;
 SELECT permission INTO STRICT perm FROM company_private.operation_permissions WHERE operation_id=x.operation_id AND execution_class NOT IN ('QUERY','STREAM');
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_FINALIZE_COMMAND'; END IF;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=x.tenant_id AND id=p_command AND principal_id=x.principal_id AND operation=x.operation_id FOR UPDATE;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_FINALIZE_AFTER_LOCK_WAIT'; END IF;
 IF c.state IS DISTINCT FROM 'SUCCEEDED' OR c.result_ref IS DISTINCT FROM p_aggregate OR c.payload_digest IS NULL OR c.correlation_id IS NULL THEN RAISE EXCEPTION 'COMMAND_NOT_CANONICAL_SUCCESS'; END IF;
 d=encode(sha256(convert_to(jsonb_build_array(c.id,c.payload_digest,c.result_ref,p_revision,p_event_kind,p_result_payload,'r55-cp1')::text,'UTF8')),'hex');
 IF c.r55_result_digest IS NOT NULL THEN
  IF c.r55_result_digest IS DISTINCT FROM d OR c.r55_project_id IS DISTINCT FROM x.project_id OR c.r55_event_sequence IS NULL OR c.r55_audit_id IS NULL THEN RAISE EXCEPTION 'CONFLICT_RESULT_DIGEST'; END IF;
  RETURN jsonb_build_object('command_id',c.id,'correlation_id',c.correlation_id,'state',c.state,'result_ref',c.result_ref);
 END IF;
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(x.tenant_id,c.correlation_id,x.principal_id,p_event_kind) RETURNING id INTO aid;
 event_payload=jsonb_build_object('command_id',c.id,'request_digest',c.payload_digest,'result_digest',d,'result_ref',c.result_ref,'source_revision','r55-cp1');
 seq=company_private.r55_cp_emit_event(x.tenant_id,x.project_id,c.id,p_aggregate,p_revision,p_event_kind,event_payload);
 UPDATE company.commands SET r55_project_id=x.project_id,r55_result_payload=p_result_payload,r55_result_digest=d,r55_event_sequence=seq,r55_audit_id=aid,r55_source_revision='r55-cp1' WHERE tenant_id=c.tenant_id AND id=c.id AND r55_result_digest IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'CONFLICT_RESULT_FINALIZATION'; END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_COMMAND_COMMIT_CUT'; END IF;
 RETURN jsonb_build_object('command_id',c.id,'correlation_id',c.correlation_id,'state',c.state,'result_ref',c.result_ref);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'COMMAND_OR_CONTEXT_UNRESOLVED';
END $$;
ALTER FUNCTION company_private.r55_cp_finalize_command(uuid,uuid,bigint,text,jsonb) OWNER TO company_atomic_functions_r55;
REVOKE ALL ON FUNCTION company_private.r55_cp_finalize_command(uuid,uuid,bigint,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_finalize_command(uuid,uuid,bigint,text,jsonb) TO company_first_run_functions_r53;

CREATE FUNCTION company_private.r55_cp_result_immutable() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF OLD.r55_result_digest IS NOT NULL THEN RAISE EXCEPTION 'IMMUTABLE_CANONICAL_COMMAND_RESULT'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION company_private.r55_cp_result_immutable() FROM PUBLIC;
CREATE TRIGGER r55_cp_result_immutable BEFORE UPDATE OR DELETE ON company.commands FOR EACH ROW EXECUTE FUNCTION company_private.r55_cp_result_immutable();

CREATE FUNCTION company_private.r55_cp_require_finalized_command() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c company.commands%ROWTYPE;
BEGIN
 IF company_private.r55_cp_event_kind(NEW.operation) IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=NEW.tenant_id AND id=NEW.id;
 IF c.state IS DISTINCT FROM 'SUCCEEDED' OR c.r55_result_digest IS NULL OR c.r55_event_sequence IS NULL OR c.r55_audit_id IS NULL
 OR NOT EXISTS(SELECT 1 FROM company.audit_events a WHERE a.tenant_id=c.tenant_id AND a.id=c.r55_audit_id AND a.actor_id=c.principal_id AND a.correlation_id=c.correlation_id AND a.kind=company_private.r55_cp_event_kind(c.operation))
 OR NOT EXISTS(SELECT 1 FROM company.outbox e WHERE e.tenant_id=c.tenant_id AND e.project_id=c.r55_project_id AND e.project_sequence=c.r55_event_sequence AND e.event_instance_id=c.id AND e.event_writer_generation=54 AND e.payload->>'result_digest'=c.r55_result_digest AND e.payload->>'request_digest'=c.payload_digest)
 THEN RAISE EXCEPTION 'MANDATORY_COMMAND_RECEIPT_AUDIT_EVENT_MISSING'; END IF;
 RETURN NULL;
END $$;
ALTER FUNCTION company_private.r55_cp_require_finalized_command() OWNER TO company_atomic_functions_r55;
REVOKE ALL ON FUNCTION company_private.r55_cp_require_finalized_command() FROM PUBLIC;
CREATE CONSTRAINT TRIGGER r55_cp_require_finalized_command AFTER INSERT OR UPDATE ON company.commands DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION company_private.r55_cp_require_finalized_command();
CREATE FUNCTION company_private.r55_cp_context_exit(p_nonce uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 -- Evaluate deferred result linkage while transaction-bound context still exists.
 -- Constraints remain IMMEDIATE; no protected write is allowed after this cut.
 SET CONSTRAINTS company.r55_cp_require_finalized_command IMMEDIATE;
 PERFORM company_private.r54_context_exit(p_nonce);
END $$;
ALTER FUNCTION company_private.r55_cp_context_exit(uuid) OWNER TO company_context_owner;
REVOKE ALL ON FUNCTION company_private.r55_cp_context_exit(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_context_exit(uuid) TO company_transport_r54;
-- HMAC envelope verification is NOT provided by these digests. E0-04 remains
-- blocked until enrolled-key verifier -> immutable envelope INSERT is accepted.

-- SOURCE sql/021_R55_E0_RESOURCE_PROCESS_NATIVE_CANDIDATES.sql
-- SOURCE CANDIDATE ONLY. r53 unified schema + r54 E0 delta precede this file.
-- No new canonical relation. Add proof metadata to the existing immutable artifact
-- owner; current process journal remains the sole local process/resource owner.
ALTER TABLE company.artifacts ADD COLUMN r55_e0_process_manifest jsonb;
ALTER TABLE company.artifacts ADD COLUMN r55_e0_process_observation jsonb;
ALTER TABLE company.process_runs ADD COLUMN r55_host_boot_id uuid;
