-- SOURCE sql/023_R55_PROCESS_PROOF_PERSISTENCE_CANDIDATE.sql
-- Assemble after B process schema + C evaluation receipt primitives.
-- Finite profile extension of the same Company Kernel envelope persistence.
INSERT INTO company_private.operation_permissions(operation_id,permission,scope_kind,execution_class,policy_revision,approved_policy_digest)
VALUES('e0.process_proof_persist','e0.process_proof_persist','PROJECT','COMMAND',0,NULL);
GRANT SELECT ON company_private.bootstrap_receipts,company.process_runs TO company_receipt_functions_r55;
GRANT UPDATE(revision) ON company.process_runs TO company_receipt_functions_r55;
GRANT INSERT ON company.artifacts TO company_receipt_functions_r55;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_e0_verified_artifact(uuid,uuid,uuid,uuid,uuid,uuid,text,uuid,text) TO company_receipt_functions_r55;
CREATE POLICY r55_receipt_bootstrap ON company_private.bootstrap_receipts FOR SELECT TO company_receipt_functions_r55 USING(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=bootstrap_receipts.tenant_id AND x.project_id=bootstrap_receipts.project_id AND x.writer_generation=54));
CREATE POLICY r55_receipt_process ON company.process_runs FOR SELECT TO company_receipt_functions_r55 USING(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=process_runs.tenant_id AND x.project_id=process_runs.project_id AND x.writer_generation=54));
CREATE POLICY r55_receipt_process_lock ON company.process_runs FOR UPDATE TO company_receipt_functions_r55 USING(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=process_runs.tenant_id AND x.project_id=process_runs.project_id AND x.writer_generation=54)) WITH CHECK(false);
CREATE POLICY r55_receipt_process_artifact_insert ON company.artifacts FOR INSERT TO company_receipt_functions_r55 WITH CHECK(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=artifacts.tenant_id AND x.project_id=artifacts.project_id AND x.operation_id='e0.process_proof_persist' AND x.writer_generation=54));
GRANT EXECUTE ON FUNCTION company_private.r55_cp_time_window_current(uuid,uuid,timestamptz,timestamptz) TO company_receipt_functions_r55;
CREATE FUNCTION company_private.r55_cp_persist_process_proof(p_artifact uuid,p_raw jsonb,p_envelope jsonb,p_key_material bytea,p_idempotency text,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; e company.evaluation_runs%ROWTYPE; pr company.process_runs%ROWTYPE; en company.signer_enrollments%ROWTYPE; b company_private.bootstrap_receipts%ROWTYPE; c company.commands%ROWTYPE;
 profile text; fields text[]; issuer uuid; task_id uuid; attempt_id uuid; rid uuid; cmd uuid; digest text; binding text; envelope_digest text; request_digest text; raw bytea; tag bytea; item text; n bigint; verified company.artifacts%ROWTYPE;
BEGIN
 IF NOT pg_has_role(session_user,'company_receipt_ingest_r55','MEMBER') THEN RAISE EXCEPTION 'TRUSTED_RECEIPT_INGEST_REQUIRED'; END IF;
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54 AND operation_id='e0.process_proof_persist';
 IF p_artifact IS NULL OR p_raw IS NULL OR jsonb_typeof(p_raw) IS DISTINCT FROM 'object' OR p_envelope IS NULL OR jsonb_typeof(p_envelope) IS DISTINCT FROM 'object'
 OR p_key_material IS NULL OR octet_length(p_key_material)<>32 OR p_idempotency IS NULL OR p_idempotency !~ '^[A-Za-z0-9_.:-]{16,128}$' OR p_correlation IS NULL THEN RAISE EXCEPTION 'INVALID_PROCESS_PROOF_INPUT'; END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'e0.process_proof_persist',x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_PROCESS_PROOF_AUTHORITY'; END IF;
 profile=p_raw->>'profile';
 IF profile IS NULL OR profile NOT IN ('r55.e0-process-admission.pg-jsonb.v1','r55.e0-process-observation.pg-jsonb.v1') THEN RAISE EXCEPTION 'PROCESS_PROOF_PROFILE_NOT_ALLOWED'; END IF;
 fields=ARRAY['tenant_id','issuer_id','key_id','purpose','profile_id','enrollment_revision','receipt_id','canonical_artifact_digest','expected_binding_digest','envelope_digest','auth_tag'];
 IF NOT(p_envelope ?& fields) OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_envelope) k WHERE k<>ALL(fields)) OR NOT((p_envelope->>'tenant_id'=x.tenant_id::text
 AND p_envelope->>'issuer_id'=x.principal_id::text AND p_envelope->>'purpose'='EVALUATION' AND p_envelope->>'profile_id'=profile
 AND jsonb_typeof(p_envelope->'enrollment_revision')='number' AND p_envelope->>'enrollment_revision' ~ '^[0-9]+$' AND p_envelope->>'auth_tag' ~ '^[A-Za-z0-9_-]{43}$') IS TRUE)
 THEN RAISE EXCEPTION 'PROCESS_PROOF_ENROLLMENT_BINDING_INVALID'; END IF;
 rid=(p_envelope->>'receipt_id')::uuid;
 PERFORM 1 FROM company.projects WHERE tenant_id=x.tenant_id AND id=x.project_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PROCESS_PROOF_PROJECT_UNRESOLVED'; END IF;
 IF profile='r55.e0-process-admission.pg-jsonb.v1' THEN
  SELECT * INTO STRICT e FROM company.evaluation_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=(p_raw->>'evaluation_run_id')::uuid FOR SHARE;
  SELECT * INTO STRICT b FROM company_private.bootstrap_receipts WHERE installation_id=e.e0_installation_id AND tenant_id=e.tenant_id AND project_id=e.project_id;
  issuer=b.accepted_human_id; task_id=e.evaluation_task_id; attempt_id=e.evaluation_attempt_id;
  binding=encode(sha256(convert_to(jsonb_build_array(x.tenant_id,x.project_id,e.id,e.evaluation_task_id,e.evaluation_attempt_id,p_artifact)::text,'UTF8')),'hex');
 ELSE
  SELECT * INTO STRICT pr FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=(p_raw->>'process_run_id')::uuid FOR SHARE;
  IF pr.e0_evaluation_run_id IS NULL OR pr.qualification_id IS NOT NULL THEN RAISE EXCEPTION 'E0_PROCESS_PROOF_ONLY'; END IF;
  issuer=pr.controller_id;task_id=pr.task_id;attempt_id=pr.attempt_id;
  binding=encode(sha256(convert_to(jsonb_build_array(pr.tenant_id,pr.project_id,pr.id,pr.task_id,pr.attempt_id,pr.attempt_fencing_epoch,pr.host_registration_id,pr.host_registration_revision,pr.host_generation,pr.r55_host_boot_id,pr.controller_id,pr.controller_generation,pr.manifest_digest)::text,'UTF8')),'hex');
 END IF;
 IF issuer IS NULL OR issuer IS DISTINCT FROM x.principal_id OR p_raw->>'tenant_id' IS DISTINCT FROM x.tenant_id::text OR p_raw->>'project_id' IS DISTINCT FROM x.project_id::text
 OR p_raw->>'task_id' IS DISTINCT FROM task_id::text OR p_raw->>'attempt_id' IS DISTINCT FROM attempt_id::text THEN RAISE EXCEPTION 'PROCESS_PROOF_ISSUER_OR_SCOPE_INVALID'; END IF;
 SELECT * INTO STRICT en FROM company.signer_enrollments WHERE tenant_id=x.tenant_id AND issuer_id=issuer AND key_id=(p_envelope->>'key_id')::uuid AND purpose='EVALUATION' AND profile_id=profile AND enrollment_revision=(p_envelope->>'enrollment_revision')::bigint FOR SHARE;
 IF en.revoked_at IS NOT NULL OR en.compromised_since IS NOT NULL OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,en.valid_from,en.valid_until) IS NOT TRUE OR en.key_fingerprint IS DISTINCT FROM encode(sha256(p_key_material),'hex')
 OR NOT EXISTS(SELECT 1 FROM company.principals hp WHERE hp.tenant_id=en.tenant_id AND hp.id=en.approved_by AND hp.kind='HUMAN') THEN RAISE EXCEPTION 'DENIED_PROCESS_PROOF_CURRENT_ENROLLMENT'; END IF;
 digest=encode(sha256(convert_to(p_raw::text,'UTF8')),'hex'); n=octet_length(convert_to(p_raw::text,'UTF8'));
 IF n>52428800 OR digest IS DISTINCT FROM p_envelope->>'canonical_artifact_digest' OR binding IS DISTINCT FROM p_envelope->>'expected_binding_digest' THEN RAISE EXCEPTION 'PROCESS_PROOF_DIGEST_BINDING_INVALID'; END IF;
 raw=convert_to('R54-EVALUATION-v1','UTF8')||decode('00','hex');
 FOREACH item IN ARRAY ARRAY[x.tenant_id::text,issuer::text,en.key_id::text,'EVALUATION',profile,en.enrollment_revision::text,rid::text,digest,binding] LOOP
  raw=raw||convert_to(octet_length(convert_to(item,'UTF8'))::text||':'||item,'UTF8');
 END LOOP;
 envelope_digest=encode(sha256(raw),'hex');tag=decode(translate(p_envelope->>'auth_tag','-_','+/')||'=','base64');
 IF envelope_digest IS DISTINCT FROM p_envelope->>'envelope_digest' OR company_private.r55_cp_tag_equal(company_private.r55_cp_hmac_sha256(p_key_material,raw),tag) IS DISTINCT FROM true THEN RAISE EXCEPTION 'INVALID_PROCESS_PROOF_HMAC'; END IF;
 request_digest=encode(sha256(convert_to(jsonb_build_array(p_artifact,p_raw,p_envelope)::text,'UTF8')),'hex');
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation=x.operation_id AND idempotency_key=p_idempotency;
 IF FOUND THEN
  IF c.payload_digest IS DISTINCT FROM request_digest OR c.r55_project_id IS DISTINCT FROM x.project_id OR c.r55_result_payload IS NULL THEN RAISE EXCEPTION 'CONFLICT_PROCESS_PROOF_IDEMPOTENCY'; END IF;
  RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,0,'E0ProcessProofPersisted',c.r55_result_payload);
 END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'e0.process_proof_persist',x.task_id,true) IS DISTINCT FROM true OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,en.valid_from,en.valid_until) IS NOT TRUE THEN RAISE EXCEPTION 'DENIED_PROCESS_PROOF_INSERT_CUT'; END IF;
 INSERT INTO company.artifacts(tenant_id,project_id,task_id,attempt_id,id,storage_key,sha256,size_bytes,state,r55_e0_process_manifest,r55_e0_process_observation)
 VALUES(x.tenant_id,x.project_id,task_id,attempt_id,p_artifact,gen_random_uuid(),digest,n,'AVAILABLE',CASE WHEN profile='r55.e0-process-admission.pg-jsonb.v1' THEN p_raw ELSE NULL END,CASE WHEN profile='r55.e0-process-observation.pg-jsonb.v1' THEN p_raw ELSE NULL END);
 INSERT INTO company.internal_receipt_envelopes(tenant_id,issuer_id,key_id,purpose,enrollment_revision,receipt_id,profile_id,envelope_digest,expected_binding_digest,canonical_artifact_digest,auth_tag,verified_at)
 VALUES(x.tenant_id,issuer,en.key_id,'EVALUATION',en.enrollment_revision,rid,profile,envelope_digest,binding,digest,p_envelope->>'auth_tag',clock_timestamp());
 verified=company_private.r55_cp_e0_verified_artifact(x.tenant_id,x.project_id,task_id,attempt_id,p_artifact,rid,profile,issuer,binding);
 cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,cmd,x.principal_id,x.operation_id,p_idempotency,request_digest,p_correlation,'SUCCEEDED',p_artifact);
 RETURN company_private.r55_cp_finalize_command(cmd,p_artifact,0,'E0ProcessProofPersisted',jsonb_build_object('artifact_id',p_artifact,'receipt_id',rid,'profile',profile,'sha256',digest));
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'PROCESS_PROOF_CANONICAL_SOURCE_UNRESOLVED';
 WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_PROCESS_PROOF_TYPED_BINDING';
 WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_PROCESS_PROOF_IDENTITY';
END $$;
ALTER FUNCTION company_private.r55_cp_persist_process_proof(uuid,jsonb,jsonb,bytea,text,uuid) OWNER TO company_receipt_functions_r55;
REVOKE ALL ON FUNCTION company_private.r55_cp_persist_process_proof(uuid,jsonb,jsonb,bytea,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_persist_process_proof(uuid,jsonb,jsonb,bytea,text,uuid) TO company_receipt_ingest_r55;
-- Actual narrow ingest login, SecretAdapter, signer custody and OS attestation
-- producer remain uninstalled/unapproved. No signed sample is fabricated here.

-- SOURCE sql/024_R55_READBACK_CONTEXT_GUARDED_CANDIDATE.sql
-- Read-only authority projection; no direct context/registry SELECT for transport.
CREATE FUNCTION company_private.r55_cp_read_authority(p_operation text,p_task uuid,p_nonce uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; op company_private.operation_permissions%ROWTYPE; allowed boolean;
BEGIN
 IF p_nonce IS NULL OR p_operation IS NULL OR p_operation NOT IN ('candidate.r54.attempts.read','candidate.r54.qualifications.read','candidate.r54.agent_runs.read','candidate.r54.tool_requests.read','candidate.r54.evidence.read','candidate.r54.acceptance_decisions.read') THEN RAISE EXCEPTION 'UNSUPPORTED_READ_AUTHORITY'; END IF;
 IF NOT pg_has_role(session_user,'company_transport_r54','MEMBER') THEN RAISE EXCEPTION 'TRANSPORT_REQUIRED'; END IF;
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND request_nonce=p_nonce AND operation_id=p_operation AND writer_generation=54;
 IF x.task_id IS DISTINCT FROM p_task THEN RAISE EXCEPTION 'READ_CONTEXT_TASK_MISMATCH'; END IF;
 SELECT * INTO STRICT op FROM company_private.operation_permissions WHERE operation_id=p_operation AND execution_class='QUERY' AND scope_kind='PROJECT';
 allowed=company_private.r54_allowed(x.tenant_id,x.project_id,op.permission,p_task,false);
 IF allowed IS DISTINCT FROM true THEN RAISE EXCEPTION 'NOT_FOUND_OR_DENIED'; END IF;
 RETURN jsonb_build_object('tenant_id',x.tenant_id,'project_id',x.project_id,'principal_id',x.principal_id,'session_id',x.session_id,
 'tenant_epoch',x.tenant_epoch,'project_epoch',x.project_epoch,'session_epoch',x.session_epoch,'policy_revision',x.policy_revision,
 'writer_generation',x.writer_generation,'allowed',true);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'NOT_FOUND_OR_DENIED';
END $$;
ALTER FUNCTION company_private.r55_cp_read_authority(text,uuid,uuid) OWNER TO company_context_owner;
REVOKE ALL ON FUNCTION company_private.r55_cp_read_authority(text,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_read_authority(text,uuid,uuid) TO company_transport_r54;

-- SOURCE sql/025_R55_PLAN_TASK_RESULT_FINALITY_OVERLAY.sql
CREATE OR REPLACE FUNCTION company_private.r54_plans_create(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; pid uuid; parent_id uuid; rid uuid; cid uuid; correlation uuid; k text; d text; rev bigint; dep uuid;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND operation_id='plans.create';
 IF q IS NULL OR jsonb_typeof(q)<>'object' OR NOT(q ?& ARRAY['idempotency_key','correlation_id','project_id','objective_id','expected_revision','assumptions','acceptance_criteria']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(q) key WHERE key<>ALL(ARRAY['idempotency_key','correlation_id','project_id','objective_id','expected_revision','assumptions','acceptance_criteria'])) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 pid=(q->>'project_id')::uuid; parent_id=(q->>'objective_id')::uuid; correlation=(q->>'correlation_id')::uuid; k=q->>'idempotency_key';
 IF pid IS DISTINCT FROM x.project_id OR x.task_id IS NOT NULL OR k IS NULL OR k !~ '^[A-Za-z0-9_.:-]{16,128}$' OR NOT company_private.r54_allowed(x.tenant_id,pid,'plans.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_CURRENT_AUTHORITY'; END IF;
 IF jsonb_typeof(q->'acceptance_criteria') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF jsonb_array_length(q->'acceptance_criteria') NOT BETWEEN 1 AND 20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'acceptance_criteria') e WHERE jsonb_typeof(e)<>'string' OR length(e#>>'{}') NOT BETWEEN 1 AND 2000) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 d=encode(sha256(convert_to((q-'correlation_id'-'idempotency_key')::text,'UTF8')),'hex');
 SELECT revision INTO STRICT rev FROM company.projects WHERE tenant_id=x.tenant_id AND id=pid FOR UPDATE;
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation='plans.create' AND idempotency_key=k;
 IF FOUND THEN
  IF c.payload_digest<>d THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  IF c.r55_result_payload IS NULL THEN RAISE EXCEPTION 'BLOCKED_LEGACY_UNFINALIZED_COMMAND'; END IF;
  RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,0,'PlanCreated',c.r55_result_payload);
 END IF;
 PERFORM 1 FROM company.objectives WHERE tenant_id=x.tenant_id AND project_id=pid AND id=parent_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PARENT_NOT_FOUND_OR_DENIED'; END IF;
 IF jsonb_typeof(q->'expected_revision') IS DISTINCT FROM 'number' OR (q->>'expected_revision') !~ '^[0-9]+$' OR (q->>'expected_revision')::bigint<>rev THEN RAISE EXCEPTION 'STALE_PROJECT_REVISION'; END IF;
 IF jsonb_typeof(q->'assumptions') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF jsonb_array_length(q->'assumptions')>20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'assumptions') e WHERE jsonb_typeof(e)<>'string' OR length(e#>>'{}') NOT BETWEEN 1 AND 2000) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 rid=gen_random_uuid(); cid=gen_random_uuid();
 INSERT INTO company.plans(tenant_id,project_id,id,objective_id,revision,assumptions,acceptance_criteria) VALUES(x.tenant_id,pid,rid,parent_id,0,q->'assumptions',q->'acceptance_criteria');
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref) VALUES(x.tenant_id,cid,x.principal_id,'plans.create',k,d,correlation,'SUCCEEDED',rid);
 UPDATE company.projects SET revision=revision+1 WHERE tenant_id=x.tenant_id AND id=pid AND revision=rev;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_PROJECT_REVISION'; END IF;
 PERFORM company_private.r55_cp_finalize_command(cid,rid,0,'PlanCreated',jsonb_build_object('resource_id',rid,'project_revision',rev+1));
 IF NOT company_private.r54_allowed(x.tenant_id,pid,'plans.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_COMMIT_CUT'; END IF;
 RETURN jsonb_build_object('command_id',cid,'correlation_id',correlation,'state','SUCCEEDED','result_ref',rid);
EXCEPTION WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING';
 WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST';
END $$;
CREATE OR REPLACE FUNCTION company_private.r54_tasks_create(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; pid uuid; parent_id uuid; rid uuid; cid uuid; correlation uuid; k text; d text; rev bigint; dep uuid;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND operation_id='tasks.create';
 IF q IS NULL OR jsonb_typeof(q)<>'object' OR NOT(q ?& ARRAY['idempotency_key','correlation_id','project_id','plan_id','title','role_id','acceptance_criteria']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(q) key WHERE key<>ALL(ARRAY['idempotency_key','correlation_id','project_id','plan_id','title','role_id','acceptance_criteria','depends_on'])) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 pid=(q->>'project_id')::uuid; parent_id=(q->>'plan_id')::uuid; correlation=(q->>'correlation_id')::uuid; k=q->>'idempotency_key';
 IF pid IS DISTINCT FROM x.project_id OR x.task_id IS NOT NULL OR k IS NULL OR k !~ '^[A-Za-z0-9_.:-]{16,128}$' OR NOT company_private.r54_allowed(x.tenant_id,pid,'tasks.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_CURRENT_AUTHORITY'; END IF;
 IF jsonb_typeof(q->'acceptance_criteria') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF jsonb_array_length(q->'acceptance_criteria') NOT BETWEEN 1 AND 20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'acceptance_criteria') e WHERE jsonb_typeof(e)<>'string' OR length(e#>>'{}') NOT BETWEEN 1 AND 2000) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 d=encode(sha256(convert_to((q-'correlation_id'-'idempotency_key')::text,'UTF8')),'hex');
 SELECT revision INTO STRICT rev FROM company.projects WHERE tenant_id=x.tenant_id AND id=pid FOR UPDATE;
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation='tasks.create' AND idempotency_key=k;
 IF FOUND THEN
  IF c.payload_digest<>d THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  IF c.r55_result_payload IS NULL THEN RAISE EXCEPTION 'BLOCKED_LEGACY_UNFINALIZED_COMMAND'; END IF;
  RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,0,'TaskCreated',c.r55_result_payload);
 END IF;
 PERFORM 1 FROM company.plans WHERE tenant_id=x.tenant_id AND project_id=pid AND id=parent_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PARENT_NOT_FOUND_OR_DENIED'; END IF;
 IF jsonb_typeof(q->'title') IS DISTINCT FROM 'string' OR length(q->>'title') NOT BETWEEN 3 AND 200 OR jsonb_typeof(q->'role_id') IS DISTINCT FROM 'string' OR (q->>'role_id') !~ '^(MGR|EXP)-[0-9]{2,3}$' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF q ? 'depends_on' THEN
  IF jsonb_typeof(q->'depends_on') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
  IF jsonb_array_length(q->'depends_on')>32 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'depends_on') e WHERE jsonb_typeof(e)<>'string') OR (SELECT count(*)<>count(DISTINCT value) FROM jsonb_array_elements_text(q->'depends_on')) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 END IF;
 rid=gen_random_uuid(); cid=gen_random_uuid();
 INSERT INTO company.tasks(tenant_id,project_id,id,plan_id,title,role_id,state,revision,fencing_epoch,acceptance_criteria) VALUES(x.tenant_id,pid,rid,parent_id,q->>'title',q->>'role_id','DRAFT',0,0,q->'acceptance_criteria');
 -- Existing dependency rows cannot point to a not-yet-created rid; only outgoing edges added => no cycle introduced.
 FOR dep IN SELECT value::uuid FROM jsonb_array_elements_text(COALESCE(q->'depends_on','[]'::jsonb)) ORDER BY value LOOP
  PERFORM 1 FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=pid AND id=dep;
  IF NOT FOUND THEN RAISE EXCEPTION 'DEPENDENCY_NOT_FOUND_OR_DENIED'; END IF;
  INSERT INTO company.task_dependencies(tenant_id,project_id,task_id,depends_on_task_id) VALUES(x.tenant_id,pid,rid,dep);
 END LOOP;
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref) VALUES(x.tenant_id,cid,x.principal_id,'tasks.create',k,d,correlation,'SUCCEEDED',rid);
 UPDATE company.projects SET revision=revision+1 WHERE tenant_id=x.tenant_id AND id=pid AND revision=rev;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_PROJECT_REVISION'; END IF;
 PERFORM company_private.r55_cp_finalize_command(cid,rid,0,'TaskCreated',jsonb_build_object('resource_id',rid,'project_revision',rev+1));
 IF NOT company_private.r54_allowed(x.tenant_id,pid,'tasks.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_COMMIT_CUT'; END IF;
 RETURN jsonb_build_object('command_id',cid,'correlation_id',correlation,'state','SUCCEEDED','result_ref',rid);
EXCEPTION WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING';
 WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST';
END $$;

-- SOURCE sql/026_R55_OBJECTIVE_RESULT_FINALITY_OVERLAY.sql
CREATE OR REPLACE FUNCTION company_private.r53_objectives_create(p_request jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; v_project uuid; v_correlation uuid;
 v_key text; v_digest text; v_id uuid; v_command uuid; v_revision bigint; element jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND operation_id='objectives.create';
 IF p_request IS NULL OR jsonb_typeof(p_request)<>'object' OR NOT (p_request ?& ARRAY['idempotency_key','correlation_id','project_id','goal','constraints','expected_outputs'])
 OR (SELECT count(*) FROM jsonb_object_keys(p_request))<>6 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 IF jsonb_typeof(p_request->'idempotency_key')<>'string' OR jsonb_typeof(p_request->'correlation_id')<>'string' OR jsonb_typeof(p_request->'project_id')<>'string'
 OR jsonb_typeof(p_request->'goal')<>'string' OR jsonb_typeof(p_request->'constraints')<>'array' OR jsonb_typeof(p_request->'expected_outputs')<>'array' THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 v_project=(p_request->>'project_id')::uuid; v_correlation=(p_request->>'correlation_id')::uuid; v_key=p_request->>'idempotency_key';
 IF v_project IS DISTINCT FROM x.project_id OR x.resource_kind<>'PROJECT' OR NOT company_private.r54_allowed(x.tenant_id,v_project,'objectives.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_CURRENT_AUTHORITY'; END IF;
 IF length(v_key) NOT BETWEEN 16 AND 128 OR v_key !~ '^[A-Za-z0-9_.:-]+$' OR length(p_request->>'goal') NOT BETWEEN 10 AND 4000
 OR jsonb_array_length(p_request->'constraints') NOT BETWEEN 1 AND 20 OR jsonb_array_length(p_request->'expected_outputs') NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 FOR element IN SELECT value FROM jsonb_array_elements((p_request->'constraints')||(p_request->'expected_outputs')) LOOP
  IF jsonb_typeof(element)<>'string' OR length(element#>>'{}') NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 END LOOP;
 -- Server-owned profile PG_JSONB_TEXT_UTF8_R53; JCS veya caller digest iddiası yok.
 -- correlation_id semantik payload dışıdır: replay ilk correlation id'yi döndürür.
 v_digest=encode(sha256(convert_to((p_request-'correlation_id'-'idempotency_key')::text,'UTF8')),'hex');
 -- Project authority advisory lock context enter'da alınmıştır; row lock bundan sonra.
 SELECT revision INTO STRICT v_revision FROM company.projects WHERE tenant_id=x.tenant_id AND id=v_project FOR UPDATE;
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation='objectives.create' AND idempotency_key=v_key;
 IF FOUND THEN
  IF c.payload_digest<>v_digest THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  IF c.r55_result_payload IS NULL OR c.r55_result_payload->>'project_revision' IS NULL THEN RAISE EXCEPTION 'BLOCKED_LEGACY_UNFINALIZED_COMMAND'; END IF;
  RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,(c.r55_result_payload->>'project_revision')::bigint,'ObjectiveCreated',c.r55_result_payload);
 END IF;
 v_id=gen_random_uuid(); v_command=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,v_command,x.principal_id,'objectives.create',v_key,v_digest,v_correlation,'RUNNING',NULL);
 INSERT INTO company.objectives(tenant_id,project_id,id,goal,constraints,expected_outputs,created_by)
 VALUES(x.tenant_id,v_project,v_id,p_request->>'goal',p_request->'constraints',p_request->'expected_outputs',x.principal_id);
 UPDATE company.projects SET revision=revision+1 WHERE tenant_id=x.tenant_id AND id=v_project AND revision=v_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_PROJECT'; END IF;
 UPDATE company.commands SET state='SUCCEEDED',result_ref=v_id WHERE tenant_id=x.tenant_id AND id=v_command;
 PERFORM company_private.r55_cp_finalize_command(v_command,v_id,v_revision+1,'ObjectiveCreated',jsonb_build_object('objective_id',v_id,'project_revision',v_revision+1));
 IF NOT company_private.r54_allowed(x.tenant_id,v_project,'objectives.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_COMMIT_CUT'; END IF;
 RETURN jsonb_build_object('command_id',v_command,'correlation_id',v_correlation,'state','SUCCEEDED','result_ref',v_id);
EXCEPTION WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST';
WHEN INVALID_TEXT_REPRESENTATION THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING';
END $$;

-- SOURCE sql/027_R56_BOOTSTRAP_NATIVE_CANDIDATE.sql
-- Inert r56 FIRST BOOTSTRAP source overlay; not an authorized migration.
DO $preflight$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname IN ('company','company_private') AND (coalesce(pg_get_expr(p.polqual,p.polrelid),'') LIKE '%app.tenant_id%'
 OR coalesce(pg_get_expr(p.polwithcheck,p.polrelid),'') LIKE '%app.tenant_id%'))
 THEN RAISE EXCEPTION 'LEGACY_GUC_POLICY_NOT_FENCED'; END IF;
END $preflight$;

CREATE ROLE company_bootstrap_functions_r56 NOLOGIN NOSUPERUSER NOBYPASSRLS NOINHERIT;
CREATE ROLE company_bootstrap_transport_r56 NOLOGIN NOSUPERUSER NOBYPASSRLS NOINHERIT;
GRANT USAGE ON SCHEMA company,company_private TO company_bootstrap_functions_r56;
GRANT USAGE ON SCHEMA company_private TO company_bootstrap_transport_r56;
-- No member/login/key/enrollment row is created. Physical enrollment is separate.
ALTER TABLE company_private.r55_setup_root_enrollments ADD COLUMN r56_anchor_boottime_ns numeric(20,0);
ALTER TABLE company_private.r55_setup_root_enrollments ADD COLUMN r56_anchor_utc_lower timestamptz;
ALTER TABLE company_private.r55_setup_root_enrollments ADD COLUMN r56_anchor_utc_upper timestamptz;
ALTER TABLE company_private.r55_setup_root_enrollments ADD COLUMN r56_issuer_class text;
ALTER TABLE company_private.r55_setup_root_enrollments ADD COLUMN r56_approved_manifest_digest text;
ALTER TABLE company_private.r55_setup_root_enrollments ADD COLUMN r56_approved_nonce_hash text;
ALTER TABLE company_private.r55_setup_root_enrollments ADD COLUMN r56_human_consent_evidence_digest text;
ALTER TABLE company_private.r55_setup_root_enrollments ADD CONSTRAINT r56_root_anchor_shape CHECK(
 (r56_anchor_boottime_ns IS NULL AND r56_anchor_utc_lower IS NULL AND r56_anchor_utc_upper IS NULL AND r56_issuer_class IS NULL)
 OR ((r56_anchor_boottime_ns>=0 AND r56_anchor_boottime_ns IS NOT NULL
 AND r56_anchor_utc_lower IS NOT NULL AND r56_anchor_utc_upper IS NOT NULL
 AND isfinite(r56_anchor_utc_lower) AND isfinite(r56_anchor_utc_upper)
 AND r56_anchor_utc_lower<=r56_anchor_utc_upper AND r56_issuer_class='PROVISIONING_SERVICE') IS TRUE));
ALTER TABLE company_private.bootstrap_request_contexts ADD COLUMN r56_manifest jsonb;
ALTER TABLE company_private.bootstrap_request_contexts ADD COLUMN r56_command_id uuid;
ALTER TABLE company_private.bootstrap_request_contexts ADD COLUMN r56_final_proof jsonb;
ALTER TABLE company_private.bootstrap_request_contexts ADD COLUMN r56_grants_digest text;
ALTER TABLE company_private.bootstrap_receipts ADD COLUMN r56_final_proof jsonb;
ALTER TABLE company_private.bootstrap_receipts ADD COLUMN r56_result_digest text;
ALTER TABLE company.commands DROP CONSTRAINT r55_command_finality_shape;
ALTER TABLE company.commands ADD CONSTRAINT r56_command_finality_shape CHECK(
 (r55_project_id IS NULL AND r55_result_payload IS NULL AND r55_result_digest IS NULL AND r55_event_sequence IS NULL AND r55_audit_id IS NULL AND r55_source_revision IS NULL)
 OR ((state='SUCCEEDED' AND r55_project_id IS NOT NULL AND jsonb_typeof(r55_result_payload)='object'
 AND r55_result_digest ~ '^[a-f0-9]{64}$' AND r55_event_sequence>0 AND r55_audit_id IS NOT NULL
 AND r55_source_revision IN ('r55-cp1','r56')) IS TRUE));

GRANT SELECT ON company_private.r55_setup_root_enrollments,company_private.installation_bootstrap_control,
 company_private.bootstrap_request_contexts,company_private.bootstrap_receipts,
 company_private.scope_lock_registry,company_private.operation_permissions TO company_bootstrap_functions_r56;
GRANT UPDATE(revoked_at) ON company_private.r55_setup_root_enrollments TO company_bootstrap_functions_r56;
GRANT INSERT,UPDATE,DELETE ON company_private.bootstrap_request_contexts TO company_bootstrap_functions_r56;
GRANT UPDATE(state,consumed_command_id) ON company_private.installation_bootstrap_control TO company_bootstrap_functions_r56;
GRANT INSERT ON company_private.bootstrap_receipts,company_private.scope_lock_registry TO company_bootstrap_functions_r56;
GRANT UPDATE(policy_revision) ON company_private.operation_permissions TO company_bootstrap_functions_r56;
GRANT SELECT,INSERT ON company.tenants,company.principals,company.memberships,company.workspaces,
 company.projects,company.objectives,company.plans,company.authority_scope_heads,company.project_grants,
 company.commands,company.audit_events,company.outbox,company.project_event_heads TO company_bootstrap_functions_r56;
GRANT UPDATE ON company.commands,company.project_event_heads TO company_bootstrap_functions_r56;
GRANT USAGE ON SEQUENCE company_private.scope_lock_registry_lock_id_seq,company.audit_events_id_seq,
 company.outbox_event_id_seq TO company_bootstrap_functions_r56;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_hmac_sha256(bytea,bytea),
 company_private.r55_cp_tag_equal(bytea,bytea),company_private.r55_cp_clock_observe_local()
 TO company_bootstrap_functions_r56;
CREATE POLICY r56_root_read ON company_private.r55_setup_root_enrollments FOR SELECT TO company_bootstrap_functions_r56 USING(true);
CREATE POLICY r56_root_lock ON company_private.r55_setup_root_enrollments FOR UPDATE TO company_bootstrap_functions_r56 USING(true) WITH CHECK(false);
CREATE POLICY r56_control_read ON company_private.installation_bootstrap_control FOR SELECT TO company_bootstrap_functions_r56 USING(true);
CREATE POLICY r56_control_update ON company_private.installation_bootstrap_control FOR UPDATE TO company_bootstrap_functions_r56 USING(true) WITH CHECK(state='CONSUMED');
CREATE POLICY r56_boot_context ON company_private.bootstrap_request_contexts TO company_bootstrap_functions_r56
 USING(backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user)
 WITH CHECK(backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user);
CREATE POLICY r56_receipt_read ON company_private.bootstrap_receipts FOR SELECT TO company_bootstrap_functions_r56 USING(true);
CREATE POLICY r56_locks ON company_private.scope_lock_registry TO company_bootstrap_functions_r56 USING(true) WITH CHECK(true);
CREATE POLICY r56_registry_read ON company_private.operation_permissions FOR SELECT TO company_bootstrap_functions_r56 USING(true);
CREATE POLICY r56_registry_lock ON company_private.operation_permissions FOR UPDATE TO company_bootstrap_functions_r56 USING(true) WITH CHECK(false);

CREATE FUNCTION company_private.r56_root_bounds(p_installation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE e company_private.r55_setup_root_enrollments%ROWTYPE;b company_private.installation_bootstrap_control%ROWTYPE;
 o jsonb;bt0 numeric;bt1 numeric;age numeric;drift numeric;lo timestamptz;hi timestamptz;wall timestamptz;
BEGIN
 SELECT * INTO STRICT b FROM company_private.installation_bootstrap_control WHERE installation_id=p_installation;
 SELECT * INTO STRICT e FROM company_private.r55_setup_root_enrollments WHERE installation_id=p_installation AND generation=b.generation FOR SHARE;
 IF e.revoked_at IS NOT NULL OR e.compromised_at IS NOT NULL OR e.r56_issuer_class IS DISTINCT FROM 'PROVISIONING_SERVICE'
 OR e.actual_human_id IS DISTINCT FROM e.custodian_id OR e.actual_human_id=e.issuer_id
 OR e.r56_approved_manifest_digest IS NULL OR e.r56_approved_manifest_digest IS DISTINCT FROM b.payload_digest
 OR e.r56_approved_nonce_hash IS NULL OR e.r56_approved_nonce_hash IS DISTINCT FROM b.nonce_hash
 OR e.r56_human_consent_evidence_digest IS NULL OR e.r56_human_consent_evidence_digest !~ '^[a-f0-9]{64}$'
 OR e.r56_anchor_boottime_ns IS NULL OR e.r56_anchor_utc_lower IS NULL OR e.r56_anchor_utc_upper IS NULL
 OR e.enrollment_digest IS DISTINCT FROM b.r55_root_enrollment_digest
 OR e.host_boot_id IS DISTINCT FROM b.r55_host_boot_id OR e.clock_policy_digest IS DISTINCT FROM b.r55_clock_policy_digest
 THEN RAISE EXCEPTION 'ROOT_ENROLLMENT_OR_SINGLE_HUMAN_BINDING_REQUIRED'; END IF;
 o=company_private.r55_cp_clock_observe_local();
 IF o->>'profile' IS DISTINCT FROM 'LINUX_ADJTIMEX_DB_LOCAL_V1' OR o->>'host_boot_id' IS DISTINCT FROM e.host_boot_id::text
 OR o->>'backend_pid' IS DISTINCT FROM pg_backend_pid()::text OR o->>'source_sync_state' IS DISTINCT FROM 'SYNC'
 OR NOT ((o ?& ARRAY['boottime_before_ns','boottime_after_ns','utc_ns','maxerror_us','esterror_us','tolerance_scaled_ppm']) IS TRUE)
 OR EXISTS(SELECT 1 FROM jsonb_each(o) z WHERE z.key=ANY(ARRAY['boottime_before_ns','boottime_after_ns','utc_ns','maxerror_us','esterror_us','tolerance_scaled_ppm'])
 AND (jsonb_typeof(z.value) IS DISTINCT FROM 'number' OR z.value::text !~ '^[0-9]+$'))
 THEN RAISE EXCEPTION 'ROOT_TRUSTED_LOCAL_OBSERVATION_REQUIRED'; END IF;
 bt0=(o->>'boottime_before_ns')::numeric;bt1=(o->>'boottime_after_ns')::numeric;
 IF bt0<e.r56_anchor_boottime_ns OR bt1<bt0 OR bt1>=e.not_after_boottime_ns
 OR bt1>=b.r55_not_after_boottime_ns THEN RAISE EXCEPTION 'ROOT_BOOTTIME_EXPIRED_OR_REBOOTED'; END IF;
 age=bt1-e.r56_anchor_boottime_ns;
 drift=ceil(age*(o->>'tolerance_scaled_ppm')::numeric/65536/1000000)
       +greatest((o->>'maxerror_us')::numeric,(o->>'esterror_us')::numeric)*1000;
 IF age>9007199254740991 OR drift>9007199254740991 THEN RAISE EXCEPTION 'ROOT_TIME_NUMERIC_PROFILE_RANGE'; END IF;
 lo=e.r56_anchor_utc_lower+((bt0-e.r56_anchor_boottime_ns-drift)/1000000000)::double precision*interval '1 second';
 hi=e.r56_anchor_utc_upper+((bt1-e.r56_anchor_boottime_ns+drift)/1000000000)::double precision*interval '1 second';
 -- Timestamp precision is microseconds. Expand, never round toward eligibility.
 lo=lo-interval '1 microsecond';hi=hi+interval '1 microsecond';
 wall=to_timestamp(((o->>'utc_ns')::numeric/1000000000)::double precision);
 IF NOT ((isfinite(lo) AND isfinite(hi) AND e.not_before<=lo AND lo<=hi AND hi<e.not_after
 AND hi<b.expires_at AND lo<=wall AND wall<=hi) IS TRUE) THEN RAISE EXCEPTION 'ROOT_TIME_EXPIRED_OR_AMBIGUOUS'; END IF;
 RETURN jsonb_build_object('utc_lower',lo,'utc_upper',hi,'boottime_ns',bt1,'host_boot_id',e.host_boot_id,
 'installation_id',b.installation_id,'generation',b.generation,'backend_pid',pg_backend_pid(),'transaction_id',pg_current_xact_id()::text,'db_login',session_user);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'ROOT_TRUST_ANCHOR_NOT_ENROLLED';
END $$;
ALTER FUNCTION company_private.r56_root_bounds(uuid) OWNER TO company_bootstrap_functions_r56;
REVOKE ALL ON FUNCTION company_private.r56_root_bounds(uuid) FROM PUBLIC;

CREATE FUNCTION company_private.r56_setup_scope(p_tenant uuid,p_project uuid,p_write boolean) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 RETURN EXISTS(SELECT 1 FROM company_private.bootstrap_request_contexts x
 JOIN company_private.installation_bootstrap_control b ON b.installation_id=x.installation_id AND b.generation=x.generation
 WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user
 AND b.expected_tenant_id=p_tenant AND (p_project IS NULL OR b.expected_project_id=p_project)
 AND ((p_write IS TRUE AND b.state='ARMED') OR (p_write IS FALSE AND
 (b.state='ARMED' OR (b.state='CONSUMED' AND b.consumed_command_id=x.r56_command_id))))
 AND x.r55_verified_proof_digest IS NOT NULL AND x.r56_manifest IS NOT NULL
 AND x.manifest_digest=b.payload_digest
 AND pg_has_role(session_user,'company_bootstrap_transport_r56','MEMBER'));
END $$;
ALTER FUNCTION company_private.r56_setup_scope(uuid,uuid,boolean) OWNER TO company_bootstrap_functions_r56;
REVOKE ALL ON FUNCTION company_private.r56_setup_scope(uuid,uuid,boolean) FROM PUBLIC;

-- The canonical r50 trigger treats added r55 fields as identity. Allow only the
-- one protected r56 RUNNING -> SUCCEEDED finalization; retain its old rule for
-- every ordinary operation and every later mutation.
CREATE OR REPLACE FUNCTION company.r50_command_identity_immutable() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF OLD.operation='trusted_setup.consume' AND OLD.state='RUNNING' AND OLD.r55_result_digest IS NULL
 AND NEW.state='SUCCEEDED' AND NEW.r55_source_revision='r56' THEN
  IF (to_jsonb(OLD)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
   IS DISTINCT FROM
   (to_jsonb(NEW)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
  OR NOT EXISTS(SELECT 1 FROM company_private.bootstrap_request_contexts x
   JOIN company_private.installation_bootstrap_control b ON b.installation_id=x.installation_id AND b.generation=x.generation
   WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user
   AND x.r56_command_id=OLD.id AND b.expected_tenant_id=OLD.tenant_id AND b.expected_human_id=OLD.principal_id
   AND b.expected_project_id=NEW.r55_project_id AND b.installation_id=NEW.result_ref
   AND b.state='ARMED' AND x.manifest_digest=OLD.payload_digest)
  THEN RAISE EXCEPTION 'IMMUTABLE_COMMAND_RECEIPT'; END IF;
 ELSE
  IF (to_jsonb(OLD)-'state'-'result_ref') IS DISTINCT FROM (to_jsonb(NEW)-'state'-'result_ref')
  OR (OLD.state IN ('SUCCEEDED','FAILED') AND ROW(OLD.state,OLD.result_ref) IS DISTINCT FROM ROW(NEW.state,NEW.result_ref))
  THEN RAISE EXCEPTION 'IMMUTABLE_COMMAND_RECEIPT'; END IF;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION company.r50_command_identity_immutable() FROM PUBLIC;

CREATE FUNCTION company_private.r56_bootstrap_enter(p_installation uuid,p_generation bigint,p_nonce bytea,p_raw bytea,p_tag bytea,p_key bytea)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE b company_private.installation_bootstrap_control%ROWTYPE;e company_private.r55_setup_root_enrollments%ROWTYPE;
 j jsonb;m jsonb;item bytea;raw bytea;n uuid;bounds jsonb;v bytea[];op text;reg company_private.operation_permissions%ROWTYPE;
BEGIN
 IF NOT pg_has_role(session_user,'company_bootstrap_transport_r56','MEMBER') THEN RAISE EXCEPTION 'TRUSTED_BOOTSTRAP_TRANSPORT_REQUIRED'; END IF;
 IF p_installation IS NULL OR p_generation IS NULL OR p_generation<1 OR p_nonce IS NULL OR octet_length(p_nonce)<>32
 OR p_raw IS NULL OR octet_length(p_raw) NOT BETWEEN 1 AND 65536 OR p_tag IS NULL OR octet_length(p_tag)<>32
 OR p_key IS NULL OR octet_length(p_key)<>32 THEN RAISE EXCEPTION 'INVALID_BOOTSTRAP_WIRE'; END IF;
 IF EXISTS(SELECT 1 FROM company_private.bootstrap_request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id())
 THEN RAISE EXCEPTION 'BOOTSTRAP_CONTEXT_ALREADY_BOUND'; END IF;
 SELECT * INTO STRICT b FROM company_private.installation_bootstrap_control WHERE installation_id=p_installation;
 PERFORM pg_advisory_xact_lock(b.lock_id);
 SELECT * INTO STRICT b FROM company_private.installation_bootstrap_control WHERE installation_id=p_installation FOR UPDATE;
 SELECT * INTO STRICT e FROM company_private.r55_setup_root_enrollments WHERE installation_id=p_installation AND generation=p_generation FOR SHARE;
 IF b.generation IS DISTINCT FROM p_generation OR b.state NOT IN ('ARMED','CONSUMED')
 OR encode(sha256(p_nonce),'hex') IS DISTINCT FROM b.nonce_hash
 OR e.key_fingerprint IS DISTINCT FROM encode(sha256(p_key),'hex')
 OR NOT EXISTS(SELECT 1 FROM company_private.scope_lock_registry WHERE lock_id=b.lock_id AND rank=0
 AND identity_key=jsonb_build_object('kind','INSTALLATION_BOOTSTRAP','installation_id',p_installation))
 THEN RAISE EXCEPTION 'BOOTSTRAP_INSTALLATION_BINDING_REJECTED'; END IF;
 bounds=company_private.r56_root_bounds(p_installation);
 j=convert_from(p_raw,'UTF8')::jsonb;
 IF jsonb_typeof(j) IS DISTINCT FROM 'object' OR EXISTS(SELECT key FROM json_each(convert_from(p_raw,'UTF8')::json) GROUP BY key HAVING count(*)>1)
 THEN RAISE EXCEPTION 'AMBIGUOUS_BOOTSTRAP_PROOF'; END IF;
 IF NOT ((j ?& ARRAY['profile','phase','installation_id','generation','backend_pid','transaction_id','db_login','human_id','host_boot_id','nonce_hash','manifest_digest','root_proof_digest','release_digest']) IS TRUE)
 OR (SELECT count(*) FROM jsonb_object_keys(j))<>13
 OR EXISTS(SELECT 1 FROM jsonb_each(j) z WHERE z.key NOT IN ('generation','backend_pid') AND jsonb_typeof(z.value) IS DISTINCT FROM 'string')
 OR jsonb_typeof(j->'generation') IS DISTINCT FROM 'number' OR j->>'generation' !~ '^[1-9][0-9]*$'
 OR jsonb_typeof(j->'backend_pid') IS DISTINCT FROM 'number' OR j->>'backend_pid' !~ '^[1-9][0-9]*$'
 THEN RAISE EXCEPTION 'BOOTSTRAP_PROOF_TYPED_FIELDS_REQUIRED'; END IF;
 IF NOT ((j->>'profile'='r56.bootstrap-enter.v1' AND j->>'phase'='BOOTSTRAP_ENTER'
 AND j->>'installation_id'=b.installation_id::text AND j->>'generation'=b.generation::text
 AND j->>'backend_pid'=pg_backend_pid()::text AND j->>'transaction_id'=pg_current_xact_id()::text
 AND j->>'db_login'=session_user::text AND j->>'human_id'=e.actual_human_id::text
 AND j->>'host_boot_id'=e.host_boot_id::text AND j->>'nonce_hash'=b.nonce_hash
 AND j->>'manifest_digest'=b.payload_digest AND j->>'root_proof_digest'=b.r55_root_proof_digest AND j->>'release_digest'=e.release_digest) IS TRUE)
 THEN RAISE EXCEPTION 'BOOTSTRAP_PROOF_CONTEXT_MISMATCH'; END IF;
 raw=convert_to('R56-BOOTSTRAP-v1','UTF8')||decode('00','hex');
 v=ARRAY[convert_to(b.installation_id::text,'UTF8'),convert_to(b.generation::text,'UTF8'),convert_to(e.issuer_id::text,'UTF8'),
 convert_to(e.key_id::text,'UTF8'),convert_to(e.enrollment_revision::text,'UTF8'),p_raw];
 FOREACH item IN ARRAY v LOOP raw=raw||convert_to(octet_length(item)::text||':','UTF8')||item; END LOOP;
 IF company_private.r55_cp_tag_equal(company_private.r55_cp_hmac_sha256(p_key,raw),p_tag) IS NOT TRUE THEN RAISE EXCEPTION 'INVALID_BOOTSTRAP_HMAC'; END IF;
 m=(convert_from(b.r55_root_proof,'UTF8')::jsonb)->'manifest';
 IF m IS NULL OR jsonb_typeof(m) IS DISTINCT FROM 'object'
 OR encode(sha256(convert_to(m::text,'UTF8')),'hex') IS DISTINCT FROM b.payload_digest
 OR encode(sha256(convert_to((m-'setup_manifest_digest')::text,'UTF8')),'hex') IS DISTINCT FROM b.setup_manifest_digest
 OR m->>'verified_human_id' IS DISTINCT FROM e.actual_human_id::text
 OR (m->>'tenant_id')::uuid IS DISTINCT FROM b.expected_tenant_id
 OR (m->>'project_id')::uuid IS DISTINCT FROM b.expected_project_id
 OR (m->>'workspace_id')::uuid IS DISTINCT FROM b.expected_workspace_id
 OR jsonb_typeof(m->'finite_initial_operations') IS DISTINCT FROM 'array'
 OR jsonb_array_length(m->'finite_initial_operations') NOT BETWEEN 1 AND 4
 THEN RAISE EXCEPTION 'BOOTSTRAP_CANONICAL_MANIFEST_MISMATCH'; END IF;
 FOR op IN SELECT value FROM jsonb_array_elements_text(m->'finite_initial_operations') ORDER BY value LOOP
  IF op IS NULL OR op NOT IN ('projects.read','projects.create','e0.setup_mandate_consume','e0.evaluation_attempt_create')
  OR NOT ((op=ANY(e.allowed_operations) AND op=ANY(b.r55_allowed_operations)) IS TRUE) THEN RAISE EXCEPTION 'BOOTSTRAP_SCOPE_EXPANSION'; END IF;
  SELECT * INTO STRICT reg FROM company_private.operation_permissions WHERE operation_id=op FOR SHARE;
  IF reg.scope_kind IS DISTINCT FROM 'PROJECT' OR reg.permission LIKE '%*%' OR reg.permission LIKE 'secret.read:%'
  THEN RAISE EXCEPTION 'BOOTSTRAP_PERMISSION_NOT_FINITE_PROJECT_SCOPE'; END IF;
 END LOOP;
 IF jsonb_array_length(m->'finite_initial_operations')<1 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(m->'finite_initial_operations') z GROUP BY value HAVING count(*)>1)
 THEN RAISE EXCEPTION 'BOOTSTRAP_DUPLICATE_OR_EMPTY_PERMISSION'; END IF;
 n=gen_random_uuid();
 INSERT INTO company_private.bootstrap_request_contexts(backend_pid,transaction_id,db_login,context_nonce,installation_id,generation,manifest_digest,
 human_proof_digest,expires_at,r55_verified_proof_digest,r55_mandate_digest,r56_manifest,r56_command_id)
 VALUES(pg_backend_pid(),pg_current_xact_id(),session_user,n,b.installation_id,b.generation,b.payload_digest,
 encode(sha256(p_raw),'hex'),b.expires_at,b.r55_root_proof_digest,
 encode(sha256(convert_to((m->'e0_mandate')::text,'UTF8')),'hex'),m,b.consumed_command_id);
 RETURN n;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'BOOTSTRAP_TRUSTED_SOURCE_MISSING';
END $$;
ALTER FUNCTION company_private.r56_bootstrap_enter(uuid,bigint,bytea,bytea,bytea,bytea) OWNER TO company_bootstrap_functions_r56;
REVOKE ALL ON FUNCTION company_private.r56_bootstrap_enter(uuid,bigint,bytea,bytea,bytea,bytea) FROM PUBLIC;

CREATE FUNCTION company_private.r56_bootstrap_final_proof(p_nonce uuid,p_phase text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.bootstrap_request_contexts%ROWTYPE;p jsonb;b jsonb;d text;
BEGIN
 SELECT * INTO STRICT x FROM company_private.bootstrap_request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id()
 AND db_login=session_user AND context_nonce=p_nonce;
 IF NOT pg_has_role(session_user,'company_bootstrap_transport_r56','MEMBER') THEN RAISE EXCEPTION 'BOOTSTRAP_TRANSPORT_REVOKED'; END IF;
 IF p_phase IS NULL OR p_phase NOT IN ('AFTER_DOMAIN_LOCKS','COMMIT_CUT','REPLAY_READ') THEN RAISE EXCEPTION 'INVALID_BOOTSTRAP_PHASE'; END IF;
 b=company_private.r56_root_bounds(x.installation_id);
 p=jsonb_build_object('profile','r56.bootstrap-final.v1','phase',p_phase,'context_nonce',x.context_nonce,
 'installation_id',x.installation_id,'generation',x.generation,'manifest_digest',x.manifest_digest,
 'human_proof_digest',x.human_proof_digest,'bounds',b);
 d=encode(sha256(convert_to(p::text,'UTF8')),'hex');
 UPDATE company_private.bootstrap_request_contexts SET r56_final_proof=p,r55_final_proof_digest=d
 WHERE backend_pid=x.backend_pid AND transaction_id=x.transaction_id AND context_nonce=x.context_nonce AND db_login=session_user;
 IF NOT FOUND THEN RAISE EXCEPTION 'BOOTSTRAP_FINAL_CONTEXT_LOST'; END IF;
 RETURN p;
END $$;
ALTER FUNCTION company_private.r56_bootstrap_final_proof(uuid,text) OWNER TO company_bootstrap_functions_r56;
REVOKE ALL ON FUNCTION company_private.r56_bootstrap_final_proof(uuid,text) FROM PUBLIC;

-- Finite domain policies use a protected bootstrap context, never app.* GUC.
CREATE POLICY r56_tenant_read ON company.tenants FOR SELECT TO company_bootstrap_functions_r56 USING(company_private.r56_setup_scope(id,NULL,false));
CREATE POLICY r56_tenant_insert ON company.tenants FOR INSERT TO company_bootstrap_functions_r56 WITH CHECK(company_private.r56_setup_scope(id,NULL,true));
DO $policies$ DECLARE t text;BEGIN
 FOREACH t IN ARRAY ARRAY['principals','memberships','workspaces'] LOOP
  EXECUTE format('CREATE POLICY r56_boot_read ON company.%I FOR SELECT TO company_bootstrap_functions_r56 USING(company_private.r56_setup_scope(tenant_id,NULL,false))',t);
  EXECUTE format('CREATE POLICY r56_boot_insert ON company.%I FOR INSERT TO company_bootstrap_functions_r56 WITH CHECK(company_private.r56_setup_scope(tenant_id,NULL,true))',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['projects'] LOOP
  EXECUTE format('CREATE POLICY r56_boot_read ON company.%I FOR SELECT TO company_bootstrap_functions_r56 USING(company_private.r56_setup_scope(tenant_id,id,false))',t);
  EXECUTE format('CREATE POLICY r56_boot_insert ON company.%I FOR INSERT TO company_bootstrap_functions_r56 WITH CHECK(company_private.r56_setup_scope(tenant_id,id,true))',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['objectives','plans','project_grants','outbox','project_event_heads'] LOOP
  EXECUTE format('CREATE POLICY r56_boot_read ON company.%I FOR SELECT TO company_bootstrap_functions_r56 USING(company_private.r56_setup_scope(tenant_id,project_id,false))',t);
  EXECUTE format('CREATE POLICY r56_boot_insert ON company.%I FOR INSERT TO company_bootstrap_functions_r56 WITH CHECK(company_private.r56_setup_scope(tenant_id,project_id,true))',t);
 END LOOP;
END $policies$;
CREATE POLICY r56_heads_read ON company.authority_scope_heads FOR SELECT TO company_bootstrap_functions_r56 USING(company_private.r56_setup_scope(tenant_id,project_id,false));
CREATE POLICY r56_heads_insert ON company.authority_scope_heads FOR INSERT TO company_bootstrap_functions_r56 WITH CHECK(company_private.r56_setup_scope(tenant_id,project_id,true) AND scope_kind IN ('TENANT','PROJECT') AND epoch=0 AND revision=0);
CREATE POLICY r56_command_read ON company.commands FOR SELECT TO company_bootstrap_functions_r56 USING(company_private.r56_setup_scope(tenant_id,r55_project_id,false) AND operation='trusted_setup.consume');
CREATE POLICY r56_command_insert ON company.commands FOR INSERT TO company_bootstrap_functions_r56 WITH CHECK(company_private.r56_setup_scope(tenant_id,NULL,true) AND operation='trusted_setup.consume' AND state='RUNNING');
CREATE POLICY r56_command_update ON company.commands FOR UPDATE TO company_bootstrap_functions_r56 USING(company_private.r56_setup_scope(tenant_id,NULL,true) AND operation='trusted_setup.consume') WITH CHECK(company_private.r56_setup_scope(tenant_id,r55_project_id,true) AND operation='trusted_setup.consume' AND state='SUCCEEDED');
CREATE POLICY r56_event_head_update ON company.project_event_heads FOR UPDATE TO company_bootstrap_functions_r56 USING(company_private.r56_setup_scope(tenant_id,project_id,true)) WITH CHECK(company_private.r56_setup_scope(tenant_id,project_id,true) AND writer_generation=54);
CREATE POLICY r56_audit ON company.audit_events TO company_bootstrap_functions_r56 USING(company_private.r56_setup_scope(tenant_id,NULL,false)) WITH CHECK(company_private.r56_setup_scope(tenant_id,NULL,true));
CREATE POLICY r56_receipt_insert ON company_private.bootstrap_receipts FOR INSERT TO company_bootstrap_functions_r56 WITH CHECK(company_private.r56_setup_scope(tenant_id,project_id,true));

CREATE FUNCTION company_private.r56_bootstrap_initial_write(p_nonce uuid,p_correlation uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.bootstrap_request_contexts%ROWTYPE;b company_private.installation_bootstrap_control%ROWTYPE;
 m jsonb;v jsonb;op text;permission_text text;cmd uuid;tl bigint;pl bigint;gd text;bounds jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.bootstrap_request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND context_nonce=p_nonce;
 SELECT * INTO STRICT b FROM company_private.installation_bootstrap_control WHERE installation_id=x.installation_id FOR UPDATE;
 IF b.state IS DISTINCT FROM 'ARMED' OR b.generation IS DISTINCT FROM x.generation OR p_correlation IS NULL THEN RAISE EXCEPTION 'BOOTSTRAP_NOT_FRESH_ARMED'; END IF;
 m=x.r56_manifest;
 IF NOT ((m ?& ARRAY['tenant_name','human_name','project_name','initial_principals','evaluation_objective','evaluation_plan','e0_mandate']) IS TRUE)
 OR jsonb_typeof(m->'tenant_name') IS DISTINCT FROM 'string' OR length(m->>'tenant_name') NOT BETWEEN 3 AND 200
 OR jsonb_typeof(m->'human_name') IS DISTINCT FROM 'string' OR length(m->>'human_name') NOT BETWEEN 1 AND 200
 OR jsonb_typeof(m->'project_name') IS DISTINCT FROM 'string' OR length(m->>'project_name') NOT BETWEEN 3 AND 200
 OR jsonb_typeof(m->'initial_principals') IS DISTINCT FROM 'array' OR jsonb_array_length(m->'initial_principals') NOT BETWEEN 1 AND 32
 THEN RAISE EXCEPTION 'INVALID_BOOTSTRAP_INITIAL_SHAPE'; END IF;
 IF EXISTS(SELECT 1 FROM company.tenants WHERE id=b.expected_tenant_id) THEN RAISE EXCEPTION 'PREEXISTING_TENANT_NOT_FRESH_BOOTSTRAP'; END IF;
 bounds=company_private.r56_root_bounds(b.installation_id);
 INSERT INTO company_private.scope_lock_registry(rank,identity_key) VALUES(0,jsonb_build_object('kind','TENANT','tenant_id',b.expected_tenant_id)) RETURNING lock_id INTO tl;
 INSERT INTO company_private.scope_lock_registry(rank,identity_key) VALUES(1,jsonb_build_object('kind','PROJECT','tenant_id',b.expected_tenant_id,'project_id',b.expected_project_id)) RETURNING lock_id INTO pl;
 IF tl<=b.lock_id THEN RAISE EXCEPTION 'BOOTSTRAP_LOCK_ORDER_PREFLIGHT_FAILED'; END IF;
 PERFORM pg_advisory_xact_lock(tl);PERFORM pg_advisory_xact_lock(pl);
 INSERT INTO company.tenants(id,name) VALUES(b.expected_tenant_id,m->>'tenant_name');
 INSERT INTO company.principals(tenant_id,id,name,kind) VALUES(b.expected_tenant_id,b.expected_human_id,m->>'human_name','HUMAN');
 INSERT INTO company.memberships(tenant_id,principal_id,role) VALUES(b.expected_tenant_id,b.expected_human_id,'OPERATOR');
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(m->'initial_principals') z GROUP BY (z->>'id')::uuid HAVING count(*)>1) THEN RAISE EXCEPTION 'DUPLICATE_BOOTSTRAP_PRINCIPAL'; END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(m->'initial_principals') LOOP
  IF NOT ((jsonb_typeof(v)='object' AND v ?& ARRAY['id','name','kind'] AND v->>'kind' IN ('AGENT','WORKER','VERIFIER')
  AND jsonb_typeof(v->'name')='string' AND length(v->>'name') BETWEEN 1 AND 200
  AND (v->>'id')::uuid<>b.expected_human_id) IS TRUE) THEN RAISE EXCEPTION 'SINGLE_HUMAN_ONLY_NO_AGENT_HUMAN_ALIAS'; END IF;
  INSERT INTO company.principals(tenant_id,id,name,kind) VALUES(b.expected_tenant_id,(v->>'id')::uuid,v->>'name',v->>'kind');
 END LOOP;
 INSERT INTO company.workspaces(tenant_id,id,root_ref,trust_class) VALUES(b.expected_tenant_id,b.expected_workspace_id,'bootstrap:'||b.installation_id::text||':'||b.expected_workspace_id::text,'DISPOSABLE_TEST');
 INSERT INTO company.projects(tenant_id,id,workspace_id,name,revision) VALUES(b.expected_tenant_id,b.expected_project_id,b.expected_workspace_id,m->>'project_name',0);
 INSERT INTO company.authority_scope_heads(tenant_id,scope_kind,scope_ref,project_id,epoch,lock_id,revision) VALUES(b.expected_tenant_id,'TENANT',b.expected_tenant_id,NULL,0,tl,0),(b.expected_tenant_id,'PROJECT',b.expected_project_id,b.expected_project_id,0,pl,0);
 FOR op IN SELECT value FROM jsonb_array_elements_text(m->'finite_initial_operations') ORDER BY value LOOP
  SELECT permission INTO STRICT permission_text FROM company_private.operation_permissions WHERE operation_id=op;
  INSERT INTO company.project_grants(tenant_id,project_id,principal_id,permission,base_permission,grant_id,revision,valid_from,valid_until,granted_by)
  VALUES(b.expected_tenant_id,b.expected_project_id,b.expected_human_id,permission_text,permission_text,gen_random_uuid(),0,(bounds->>'utc_lower')::timestamptz,b.expires_at,b.expected_human_id);
 END LOOP;
 -- Exactly one signed, disposable E0 seed; not a general Objective/Plan writer.
 v=m->'evaluation_objective';
 IF NOT ((jsonb_typeof(v)='object' AND v ?& ARRAY['id','goal','constraints','expected_outputs'] AND jsonb_typeof(v->'goal')='string'
 AND length(v->>'goal') BETWEEN 1 AND 2000 AND jsonb_typeof(v->'constraints')='array' AND jsonb_typeof(v->'expected_outputs')='array') IS TRUE)
 THEN RAISE EXCEPTION 'INVALID_SIGNED_E0_OBJECTIVE'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v->'constraints') z WHERE jsonb_typeof(z) IS DISTINCT FROM 'string')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'expected_outputs') z WHERE jsonb_typeof(z) IS DISTINCT FROM 'string')
 THEN RAISE EXCEPTION 'INVALID_SIGNED_E0_OBJECTIVE_ITEMS'; END IF;
 INSERT INTO company.objectives(tenant_id,project_id,id,goal,constraints,expected_outputs,created_by) VALUES(b.expected_tenant_id,b.expected_project_id,(v->>'id')::uuid,v->>'goal',v->'constraints',v->'expected_outputs',b.expected_human_id);
 v=m->'evaluation_plan';
 IF NOT ((jsonb_typeof(v)='object' AND v ?& ARRAY['id','objective_id','assumptions','acceptance_criteria']
 AND v->>'objective_id'=m#>>'{evaluation_objective,id}' AND v->>'id'=m#>>'{e0_mandate,plan_id}'
 AND jsonb_typeof(v->'assumptions')='array' AND jsonb_typeof(v->'acceptance_criteria')='array' AND jsonb_array_length(v->'acceptance_criteria')>0) IS TRUE)
 THEN RAISE EXCEPTION 'INVALID_SIGNED_E0_PLAN'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v->'assumptions') z WHERE jsonb_typeof(z) IS DISTINCT FROM 'string')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'acceptance_criteria') z WHERE jsonb_typeof(z) IS DISTINCT FROM 'string')
 THEN RAISE EXCEPTION 'INVALID_SIGNED_E0_PLAN_ITEMS'; END IF;
 INSERT INTO company.plans(tenant_id,project_id,id,objective_id,revision,assumptions,acceptance_criteria) VALUES(b.expected_tenant_id,b.expected_project_id,(v->>'id')::uuid,(v->>'objective_id')::uuid,0,v->'assumptions',v->'acceptance_criteria');
 v=m->'e0_mandate';
 IF NOT ((jsonb_typeof(v)='object' AND v->>'kind'='EVALUATION_ONLY' AND v->>'network'='DENY' AND v->>'external_effects'='DENY'
 AND v->>'workspace_id'=b.expected_workspace_id::text AND v->>'model_digest' ~ '^[a-f0-9]{64}$'
 AND v->>'fixture_digest' ~ '^[a-f0-9]{64}$' AND v->>'profile_digest' ~ '^[a-f0-9]{64}$'
 AND v->>'negative_suite_digest' ~ '^[a-f0-9]{64}$' AND jsonb_typeof(v->'role_id')='string' AND length(v->>'role_id')>0
 AND jsonb_typeof(v->'required_positive_oracle_ids')='array' AND jsonb_array_length(v->'required_positive_oracle_ids')>0
 AND jsonb_typeof(v->'required_negative_oracle_ids')='array' AND jsonb_array_length(v->'required_negative_oracle_ids')>0) IS TRUE)
 OR NOT EXISTS(SELECT 1 FROM company.principals p WHERE p.tenant_id=b.expected_tenant_id AND p.id=(v->>'subject_principal_id')::uuid AND p.kind IN ('WORKER','VERIFIER'))
 THEN RAISE EXCEPTION 'INVALID_E0_ONLY_MANDATE_OR_SUBJECT'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements((v->'required_positive_oracle_ids')||(v->'required_negative_oracle_ids')) z
 WHERE jsonb_typeof(z) IS DISTINCT FROM 'string') THEN RAISE EXCEPTION 'INVALID_E0_ORACLE_ID_TYPE'; END IF;
 SELECT encode(sha256(convert_to(jsonb_agg(jsonb_build_array(g.grant_id,g.permission,g.valid_from,g.valid_until) ORDER BY g.grant_id)::text,'UTF8')),'hex') INTO gd FROM company.project_grants g WHERE g.tenant_id=b.expected_tenant_id AND g.project_id=b.expected_project_id;
 cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(b.expected_tenant_id,cmd,b.expected_human_id,'trusted_setup.consume','setup:'||b.installation_id::text||':'||b.generation::text,b.payload_digest,p_correlation,'RUNNING',NULL);
 INSERT INTO company.project_event_heads(tenant_id,project_id,writer_generation,committed_sequence,migration_manifest_digest) VALUES(b.expected_tenant_id,b.expected_project_id,54,0,b.setup_manifest_digest);
 UPDATE company_private.bootstrap_request_contexts SET r56_command_id=cmd,r56_grants_digest=gd WHERE backend_pid=x.backend_pid AND transaction_id=x.transaction_id AND context_nonce=p_nonce;
 RETURN cmd;
END $$;
ALTER FUNCTION company_private.r56_bootstrap_initial_write(uuid,uuid) OWNER TO company_bootstrap_functions_r56;
REVOKE ALL ON FUNCTION company_private.r56_bootstrap_initial_write(uuid,uuid) FROM PUBLIC;

CREATE FUNCTION company_private.r56_bootstrap_finish(p_nonce uuid,p_command uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.bootstrap_request_contexts%ROWTYPE;b company_private.installation_bootstrap_control%ROWTYPE;c company.commands%ROWTYPE;
 proof jsonb;result jsonb;payload jsonb;d text;event_d text;aid bigint;n bigint;
BEGIN
 SELECT * INTO STRICT x FROM company_private.bootstrap_request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND context_nonce=p_nonce;
 SELECT * INTO STRICT b FROM company_private.installation_bootstrap_control WHERE installation_id=x.installation_id FOR UPDATE;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=b.expected_tenant_id AND id=p_command FOR UPDATE;
 SELECT committed_sequence INTO STRICT n FROM company.project_event_heads WHERE tenant_id=b.expected_tenant_id AND project_id=b.expected_project_id AND writer_generation=54 FOR UPDATE;
 IF b.state IS DISTINCT FROM 'ARMED' OR c.operation IS DISTINCT FROM 'trusted_setup.consume' OR c.state IS DISTINCT FROM 'RUNNING'
 OR c.principal_id IS DISTINCT FROM b.expected_human_id OR c.payload_digest IS DISTINCT FROM b.payload_digest
 OR x.r56_command_id IS DISTINCT FROM c.id OR x.r56_grants_digest IS NULL OR n<>0 THEN RAISE EXCEPTION 'BOOTSTRAP_FINALIZER_BINDING_MISMATCH'; END IF;
 proof=company_private.r56_bootstrap_final_proof(p_nonce,'AFTER_DOMAIN_LOCKS');
 result=jsonb_build_object('installation_id',b.installation_id,'generation',b.generation,'tenant_id',b.expected_tenant_id,'project_id',b.expected_project_id,
 'workspace_id',b.expected_workspace_id,'accepted_human_id',b.expected_human_id,'grants_digest',x.r56_grants_digest,'human_count',1,
 'source_revision','r56','e0_started',false,'ordinary_worker_authorized',false,'final_proof',proof);
 d=encode(sha256(convert_to(jsonb_build_array(c.id,c.payload_digest,b.installation_id,result)::text,'UTF8')),'hex');
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(b.expected_tenant_id,c.correlation_id,b.expected_human_id,'InstallationBootstrapped') RETURNING id INTO aid;
 payload=jsonb_build_object('command_id',c.id,'request_digest',c.payload_digest,'result_digest',d,'installation_id',b.installation_id,'source_revision','r56');
 event_d=encode(sha256(convert_to(jsonb_build_array(b.expected_project_id,0,'InstallationBootstrapped',payload)::text,'UTF8')),'hex');
 INSERT INTO company.outbox(tenant_id,project_id,aggregate_id,aggregate_revision,kind,payload,project_sequence,event_writer_generation,event_instance_id,event_digest)
 VALUES(b.expected_tenant_id,b.expected_project_id,b.expected_project_id,0,'InstallationBootstrapped',payload,1,54,c.id,event_d);
 UPDATE company.project_event_heads SET committed_sequence=1 WHERE tenant_id=b.expected_tenant_id AND project_id=b.expected_project_id AND committed_sequence=0 AND writer_generation=54;
 IF NOT FOUND THEN RAISE EXCEPTION 'BOOTSTRAP_EVENT_HEAD_CONFLICT'; END IF;
 UPDATE company.commands SET state='SUCCEEDED',result_ref=b.installation_id,r55_project_id=b.expected_project_id,r55_result_payload=result,
 r55_result_digest=d,r55_event_sequence=1,r55_audit_id=aid,r55_source_revision='r56' WHERE tenant_id=c.tenant_id AND id=c.id AND state='RUNNING';
 IF NOT FOUND THEN RAISE EXCEPTION 'BOOTSTRAP_COMMAND_CONFLICT'; END IF;
 INSERT INTO company_private.bootstrap_receipts(installation_id,generation,tenant_id,project_id,command_id,payload_digest,setup_manifest_digest,initial_grants_digest,accepted_human_id,
 e0_mandate,e0_valid_until,r56_final_proof,r56_result_digest)
 VALUES(b.installation_id,b.generation,b.expected_tenant_id,b.expected_project_id,c.id,b.payload_digest,b.setup_manifest_digest,x.r56_grants_digest,b.expected_human_id,
 x.r56_manifest->'e0_mandate',b.expires_at,proof,d);
 UPDATE company_private.installation_bootstrap_control SET state='CONSUMED',consumed_command_id=c.id WHERE installation_id=b.installation_id AND generation=b.generation AND state='ARMED';
 IF NOT FOUND THEN RAISE EXCEPTION 'BOOTSTRAP_CONSUME_CAS_CONFLICT'; END IF;
 PERFORM company_private.r56_bootstrap_final_proof(p_nonce,'COMMIT_CUT');
 RETURN jsonb_build_object('command_id',c.id,'state','SUCCEEDED','result_ref',b.installation_id,'receipt_digest',d,'spawned',false);
END $$;
ALTER FUNCTION company_private.r56_bootstrap_finish(uuid,uuid) OWNER TO company_bootstrap_functions_r56;
REVOKE ALL ON FUNCTION company_private.r56_bootstrap_finish(uuid,uuid) FROM PUBLIC;

CREATE FUNCTION company_private.r56_bootstrap_invariant() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c company.commands%ROWTYPE;b company_private.bootstrap_receipts%ROWTYPE;
BEGIN
 IF NEW.operation IS DISTINCT FROM 'trusted_setup.consume' OR NEW.r55_source_revision IS DISTINCT FROM 'r56' THEN RETURN NULL; END IF;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=NEW.tenant_id AND id=NEW.id;
 SELECT * INTO STRICT b FROM company_private.bootstrap_receipts WHERE command_id=c.id AND tenant_id=c.tenant_id;
 IF c.state IS DISTINCT FROM 'SUCCEEDED' OR b.r56_result_digest IS DISTINCT FROM c.r55_result_digest
 OR b.accepted_human_id IS DISTINCT FROM c.principal_id OR b.payload_digest IS DISTINCT FROM c.payload_digest
 OR NOT EXISTS(SELECT 1 FROM company_private.installation_bootstrap_control z WHERE z.installation_id=b.installation_id AND z.generation=b.generation AND z.state='CONSUMED' AND z.consumed_command_id=c.id)
 OR NOT EXISTS(SELECT 1 FROM company.audit_events a WHERE a.id=c.r55_audit_id AND a.tenant_id=c.tenant_id AND a.actor_id=c.principal_id AND a.correlation_id=c.correlation_id AND a.kind='InstallationBootstrapped')
 OR NOT EXISTS(SELECT 1 FROM company.outbox e WHERE e.tenant_id=c.tenant_id AND e.project_id=b.project_id AND e.project_sequence=1 AND e.event_instance_id=c.id AND e.event_writer_generation=54 AND e.payload->>'result_digest'=c.r55_result_digest)
 THEN RAISE EXCEPTION 'BOOTSTRAP_ATOMIC_WITNESS_MISSING'; END IF;
 PERFORM company_private.r56_root_bounds(b.installation_id);
 RETURN NULL;
END $$;
ALTER FUNCTION company_private.r56_bootstrap_invariant() OWNER TO company_bootstrap_functions_r56;
REVOKE ALL ON FUNCTION company_private.r56_bootstrap_invariant() FROM PUBLIC;
CREATE CONSTRAINT TRIGGER r56_bootstrap_invariant AFTER INSERT OR UPDATE ON company.commands DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION company_private.r56_bootstrap_invariant();

CREATE FUNCTION company_private.r56_bootstrap_consume(p_installation uuid,p_generation bigint,p_nonce bytea,p_raw bytea,p_tag bytea,p_key bytea,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE n uuid;cmd uuid;result jsonb;b company_private.bootstrap_receipts%ROWTYPE;ctl company_private.installation_bootstrap_control%ROWTYPE;
BEGIN
 IF p_correlation IS NULL THEN RAISE EXCEPTION 'BOOTSTRAP_CORRELATION_REQUIRED'; END IF;
 n=company_private.r56_bootstrap_enter(p_installation,p_generation,p_nonce,p_raw,p_tag,p_key);
 SELECT * INTO STRICT ctl FROM company_private.installation_bootstrap_control WHERE installation_id=p_installation;
 IF ctl.state='CONSUMED' THEN
  SELECT * INTO STRICT b FROM company_private.bootstrap_receipts WHERE installation_id=p_installation AND generation=p_generation AND payload_digest=ctl.payload_digest AND accepted_human_id=ctl.expected_human_id;
  IF b.r56_result_digest IS NULL OR b.r56_final_proof IS NULL OR NOT EXISTS(
   SELECT 1 FROM company.commands c JOIN company.audit_events a ON a.tenant_id=c.tenant_id AND a.id=c.r55_audit_id
   JOIN company.outbox e ON e.tenant_id=c.tenant_id AND e.project_id=b.project_id AND e.event_instance_id=c.id
   WHERE c.tenant_id=b.tenant_id AND c.id=b.command_id AND c.principal_id=b.accepted_human_id
   AND c.state='SUCCEEDED' AND c.result_ref=b.installation_id AND c.payload_digest=b.payload_digest
   AND c.r55_source_revision='r56' AND c.r55_result_digest=b.r56_result_digest
   AND a.kind='InstallationBootstrapped' AND a.actor_id=c.principal_id AND a.correlation_id=c.correlation_id
   AND e.kind='InstallationBootstrapped' AND e.project_sequence=1 AND e.event_writer_generation=54
   AND e.payload->>'result_digest'=c.r55_result_digest)
  THEN RAISE EXCEPTION 'BOOTSTRAP_REPLAY_WITNESS_MISSING_OR_LEGACY'; END IF;
  PERFORM company_private.r56_bootstrap_final_proof(n,'REPLAY_READ');
  result=jsonb_build_object('command_id',b.command_id,'state','SUCCEEDED','result_ref',b.installation_id,'receipt_digest',b.r56_result_digest,'outcome','REPLAY_NO_NEW_GRANT');
 ELSE
  cmd=company_private.r56_bootstrap_initial_write(n,p_correlation);
  result=company_private.r56_bootstrap_finish(n,cmd);
 END IF;
 -- Deferred witnesses must execute while the protected setup context exists.
 SET CONSTRAINTS company.r56_bootstrap_invariant IMMEDIATE;
 DELETE FROM company_private.bootstrap_request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND context_nonce=n;
 IF NOT FOUND THEN RAISE EXCEPTION 'BOOTSTRAP_EXIT_CONTEXT_LOST'; END IF;
 RETURN result;
END $$;
ALTER FUNCTION company_private.r56_bootstrap_consume(uuid,bigint,bytea,bytea,bytea,bytea,uuid) OWNER TO company_bootstrap_functions_r56;
REVOKE ALL ON FUNCTION company_private.r56_bootstrap_consume(uuid,bigint,bytea,bytea,bytea,bytea,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r56_bootstrap_consume(uuid,bigint,bytea,bytea,bytea,bytea,uuid) TO company_bootstrap_transport_r56;
-- Fresh/native catalog preflight and explicit G0/human enrollment remain mandatory.
-- Domain DML and private helper EXECUTE are never granted to the transport.

-- SOURCE sql/028_R57_BOOTSTRAP_FINALITY_OVERLAY.sql
-- Replacement bodies AFTER r56. No historical DDL repeated.
CREATE OR REPLACE FUNCTION company_private.r56_bootstrap_initial_write(p_nonce uuid,p_correlation uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.bootstrap_request_contexts%ROWTYPE;b company_private.installation_bootstrap_control%ROWTYPE;
 m jsonb;v jsonb;op text;permission_text text;cmd uuid;tl bigint;pl bigint;gd text;bounds jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.bootstrap_request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND context_nonce=p_nonce;
 SELECT * INTO STRICT b FROM company_private.installation_bootstrap_control WHERE installation_id=x.installation_id FOR UPDATE;
 IF b.state IS DISTINCT FROM 'ARMED' OR b.generation IS DISTINCT FROM x.generation OR p_correlation IS NULL THEN RAISE EXCEPTION 'BOOTSTRAP_NOT_FRESH_ARMED'; END IF;
 m=x.r56_manifest;
 IF jsonb_typeof(m) IS DISTINCT FROM 'object' OR NOT ((m ?& ARRAY['tenant_id','project_id','workspace_id','verified_human_id','nonce_hash','setup_manifest_digest','valid_until','finite_initial_operations','tenant_name','human_name','project_name','initial_principals','evaluation_objective','evaluation_plan','e0_mandate']) IS TRUE) OR EXISTS(SELECT 1 FROM jsonb_object_keys(m) k WHERE k<>ALL(ARRAY['tenant_id','project_id','workspace_id','verified_human_id','nonce_hash','setup_manifest_digest','valid_until','finite_initial_operations','tenant_name','human_name','project_name','initial_principals','evaluation_objective','evaluation_plan','e0_mandate']))
 OR jsonb_typeof((m->'evaluation_objective')) IS DISTINCT FROM 'object' OR NOT (((m->'evaluation_objective') ?& ARRAY['id','goal','constraints','expected_outputs']) IS TRUE) OR EXISTS(SELECT 1 FROM jsonb_object_keys((m->'evaluation_objective')) k WHERE k<>ALL(ARRAY['id','goal','constraints','expected_outputs']))
 OR jsonb_typeof((m->'evaluation_plan')) IS DISTINCT FROM 'object' OR NOT (((m->'evaluation_plan') ?& ARRAY['id','objective_id','assumptions','acceptance_criteria']) IS TRUE) OR EXISTS(SELECT 1 FROM jsonb_object_keys((m->'evaluation_plan')) k WHERE k<>ALL(ARRAY['id','objective_id','assumptions','acceptance_criteria']))
 OR jsonb_typeof((m->'e0_mandate')) IS DISTINCT FROM 'object' OR NOT (((m->'e0_mandate') ?& ARRAY['kind','network','external_effects','workspace_id','plan_id','subject_principal_id','model_digest','fixture_digest','profile_digest','negative_suite_digest','role_id','required_positive_oracle_ids','required_negative_oracle_ids']) IS TRUE) OR EXISTS(SELECT 1 FROM jsonb_object_keys((m->'e0_mandate')) k WHERE k<>ALL(ARRAY['kind','network','external_effects','workspace_id','plan_id','subject_principal_id','model_digest','fixture_digest','profile_digest','negative_suite_digest','role_id','required_positive_oracle_ids','required_negative_oracle_ids']))
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(m->'initial_principals') elem(value) WHERE jsonb_typeof(elem.value) IS DISTINCT FROM 'object' OR NOT ((elem.value ?& ARRAY['id','name','kind']) IS TRUE) OR EXISTS(SELECT 1 FROM jsonb_object_keys(elem.value) k WHERE k<>ALL(ARRAY['id','name','kind']))) THEN RAISE EXCEPTION 'CLOSED_BOOTSTRAP_MANIFEST_REQUIRED'; END IF;
 IF NOT ((m ?& ARRAY['tenant_name','human_name','project_name','initial_principals','evaluation_objective','evaluation_plan','e0_mandate']) IS TRUE)
 OR jsonb_typeof(m->'tenant_name') IS DISTINCT FROM 'string' OR length(m->>'tenant_name') NOT BETWEEN 3 AND 200
 OR jsonb_typeof(m->'human_name') IS DISTINCT FROM 'string' OR length(m->>'human_name') NOT BETWEEN 1 AND 200
 OR jsonb_typeof(m->'project_name') IS DISTINCT FROM 'string' OR length(m->>'project_name') NOT BETWEEN 3 AND 200
 OR jsonb_typeof(m->'initial_principals') IS DISTINCT FROM 'array' OR jsonb_array_length(m->'initial_principals') NOT BETWEEN 1 AND 32
 THEN RAISE EXCEPTION 'INVALID_BOOTSTRAP_INITIAL_SHAPE'; END IF;
 IF EXISTS(SELECT 1 FROM company.tenants WHERE id=b.expected_tenant_id) THEN RAISE EXCEPTION 'PREEXISTING_TENANT_NOT_FRESH_BOOTSTRAP'; END IF;
 bounds=company_private.r56_root_bounds(b.installation_id);
 INSERT INTO company_private.scope_lock_registry(rank,identity_key) VALUES(0,jsonb_build_object('kind','TENANT','tenant_id',b.expected_tenant_id)) RETURNING lock_id INTO tl;
 INSERT INTO company_private.scope_lock_registry(rank,identity_key) VALUES(1,jsonb_build_object('kind','PROJECT','tenant_id',b.expected_tenant_id,'project_id',b.expected_project_id)) RETURNING lock_id INTO pl;
 IF tl<=b.lock_id THEN RAISE EXCEPTION 'BOOTSTRAP_LOCK_ORDER_PREFLIGHT_FAILED'; END IF;
 PERFORM pg_advisory_xact_lock(tl);PERFORM pg_advisory_xact_lock(pl);
 INSERT INTO company.tenants(id,name) VALUES(b.expected_tenant_id,m->>'tenant_name');
 INSERT INTO company.principals(tenant_id,id,name,kind) VALUES(b.expected_tenant_id,b.expected_human_id,m->>'human_name','HUMAN');
 INSERT INTO company.memberships(tenant_id,principal_id,role) VALUES(b.expected_tenant_id,b.expected_human_id,'OPERATOR');
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(m->'initial_principals') z GROUP BY (z->>'id')::uuid HAVING count(*)>1) THEN RAISE EXCEPTION 'DUPLICATE_BOOTSTRAP_PRINCIPAL'; END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(m->'initial_principals') LOOP
  IF NOT ((jsonb_typeof(v)='object' AND v ?& ARRAY['id','name','kind'] AND v->>'kind' IN ('AGENT','WORKER','VERIFIER')
  AND jsonb_typeof(v->'name')='string' AND length(v->>'name') BETWEEN 1 AND 200
  AND (v->>'id')::uuid<>b.expected_human_id) IS TRUE) THEN RAISE EXCEPTION 'SINGLE_HUMAN_ONLY_NO_AGENT_HUMAN_ALIAS'; END IF;
  INSERT INTO company.principals(tenant_id,id,name,kind) VALUES(b.expected_tenant_id,(v->>'id')::uuid,v->>'name',v->>'kind');
 END LOOP;
 INSERT INTO company.workspaces(tenant_id,id,root_ref,trust_class) VALUES(b.expected_tenant_id,b.expected_workspace_id,'bootstrap:'||b.installation_id::text||':'||b.expected_workspace_id::text,'DISPOSABLE_TEST');
 INSERT INTO company.projects(tenant_id,id,workspace_id,name,revision) VALUES(b.expected_tenant_id,b.expected_project_id,b.expected_workspace_id,m->>'project_name',0);
 INSERT INTO company.authority_scope_heads(tenant_id,scope_kind,scope_ref,project_id,epoch,lock_id,revision) VALUES(b.expected_tenant_id,'TENANT',b.expected_tenant_id,NULL,0,tl,0),(b.expected_tenant_id,'PROJECT',b.expected_project_id,b.expected_project_id,0,pl,0);
 FOR op IN SELECT value FROM jsonb_array_elements_text(m->'finite_initial_operations') ORDER BY value LOOP
  SELECT permission INTO STRICT permission_text FROM company_private.operation_permissions WHERE operation_id=op;
  INSERT INTO company.project_grants(tenant_id,project_id,principal_id,permission,base_permission,grant_id,revision,valid_from,valid_until,granted_by)
  VALUES(b.expected_tenant_id,b.expected_project_id,b.expected_human_id,permission_text,permission_text,gen_random_uuid(),0,(bounds->>'utc_lower')::timestamptz,b.expires_at,b.expected_human_id);
 END LOOP;
 -- Exactly one signed, disposable E0 seed; not a general Objective/Plan writer.
 v=m->'evaluation_objective';
 IF NOT ((jsonb_typeof(v)='object' AND v ?& ARRAY['id','goal','constraints','expected_outputs'] AND jsonb_typeof(v->'goal')='string'
 AND length(v->>'goal') BETWEEN 1 AND 2000 AND jsonb_typeof(v->'constraints')='array' AND jsonb_typeof(v->'expected_outputs')='array') IS TRUE)
 THEN RAISE EXCEPTION 'INVALID_SIGNED_E0_OBJECTIVE'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v->'constraints') z WHERE jsonb_typeof(z) IS DISTINCT FROM 'string')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'expected_outputs') z WHERE jsonb_typeof(z) IS DISTINCT FROM 'string')
 THEN RAISE EXCEPTION 'INVALID_SIGNED_E0_OBJECTIVE_ITEMS'; END IF;
 INSERT INTO company.objectives(tenant_id,project_id,id,goal,constraints,expected_outputs,created_by) VALUES(b.expected_tenant_id,b.expected_project_id,(v->>'id')::uuid,v->>'goal',v->'constraints',v->'expected_outputs',b.expected_human_id);
 v=m->'evaluation_plan';
 IF NOT ((jsonb_typeof(v)='object' AND v ?& ARRAY['id','objective_id','assumptions','acceptance_criteria']
 AND v->>'objective_id'=m#>>'{evaluation_objective,id}' AND v->>'id'=m#>>'{e0_mandate,plan_id}'
 AND jsonb_typeof(v->'assumptions')='array' AND jsonb_typeof(v->'acceptance_criteria')='array' AND jsonb_array_length(v->'acceptance_criteria')>0) IS TRUE)
 THEN RAISE EXCEPTION 'INVALID_SIGNED_E0_PLAN'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v->'assumptions') z WHERE jsonb_typeof(z) IS DISTINCT FROM 'string')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'acceptance_criteria') z WHERE jsonb_typeof(z) IS DISTINCT FROM 'string')
 THEN RAISE EXCEPTION 'INVALID_SIGNED_E0_PLAN_ITEMS'; END IF;
 INSERT INTO company.plans(tenant_id,project_id,id,objective_id,revision,assumptions,acceptance_criteria) VALUES(b.expected_tenant_id,b.expected_project_id,(v->>'id')::uuid,(v->>'objective_id')::uuid,0,v->'assumptions',v->'acceptance_criteria');
 v=m->'e0_mandate';
 IF NOT ((jsonb_typeof(v)='object' AND v->>'kind'='EVALUATION_ONLY' AND v->>'network'='DENY' AND v->>'external_effects'='DENY'
 AND v->>'workspace_id'=b.expected_workspace_id::text AND v->>'model_digest' ~ '^[a-f0-9]{64}$'
 AND v->>'fixture_digest' ~ '^[a-f0-9]{64}$' AND v->>'profile_digest' ~ '^[a-f0-9]{64}$'
 AND v->>'negative_suite_digest' ~ '^[a-f0-9]{64}$' AND jsonb_typeof(v->'role_id')='string' AND length(v->>'role_id')>0
 AND jsonb_typeof(v->'required_positive_oracle_ids')='array' AND jsonb_array_length(v->'required_positive_oracle_ids')>0
 AND jsonb_typeof(v->'required_negative_oracle_ids')='array' AND jsonb_array_length(v->'required_negative_oracle_ids')>0) IS TRUE)
 OR NOT EXISTS(SELECT 1 FROM company.principals p WHERE p.tenant_id=b.expected_tenant_id AND p.id=(v->>'subject_principal_id')::uuid AND p.kind IN ('WORKER','VERIFIER'))
 THEN RAISE EXCEPTION 'INVALID_E0_ONLY_MANDATE_OR_SUBJECT'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements((v->'required_positive_oracle_ids')||(v->'required_negative_oracle_ids')) z
 WHERE jsonb_typeof(z) IS DISTINCT FROM 'string') THEN RAISE EXCEPTION 'INVALID_E0_ORACLE_ID_TYPE'; END IF;
 SELECT encode(sha256(convert_to(jsonb_agg(jsonb_build_array(g.grant_id,g.permission,g.valid_from,g.valid_until) ORDER BY g.grant_id)::text,'UTF8')),'hex') INTO gd FROM company.project_grants g WHERE g.tenant_id=b.expected_tenant_id AND g.project_id=b.expected_project_id;
 cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(b.expected_tenant_id,cmd,b.expected_human_id,'trusted_setup.consume','setup:'||b.installation_id::text||':'||b.generation::text,b.payload_digest,p_correlation,'RUNNING',NULL);
 INSERT INTO company.project_event_heads(tenant_id,project_id,writer_generation,committed_sequence,migration_manifest_digest) VALUES(b.expected_tenant_id,b.expected_project_id,54,0,b.setup_manifest_digest);
 UPDATE company_private.bootstrap_request_contexts SET r56_command_id=cmd,r56_grants_digest=gd WHERE backend_pid=x.backend_pid AND transaction_id=x.transaction_id AND context_nonce=p_nonce;
 RETURN cmd;
END $$;

CREATE OR REPLACE FUNCTION company_private.r56_bootstrap_finish(p_nonce uuid,p_command uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.bootstrap_request_contexts%ROWTYPE;b company_private.installation_bootstrap_control%ROWTYPE;c company.commands%ROWTYPE;
 proof jsonb;result jsonb;payload jsonb;d text;event_d text;aid bigint;n bigint;
BEGIN
 SELECT * INTO STRICT x FROM company_private.bootstrap_request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND context_nonce=p_nonce;
 SELECT * INTO STRICT b FROM company_private.installation_bootstrap_control WHERE installation_id=x.installation_id FOR UPDATE;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=b.expected_tenant_id AND id=p_command FOR UPDATE;
 SELECT committed_sequence INTO STRICT n FROM company.project_event_heads WHERE tenant_id=b.expected_tenant_id AND project_id=b.expected_project_id AND writer_generation=54 FOR UPDATE;
 IF b.state IS DISTINCT FROM 'ARMED' OR c.operation IS DISTINCT FROM 'trusted_setup.consume' OR c.state IS DISTINCT FROM 'RUNNING'
 OR c.principal_id IS DISTINCT FROM b.expected_human_id OR c.payload_digest IS DISTINCT FROM b.payload_digest
 OR x.r56_command_id IS DISTINCT FROM c.id OR x.r56_grants_digest IS NULL OR n<>0 THEN RAISE EXCEPTION 'BOOTSTRAP_FINALIZER_BINDING_MISMATCH'; END IF;
 PERFORM company_private.r56_bootstrap_final_proof(p_nonce,'AFTER_DOMAIN_LOCKS');
 -- Logical final authorization cut precedes immutable result sealing.
 -- Held authority locks serialize revoke until the transaction ends.
 proof=company_private.r56_bootstrap_final_proof(p_nonce,'COMMIT_CUT');
 result=jsonb_build_object('installation_id',b.installation_id,'generation',b.generation,'tenant_id',b.expected_tenant_id,'project_id',b.expected_project_id,
 'workspace_id',b.expected_workspace_id,'accepted_human_id',b.expected_human_id,'grants_digest',x.r56_grants_digest,'human_count',1,
 'source_revision','r56','e0_started',false,'ordinary_worker_authorized',false,'final_proof',proof);
 d=encode(sha256(convert_to(jsonb_build_array(c.id,c.payload_digest,b.installation_id,result)::text,'UTF8')),'hex');
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(b.expected_tenant_id,c.correlation_id,b.expected_human_id,'InstallationBootstrapped') RETURNING id INTO aid;
 payload=jsonb_build_object('command_id',c.id,'request_digest',c.payload_digest,'result_digest',d,'installation_id',b.installation_id,'source_revision','r56');
 event_d=encode(sha256(convert_to(jsonb_build_array(b.expected_project_id,0,'InstallationBootstrapped',payload)::text,'UTF8')),'hex');
 INSERT INTO company.outbox(tenant_id,project_id,aggregate_id,aggregate_revision,kind,payload,project_sequence,event_writer_generation,event_instance_id,event_digest)
 VALUES(b.expected_tenant_id,b.expected_project_id,b.expected_project_id,0,'InstallationBootstrapped',payload,1,54,c.id,event_d);
 UPDATE company.project_event_heads SET committed_sequence=1 WHERE tenant_id=b.expected_tenant_id AND project_id=b.expected_project_id AND committed_sequence=0 AND writer_generation=54;
 IF NOT FOUND THEN RAISE EXCEPTION 'BOOTSTRAP_EVENT_HEAD_CONFLICT'; END IF;
 UPDATE company.commands SET state='SUCCEEDED',result_ref=b.installation_id,r55_project_id=b.expected_project_id,r55_result_payload=result,
 r55_result_digest=d,r55_event_sequence=1,r55_audit_id=aid,r55_source_revision='r56' WHERE tenant_id=c.tenant_id AND id=c.id AND state='RUNNING';
 IF NOT FOUND THEN RAISE EXCEPTION 'BOOTSTRAP_COMMAND_CONFLICT'; END IF;
 INSERT INTO company_private.bootstrap_receipts(installation_id,generation,tenant_id,project_id,command_id,payload_digest,setup_manifest_digest,initial_grants_digest,accepted_human_id,
 e0_mandate,e0_valid_until,r56_final_proof,r56_result_digest)
 VALUES(b.installation_id,b.generation,b.expected_tenant_id,b.expected_project_id,c.id,b.payload_digest,b.setup_manifest_digest,x.r56_grants_digest,b.expected_human_id,
 x.r56_manifest->'e0_mandate',b.expires_at,proof,d);
 UPDATE company_private.installation_bootstrap_control SET state='CONSUMED',consumed_command_id=c.id WHERE installation_id=b.installation_id AND generation=b.generation AND state='ARMED';
 IF NOT FOUND THEN RAISE EXCEPTION 'BOOTSTRAP_CONSUME_CAS_CONFLICT'; END IF;
 -- Post-seal freshness is an additional abort check, never a discarded final proof.
 PERFORM company_private.r56_root_bounds(b.installation_id);
 RETURN jsonb_build_object('command_id',c.id,'state','SUCCEEDED','result_ref',b.installation_id,'receipt_digest',d,'spawned',false);
END $$;

CREATE OR REPLACE FUNCTION company_private.r56_bootstrap_invariant() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c company.commands%ROWTYPE;b company_private.bootstrap_receipts%ROWTYPE;
BEGIN
 IF NEW.operation IS DISTINCT FROM 'trusted_setup.consume' OR NEW.r55_source_revision IS DISTINCT FROM 'r56' THEN RETURN NULL; END IF;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=NEW.tenant_id AND id=NEW.id;
 SELECT * INTO STRICT b FROM company_private.bootstrap_receipts WHERE command_id=c.id AND tenant_id=c.tenant_id;
 IF c.state IS DISTINCT FROM 'SUCCEEDED' OR b.r56_result_digest IS DISTINCT FROM c.r55_result_digest
 OR b.r56_final_proof->>'phase' IS DISTINCT FROM 'COMMIT_CUT'
 OR b.r56_final_proof IS DISTINCT FROM c.r55_result_payload->'final_proof'
 OR b.r56_final_proof->>'installation_id' IS DISTINCT FROM b.installation_id::text
 OR b.r56_final_proof->>'generation' IS DISTINCT FROM b.generation::text
 OR b.r56_final_proof->>'manifest_digest' IS DISTINCT FROM b.payload_digest
 OR b.r56_result_digest IS DISTINCT FROM encode(sha256(convert_to(jsonb_build_array(c.id,c.payload_digest,b.installation_id,c.r55_result_payload)::text,'UTF8')),'hex')
 OR b.accepted_human_id IS DISTINCT FROM c.principal_id OR b.payload_digest IS DISTINCT FROM c.payload_digest
 OR NOT EXISTS(SELECT 1 FROM company_private.installation_bootstrap_control z WHERE z.installation_id=b.installation_id AND z.generation=b.generation AND z.state='CONSUMED' AND z.consumed_command_id=c.id)
 OR NOT EXISTS(SELECT 1 FROM company.audit_events a WHERE a.id=c.r55_audit_id AND a.tenant_id=c.tenant_id AND a.actor_id=c.principal_id AND a.correlation_id=c.correlation_id AND a.kind='InstallationBootstrapped')
 OR NOT EXISTS(SELECT 1 FROM company.outbox e WHERE e.tenant_id=c.tenant_id AND e.project_id=b.project_id AND e.project_sequence=1 AND e.event_instance_id=c.id AND e.event_writer_generation=54 AND e.payload->>'result_digest'=c.r55_result_digest AND e.kind='InstallationBootstrapped' AND e.aggregate_id=b.project_id AND e.aggregate_revision=0 AND e.payload->>'request_digest'=c.payload_digest AND e.event_digest=encode(sha256(convert_to(jsonb_build_array(e.aggregate_id,e.aggregate_revision,e.kind,e.payload)::text,'UTF8')),'hex'))
 THEN RAISE EXCEPTION 'BOOTSTRAP_ATOMIC_WITNESS_MISSING'; END IF;
 PERFORM company_private.r56_root_bounds(b.installation_id);
 RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION company_private.r56_bootstrap_consume(p_installation uuid,p_generation bigint,p_nonce bytea,p_raw bytea,p_tag bytea,p_key bytea,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE n uuid;cmd uuid;result jsonb;b company_private.bootstrap_receipts%ROWTYPE;ctl company_private.installation_bootstrap_control%ROWTYPE;
BEGIN
 IF p_correlation IS NULL THEN RAISE EXCEPTION 'BOOTSTRAP_CORRELATION_REQUIRED'; END IF;
 n=company_private.r56_bootstrap_enter(p_installation,p_generation,p_nonce,p_raw,p_tag,p_key);
 SELECT * INTO STRICT ctl FROM company_private.installation_bootstrap_control WHERE installation_id=p_installation;
 IF ctl.state='CONSUMED' THEN
  SELECT * INTO STRICT b FROM company_private.bootstrap_receipts WHERE installation_id=p_installation AND generation=p_generation AND payload_digest=ctl.payload_digest AND accepted_human_id=ctl.expected_human_id;
  IF b.r56_result_digest IS NULL OR b.r56_final_proof IS NULL
 OR b.r56_final_proof->>'phase' IS DISTINCT FROM 'COMMIT_CUT' OR NOT EXISTS(
   SELECT 1 FROM company.commands c JOIN company.audit_events a ON a.tenant_id=c.tenant_id AND a.id=c.r55_audit_id
   JOIN company.outbox e ON e.tenant_id=c.tenant_id AND e.project_id=b.project_id AND e.event_instance_id=c.id
   WHERE c.tenant_id=b.tenant_id AND c.id=b.command_id AND c.principal_id=b.accepted_human_id
   AND c.state='SUCCEEDED' AND c.result_ref=b.installation_id AND c.payload_digest=b.payload_digest
   AND c.r55_source_revision='r56' AND c.r55_result_digest=b.r56_result_digest
   AND c.r55_result_payload->'final_proof'=b.r56_final_proof
   AND b.r56_final_proof->>'installation_id'=b.installation_id::text
   AND b.r56_final_proof->>'generation'=b.generation::text
   AND b.r56_final_proof->>'manifest_digest'=b.payload_digest
   AND c.r55_result_digest=encode(sha256(convert_to(jsonb_build_array(c.id,c.payload_digest,b.installation_id,c.r55_result_payload)::text,'UTF8')),'hex')
   AND a.kind='InstallationBootstrapped' AND a.actor_id=c.principal_id AND a.correlation_id=c.correlation_id
   AND e.kind='InstallationBootstrapped' AND e.project_sequence=1 AND e.event_writer_generation=54
   AND e.payload->>'result_digest'=c.r55_result_digest AND e.aggregate_id=b.project_id AND e.aggregate_revision=0 AND e.payload->>'request_digest'=c.payload_digest AND e.event_digest=encode(sha256(convert_to(jsonb_build_array(e.aggregate_id,e.aggregate_revision,e.kind,e.payload)::text,'UTF8')),'hex'))
  THEN RAISE EXCEPTION 'BOOTSTRAP_REPLAY_WITNESS_MISSING_OR_LEGACY'; END IF;
  PERFORM company_private.r56_bootstrap_final_proof(n,'REPLAY_READ');
  result=jsonb_build_object('command_id',b.command_id,'state','SUCCEEDED','result_ref',b.installation_id,'receipt_digest',b.r56_result_digest,'outcome','REPLAY_NO_NEW_GRANT');
 ELSE
  cmd=company_private.r56_bootstrap_initial_write(n,p_correlation);
  result=company_private.r56_bootstrap_finish(n,cmd);
 END IF;
 -- Deferred witnesses must execute while the protected setup context exists.
 SET CONSTRAINTS company.r56_bootstrap_invariant IMMEDIATE;
 DELETE FROM company_private.bootstrap_request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND context_nonce=n;
 IF NOT FOUND THEN RAISE EXCEPTION 'BOOTSTRAP_EXIT_CONTEXT_LOST'; END IF;
 RETURN result;
END $$;

-- SOURCE sql/029_R57_NORMAL_COMMAND_FINALITY_OVERLAY.sql
GRANT UPDATE(state,result_ref) ON company.commands TO company_atomic_functions_r55;
CREATE OR REPLACE FUNCTION company.r50_command_identity_immutable() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF OLD.operation='trusted_setup.consume' AND OLD.state='RUNNING' AND OLD.r55_result_digest IS NULL
 AND NEW.state='SUCCEEDED' AND NEW.r55_source_revision='r56' THEN
  IF (to_jsonb(OLD)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
   IS DISTINCT FROM
   (to_jsonb(NEW)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
  OR NOT EXISTS(SELECT 1 FROM company_private.bootstrap_request_contexts x
   JOIN company_private.installation_bootstrap_control b ON b.installation_id=x.installation_id AND b.generation=x.generation
   WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user
   AND x.r56_command_id=OLD.id AND b.expected_tenant_id=OLD.tenant_id AND b.expected_human_id=OLD.principal_id
   AND b.expected_project_id=NEW.r55_project_id AND b.installation_id=NEW.result_ref
   AND b.state='ARMED' AND x.manifest_digest=OLD.payload_digest)
  THEN RAISE EXCEPTION 'IMMUTABLE_COMMAND_RECEIPT'; END IF;
 ELSIF OLD.operation IN ('objectives.create','plans.create','tasks.create','e0.process_proof_persist','e0.evaluation_envelope_persist','e0.process_admit','e0.process_stop_confirm','e0.process_reconcile','e0.process_release')
 AND OLD.state='RUNNING' AND OLD.result_ref IS NULL AND OLD.r55_result_digest IS NULL
 AND NEW.state='SUCCEEDED' AND NEW.r55_source_revision='r55-cp1' THEN
  IF current_user<>'company_atomic_functions_r55'
  OR (to_jsonb(OLD)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
   IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
  OR NOT EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid()
   AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.writer_generation=54
   AND x.tenant_id=OLD.tenant_id AND x.project_id=NEW.r55_project_id AND x.principal_id=OLD.principal_id AND x.operation_id=OLD.operation)
  THEN RAISE EXCEPTION 'IMMUTABLE_COMMAND_RECEIPT'; END IF;
 ELSE
  IF (to_jsonb(OLD)-'state'-'result_ref') IS DISTINCT FROM (to_jsonb(NEW)-'state'-'result_ref')
  OR (OLD.state IN ('SUCCEEDED','FAILED') AND ROW(OLD.state,OLD.result_ref) IS DISTINCT FROM ROW(NEW.state,NEW.result_ref))
  THEN RAISE EXCEPTION 'IMMUTABLE_COMMAND_RECEIPT'; END IF;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION company.r50_command_identity_immutable() FROM PUBLIC;

CREATE OR REPLACE FUNCTION company_private.r55_cp_finalize_command(p_command uuid,p_aggregate uuid,p_revision bigint,p_event_kind text,p_result_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; d text; seq bigint; aid bigint; perm text; event_payload jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 IF p_command IS NULL OR p_aggregate IS NULL OR p_revision IS NULL OR p_revision<0 OR p_result_payload IS NULL OR jsonb_typeof(p_result_payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'INVALID_RESULT_BINDING'; END IF;
 IF p_event_kind IS DISTINCT FROM company_private.r55_cp_event_kind(x.operation_id) OR company_private.r55_cp_event_kind(x.operation_id) IS NULL THEN RAISE EXCEPTION 'UNREGISTERED_FINALIZER_OPERATION'; END IF;
 SELECT permission INTO STRICT perm FROM company_private.operation_permissions WHERE operation_id=x.operation_id AND execution_class NOT IN ('QUERY','STREAM');
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_FINALIZE_COMMAND'; END IF;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=x.tenant_id AND id=p_command AND principal_id=x.principal_id AND operation=x.operation_id FOR UPDATE;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_FINALIZE_AFTER_LOCK_WAIT'; END IF;
 IF c.payload_digest IS NULL OR c.correlation_id IS NULL THEN RAISE EXCEPTION 'COMMAND_IDENTITY_INCOMPLETE'; END IF;
 d=encode(sha256(convert_to(jsonb_build_array(c.id,c.payload_digest,p_aggregate,p_revision,p_event_kind,p_result_payload,'r55-cp1')::text,'UTF8')),'hex');
 IF c.r55_result_digest IS NOT NULL THEN
  IF c.state IS DISTINCT FROM 'SUCCEEDED' OR c.result_ref IS DISTINCT FROM p_aggregate
   OR c.r55_result_digest IS DISTINCT FROM d OR c.r55_project_id IS DISTINCT FROM x.project_id
   OR c.r55_result_payload IS DISTINCT FROM p_result_payload OR c.r55_event_sequence IS NULL OR c.r55_audit_id IS NULL
   OR NOT EXISTS(SELECT 1 FROM company.audit_events a WHERE a.tenant_id=c.tenant_id AND a.id=c.r55_audit_id AND a.actor_id=c.principal_id AND a.correlation_id=c.correlation_id AND a.kind=p_event_kind)
   OR NOT EXISTS(SELECT 1 FROM company.outbox e WHERE e.tenant_id=c.tenant_id AND e.project_id=c.r55_project_id AND e.project_sequence=c.r55_event_sequence AND e.event_instance_id=c.id AND e.event_writer_generation=54 AND e.kind=p_event_kind AND e.payload->>'result_digest'=d AND e.payload->>'request_digest'=c.payload_digest) THEN RAISE EXCEPTION 'CONFLICT_RESULT_DIGEST'; END IF;
  RETURN jsonb_build_object('command_id',c.id,'correlation_id',c.correlation_id,'state',c.state,'result_ref',c.result_ref);
 END IF;
 IF c.state IS DISTINCT FROM 'RUNNING' OR c.result_ref IS NOT NULL THEN RAISE EXCEPTION 'UNSEALED_RUNNING_COMMAND_REQUIRED'; END IF;
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(x.tenant_id,c.correlation_id,x.principal_id,p_event_kind) RETURNING id INTO aid;
 event_payload=jsonb_build_object('command_id',c.id,'request_digest',c.payload_digest,'result_digest',d,'result_ref',p_aggregate,'source_revision','r55-cp1');
 seq=company_private.r55_cp_emit_event(x.tenant_id,x.project_id,c.id,p_aggregate,p_revision,p_event_kind,event_payload);
 UPDATE company.commands SET state='SUCCEEDED',result_ref=p_aggregate,r55_project_id=x.project_id,r55_result_payload=p_result_payload,r55_result_digest=d,r55_event_sequence=seq,r55_audit_id=aid,r55_source_revision='r55-cp1' WHERE tenant_id=c.tenant_id AND id=c.id AND state='RUNNING' AND result_ref IS NULL AND r55_result_digest IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'CONFLICT_RESULT_FINALIZATION'; END IF;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=x.tenant_id AND id=p_command;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_COMMAND_COMMIT_CUT'; END IF;
 RETURN jsonb_build_object('command_id',c.id,'correlation_id',c.correlation_id,'state',c.state,'result_ref',c.result_ref);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'COMMAND_OR_CONTEXT_UNRESOLVED';
END $$;
ALTER FUNCTION company_private.r55_cp_finalize_command(uuid,uuid,bigint,text,jsonb) OWNER TO company_atomic_functions_r55;
REVOKE ALL ON FUNCTION company_private.r55_cp_finalize_command(uuid,uuid,bigint,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_finalize_command(uuid,uuid,bigint,text,jsonb) TO company_first_run_functions_r53;


-- SOURCE sql/030_R57_CALLER_FINALITY_OVERLAY.sql
CREATE OR REPLACE FUNCTION company_private.r53_objectives_create(p_request jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; v_project uuid; v_correlation uuid;
 v_key text; v_digest text; v_id uuid; v_command uuid; v_revision bigint; element jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND operation_id='objectives.create';
 IF p_request IS NULL OR jsonb_typeof(p_request)<>'object' OR NOT (p_request ?& ARRAY['idempotency_key','correlation_id','project_id','goal','constraints','expected_outputs'])
 OR (SELECT count(*) FROM jsonb_object_keys(p_request))<>6 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 IF jsonb_typeof(p_request->'idempotency_key')<>'string' OR jsonb_typeof(p_request->'correlation_id')<>'string' OR jsonb_typeof(p_request->'project_id')<>'string'
 OR jsonb_typeof(p_request->'goal')<>'string' OR jsonb_typeof(p_request->'constraints')<>'array' OR jsonb_typeof(p_request->'expected_outputs')<>'array' THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 v_project=(p_request->>'project_id')::uuid; v_correlation=(p_request->>'correlation_id')::uuid; v_key=p_request->>'idempotency_key';
 IF v_project IS DISTINCT FROM x.project_id OR x.resource_kind<>'PROJECT' OR NOT company_private.r54_allowed(x.tenant_id,v_project,'objectives.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_CURRENT_AUTHORITY'; END IF;
 IF length(v_key) NOT BETWEEN 16 AND 128 OR v_key !~ '^[A-Za-z0-9_.:-]+$' OR length(p_request->>'goal') NOT BETWEEN 10 AND 4000
 OR jsonb_array_length(p_request->'constraints') NOT BETWEEN 1 AND 20 OR jsonb_array_length(p_request->'expected_outputs') NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 FOR element IN SELECT value FROM jsonb_array_elements((p_request->'constraints')||(p_request->'expected_outputs')) LOOP
  IF jsonb_typeof(element)<>'string' OR length(element#>>'{}') NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 END LOOP;
 -- Server-owned profile PG_JSONB_TEXT_UTF8_R53; JCS veya caller digest iddiası yok.
 -- correlation_id semantik payload dışıdır: replay ilk correlation id'yi döndürür.
 v_digest=encode(sha256(convert_to((p_request-'correlation_id'-'idempotency_key')::text,'UTF8')),'hex');
 -- Project authority advisory lock context enter'da alınmıştır; row lock bundan sonra.
 SELECT revision INTO STRICT v_revision FROM company.projects WHERE tenant_id=x.tenant_id AND id=v_project FOR UPDATE;
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation='objectives.create' AND idempotency_key=v_key;
 IF FOUND THEN
  IF c.payload_digest<>v_digest THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  IF c.r55_result_payload IS NULL OR c.r55_result_payload->>'project_revision' IS NULL THEN RAISE EXCEPTION 'BLOCKED_LEGACY_UNFINALIZED_COMMAND'; END IF;
  RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,(c.r55_result_payload->>'project_revision')::bigint,'ObjectiveCreated',c.r55_result_payload);
 END IF;
 v_id=gen_random_uuid(); v_command=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,v_command,x.principal_id,'objectives.create',v_key,v_digest,v_correlation,'RUNNING',NULL);
 INSERT INTO company.objectives(tenant_id,project_id,id,goal,constraints,expected_outputs,created_by)
 VALUES(x.tenant_id,v_project,v_id,p_request->>'goal',p_request->'constraints',p_request->'expected_outputs',x.principal_id);
 UPDATE company.projects SET revision=revision+1 WHERE tenant_id=x.tenant_id AND id=v_project AND revision=v_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_PROJECT'; END IF;
 PERFORM company_private.r55_cp_finalize_command(v_command,v_id,v_revision+1,'ObjectiveCreated',jsonb_build_object('objective_id',v_id,'project_revision',v_revision+1));
 IF NOT company_private.r54_allowed(x.tenant_id,v_project,'objectives.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_COMMIT_CUT'; END IF;
 RETURN jsonb_build_object('command_id',v_command,'correlation_id',v_correlation,'state','SUCCEEDED','result_ref',v_id);
EXCEPTION WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST';
WHEN INVALID_TEXT_REPRESENTATION THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING';
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_plans_create(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; pid uuid; parent_id uuid; rid uuid; cid uuid; correlation uuid; k text; d text; rev bigint; dep uuid;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND operation_id='plans.create';
 IF q IS NULL OR jsonb_typeof(q)<>'object' OR NOT(q ?& ARRAY['idempotency_key','correlation_id','project_id','objective_id','expected_revision','assumptions','acceptance_criteria']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(q) key WHERE key<>ALL(ARRAY['idempotency_key','correlation_id','project_id','objective_id','expected_revision','assumptions','acceptance_criteria'])) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 pid=(q->>'project_id')::uuid; parent_id=(q->>'objective_id')::uuid; correlation=(q->>'correlation_id')::uuid; k=q->>'idempotency_key';
 IF pid IS DISTINCT FROM x.project_id OR x.task_id IS NOT NULL OR k IS NULL OR k !~ '^[A-Za-z0-9_.:-]{16,128}$' OR NOT company_private.r54_allowed(x.tenant_id,pid,'plans.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_CURRENT_AUTHORITY'; END IF;
 IF jsonb_typeof(q->'acceptance_criteria') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF jsonb_array_length(q->'acceptance_criteria') NOT BETWEEN 1 AND 20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'acceptance_criteria') e WHERE jsonb_typeof(e)<>'string' OR length(e#>>'{}') NOT BETWEEN 1 AND 2000) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 d=encode(sha256(convert_to((q-'correlation_id'-'idempotency_key')::text,'UTF8')),'hex');
 SELECT revision INTO STRICT rev FROM company.projects WHERE tenant_id=x.tenant_id AND id=pid FOR UPDATE;
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation='plans.create' AND idempotency_key=k;
 IF FOUND THEN
  IF c.payload_digest<>d THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  IF c.r55_result_payload IS NULL THEN RAISE EXCEPTION 'BLOCKED_LEGACY_UNFINALIZED_COMMAND'; END IF;
  RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,0,'PlanCreated',c.r55_result_payload);
 END IF;
 PERFORM 1 FROM company.objectives WHERE tenant_id=x.tenant_id AND project_id=pid AND id=parent_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PARENT_NOT_FOUND_OR_DENIED'; END IF;
 IF jsonb_typeof(q->'expected_revision') IS DISTINCT FROM 'number' OR (q->>'expected_revision') !~ '^[0-9]+$' OR (q->>'expected_revision')::bigint<>rev THEN RAISE EXCEPTION 'STALE_PROJECT_REVISION'; END IF;
 IF jsonb_typeof(q->'assumptions') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF jsonb_array_length(q->'assumptions')>20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'assumptions') e WHERE jsonb_typeof(e)<>'string' OR length(e#>>'{}') NOT BETWEEN 1 AND 2000) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 rid=gen_random_uuid(); cid=gen_random_uuid();
 INSERT INTO company.plans(tenant_id,project_id,id,objective_id,revision,assumptions,acceptance_criteria) VALUES(x.tenant_id,pid,rid,parent_id,0,q->'assumptions',q->'acceptance_criteria');
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref) VALUES(x.tenant_id,cid,x.principal_id,'plans.create',k,d,correlation,'RUNNING',NULL);
 UPDATE company.projects SET revision=revision+1 WHERE tenant_id=x.tenant_id AND id=pid AND revision=rev;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_PROJECT_REVISION'; END IF;
 PERFORM company_private.r55_cp_finalize_command(cid,rid,0,'PlanCreated',jsonb_build_object('resource_id',rid,'project_revision',rev+1));
 IF NOT company_private.r54_allowed(x.tenant_id,pid,'plans.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_COMMIT_CUT'; END IF;
 RETURN jsonb_build_object('command_id',cid,'correlation_id',correlation,'state','SUCCEEDED','result_ref',rid);
EXCEPTION WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING';
 WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST';
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_tasks_create(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; pid uuid; parent_id uuid; rid uuid; cid uuid; correlation uuid; k text; d text; rev bigint; dep uuid;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND operation_id='tasks.create';
 IF q IS NULL OR jsonb_typeof(q)<>'object' OR NOT(q ?& ARRAY['idempotency_key','correlation_id','project_id','plan_id','title','role_id','acceptance_criteria']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(q) key WHERE key<>ALL(ARRAY['idempotency_key','correlation_id','project_id','plan_id','title','role_id','acceptance_criteria','depends_on'])) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 pid=(q->>'project_id')::uuid; parent_id=(q->>'plan_id')::uuid; correlation=(q->>'correlation_id')::uuid; k=q->>'idempotency_key';
 IF pid IS DISTINCT FROM x.project_id OR x.task_id IS NOT NULL OR k IS NULL OR k !~ '^[A-Za-z0-9_.:-]{16,128}$' OR NOT company_private.r54_allowed(x.tenant_id,pid,'tasks.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_CURRENT_AUTHORITY'; END IF;
 IF jsonb_typeof(q->'acceptance_criteria') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF jsonb_array_length(q->'acceptance_criteria') NOT BETWEEN 1 AND 20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'acceptance_criteria') e WHERE jsonb_typeof(e)<>'string' OR length(e#>>'{}') NOT BETWEEN 1 AND 2000) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 d=encode(sha256(convert_to((q-'correlation_id'-'idempotency_key')::text,'UTF8')),'hex');
 SELECT revision INTO STRICT rev FROM company.projects WHERE tenant_id=x.tenant_id AND id=pid FOR UPDATE;
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation='tasks.create' AND idempotency_key=k;
 IF FOUND THEN
  IF c.payload_digest<>d THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  IF c.r55_result_payload IS NULL THEN RAISE EXCEPTION 'BLOCKED_LEGACY_UNFINALIZED_COMMAND'; END IF;
  RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,0,'TaskCreated',c.r55_result_payload);
 END IF;
 PERFORM 1 FROM company.plans WHERE tenant_id=x.tenant_id AND project_id=pid AND id=parent_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PARENT_NOT_FOUND_OR_DENIED'; END IF;
 IF jsonb_typeof(q->'title') IS DISTINCT FROM 'string' OR length(q->>'title') NOT BETWEEN 3 AND 200 OR jsonb_typeof(q->'role_id') IS DISTINCT FROM 'string' OR (q->>'role_id') !~ '^(MGR|EXP)-[0-9]{2,3}$' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF q ? 'depends_on' THEN
  IF jsonb_typeof(q->'depends_on') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
  IF jsonb_array_length(q->'depends_on')>32 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'depends_on') e WHERE jsonb_typeof(e)<>'string') OR (SELECT count(*)<>count(DISTINCT value) FROM jsonb_array_elements_text(q->'depends_on')) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 END IF;
 rid=gen_random_uuid(); cid=gen_random_uuid();
 INSERT INTO company.tasks(tenant_id,project_id,id,plan_id,title,role_id,state,revision,fencing_epoch,acceptance_criteria) VALUES(x.tenant_id,pid,rid,parent_id,q->>'title',q->>'role_id','DRAFT',0,0,q->'acceptance_criteria');
 -- Existing dependency rows cannot point to a not-yet-created rid; only outgoing edges added => no cycle introduced.
 FOR dep IN SELECT value::uuid FROM jsonb_array_elements_text(COALESCE(q->'depends_on','[]'::jsonb)) ORDER BY value LOOP
  PERFORM 1 FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=pid AND id=dep;
  IF NOT FOUND THEN RAISE EXCEPTION 'DEPENDENCY_NOT_FOUND_OR_DENIED'; END IF;
  INSERT INTO company.task_dependencies(tenant_id,project_id,task_id,depends_on_task_id) VALUES(x.tenant_id,pid,rid,dep);
 END LOOP;
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref) VALUES(x.tenant_id,cid,x.principal_id,'tasks.create',k,d,correlation,'RUNNING',NULL);
 UPDATE company.projects SET revision=revision+1 WHERE tenant_id=x.tenant_id AND id=pid AND revision=rev;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_PROJECT_REVISION'; END IF;
 PERFORM company_private.r55_cp_finalize_command(cid,rid,0,'TaskCreated',jsonb_build_object('resource_id',rid,'project_revision',rev+1));
 IF NOT company_private.r54_allowed(x.tenant_id,pid,'tasks.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_COMMIT_CUT'; END IF;
 RETURN jsonb_build_object('command_id',cid,'correlation_id',correlation,'state','SUCCEEDED','result_ref',rid);
EXCEPTION WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING';
 WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST';
END $$;

CREATE OR REPLACE FUNCTION company_private.r55_cp_persist_process_proof(p_artifact uuid,p_raw jsonb,p_envelope jsonb,p_key_material bytea,p_idempotency text,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; e company.evaluation_runs%ROWTYPE; pr company.process_runs%ROWTYPE; en company.signer_enrollments%ROWTYPE; b company_private.bootstrap_receipts%ROWTYPE; c company.commands%ROWTYPE;
 profile text; fields text[]; issuer uuid; task_id uuid; attempt_id uuid; rid uuid; cmd uuid; digest text; binding text; envelope_digest text; request_digest text; raw bytea; tag bytea; item text; n bigint; verified company.artifacts%ROWTYPE;
BEGIN
 IF NOT pg_has_role(session_user,'company_receipt_ingest_r55','MEMBER') THEN RAISE EXCEPTION 'TRUSTED_RECEIPT_INGEST_REQUIRED'; END IF;
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54 AND operation_id='e0.process_proof_persist';
 IF p_artifact IS NULL OR p_raw IS NULL OR jsonb_typeof(p_raw) IS DISTINCT FROM 'object' OR p_envelope IS NULL OR jsonb_typeof(p_envelope) IS DISTINCT FROM 'object'
 OR p_key_material IS NULL OR octet_length(p_key_material)<>32 OR p_idempotency IS NULL OR p_idempotency !~ '^[A-Za-z0-9_.:-]{16,128}$' OR p_correlation IS NULL THEN RAISE EXCEPTION 'INVALID_PROCESS_PROOF_INPUT'; END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'e0.process_proof_persist',x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_PROCESS_PROOF_AUTHORITY'; END IF;
 profile=p_raw->>'profile';
 IF profile IS NULL OR profile NOT IN ('r55.e0-process-admission.pg-jsonb.v1','r55.e0-process-observation.pg-jsonb.v1') THEN RAISE EXCEPTION 'PROCESS_PROOF_PROFILE_NOT_ALLOWED'; END IF;
 fields=ARRAY['tenant_id','issuer_id','key_id','purpose','profile_id','enrollment_revision','receipt_id','canonical_artifact_digest','expected_binding_digest','envelope_digest','auth_tag'];
 IF NOT(p_envelope ?& fields) OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_envelope) k WHERE k<>ALL(fields)) OR NOT((p_envelope->>'tenant_id'=x.tenant_id::text
 AND p_envelope->>'issuer_id'=x.principal_id::text AND p_envelope->>'purpose'='EVALUATION' AND p_envelope->>'profile_id'=profile
 AND jsonb_typeof(p_envelope->'enrollment_revision')='number' AND p_envelope->>'enrollment_revision' ~ '^[0-9]+$' AND p_envelope->>'auth_tag' ~ '^[A-Za-z0-9_-]{43}$') IS TRUE)
 THEN RAISE EXCEPTION 'PROCESS_PROOF_ENROLLMENT_BINDING_INVALID'; END IF;
 rid=(p_envelope->>'receipt_id')::uuid;
 PERFORM 1 FROM company.projects WHERE tenant_id=x.tenant_id AND id=x.project_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PROCESS_PROOF_PROJECT_UNRESOLVED'; END IF;
 IF profile='r55.e0-process-admission.pg-jsonb.v1' THEN
  SELECT * INTO STRICT e FROM company.evaluation_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=(p_raw->>'evaluation_run_id')::uuid FOR SHARE;
  SELECT * INTO STRICT b FROM company_private.bootstrap_receipts WHERE installation_id=e.e0_installation_id AND tenant_id=e.tenant_id AND project_id=e.project_id;
  issuer=b.accepted_human_id; task_id=e.evaluation_task_id; attempt_id=e.evaluation_attempt_id;
  binding=encode(sha256(convert_to(jsonb_build_array(x.tenant_id,x.project_id,e.id,e.evaluation_task_id,e.evaluation_attempt_id,p_artifact)::text,'UTF8')),'hex');
 ELSE
  SELECT * INTO STRICT pr FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=(p_raw->>'process_run_id')::uuid FOR SHARE;
  IF pr.e0_evaluation_run_id IS NULL OR pr.qualification_id IS NOT NULL THEN RAISE EXCEPTION 'E0_PROCESS_PROOF_ONLY'; END IF;
  issuer=pr.controller_id;task_id=pr.task_id;attempt_id=pr.attempt_id;
  binding=encode(sha256(convert_to(jsonb_build_array(pr.tenant_id,pr.project_id,pr.id,pr.task_id,pr.attempt_id,pr.attempt_fencing_epoch,pr.host_registration_id,pr.host_registration_revision,pr.host_generation,pr.r55_host_boot_id,pr.controller_id,pr.controller_generation,pr.manifest_digest)::text,'UTF8')),'hex');
 END IF;
 IF issuer IS NULL OR issuer IS DISTINCT FROM x.principal_id OR p_raw->>'tenant_id' IS DISTINCT FROM x.tenant_id::text OR p_raw->>'project_id' IS DISTINCT FROM x.project_id::text
 OR p_raw->>'task_id' IS DISTINCT FROM task_id::text OR p_raw->>'attempt_id' IS DISTINCT FROM attempt_id::text THEN RAISE EXCEPTION 'PROCESS_PROOF_ISSUER_OR_SCOPE_INVALID'; END IF;
 SELECT * INTO STRICT en FROM company.signer_enrollments WHERE tenant_id=x.tenant_id AND issuer_id=issuer AND key_id=(p_envelope->>'key_id')::uuid AND purpose='EVALUATION' AND profile_id=profile AND enrollment_revision=(p_envelope->>'enrollment_revision')::bigint FOR SHARE;
 IF en.revoked_at IS NOT NULL OR en.compromised_since IS NOT NULL OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,en.valid_from,en.valid_until) IS NOT TRUE OR en.key_fingerprint IS DISTINCT FROM encode(sha256(p_key_material),'hex')
 OR NOT EXISTS(SELECT 1 FROM company.principals hp WHERE hp.tenant_id=en.tenant_id AND hp.id=en.approved_by AND hp.kind='HUMAN') THEN RAISE EXCEPTION 'DENIED_PROCESS_PROOF_CURRENT_ENROLLMENT'; END IF;
 digest=encode(sha256(convert_to(p_raw::text,'UTF8')),'hex'); n=octet_length(convert_to(p_raw::text,'UTF8'));
 IF n>52428800 OR digest IS DISTINCT FROM p_envelope->>'canonical_artifact_digest' OR binding IS DISTINCT FROM p_envelope->>'expected_binding_digest' THEN RAISE EXCEPTION 'PROCESS_PROOF_DIGEST_BINDING_INVALID'; END IF;
 raw=convert_to('R54-EVALUATION-v1','UTF8')||decode('00','hex');
 FOREACH item IN ARRAY ARRAY[x.tenant_id::text,issuer::text,en.key_id::text,'EVALUATION',profile,en.enrollment_revision::text,rid::text,digest,binding] LOOP
  raw=raw||convert_to(octet_length(convert_to(item,'UTF8'))::text||':'||item,'UTF8');
 END LOOP;
 envelope_digest=encode(sha256(raw),'hex');tag=decode(translate(p_envelope->>'auth_tag','-_','+/')||'=','base64');
 IF envelope_digest IS DISTINCT FROM p_envelope->>'envelope_digest' OR company_private.r55_cp_tag_equal(company_private.r55_cp_hmac_sha256(p_key_material,raw),tag) IS DISTINCT FROM true THEN RAISE EXCEPTION 'INVALID_PROCESS_PROOF_HMAC'; END IF;
 request_digest=encode(sha256(convert_to(jsonb_build_array(p_artifact,p_raw,p_envelope)::text,'UTF8')),'hex');
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation=x.operation_id AND idempotency_key=p_idempotency;
 IF FOUND THEN
  IF c.payload_digest IS DISTINCT FROM request_digest OR c.r55_project_id IS DISTINCT FROM x.project_id OR c.r55_result_payload IS NULL THEN RAISE EXCEPTION 'CONFLICT_PROCESS_PROOF_IDEMPOTENCY'; END IF;
  RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,0,'E0ProcessProofPersisted',c.r55_result_payload);
 END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'e0.process_proof_persist',x.task_id,true) IS DISTINCT FROM true OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,en.valid_from,en.valid_until) IS NOT TRUE THEN RAISE EXCEPTION 'DENIED_PROCESS_PROOF_INSERT_CUT'; END IF;
 INSERT INTO company.artifacts(tenant_id,project_id,task_id,attempt_id,id,storage_key,sha256,size_bytes,state,r55_e0_process_manifest,r55_e0_process_observation)
 VALUES(x.tenant_id,x.project_id,task_id,attempt_id,p_artifact,gen_random_uuid(),digest,n,'AVAILABLE',CASE WHEN profile='r55.e0-process-admission.pg-jsonb.v1' THEN p_raw ELSE NULL END,CASE WHEN profile='r55.e0-process-observation.pg-jsonb.v1' THEN p_raw ELSE NULL END);
 INSERT INTO company.internal_receipt_envelopes(tenant_id,issuer_id,key_id,purpose,enrollment_revision,receipt_id,profile_id,envelope_digest,expected_binding_digest,canonical_artifact_digest,auth_tag,verified_at)
 VALUES(x.tenant_id,issuer,en.key_id,'EVALUATION',en.enrollment_revision,rid,profile,envelope_digest,binding,digest,p_envelope->>'auth_tag',clock_timestamp());
 verified=company_private.r55_cp_e0_verified_artifact(x.tenant_id,x.project_id,task_id,attempt_id,p_artifact,rid,profile,issuer,binding);
 cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,cmd,x.principal_id,x.operation_id,p_idempotency,request_digest,p_correlation,'RUNNING',NULL);
 RETURN company_private.r55_cp_finalize_command(cmd,p_artifact,0,'E0ProcessProofPersisted',jsonb_build_object('artifact_id',p_artifact,'receipt_id',rid,'profile',profile,'sha256',digest));
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'PROCESS_PROOF_CANONICAL_SOURCE_UNRESOLVED';
 WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_PROCESS_PROOF_TYPED_BINDING';
 WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_PROCESS_PROOF_IDENTITY';
END $$;

CREATE OR REPLACE FUNCTION company_private.r55_cp_persist_evaluation_envelope(p_evaluation uuid,p_binding jsonb,p_envelope jsonb,p_key_material bytea,p_idempotency text,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; e company.evaluation_runs%ROWTYPE; ev company.evidence%ROWTYPE; v company.verification_runs%ROWTYPE; a company.artifacts%ROWTYPE; en company.signer_enrollments%ROWTYPE; old company.internal_receipt_envelopes%ROWTYPE; cmd company.commands%ROWTYPE;
 raw bytea; tag bytea; item text; binding_digest text; artifact_digest text; envelope_digest text; request_digest text; rid uuid; cid uuid; revision bigint; fields text[]; now_at timestamptz;
BEGIN
 IF NOT pg_has_role(session_user,'company_receipt_ingest_r55','MEMBER') THEN RAISE EXCEPTION 'TRUSTED_RECEIPT_INGEST_REQUIRED'; END IF;
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54 AND operation_id='e0.evaluation_envelope_persist';
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'e0.evaluation_envelope_persist',x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_RECEIPT_AUTHORITY'; END IF;
 fields=ARRAY['tenant_id','issuer_id','key_id','purpose','profile_id','enrollment_revision','receipt_id','canonical_artifact_digest','expected_binding_digest','envelope_digest','auth_tag'];
 IF p_binding IS NULL OR jsonb_typeof(p_binding) IS DISTINCT FROM 'object' OR p_envelope IS NULL OR jsonb_typeof(p_envelope) IS DISTINCT FROM 'object' OR NOT(p_envelope ?& fields) OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_envelope) k WHERE k<>ALL(fields))
 OR p_key_material IS NULL OR octet_length(p_key_material)<>32 OR p_idempotency IS NULL OR p_idempotency !~ '^[A-Za-z0-9_.:-]{16,128}$' OR p_correlation IS NULL THEN RAISE EXCEPTION 'INVALID_RECEIPT_INPUT'; END IF;
 IF NOT ((p_envelope->>'tenant_id'=x.tenant_id::text AND p_envelope->>'issuer_id'=x.principal_id::text AND p_envelope->>'purpose'='EVALUATION' AND p_envelope->>'profile_id'='r54.evaluation-report.pg-jsonb.v1'
 AND jsonb_typeof(p_envelope->'enrollment_revision')='number' AND p_envelope->>'enrollment_revision' ~ '^[0-9]+$' AND p_envelope->>'auth_tag' ~ '^[A-Za-z0-9_-]{43}$') IS TRUE) THEN RAISE EXCEPTION 'WRONG_ENROLLMENT_BINDING'; END IF;
 PERFORM company_private.r54_schema_check(p_binding,'{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"schema_version":{"const":"r53.execution-binding.v1"},"subject_principal_id":{"type":"string","format":"uuid"},"role_definition":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"agent_profile":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"model":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"engine":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"tools":{"type":"array","items":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"minItems":1,"uniqueItems":true},"suite":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"policy":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"resource_scope":{"type":"object","properties":{"tenant_id":{"type":"string","format":"uuid"},"project_id":{"type":"string","format":"uuid"},"workspace_id":{"type":"string","format":"uuid"}},"required":["tenant_id","project_id","workspace_id"],"additionalProperties":false},"independent_evidence":{"type":"object","properties":{"task_id":{"type":"string","format":"uuid"},"attempt_id":{"type":"string","format":"uuid"},"evidence_id":{"type":"string","format":"uuid"},"verification_run_id":{"type":"string","format":"uuid"},"producer_id":{"type":"string","format":"uuid"},"verifier_id":{"type":"string","format":"uuid"},"artifact_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["task_id","attempt_id","evidence_id","verification_run_id","producer_id","verifier_id","artifact_sha256"],"additionalProperties":false},"source_revision":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["schema_version","subject_principal_id","role_definition","agent_profile","model","engine","tools","suite","policy","resource_scope","independent_evidence","source_revision"],"additionalProperties":false}'::jsonb);
 revision=(p_envelope->>'enrollment_revision')::bigint; rid=(p_envelope->>'receipt_id')::uuid;
 -- Domain project row precedes enrollment locks, command and event-head locks.
 PERFORM 1 FROM company.projects WHERE tenant_id=x.tenant_id AND id=x.project_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RECEIPT_PROJECT_UNRESOLVED'; END IF;
 -- Lock enrollment through commit so revoke/rotation cannot race verified INSERT.
 SELECT * INTO STRICT en FROM company.signer_enrollments WHERE tenant_id=x.tenant_id AND issuer_id=x.principal_id AND key_id=(p_envelope->>'key_id')::uuid AND purpose='EVALUATION' AND enrollment_revision=revision AND profile_id='r54.evaluation-report.pg-jsonb.v1' FOR SHARE;
 now_at=clock_timestamp();
 IF en.revoked_at IS NOT NULL OR en.compromised_since IS NOT NULL OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,en.valid_from,en.valid_until) IS NOT TRUE
 OR en.key_fingerprint IS DISTINCT FROM encode(sha256(p_key_material),'hex') OR NOT EXISTS(SELECT 1 FROM company.principals hp WHERE hp.tenant_id=en.tenant_id AND hp.id=en.approved_by AND hp.kind='HUMAN') THEN RAISE EXCEPTION 'DENIED_CURRENT_SIGNER_ENROLLMENT'; END IF;
 SELECT * INTO STRICT e FROM company.evaluation_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_evaluation FOR SHARE;
 SELECT * INTO STRICT ev FROM company.evidence WHERE tenant_id=e.tenant_id AND project_id=e.project_id AND task_id=e.evaluation_task_id AND attempt_id=e.evaluation_attempt_id AND id=(p_binding#>>'{independent_evidence,evidence_id}')::uuid FOR SHARE;
 SELECT * INTO STRICT v FROM company.verification_runs WHERE tenant_id=ev.tenant_id AND project_id=ev.project_id AND task_id=ev.task_id AND attempt_id=ev.attempt_id AND id=ev.verification_run_id FOR SHARE;
 SELECT * INTO STRICT a FROM company.artifacts WHERE tenant_id=ev.tenant_id AND project_id=ev.project_id AND task_id=ev.task_id AND attempt_id=ev.attempt_id AND id=ev.artifact_id FOR SHARE;
 IF NOT((v.producer_id=e.subject_principal_id AND v.verifier_id=x.principal_id AND v.producer_id<>v.verifier_id AND a.state='AVAILABLE' AND a.r54_evaluation_report IS NOT NULL AND a.r54_evaluation_report->>'receipt_id'=rid::text AND ev.command_receipt IS NOT NULL) IS TRUE) THEN RAISE EXCEPTION 'DENIED_CANONICAL_REPORT_BINDING'; END IF;
 artifact_digest=encode(sha256(convert_to(a.r54_evaluation_report::text,'UTF8')),'hex');
 binding_digest=encode(sha256(convert_to(p_binding::text,'UTF8')),'hex');
 IF artifact_digest IS DISTINCT FROM a.sha256 OR artifact_digest IS DISTINCT FROM p_envelope->>'canonical_artifact_digest' OR binding_digest IS DISTINCT FROM p_envelope->>'expected_binding_digest' THEN RAISE EXCEPTION 'WRONG_REPORT_BINDING'; END IF;
 raw=convert_to('R54-EVALUATION-v1','UTF8')||decode('00','hex');
 FOREACH item IN ARRAY ARRAY[x.tenant_id::text,x.principal_id::text,en.key_id::text,'EVALUATION',en.profile_id,revision::text,rid::text,artifact_digest,binding_digest] LOOP
  raw=raw||convert_to(octet_length(convert_to(item,'UTF8'))::text||':'||item,'UTF8');
 END LOOP;
 envelope_digest=encode(sha256(raw),'hex');
 tag=decode(translate(p_envelope->>'auth_tag','-_','+/')||'=','base64');
 IF envelope_digest IS DISTINCT FROM p_envelope->>'envelope_digest' OR company_private.r55_cp_tag_equal(company_private.r55_cp_hmac_sha256(p_key_material,raw),tag) IS DISTINCT FROM true THEN RAISE EXCEPTION 'INVALID_ENVELOPE_HMAC'; END IF;
 request_digest=encode(sha256(convert_to(jsonb_build_array(p_evaluation,p_envelope,p_binding)::text,'UTF8')),'hex');
 -- Shared project row serializes idempotency before INSERT, not global outbox IDs.
 SELECT * INTO cmd FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation=x.operation_id AND idempotency_key=p_idempotency;
 IF FOUND THEN
  IF cmd.payload_digest IS DISTINCT FROM request_digest OR cmd.r55_project_id IS DISTINCT FROM x.project_id OR cmd.r55_result_digest IS NULL THEN RAISE EXCEPTION 'CONFLICT_RECEIPT_COMMAND'; END IF;
  IF company_private.r54_allowed(x.tenant_id,x.project_id,'e0.evaluation_envelope_persist',x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_RECEIPT_REPLAY_CUT'; END IF;
  RETURN jsonb_build_object('command_id',cmd.id,'correlation_id',cmd.correlation_id,'state',cmd.state,'result_ref',cmd.result_ref);
 END IF;
 SELECT * INTO old FROM company.internal_receipt_envelopes WHERE tenant_id=x.tenant_id AND receipt_id=rid;
 IF FOUND THEN RAISE EXCEPTION 'RECEIPT_ID_ALREADY_PERSISTED_DIFFERENT_COMMAND'; END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'e0.evaluation_envelope_persist',x.task_id,true) IS DISTINCT FROM true OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,en.valid_from,en.valid_until) IS NOT TRUE THEN RAISE EXCEPTION 'DENIED_RECEIPT_AFTER_LOCK_WAIT'; END IF;
 INSERT INTO company.internal_receipt_envelopes(tenant_id,issuer_id,key_id,purpose,enrollment_revision,receipt_id,profile_id,envelope_digest,expected_binding_digest,canonical_artifact_digest,auth_tag,verified_at)
 VALUES(x.tenant_id,x.principal_id,en.key_id,'EVALUATION',revision,rid,en.profile_id,envelope_digest,binding_digest,artifact_digest,p_envelope->>'auth_tag',clock_timestamp());
 INSERT INTO company.verifier_receipts(tenant_id,project_id,task_id,attempt_id,id,purpose,signer_id,key_id,receipt_digest,signature)
 VALUES(x.tenant_id,x.project_id,e.evaluation_task_id,e.evaluation_attempt_id,rid,'EVALUATION',x.principal_id,en.key_id,envelope_digest,p_envelope->>'auth_tag');
 cid=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,cid,x.principal_id,x.operation_id,p_idempotency,request_digest,p_correlation,'RUNNING',NULL);
 RETURN company_private.r55_cp_finalize_command(cid,rid,0,'E0EnvelopePersisted',jsonb_build_object('receipt_id',rid,'envelope_digest',envelope_digest,'verified_profile',en.profile_id));
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'RECEIPT_CANONICAL_SOURCE_UNRESOLVED';
 WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_RECEIPT_TYPED_BINDING';
END $$;

-- SOURCE sql/031_R57_E0_PROCESS_CALLER_FINALITY_OVERLAY.sql
CREATE FUNCTION company_private.r57_replay_command(p_command uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;c company.commands%ROWTYPE;e company.outbox%ROWTYPE;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=x.tenant_id AND id=p_command AND principal_id=x.principal_id AND operation=x.operation_id;
 SELECT * INTO STRICT e FROM company.outbox WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND event_instance_id=c.id AND project_sequence=c.r55_event_sequence;
 RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,e.aggregate_revision,e.kind,c.r55_result_payload);
END $$;
ALTER FUNCTION company_private.r57_replay_command(uuid) OWNER TO company_atomic_functions_r55;
REVOKE ALL ON FUNCTION company_private.r57_replay_command(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r57_replay_command(uuid) TO company_e0_process_functions_r55;
CREATE OR REPLACE FUNCTION company_private.r55_cp_e0_process_admit(
 p_evaluation uuid,p_manifest uuid,p_receipt uuid,p_key text,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE final_result jsonb; x company_private.request_contexts%ROWTYPE; e company.evaluation_runs%ROWTYPE;
 b company_private.bootstrap_receipts%ROWTYPE; t company.tasks%ROWTYPE; at company.attempts%ROWTYPE;
 art company.artifacts%ROWTYPE; v company.budget_versions%ROWTYPE; h company.host_registrations%ROWTYPE;
 c company.commands%ROWTYPE; sl company.resource_slots%ROWTYPE; m jsonb; item jsonb;
 d text; bind text; exposure numeric; process uuid; reservation uuid; cmd uuid; n integer;
BEGIN
 x=company_private.r54_b_context('e0.process_admit',true,true);
 IF p_evaluation IS NULL OR p_manifest IS NULL OR p_receipt IS NULL OR p_correlation IS NULL
 OR p_key IS NULL OR length(p_key) NOT BETWEEN 16 AND 128 THEN RAISE EXCEPTION 'INVALID_PROCESS_ADMISSION'; END IF;
 SELECT * INTO STRICT e FROM company.evaluation_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_evaluation;
 SELECT * INTO STRICT b FROM company_private.bootstrap_receipts WHERE installation_id=e.e0_installation_id;
 bind=encode(sha256(convert_to(jsonb_build_array(x.tenant_id,x.project_id,e.id,e.evaluation_task_id,e.evaluation_attempt_id,p_manifest)::text,'UTF8')),'hex');
 art=company_private.r55_cp_e0_verified_artifact(x.tenant_id,x.project_id,e.evaluation_task_id,e.evaluation_attempt_id,
 p_manifest,p_receipt,'r55.e0-process-admission.pg-jsonb.v1',b.accepted_human_id,bind);
 m=art.r55_e0_process_manifest;
 IF NOT ((m->>'tenant_id'=x.tenant_id::text AND m->>'project_id'=x.project_id::text
 AND m->>'evaluation_run_id'=e.id::text AND m->>'task_id'=e.evaluation_task_id::text
 AND m->>'attempt_id'=e.evaluation_attempt_id::text AND m->>'worker_id'=e.subject_principal_id::text
 AND m->>'model_digest'=e.model_digest AND m->>'fixture_digest'=e.fixture_digest
 AND m->>'profile_digest'=b.e0_mandate->>'profile_digest' AND m->>'workspace_id'=b.e0_mandate->>'workspace_id'
 AND m->>'network'='DENY' AND m->>'external_effects'='DENY' AND m->>'credentials'='NONE'
 AND m->>'live_paths'='DENY' AND m->>'kind' IN ('CHECK_SUITE','MUTANT_SUITE')
 AND (m->>'amount_minor')::bigint=0 AND jsonb_typeof(m->'claims')='array'
 AND jsonb_array_length(m->'claims')>0) IS TRUE) THEN RAISE EXCEPTION 'INVALID_FINITE_E0_MANIFEST'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(m->'claims') z GROUP BY (z->>'slot_id')::uuid HAVING count(*)>1)
 THEN RAISE EXCEPTION 'DUPLICATE_RESOURCE_SLOT'; END IF;
 d=encode(sha256(convert_to(jsonb_build_array(p_evaluation,p_manifest,p_receipt,m)::text,'UTF8')),'hex');
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id
 AND operation=x.operation_id AND idempotency_key=p_key FOR UPDATE;
 IF FOUND THEN
  IF c.payload_digest IS DISTINCT FROM d OR c.state<>'SUCCEEDED' THEN RAISE EXCEPTION 'CONFLICT_PROCESS_COMMAND'; END IF;
  PERFORM company_private.r54_b_context('e0.process_admit',true,true);
  PERFORM company_private.r57_replay_command(c.id);
  RETURN jsonb_build_object('process_run_id',c.result_ref,'command_id',c.id,'outcome','REPLAY_NO_SPAWN');
 END IF;
 -- Current project authority locks already serialize this budget across revisions.
 SELECT * INTO STRICT v FROM company.budget_versions WHERE tenant_id=x.tenant_id AND project_id=x.project_id
 AND budget_id=(m->>'budget_id')::uuid AND revision=(m->>'budget_revision')::bigint FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=v.tenant_id AND id=v.approved_by AND kind='HUMAN')
 OR v.environment_policy_digest IS DISTINCT FROM m->>'environment_policy_digest'
 THEN RAISE EXCEPTION 'BUDGET_HUMAN_POLICY_REQUIRED'; END IF;
 SELECT COALESCE(sum(greatest(amount_minor,settled_minor)-released_minor),0) INTO exposure
 FROM company.budget_reservations WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND budget_id=v.budget_id;
 IF exposure>v.limit_minor THEN RAISE EXCEPTION 'BUDGET_EXPOSURE_EXCEEDED'; END IF;
 SELECT * INTO STRICT e FROM company.evaluation_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_evaluation FOR UPDATE;
 SELECT * INTO STRICT t FROM company.tasks WHERE tenant_id=e.tenant_id AND project_id=e.project_id AND id=e.evaluation_task_id FOR UPDATE;
 SELECT * INTO STRICT at FROM company.attempts WHERE tenant_id=e.tenant_id AND project_id=e.project_id AND task_id=t.id AND id=e.evaluation_attempt_id FOR UPDATE;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,b.e0_valid_until);
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,at.lease_expires_at);
 IF b.accepted_human_id IS DISTINCT FROM x.principal_id OR b.e0_valid_until IS NULL
 OR e.state<>'AUTHORIZED' OR t.execution_kind<>'EVALUATION' OR t.state NOT IN ('READY','RUNNING','VERIFYING')
 OR t.active_attempt_id IS DISTINCT FROM at.id OR t.fencing_epoch IS DISTINCT FROM at.fencing_epoch
 OR at.worker_id IS DISTINCT FROM e.subject_principal_id OR at.e0_evaluation_run_id IS DISTINCT FROM e.id
 OR at.admission_qualification_id IS NOT NULL OR at.state NOT IN ('CLAIMED','RUNNING') OR at.ended_at IS NOT NULL
 OR at.lease_expires_at>b.e0_valid_until
 OR at.fencing_epoch IS DISTINCT FROM (m->>'fencing_epoch')::bigint
 OR NOT isfinite((m->>'valid_until')::timestamptz) OR (m->>'valid_until')::timestamptz<at.lease_expires_at
 OR (m->>'valid_until')::timestamptz>b.e0_valid_until THEN RAISE EXCEPTION 'STALE_E0_ADMISSION_TUPLE'; END IF;
 PERFORM company_private.r55_cp_clock_assert_current(x.tenant_id,x.project_id,(m->>'clock_epoch_id')::uuid,(m->>'clock_sample_id')::uuid);
 IF NOT EXISTS(SELECT 1 FROM company.clock_epochs ce WHERE ce.tenant_id=x.tenant_id AND ce.epoch_id=(m->>'clock_epoch_id')::uuid
 AND ce.host_boot_id=(m->>'host_boot_id')::uuid AND ce.r55_host_registration_id=(m->>'host_registration_id')::uuid
 AND ce.r55_host_registration_revision=(m->>'host_registration_revision')::bigint
 AND ce.r55_host_generation=(m->>'host_generation')::bigint) THEN RAISE EXCEPTION 'PROCESS_CLOCK_BOOT_BINDING_MISMATCH'; END IF;
 SELECT * INTO STRICT h FROM company.host_registrations WHERE tenant_id=x.tenant_id AND project_id=x.project_id
 AND id=(m->>'host_registration_id')::uuid AND revision=(m->>'host_registration_revision')::bigint FOR SHARE;
 IF h.state<>'BOUND_NOT_LEASED' OR h.bound_generation IS DISTINCT FROM (m->>'host_generation')::bigint
 OR NOT EXISTS(SELECT 1 FROM company.projects pr JOIN company.workspaces ws ON ws.tenant_id=pr.tenant_id AND ws.id=pr.workspace_id
 WHERE pr.tenant_id=x.tenant_id AND pr.id=x.project_id AND pr.workspace_id=(m->>'workspace_id')::uuid
 AND ws.trust_class='DISPOSABLE_TEST' AND pr.host_registration_id=h.id AND pr.host_registration_revision=h.revision
 AND pr.instance_generation=h.bound_generation) THEN RAISE EXCEPTION 'E0_HOST_OR_ISOLATION_BINDING_STALE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=(m->>'controller_id')::uuid AND kind IN ('WORKER','VERIFIER'))
 OR (m->>'controller_generation')::bigint<=0 OR (m->>'controller_id')::uuid=e.subject_principal_id
 THEN RAISE EXCEPTION 'E0_INDEPENDENT_CONTROLLER_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id
 AND e0_evaluation_run_id=e.id) THEN RAISE EXCEPTION 'E0_RUN_ALREADY_RESERVED_NO_RESPAWN'; END IF;
 process=gen_random_uuid();reservation=gen_random_uuid();cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,cmd,x.principal_id,x.operation_id,p_key,d,p_correlation,'RUNNING',NULL);
 INSERT INTO company.budget_reservations(tenant_id,project_id,id,budget_id,budget_revision,task_id,attempt_id,attempt_fencing_epoch,
 semantic_key,payload_digest,admission_artifact_id,amount_minor,state,command_id)
 VALUES(x.tenant_id,x.project_id,reservation,v.budget_id,v.revision,t.id,at.id,at.fencing_epoch,
 'e0:'||e.id::text,d,p_manifest,0,'RESERVED',cmd);
 INSERT INTO company.process_runs(tenant_id,project_id,id,task_id,attempt_id,attempt_fencing_epoch,worker_lease_id,worker_id,
 qualification_id,e0_evaluation_run_id,lease_expires_at,workspace_id,host_registration_id,host_registration_revision,host_generation,
 controller_id,controller_generation,kind,state,reservation_id,manifest_artifact_id,manifest_digest,semantic_run_digest,start_command_id,
 r55_host_boot_id,r55_admission_receipt_id)
 VALUES(x.tenant_id,x.project_id,process,t.id,at.id,at.fencing_epoch,gen_random_uuid(),at.worker_id,NULL,e.id,at.lease_expires_at,
 (m->>'workspace_id')::uuid,h.id,h.revision,h.bound_generation,(m->>'controller_id')::uuid,(m->>'controller_generation')::bigint,
 m->>'kind','REQUESTED',reservation,p_manifest,art.sha256,d,cmd,(m->>'host_boot_id')::uuid,p_receipt);
 FOR item IN SELECT value FROM jsonb_array_elements(m->'claims') ORDER BY (value->>'slot_id')::uuid LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR jsonb_typeof(item->'units') IS DISTINCT FROM 'number'
  OR jsonb_typeof(item->'slot_id') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'INVALID_RESOURCE_CLAIM_SHAPE'; END IF;
  n=(item->>'units')::integer;
  IF n IS NULL OR n<=0 OR item->>'slot_id' IS NULL THEN RAISE EXCEPTION 'INVALID_RESOURCE_UNITS'; END IF;
  SELECT * INTO STRICT sl FROM company.resource_slots WHERE tenant_id=x.tenant_id AND id=(item->>'slot_id')::uuid FOR UPDATE;
  UPDATE company.resource_slots SET reserved=reserved+n WHERE tenant_id=x.tenant_id AND id=sl.id AND reserved=sl.reserved AND capacity-reserved>=n;
  IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_CAPACITY_EXCEEDED'; END IF;
  INSERT INTO company.resource_claims(tenant_id,project_id,process_run_id,slot_id,units,state)
  VALUES(x.tenant_id,x.project_id,process,sl.id,n,'HELD');
 END LOOP;
 final_result=company_private.r55_cp_finalize_command(cmd,process,0,'E0ProcessAdmitted',
 jsonb_build_object('process_run_id',process,'reservation_id',reservation,'state','REQUESTED','spawned',false,'ordinary_admission',false));
 -- R55_POST_ALL_LOCKS_CUT: finalizer can wait too; rollback all rows on expiry.
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,b.e0_valid_until);
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,at.lease_expires_at);
 PERFORM company_private.r54_b_context('e0.process_admit',true,true);
 RETURN final_result;
END $$;

CREATE OR REPLACE FUNCTION company_private.r55_cp_e0_process_observe(
 p_operation text,p_process uuid,p_expected_revision bigint,p_artifact uuid,p_receipt uuid,
 p_key text,p_correlation uuid,p_require_stop boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE final_result jsonb; x company_private.request_contexts%ROWTYPE;r company.process_runs%ROWTYPE;
 a company.artifacts%ROWTYPE;c company.commands%ROWTYPE;m jsonb;d text;bind text;cmd uuid;next_state text;
BEGIN
 IF p_operation IS NULL OR p_operation NOT IN ('e0.process_stop_confirm','e0.process_reconcile') OR p_require_stop IS NULL
 OR (p_operation='e0.process_stop_confirm') IS DISTINCT FROM p_require_stop
 OR p_process IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_artifact IS NULL OR p_receipt IS NULL
 OR p_correlation IS NULL OR p_key IS NULL OR length(p_key) NOT BETWEEN 16 AND 128 THEN RAISE EXCEPTION 'INVALID_PROCESS_OBSERVATION'; END IF;
 x=company_private.r54_b_context(p_operation,false,true);
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process FOR UPDATE;
 IF r.e0_evaluation_run_id IS NULL OR r.qualification_id IS NOT NULL OR r.controller_id IS DISTINCT FROM x.principal_id
 THEN RAISE EXCEPTION 'E0_CONTROLLER_TUPLE_REQUIRED'; END IF;
 bind=encode(sha256(convert_to(jsonb_build_array(r.tenant_id,r.project_id,r.id,r.task_id,r.attempt_id,r.attempt_fencing_epoch,
 r.host_registration_id,r.host_registration_revision,r.host_generation,r.r55_host_boot_id,r.controller_id,r.controller_generation,r.manifest_digest)::text,'UTF8')),'hex');
 a=company_private.r55_cp_e0_verified_artifact(r.tenant_id,r.project_id,r.task_id,r.attempt_id,p_artifact,p_receipt,
 'r55.e0-process-observation.pg-jsonb.v1',r.controller_id,bind);
 m=a.r55_e0_process_observation;
 d=encode(sha256(convert_to(jsonb_build_array(p_process,p_expected_revision,p_artifact,p_receipt,p_operation)::text,'UTF8')),'hex');
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation=x.operation_id AND idempotency_key=p_key FOR UPDATE;
 IF FOUND THEN
  IF c.payload_digest IS DISTINCT FROM d OR c.state<>'SUCCEEDED' THEN RAISE EXCEPTION 'CONFLICT_PROCESS_COMMAND'; END IF;
  PERFORM company_private.r54_b_context(p_operation,false,true);
  PERFORM company_private.r57_replay_command(c.id);
  RETURN jsonb_build_object('process_run_id',r.id,'command_id',c.id,'outcome','REPLAY_ORIGINAL_FACT_NO_RESPAWN');
 END IF;
 IF r.revision IS DISTINCT FROM p_expected_revision OR r.state IN ('STOPPED','COMPLETED','FAILED_NOT_STARTED')
 OR r.release_command_id IS NOT NULL THEN RAISE EXCEPTION 'STALE_OR_TERMINAL_PROCESS'; END IF;
 IF NOT ((m->>'process_run_id'=r.id::text AND m->>'task_id'=r.task_id::text AND m->>'attempt_id'=r.attempt_id::text
 AND (m->>'fencing_epoch')::bigint=r.attempt_fencing_epoch AND (m->>'host_generation')::bigint=r.host_generation
 AND m->>'host_boot_id'=r.r55_host_boot_id::text AND (m->>'controller_generation')::bigint=r.controller_generation
 AND m->>'manifest_digest'=r.manifest_digest AND m->>'network'='DENY'
 AND m->>'external_effects'='DENY' AND ((m->>'observed_state'='UNKNOWN_LOCAL' AND m->>'process_identity_digest' IS NULL)
 OR m->>'process_identity_digest' ~ '^[a-f0-9]{64}$')) IS TRUE)
 THEN RAISE EXCEPTION 'PROCESS_OBSERVATION_TUPLE_MISMATCH'; END IF;
 IF r.r55_process_identity_digest IS NOT NULL AND r.r55_process_identity_digest IS DISTINCT FROM m->>'process_identity_digest'
 THEN RAISE EXCEPTION 'ORIGINAL_PROCESS_IDENTITY_CHANGED'; END IF;
 next_state=m->>'observed_state';
 IF next_state NOT IN ('RUNNING','STOPPED','UNKNOWN_LOCAL','FAILED_NOT_STARTED') OR next_state IS NULL
 OR (p_require_stop AND next_state<>'STOPPED') THEN RAISE EXCEPTION 'INVALID_PROCESS_OBSERVATION_STATE'; END IF;
 IF next_state='RUNNING' AND r.state='STOP_REQUESTED' THEN RAISE EXCEPTION 'STALE_RUN_CANNOT_RESUME'; END IF;
 IF next_state='RUNNING' THEN
  PERFORM company_private.r55_cp_require_not_expired(r.tenant_id,r.project_id,r.lease_expires_at);
  PERFORM company_private.r55_cp_clock_assert_current(r.tenant_id,r.project_id,(m->>'clock_epoch_id')::uuid,(m->>'clock_sample_id')::uuid);
  IF NOT EXISTS(SELECT 1 FROM company.clock_epochs ce WHERE ce.tenant_id=r.tenant_id AND ce.epoch_id=(m->>'clock_epoch_id')::uuid
   AND ce.host_boot_id=r.r55_host_boot_id AND ce.r55_host_registration_id=r.host_registration_id
   AND ce.r55_host_registration_revision=r.host_registration_revision AND ce.r55_host_generation=r.host_generation)
  THEN RAISE EXCEPTION 'REBOOTED_HOST_CANNOT_RESUME_ORIGINAL_PROCESS'; END IF;
 END IF;
 IF next_state='RUNNING' AND NOT EXISTS(SELECT 1 FROM company.tasks t JOIN company.attempts at
 ON at.tenant_id=t.tenant_id AND at.project_id=t.project_id AND at.task_id=t.id AND at.id=t.active_attempt_id
 JOIN company.host_registrations h ON h.tenant_id=t.tenant_id AND h.project_id=t.project_id
 JOIN company.projects pr ON pr.tenant_id=t.tenant_id AND pr.id=t.project_id
 WHERE t.tenant_id=r.tenant_id AND t.project_id=r.project_id AND t.id=r.task_id AND t.execution_kind='EVALUATION'
 AND t.state IN ('READY','RUNNING','VERIFYING') AND at.id=r.attempt_id AND at.fencing_epoch=r.attempt_fencing_epoch
 AND t.fencing_epoch=at.fencing_epoch AND at.worker_id=r.worker_id AND at.state IN ('CLAIMED','RUNNING')
 AND at.ended_at IS NULL AND at.lease_expires_at=r.lease_expires_at
 AND h.id=r.host_registration_id AND h.revision=r.host_registration_revision AND h.bound_generation=r.host_generation
 AND h.state='BOUND_NOT_LEASED' AND pr.instance_generation=r.host_generation
 AND pr.host_registration_id=h.id AND pr.host_registration_revision=h.revision)
 THEN RAISE EXCEPTION 'STALE_OR_REVOKED_RUN_BINDING'; END IF;
 IF next_state='STOPPED' AND NOT ((m->'all_descendants_gone'='true'::jsonb AND m->'cgroup_quiescent'='true'::jsonb
 AND m->'workspace_fenced'='true'::jsonb AND m->'no_post_fence_spawn'='true'::jsonb
 AND m->>'usage_state'='VERIFIED_ZERO_LOCAL' AND (m->>'settled_minor')::bigint=0) IS TRUE)
 THEN RAISE EXCEPTION 'PROCESS_STOP_QUIESCENCE_PROOF_REQUIRED'; END IF;
 IF next_state='FAILED_NOT_STARTED' AND NOT ((m->'never_spawned'='true'::jsonb AND m->'all_descendants_gone'='true'::jsonb
 AND m->'cgroup_quiescent'='true'::jsonb AND m->'workspace_fenced'='true'::jsonb
 AND m->'no_post_fence_spawn'='true'::jsonb AND m->>'usage_state'='VERIFIED_ZERO_LOCAL'
 AND (m->>'settled_minor')::bigint=0) IS TRUE) THEN RAISE EXCEPTION 'NO_SPAWN_PROOF_REQUIRED'; END IF;
 IF next_state='RUNNING' AND NOT EXISTS(SELECT 1 FROM company.artifacts ia WHERE ia.tenant_id=r.tenant_id AND ia.project_id=r.project_id
 AND ia.task_id=r.task_id AND ia.attempt_id=r.attempt_id AND ia.id=(m->>'isolation_artifact_id')::uuid AND ia.state='AVAILABLE'
 AND ia.sha256=m->>'isolation_digest') THEN RAISE EXCEPTION 'ISOLATION_PROOF_REQUIRED'; END IF;
 cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,cmd,x.principal_id,x.operation_id,p_key,d,p_correlation,'RUNNING',NULL);
 UPDATE company.process_runs SET state=next_state,revision=revision+1,
 r55_process_identity_digest=m->>'process_identity_digest',
 stop_command_id=CASE WHEN next_state IN ('STOPPED','FAILED_NOT_STARTED') THEN cmd ELSE stop_command_id END,
 stop_artifact_id=CASE WHEN next_state IN ('STOPPED','FAILED_NOT_STARTED') THEN a.id ELSE stop_artifact_id END,
 r55_stop_receipt_id=CASE WHEN next_state IN ('STOPPED','FAILED_NOT_STARTED') THEN p_receipt ELSE r55_stop_receipt_id END,
 r55_isolation_artifact_id=CASE WHEN next_state='RUNNING' THEN (m->>'isolation_artifact_id')::uuid ELSE r55_isolation_artifact_id END
 WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=p_expected_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'PROCESS_REVISION_CONFLICT'; END IF;
 final_result=company_private.r55_cp_finalize_command(cmd,r.id,p_expected_revision+1,
 CASE WHEN p_require_stop THEN 'E0ProcessStopConfirmed' ELSE 'E0ProcessReconciled' END,
 jsonb_build_object('process_run_id',r.id,'state',next_state,'spawned',false,'resources_released',false));
 -- R55_POST_ALL_LOCKS_CUT: finalizer can wait too; rollback all rows on expiry.
 IF next_state='RUNNING' THEN
  PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,r.lease_expires_at);
 END IF;
 PERFORM company_private.r54_b_context(p_operation,false,true);
 RETURN final_result;
END $$;

CREATE OR REPLACE FUNCTION company_private.r55_cp_e0_process_release(p_process uuid,p_expected_revision bigint,p_key text,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE final_result jsonb; x company_private.request_contexts%ROWTYPE;r company.process_runs%ROWTYPE;b company.budget_reservations%ROWTYPE;
 cl company.resource_claims%ROWTYPE;v company.budget_versions%ROWTYPE;art company.artifacts%ROWTYPE;
 c company.commands%ROWTYPE;cmd uuid;d text;bind text;
BEGIN
 x=company_private.r54_b_context('e0.process_release',false,true);
 IF p_process IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_key IS NULL
 OR length(p_key) NOT BETWEEN 16 AND 128 OR p_correlation IS NULL THEN RAISE EXCEPTION 'INVALID_PROCESS_RELEASE'; END IF;
 -- Read immutable identity first, lock budget before process and slots.
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process;
 SELECT * INTO STRICT b FROM company.budget_reservations WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.reservation_id;
 SELECT * INTO STRICT v FROM company.budget_versions WHERE tenant_id=b.tenant_id AND project_id=b.project_id AND budget_id=b.budget_id AND revision=b.budget_revision FOR UPDATE;
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process FOR UPDATE;
 d=encode(sha256(convert_to(jsonb_build_array(p_process,p_expected_revision,r.stop_artifact_id,r.r55_stop_receipt_id)::text,'UTF8')),'hex');
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation=x.operation_id AND idempotency_key=p_key FOR UPDATE;
 IF FOUND THEN
  IF c.payload_digest IS DISTINCT FROM d OR c.state<>'SUCCEEDED' THEN RAISE EXCEPTION 'CONFLICT_PROCESS_COMMAND'; END IF;
  PERFORM company_private.r54_b_context('e0.process_release',false,true);
  PERFORM company_private.r57_replay_command(c.id);
  RETURN jsonb_build_object('process_run_id',r.id,'command_id',c.id,'outcome','REPLAY_NO_SECOND_RELEASE');
 END IF;
 IF r.e0_evaluation_run_id IS NULL OR r.qualification_id IS NOT NULL OR r.revision IS DISTINCT FROM p_expected_revision
 OR r.state NOT IN ('STOPPED','FAILED_NOT_STARTED') OR r.stop_artifact_id IS NULL OR r.r55_stop_receipt_id IS NULL
 OR r.release_command_id IS NOT NULL THEN RAISE EXCEPTION 'STOP_PROOF_REQUIRED_NO_TTL_RELEASE'; END IF;
 bind=encode(sha256(convert_to(jsonb_build_array(r.tenant_id,r.project_id,r.id,r.task_id,r.attempt_id,r.attempt_fencing_epoch,
 r.host_registration_id,r.host_registration_revision,r.host_generation,r.r55_host_boot_id,r.controller_id,r.controller_generation,r.manifest_digest)::text,'UTF8')),'hex');
 art=company_private.r55_cp_e0_verified_artifact(r.tenant_id,r.project_id,r.task_id,r.attempt_id,r.stop_artifact_id,r.r55_stop_receipt_id,
 'r55.e0-process-observation.pg-jsonb.v1',r.controller_id,bind);
 IF NOT ((art.r55_e0_process_observation->>'usage_state'='VERIFIED_ZERO_LOCAL'
 AND (art.r55_e0_process_observation->>'settled_minor')::bigint=0) IS TRUE) THEN RAISE EXCEPTION 'UNKNOWN_USAGE_NO_RELEASE'; END IF;
 SELECT * INTO STRICT b FROM company.budget_reservations WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.reservation_id FOR UPDATE;
 IF b.task_id IS DISTINCT FROM r.task_id OR b.attempt_id IS DISTINCT FROM r.attempt_id OR b.attempt_fencing_epoch IS DISTINCT FROM r.attempt_fencing_epoch
 OR b.state<>'RESERVED' OR b.amount_minor<>0 OR b.settled_minor<>0 OR b.released_minor<>0 THEN RAISE EXCEPTION 'RESERVATION_NOT_RELEASABLE'; END IF;
 cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,cmd,x.principal_id,x.operation_id,p_key,d,p_correlation,'RUNNING',NULL);
 FOR cl IN SELECT * FROM company.resource_claims WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND process_run_id=r.id ORDER BY slot_id FOR UPDATE LOOP
  IF cl.state<>'HELD' THEN RAISE EXCEPTION 'CLAIM_ALREADY_RELEASED'; END IF;
  UPDATE company.resource_slots SET reserved=reserved-cl.units WHERE tenant_id=cl.tenant_id AND id=cl.slot_id AND reserved>=cl.units;
  IF NOT FOUND THEN RAISE EXCEPTION 'CLAIM_CAPACITY_ACCOUNTING_CONFLICT'; END IF;
  UPDATE company.resource_claims SET state='RELEASED',revision=revision+1,release_command_id=cmd
  WHERE tenant_id=cl.tenant_id AND project_id=cl.project_id AND process_run_id=cl.process_run_id AND slot_id=cl.slot_id AND revision=cl.revision AND state='HELD';
  IF NOT FOUND THEN RAISE EXCEPTION 'CLAIM_REVISION_CONFLICT'; END IF;
 END LOOP;
 UPDATE company.budget_reservations SET state='RELEASED',revision=revision+1,released_minor=0,
 settlement_command_id=cmd,release_command_id=cmd,release_op_id=cmd
 WHERE tenant_id=b.tenant_id AND project_id=b.project_id AND id=b.id AND revision=b.revision AND state='RESERVED';
 IF NOT FOUND THEN RAISE EXCEPTION 'RESERVATION_REVISION_CONFLICT'; END IF;
 UPDATE company.process_runs SET release_command_id=cmd,revision=revision+1
 WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=p_expected_revision AND release_command_id IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'PROCESS_REVISION_CONFLICT'; END IF;
 final_result=company_private.r55_cp_finalize_command(cmd,r.id,p_expected_revision+1,'E0ProcessReleased',
 jsonb_build_object('process_run_id',r.id,'state',r.state,'released',true,'ordinary_admission',false));
 -- R55_POST_ALL_LOCKS_CUT: finalizer can wait too; rollback all rows on expiry.
 PERFORM company_private.r55_cp_e0_verified_artifact(r.tenant_id,r.project_id,r.task_id,r.attempt_id,r.stop_artifact_id,r.r55_stop_receipt_id,
 'r55.e0-process-observation.pg-jsonb.v1',r.controller_id,bind);
 PERFORM company_private.r54_b_context('e0.process_release',false,true);
 RETURN final_result;
END $$;

-- SOURCE sql/032_R57_CLOCK_POLICY_HUMAN_WRITER.sql
-- Source candidate AFTER r56; no policy values, login or enrollment installed.
CREATE ROLE company_clock_policy_owner_r57 NOLOGIN NOSUPERUSER NOBYPASSRLS NOINHERIT;
CREATE ROLE company_clock_policy_transport_r57 NOLOGIN NOSUPERUSER NOBYPASSRLS NOINHERIT;
GRANT USAGE ON SCHEMA company,company_private TO company_clock_policy_owner_r57;
GRANT USAGE ON SCHEMA company_private TO company_clock_policy_transport_r57;

-- operation_permissions is installation-global in the existing ABI. Exactly
-- one enrolled installation owns this head. Multi-installation use is denied.
CREATE TABLE company_private.r57_clock_policy_authority (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 installation_id uuid NOT NULL UNIQUE REFERENCES company_private.installation_bootstrap_control(installation_id),
 tenant_id uuid NOT NULL,
 human_id uuid NOT NULL,
 FOREIGN KEY(tenant_id,human_id) REFERENCES company.principals(tenant_id,id)
);
CREATE TABLE company_private.r57_clock_policy_consents (
 consent_id uuid PRIMARY KEY,
 installation_id uuid NOT NULL REFERENCES company_private.r57_clock_policy_authority(installation_id),
 root_generation bigint NOT NULL CHECK(root_generation>0),
 action text NOT NULL CHECK(action IN ('ACTIVATE','REVOKE')),
 expected_revision bigint NOT NULL CHECK(expected_revision>=0),
 approved_statement_digest text NOT NULL CHECK(approved_statement_digest ~ '^[a-f0-9]{64}$'),
 human_consent_evidence_digest text NOT NULL CHECK(human_consent_evidence_digest ~ '^[a-f0-9]{64}$'),
 valid_from timestamptz NOT NULL CHECK(isfinite(valid_from)),
 valid_until timestamptz NOT NULL CHECK(isfinite(valid_until)),
 revoked_at timestamptz,
 CHECK(valid_from<valid_until)
);
CREATE TABLE company_private.r57_clock_policy_receipts (
 consent_id uuid PRIMARY KEY REFERENCES company_private.r57_clock_policy_consents(consent_id),
 installation_id uuid NOT NULL,
 tenant_id uuid NOT NULL,
 human_id uuid NOT NULL,
 revision bigint NOT NULL CHECK(revision>0),
 action text NOT NULL CHECK(action IN ('ACTIVATE','REVOKE')),
 statement_digest text NOT NULL CHECK(statement_digest ~ '^[a-f0-9]{64}$'),
 policy_digest text CHECK(policy_digest ~ '^[a-f0-9]{64}$'),
 policy jsonb,
 final_proof jsonb NOT NULL,
 receipt_digest text NOT NULL CHECK(receipt_digest ~ '^[a-f0-9]{64}$'),
 audit_id bigint NOT NULL,
 UNIQUE(installation_id,revision),
 FOREIGN KEY(tenant_id,human_id) REFERENCES company.principals(tenant_id,id),
 FOREIGN KEY(audit_id) REFERENCES company.audit_events(id),
 CHECK((action='REVOKE' AND policy_digest IS NULL AND policy IS NULL)
 OR ((action='ACTIVATE' AND policy_digest IS NOT NULL AND jsonb_typeof(policy)='object') IS TRUE))
);
CREATE TRIGGER r57_clock_receipt_immutable BEFORE UPDATE OR DELETE ON company_private.r57_clock_policy_receipts
FOR EACH ROW EXECUTE FUNCTION company.reject_audit_mutation();
CREATE TRIGGER r57_clock_authority_immutable BEFORE UPDATE OR DELETE ON company_private.r57_clock_policy_authority
FOR EACH ROW EXECUTE FUNCTION company.reject_audit_mutation();
-- Authority/consent insertion and revocation are offline trusted provisioning
-- seams. Runtime owner cannot INSERT, UPDATE or DELETE them. No enrollment is
-- fabricated by a runtime call or by executing this design file.
DO $rls$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['r57_clock_policy_authority','r57_clock_policy_consents','r57_clock_policy_receipts'] LOOP
  EXECUTE format('ALTER TABLE company_private.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE company_private.%I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('REVOKE ALL ON company_private.%I FROM PUBLIC',t);
  EXECUTE format('CREATE POLICY r57_clock_read ON company_private.%I FOR SELECT TO company_clock_policy_owner_r57 USING(true)',t);
 END LOOP;
END $rls$;
GRANT SELECT ON company_private.r57_clock_policy_authority,company_private.r57_clock_policy_consents,
 company_private.r57_clock_policy_receipts,company_private.installation_bootstrap_control,
 company_private.r55_setup_root_enrollments,company_private.operation_permissions,
 company.principals TO company_clock_policy_owner_r57;
GRANT UPDATE(revoked_at) ON company_private.r57_clock_policy_consents TO company_clock_policy_owner_r57;
CREATE POLICY r57_consent_lock ON company_private.r57_clock_policy_consents FOR UPDATE TO company_clock_policy_owner_r57 USING(true) WITH CHECK(false);
GRANT UPDATE(revoked_at) ON company_private.r55_setup_root_enrollments TO company_clock_policy_owner_r57;
CREATE POLICY r57_clock_root_lock ON company_private.r55_setup_root_enrollments FOR UPDATE TO company_clock_policy_owner_r57 USING(true) WITH CHECK(false);
-- UPDATE privilege only permits row locks; WITH CHECK(false) forbids changes.
GRANT INSERT ON company_private.r57_clock_policy_receipts TO company_clock_policy_owner_r57;
GRANT SELECT,UPDATE(invalidated_at) ON company.clock_epochs TO company_clock_policy_owner_r57;
CREATE POLICY r57_clock_epoch_policy ON company.clock_epochs TO company_clock_policy_owner_r57
 USING(EXISTS(SELECT 1 FROM company_private.r57_clock_policy_authority a WHERE a.tenant_id=clock_epochs.tenant_id))
 WITH CHECK(EXISTS(SELECT 1 FROM company_private.r57_clock_policy_authority a WHERE a.tenant_id=clock_epochs.tenant_id) AND invalidated_at IS NOT NULL);
CREATE POLICY r57_clock_insert ON company_private.r57_clock_policy_receipts FOR INSERT TO company_clock_policy_owner_r57 WITH CHECK(true);
GRANT UPDATE(policy_revision,approved_policy_digest) ON company_private.operation_permissions TO company_clock_policy_owner_r57;
CREATE POLICY r57_clock_registry ON company_private.operation_permissions TO company_clock_policy_owner_r57
 USING(operation_id='clock.policy.activate') WITH CHECK(operation_id='clock.policy.activate');
CREATE POLICY r57_clock_control ON company_private.installation_bootstrap_control FOR SELECT TO company_clock_policy_owner_r57 USING(true);
CREATE POLICY r57_clock_root ON company_private.r55_setup_root_enrollments FOR SELECT TO company_clock_policy_owner_r57 USING(true);
CREATE POLICY r57_clock_human ON company.principals FOR SELECT TO company_clock_policy_owner_r57 USING(kind='HUMAN');
GRANT SELECT,INSERT ON company.audit_events TO company_clock_policy_owner_r57;
GRANT USAGE ON SEQUENCE company.audit_events_id_seq TO company_clock_policy_owner_r57;
CREATE POLICY r57_clock_audit ON company.audit_events TO company_clock_policy_owner_r57
 USING(EXISTS(SELECT 1 FROM company_private.r57_clock_policy_authority a WHERE a.tenant_id=audit_events.tenant_id AND a.human_id=audit_events.actor_id))
 WITH CHECK(EXISTS(SELECT 1 FROM company_private.r57_clock_policy_authority a WHERE a.tenant_id=audit_events.tenant_id AND a.human_id=audit_events.actor_id));
GRANT EXECUTE ON FUNCTION company_private.r56_root_bounds(uuid),company_private.r55_cp_hmac_sha256(bytea,bytea),
 company_private.r55_cp_tag_equal(bytea,bytea) TO company_clock_policy_owner_r57;

CREATE FUNCTION company_private.r57_clock_policy_write(p_consent uuid,p_raw bytea,p_tag bytea,p_key bytea)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE a company_private.r57_clock_policy_authority%ROWTYPE;
 c company_private.r57_clock_policy_consents%ROWTYPE;e company_private.r55_setup_root_enrollments%ROWTYPE;
 ctl company_private.installation_bootstrap_control%ROWTYPE;r company_private.r57_clock_policy_receipts%ROWTYPE;
 op company_private.operation_permissions%ROWTYPE;j jsonb;s jsonb;v jsonb;bounds jsonb;d text;pd text;rd text;aid bigint;
 msg bytea;item bytea;policy_key text;revision bigint;
BEGIN
 IF NOT pg_has_role(session_user,'company_clock_policy_transport_r57','MEMBER') THEN RAISE EXCEPTION 'CLOCK_POLICY_TRANSPORT_REQUIRED'; END IF;
 IF p_consent IS NULL OR p_raw IS NULL OR octet_length(p_raw) NOT BETWEEN 1 AND 65536
 OR p_tag IS NULL OR octet_length(p_tag)<>32 OR p_key IS NULL OR octet_length(p_key)<>32 THEN RAISE EXCEPTION 'INVALID_CLOCK_POLICY_WIRE'; END IF;
 SELECT * INTO STRICT a FROM company_private.r57_clock_policy_authority WHERE singleton;
 SELECT * INTO STRICT ctl FROM company_private.installation_bootstrap_control WHERE installation_id=a.installation_id;
 -- Same installation lock as bootstrap. All policy writers take this first,
 -- then consent, then registry. Root rows stay SHARE-locked through COMMIT.
 PERFORM pg_advisory_xact_lock(ctl.lock_id);
 SELECT * INTO STRICT c FROM company_private.r57_clock_policy_consents WHERE consent_id=p_consent FOR SHARE;
 SELECT * INTO STRICT e FROM company_private.r55_setup_root_enrollments WHERE installation_id=a.installation_id AND generation=c.root_generation FOR SHARE;
 IF c.installation_id IS DISTINCT FROM a.installation_id OR c.root_generation IS DISTINCT FROM ctl.generation
 OR ctl.state IS DISTINCT FROM 'CONSUMED' OR a.human_id IS DISTINCT FROM ctl.expected_human_id
 OR a.tenant_id IS DISTINCT FROM ctl.expected_tenant_id OR e.actual_human_id IS DISTINCT FROM a.human_id
 OR c.revoked_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=a.tenant_id AND id=a.human_id AND kind='HUMAN')
 OR e.key_fingerprint IS DISTINCT FROM encode(sha256(p_key),'hex') THEN RAISE EXCEPTION 'CLOCK_POLICY_HUMAN_ENROLLMENT_REQUIRED'; END IF;
 bounds=company_private.r56_root_bounds(a.installation_id);
 IF NOT ((c.valid_from<=(bounds->>'utc_lower')::timestamptz AND (bounds->>'utc_upper')::timestamptz<c.valid_until) IS TRUE)
 THEN RAISE EXCEPTION 'CLOCK_POLICY_CONSENT_EXPIRED_OR_AMBIGUOUS'; END IF;
 j=convert_from(p_raw,'UTF8')::jsonb;
 IF jsonb_typeof(j) IS DISTINCT FROM 'object'
 OR EXISTS(SELECT key FROM json_each(convert_from(p_raw,'UTF8')::json) GROUP BY key HAVING count(*)>1)
 OR NOT ((j ?& ARRAY['statement','backend_pid','transaction_id','db_login']) IS TRUE)
 OR (SELECT count(*) FROM jsonb_object_keys(j))<>4
 OR jsonb_typeof(j->'backend_pid') IS DISTINCT FROM 'number'
 OR j->>'backend_pid' !~ '^[1-9][0-9]*$'
 OR jsonb_typeof(j->'transaction_id') IS DISTINCT FROM 'string'
 OR jsonb_typeof(j->'db_login') IS DISTINCT FROM 'string'
 OR j->>'backend_pid' IS DISTINCT FROM pg_backend_pid()::text OR j->>'transaction_id' IS DISTINCT FROM pg_current_xact_id()::text
 OR j->>'db_login' IS DISTINCT FROM session_user::text THEN RAISE EXCEPTION 'CLOCK_POLICY_CONTEXT_MISMATCH'; END IF;
 s=j->'statement';
 IF jsonb_typeof(s) IS DISTINCT FROM 'object' OR NOT ((s ?& ARRAY['consent_id','installation_id','action','expected_revision','policy']) IS TRUE)
 OR (SELECT count(*) FROM jsonb_object_keys(s))<>5
 OR jsonb_typeof(s->'expected_revision') IS DISTINCT FROM 'number' OR s->>'expected_revision' !~ '^(0|[1-9][0-9]*)$'
 OR EXISTS(SELECT 1 FROM jsonb_each(s) z WHERE z.key IN ('consent_id','installation_id','action') AND jsonb_typeof(z.value) IS DISTINCT FROM 'string')
 THEN RAISE EXCEPTION 'CLOCK_POLICY_STATEMENT_SHAPE'; END IF;
 -- PG JSONB bytes, not a caller-supplied digest or Python JSON hash.
 d=encode(sha256(convert_to(s::text,'UTF8')),'hex');
 IF d IS DISTINCT FROM c.approved_statement_digest OR s->>'consent_id' IS DISTINCT FROM c.consent_id::text
 OR s->>'installation_id' IS DISTINCT FROM a.installation_id::text OR s->>'action' IS DISTINCT FROM c.action
 OR s->>'expected_revision' IS DISTINCT FROM c.expected_revision::text
 THEN RAISE EXCEPTION 'EXACT_HUMAN_POLICY_CONSENT_REQUIRED'; END IF;
 msg=convert_to('R57-CLOCK-POLICY-v1','UTF8')||decode('00','hex');
 FOREACH item IN ARRAY ARRAY[convert_to(c.consent_id::text,'UTF8'),convert_to(e.issuer_id::text,'UTF8'),convert_to(e.key_id::text,'UTF8'),convert_to(e.enrollment_revision::text,'UTF8'),p_raw] LOOP
  msg=msg||convert_to(octet_length(item)::text||':','UTF8')||item;
 END LOOP;
 IF company_private.r55_cp_tag_equal(company_private.r55_cp_hmac_sha256(p_key,msg),p_tag) IS NOT TRUE THEN RAISE EXCEPTION 'INVALID_CLOCK_POLICY_HMAC'; END IF;
 v=s->'policy';
 IF c.action='ACTIVATE' THEN
  IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR NOT ((v ?& ARRAY['bounded_handoff_duration_ms','max_uncertainty_ms','max_sample_age_ms','max_clock_jump_ms','first_alert_ms','owner_ack_ms','manual_reconcile_ms','poll_ms','max_drift_ms']) IS TRUE)
  OR (SELECT count(*) FROM jsonb_object_keys(v))<>9 THEN RAISE EXCEPTION 'NINE_EXPLICIT_CLOCK_DECISIONS_REQUIRED'; END IF;
  FOR policy_key IN SELECT jsonb_object_keys(v) LOOP
   IF jsonb_typeof(v->policy_key) IS DISTINCT FROM 'number' OR v->>policy_key !~ '^[1-9][0-9]*$' THEN RAISE EXCEPTION 'POSITIVE_INTEGER_CLOCK_DECISION_REQUIRED'; END IF;
   PERFORM (v->>policy_key)::bigint;
  END LOOP;
  IF (v->>'first_alert_ms')::bigint>(v->>'owner_ack_ms')::bigint OR (v->>'owner_ack_ms')::bigint>(v->>'manual_reconcile_ms')::bigint
  THEN RAISE EXCEPTION 'CLOCK_ESCALATION_ORDER'; END IF;
  pd=encode(sha256(convert_to(v::text,'UTF8')),'hex');
 ELSE
  IF v IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'REVOKE_POLICY_MUST_BE_NULL'; END IF;
  pd=NULL;v=NULL;
 END IF;
 SELECT * INTO STRICT op FROM company_private.operation_permissions WHERE operation_id='clock.policy.activate' FOR UPDATE;
 -- Recheck after registry lock wait, including the replay path.
 bounds=company_private.r56_root_bounds(a.installation_id);
 IF NOT ((c.valid_from<=(bounds->>'utc_lower')::timestamptz AND (bounds->>'utc_upper')::timestamptz<c.valid_until) IS TRUE)
 THEN RAISE EXCEPTION 'CLOCK_POLICY_FINAL_CONSENT_EXPIRED'; END IF;
 SELECT * INTO r FROM company_private.r57_clock_policy_receipts WHERE consent_id=c.consent_id;
 IF FOUND THEN
  IF r.statement_digest IS DISTINCT FROM d OR r.revision IS DISTINCT FROM op.policy_revision OR r.policy_digest IS DISTINCT FROM op.approved_policy_digest
  OR r.action IS DISTINCT FROM c.action
  OR r.receipt_digest IS DISTINCT FROM encode(sha256(convert_to(jsonb_build_array(r.consent_id,r.installation_id,r.human_id,r.revision,r.action,r.statement_digest,r.policy_digest,r.final_proof)::text,'UTF8')),'hex')
  OR NOT EXISTS(SELECT 1 FROM company.audit_events z WHERE z.tenant_id=r.tenant_id AND z.id=r.audit_id AND z.actor_id=r.human_id AND z.correlation_id=r.consent_id AND z.kind='ClockPolicy'||initcap(lower(r.action)))
  THEN RAISE EXCEPTION 'CLOCK_POLICY_REPLAY_STALE_OR_WITNESS_MISSING'; END IF;
  RETURN jsonb_build_object('consent_id',r.consent_id,'revision',r.revision,'receipt_digest',r.receipt_digest,'outcome','REPLAY_NO_NEW_REVISION');
 END IF;
 IF op.policy_revision IS DISTINCT FROM c.expected_revision THEN RAISE EXCEPTION 'CLOCK_POLICY_REVISION_CONFLICT'; END IF;
 revision=op.policy_revision+1;
 bounds=company_private.r56_root_bounds(a.installation_id);
 IF NOT ((c.valid_from<=(bounds->>'utc_lower')::timestamptz AND (bounds->>'utc_upper')::timestamptz<c.valid_until) IS TRUE)
 THEN RAISE EXCEPTION 'CLOCK_POLICY_FINAL_CONSENT_EXPIRED'; END IF;
 rd=encode(sha256(convert_to(jsonb_build_array(c.consent_id,a.installation_id,a.human_id,revision,c.action,d,pd,bounds)::text,'UTF8')),'hex');
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(a.tenant_id,c.consent_id,a.human_id,'ClockPolicy'||initcap(lower(c.action))) RETURNING id INTO aid;
 INSERT INTO company_private.r57_clock_policy_receipts(consent_id,installation_id,tenant_id,human_id,revision,action,statement_digest,policy_digest,policy,final_proof,receipt_digest,audit_id)
 VALUES(c.consent_id,a.installation_id,a.tenant_id,a.human_id,revision,c.action,d,pd,v,bounds,rd,aid);
 -- Registry lock precedes epoch locks in writer and every selected consumer.
 -- Retire current epochs atomically, freeing the one-current-epoch unique key.
 UPDATE company.clock_epochs SET invalidated_at=(bounds->>'utc_upper')::timestamptz
 WHERE tenant_id=a.tenant_id AND invalidated_at IS NULL;
 UPDATE company_private.operation_permissions SET policy_revision=revision,approved_policy_digest=pd
 WHERE operation_id='clock.policy.activate' AND policy_revision=c.expected_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'CLOCK_POLICY_CAS_CONFLICT'; END IF;
 -- Immutable epoch identity is preserved; only one-way invalidation changes.
 RETURN jsonb_build_object('consent_id',c.consent_id,'revision',revision,'receipt_digest',rd,'outcome',c.action);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'CLOCK_POLICY_NOT_ENROLLED';
END $$;
ALTER FUNCTION company_private.r57_clock_policy_write(uuid,bytea,bytea,bytea) OWNER TO company_clock_policy_owner_r57;
REVOKE ALL ON FUNCTION company_private.r57_clock_policy_write(uuid,bytea,bytea,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r57_clock_policy_write(uuid,bytea,bytea,bytea) TO company_clock_policy_transport_r57;

-- SOURCE sql/033_R57_CLOCK_CONSUMER_REVISION_OVERLAY.sql
ALTER TABLE company.clock_epochs ADD COLUMN r57_policy_revision bigint CHECK(r57_policy_revision>=0);
GRANT SELECT ON company_private.r57_clock_policy_receipts,company_private.r57_clock_policy_authority TO company_context_owner;
CREATE POLICY r57_clock_receipt_consumer ON company_private.r57_clock_policy_receipts FOR SELECT TO company_context_owner USING(true);
CREATE POLICY r57_clock_authority_consumer ON company_private.r57_clock_policy_authority FOR SELECT TO company_context_owner USING(true);
GRANT UPDATE(policy_revision) ON company_private.operation_permissions TO company_context_owner;
CREATE POLICY r57_clock_consumer_registry_lock ON company_private.operation_permissions FOR UPDATE TO company_context_owner USING(operation_id='clock.policy.activate') WITH CHECK(false);
-- No backfill of legacy epochs. NULL revision fails currentness.
CREATE OR REPLACE FUNCTION company_private.r55_cp_clock_epoch_register(
 p_issuer uuid,p_key_id uuid,p_revision bigint,p_raw bytea,p_tag bytea,p_secret bytea,
 p_host uuid,p_host_revision bigint,p_host_generation bigint,p_policy jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE j jsonb;obs jsonb;t uuid;project uuid;epoch uuid;d text;policy_revision bigint;
BEGIN
 j=company_private.r55_cp_verify_clock_statement(p_issuer,p_key_id,p_revision,p_raw,p_tag,p_secret);
 t=(j->>'tenant_id')::uuid;project=(j->>'project_id')::uuid;epoch=(j->>'epoch_id')::uuid;
 IF p_host IS NULL OR p_host_revision IS NULL OR p_host_generation IS NULL OR p_policy IS NULL
 OR jsonb_typeof(p_policy)<>'object' OR NOT ((p_policy ?& ARRAY['max_sample_age_ms','max_uncertainty_ms','max_drift_ms','max_clock_jump_ms']) IS TRUE)
 OR EXISTS(SELECT 1 FROM jsonb_each(p_policy) z WHERE z.key IN ('max_sample_age_ms','max_uncertainty_ms','max_drift_ms','max_clock_jump_ms')
 AND (jsonb_typeof(z.value)<>'number' OR z.value::text !~ '^[0-9]+$')) THEN RAISE EXCEPTION 'INVALID_CLOCK_EPOCH_PROFILE'; END IF;
 d=encode(sha256(convert_to(p_policy::text,'UTF8')),'hex');
 IF j->>'host_registration_id' IS DISTINCT FROM p_host::text OR j->>'host_registration_revision' IS DISTINCT FROM p_host_revision::text
 OR j->>'host_generation' IS DISTINCT FROM p_host_generation::text OR j->>'policy_digest' IS DISTINCT FROM d
 THEN RAISE EXCEPTION 'CLOCK_SIGNED_HOST_POLICY_MISMATCH'; END IF;
 SELECT op.policy_revision INTO STRICT policy_revision FROM company_private.operation_permissions op WHERE op.operation_id='clock.policy.activate' AND op.approved_policy_digest=d FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM company_private.r57_clock_policy_receipts r JOIN company_private.r57_clock_policy_authority a ON a.installation_id=r.installation_id WHERE r.revision=policy_revision AND r.tenant_id=t AND r.action='ACTIVATE' AND r.policy_digest=d)
 THEN RAISE EXCEPTION 'CLOCK_POLICY_NOT_APPROVED'; END IF;
 PERFORM 1 FROM company.host_registrations h JOIN company.projects p ON p.tenant_id=h.tenant_id AND p.id=h.project_id
 WHERE h.tenant_id=t AND h.project_id=project AND h.id=p_host AND h.revision=p_host_revision AND h.bound_generation=p_host_generation
 AND h.state='BOUND_NOT_LEASED' AND p.host_registration_id=h.id AND p.host_registration_revision=h.revision AND p.instance_generation=h.bound_generation;
 IF NOT FOUND THEN RAISE EXCEPTION 'CLOCK_HOST_GENERATION_STALE'; END IF;
 obs=company_private.r55_cp_clock_observe_local();
 IF obs->>'source_sync_state' IS DISTINCT FROM 'SYNC' OR obs->>'host_boot_id' IS DISTINCT FROM j->>'host_boot_id'
 THEN RAISE EXCEPTION 'BLOCKED_DB_LOCAL_CLOCK_SOURCE'; END IF;
 INSERT INTO company.clock_epochs(tenant_id,epoch_id,supervisor_id,host_boot_id,writer_generation,policy_digest,registered_at,
 r55_project_id,r55_host_registration_id,r55_host_registration_revision,r55_host_generation,r55_policy,r57_policy_revision)
 VALUES(t,epoch,p_issuer,(j->>'host_boot_id')::uuid,54,d,clock_timestamp(),project,p_host,p_host_revision,p_host_generation,p_policy,policy_revision);
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(t,epoch,p_issuer,'ClockEpochRegistered');
 RETURN epoch;
END $$;

CREATE OR REPLACE FUNCTION company_private.r55_cp_clock_sample_persist(
 p_issuer uuid,p_key_id uuid,p_revision bigint,p_raw bytea,p_tag bytea,p_secret bytea)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE j jsonb;e company.clock_epochs%ROWTYPE;s company.clock_samples%ROWTYPE;
 t uuid;project uuid;epoch uuid;sample uuid;seq bigint;bt numeric;age_ns numeric;d text;reason text;
 lo timestamptz;hi timestamptz;u bigint;freq numeric;margin numeric;
BEGIN
 PERFORM 1 FROM company_private.operation_permissions WHERE operation_id='clock.policy.activate' FOR SHARE;
 j=company_private.r55_cp_verify_clock_statement(p_issuer,p_key_id,p_revision,p_raw,p_tag,p_secret);
 IF NOT ((j ?& ARRAY['cut_nonce','source_sequence','sampled_at','utc_lower_bound','utc_upper_bound','sample_boottime_ns','sample_uncertainty_ms','frequency_error_ppm_bound','sampling_error_margin_ns','source_sync_state']) IS TRUE)
 THEN RAISE EXCEPTION 'CLOCK_SAMPLE_FIELDS_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(j) z WHERE z.key IN ('source_sequence','sample_boottime_ns','sample_uncertainty_ms','frequency_error_ppm_bound','sampling_error_margin_ns','current_boottime_ns','valid_until_boottime_ns')
 AND (jsonb_typeof(z.value)<>'number' OR z.value::text !~ '^[0-9]+$')) THEN RAISE EXCEPTION 'CLOCK_INTEGER_REQUIRED'; END IF;
 t=(j->>'tenant_id')::uuid;project=(j->>'project_id')::uuid;epoch=(j->>'epoch_id')::uuid;sample=(j->>'sample_id')::uuid;
 seq=(j->>'source_sequence')::bigint;bt=(j->>'sample_boottime_ns')::numeric;
 lo=(j->>'utc_lower_bound')::timestamptz;hi=(j->>'utc_upper_bound')::timestamptz;
 u=(j->>'sample_uncertainty_ms')::bigint;freq=(j->>'frequency_error_ppm_bound')::numeric;margin=(j->>'sampling_error_margin_ns')::numeric;
 IF seq<1 OR hi<lo OR u<0 OR bt<0 OR freq<0 OR margin<0
 OR extract(epoch FROM (hi-lo))*1000000000>2*u::numeric*1000000
 OR (j->>'sampled_at')::timestamptz<lo OR (j->>'sampled_at')::timestamptz>hi
 OR (j->>'current_boottime_ns')::numeric<bt
 OR (j->>'valid_until_boottime_ns')::numeric<=(j->>'current_boottime_ns')::numeric
 THEN RAISE EXCEPTION 'INVALID_CLOCK_SAMPLE_BOUNDS'; END IF;
 SELECT * INTO STRICT e FROM company.clock_epochs WHERE tenant_id=t AND epoch_id=epoch FOR UPDATE;
 IF e.invalidated_at IS NOT NULL OR e.supervisor_id IS DISTINCT FROM p_issuer OR e.writer_generation IS DISTINCT FROM 54
 OR e.r55_project_id IS DISTINCT FROM project OR e.host_boot_id IS DISTINCT FROM (j->>'host_boot_id')::uuid
 OR e.r55_policy IS NULL OR e.r55_host_registration_id IS NULL OR e.r55_host_generation IS NULL
 THEN RAISE EXCEPTION 'CLOCK_EPOCH_BINDING_MISMATCH'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company.host_registrations h JOIN company.projects p ON p.tenant_id=h.tenant_id AND p.id=h.project_id
 WHERE h.tenant_id=t AND h.project_id=project AND h.id=e.r55_host_registration_id AND h.revision=e.r55_host_registration_revision
 AND h.bound_generation=e.r55_host_generation AND h.state='BOUND_NOT_LEASED'
 AND p.host_registration_id=h.id AND p.host_registration_revision=h.revision AND p.instance_generation=h.bound_generation)
 THEN RAISE EXCEPTION 'CLOCK_HOST_GENERATION_STALE'; END IF;
 PERFORM 1 FROM company_private.operation_permissions WHERE operation_id='clock.policy.activate' FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM company_private.operation_permissions op WHERE op.operation_id='clock.policy.activate'
 AND op.policy_revision=e.r57_policy_revision
 AND EXISTS(SELECT 1 FROM company_private.r57_clock_policy_receipts r JOIN company_private.r57_clock_policy_authority a ON a.installation_id=r.installation_id WHERE r.revision=op.policy_revision AND r.tenant_id=e.tenant_id AND r.policy_digest=e.policy_digest AND r.action='ACTIVATE')
 AND op.approved_policy_digest=e.policy_digest AND op.approved_policy_digest=encode(sha256(convert_to(e.r55_policy::text,'UTF8')),'hex'))
 THEN RAISE EXCEPTION 'CLOCK_POLICY_NOT_APPROVED'; END IF;
 IF NOT ((e.r55_policy ?& ARRAY['max_clock_jump_ms','max_uncertainty_ms','max_drift_ms','max_sample_age_ms']) IS TRUE)
 OR EXISTS(SELECT 1 FROM jsonb_each(e.r55_policy) z WHERE z.key IN ('max_clock_jump_ms','max_uncertainty_ms','max_drift_ms','max_sample_age_ms')
 AND (jsonb_typeof(z.value)<>'number' OR z.value::text !~ '^[0-9]+$')) THEN RAISE EXCEPTION 'CLOCK_POLICY_INVALID'; END IF;
 d=encode(sha256(p_raw),'hex');
 SELECT * INTO s FROM company.clock_samples WHERE tenant_id=t AND epoch_id=epoch AND sample_id=sample;
 IF FOUND THEN
  IF s.r55_raw_proof_digest IS DISTINCT FROM d THEN RAISE EXCEPTION 'CLOCK_SAMPLE_DIGEST_CONFLICT'; END IF;
  RETURN jsonb_build_object('status','REPLAY_NO_NEW_CUT','sample_id',sample);
 END IF;
 SELECT * INTO s FROM company.clock_samples WHERE tenant_id=t AND epoch_id=epoch ORDER BY boottime_ns DESC,sample_id DESC LIMIT 1;
 IF FOUND THEN
  IF s.r55_source_sequence IS NULL OR seq<=s.r55_source_sequence OR bt<=s.boottime_ns THEN RAISE EXCEPTION 'CLOCK_REPLAY_OR_REORDER'; END IF;
  age_ns=bt-s.boottime_ns;
  IF greatest(abs(extract(epoch FROM (lo-s.utc_upper_bound))*1000000000-age_ns),abs(extract(epoch FROM (hi-s.utc_lower_bound))*1000000000-age_ns))
  >(e.r55_policy->>'max_clock_jump_ms')::numeric*1000000 THEN reason='CLOCK_JUMP'; END IF;
 ELSIF seq<>1 THEN RAISE EXCEPTION 'CLOCK_FIRST_SEQUENCE_REQUIRED'; END IF;
 IF j->>'source_sync_state' IS DISTINCT FROM 'SYNC' THEN reason='CLOCK_SOURCE_UNSYNCHRONIZED'; END IF;
 IF reason IS NOT NULL THEN
  UPDATE company.clock_epochs SET invalidated_at=clock_timestamp() WHERE tenant_id=t AND epoch_id=epoch AND invalidated_at IS NULL;
  INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(t,(j->>'cut_nonce')::uuid,p_issuer,reason);
  -- Commit this BLOCKED result to preserve invalidation. A caller must not turn
  -- it into a success exception handler or silently rollback and reuse the epoch.
  RETURN jsonb_build_object('status','BLOCKED','reason',reason,'epoch_invalidated',true);
 END IF;
 INSERT INTO company.clock_samples(tenant_id,epoch_id,sample_id,sampled_at,utc_lower_bound,utc_upper_bound,boottime_ns,uncertainty_ms,sample_digest,
 r55_raw_proof_digest,r55_source_sequence,r55_source_enrollment_revision,r55_source_issuer,r55_source_key,r55_frequency_error_ppm_bound,r55_sampling_error_margin_ns)
 VALUES(t,epoch,sample,(j->>'sampled_at')::timestamptz,lo,hi,bt,u,d,d,seq,p_revision,p_issuer,p_key_id,freq,margin);
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(t,(j->>'cut_nonce')::uuid,p_issuer,'ClockObservationPersisted');
 -- Cut persistence is intentionally separate from sample persistence until the
 -- live after-lock BOOTTIME adapter is implemented. No durable sample is HEALTHY.
 RETURN jsonb_build_object('status','SAMPLE_PERSISTED_NO_LIVE_CUT','sample_id',sample,'source_sequence',seq);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'CLOCK_SOURCE_UNRESOLVED';
END $$;

CREATE OR REPLACE FUNCTION company_private.r55_cp_clock_current_bounds_at(p_tenant uuid,p_project uuid,p_epoch uuid,p_sample uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE e company.clock_epochs%ROWTYPE;s company.clock_samples%ROWTYPE;
 obs jsonb;age_ns numeric;age_lower_ns numeric;drift_ns numeric;uncertainty_ns numeric;
 utc_lo timestamptz;utc_hi timestamptz;capture_ns numeric;
BEGIN
 PERFORM 1 FROM company_private.operation_permissions WHERE operation_id='clock.policy.activate' FOR SHARE;
 IF p_tenant IS NULL OR p_project IS NULL OR p_epoch IS NULL OR p_sample IS NULL THEN RAISE EXCEPTION 'BLOCKED_TIME_DEPENDENCY'; END IF;
 SELECT * INTO STRICT e FROM company.clock_epochs WHERE tenant_id=p_tenant AND epoch_id=p_epoch FOR SHARE;
 SELECT * INTO STRICT s FROM company.clock_samples WHERE tenant_id=p_tenant AND epoch_id=p_epoch AND sample_id=p_sample;
 IF e.invalidated_at IS NOT NULL OR e.writer_generation IS DISTINCT FROM 54 OR e.r55_project_id IS DISTINCT FROM p_project
 OR e.r55_host_registration_id IS NULL OR e.r55_host_registration_revision IS NULL OR e.r55_host_generation IS NULL
 OR e.r55_policy IS NULL OR s.r55_raw_proof_digest IS NULL OR s.r55_source_sequence IS NULL OR s.r55_source_sequence<2
 OR s.r55_source_issuer IS DISTINCT FROM e.supervisor_id OR s.r55_source_key IS NULL OR s.r55_source_enrollment_revision IS NULL
 OR s.r55_frequency_error_ppm_bound IS NULL OR s.r55_frequency_error_ppm_bound<0
 OR s.r55_sampling_error_margin_ns IS NULL OR s.r55_sampling_error_margin_ns<0
 THEN RAISE EXCEPTION 'CLOCK_EPOCH_SAMPLE_NOT_CURRENT'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company.host_registrations h JOIN company.projects p ON p.tenant_id=h.tenant_id AND p.id=h.project_id
 WHERE h.tenant_id=p_tenant AND h.project_id=p_project AND h.id=e.r55_host_registration_id AND h.revision=e.r55_host_registration_revision
 AND h.bound_generation=e.r55_host_generation AND h.state='BOUND_NOT_LEASED'
 AND p.host_registration_id=h.id AND p.host_registration_revision=h.revision AND p.instance_generation=h.bound_generation)
 THEN RAISE EXCEPTION 'CLOCK_HOST_GENERATION_STALE'; END IF;
 PERFORM 1 FROM company_private.operation_permissions WHERE operation_id='clock.policy.activate' FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM company_private.operation_permissions op WHERE op.operation_id='clock.policy.activate'
 AND op.policy_revision=e.r57_policy_revision
 AND EXISTS(SELECT 1 FROM company_private.r57_clock_policy_receipts r JOIN company_private.r57_clock_policy_authority a ON a.installation_id=r.installation_id WHERE r.revision=op.policy_revision AND r.tenant_id=e.tenant_id AND r.policy_digest=e.policy_digest AND r.action='ACTIVATE')
 AND op.approved_policy_digest=e.policy_digest AND op.approved_policy_digest=encode(sha256(convert_to(e.r55_policy::text,'UTF8')),'hex'))
 THEN RAISE EXCEPTION 'CLOCK_POLICY_NOT_APPROVED'; END IF;
 IF NOT ((jsonb_typeof(e.r55_policy)='object' AND e.r55_policy ?& ARRAY['max_sample_age_ms','max_uncertainty_ms','max_drift_ms','max_clock_jump_ms']) IS TRUE)
 OR EXISTS(SELECT 1 FROM jsonb_each(e.r55_policy) z WHERE z.key IN ('max_sample_age_ms','max_uncertainty_ms','max_drift_ms','max_clock_jump_ms')
 AND (jsonb_typeof(z.value)<>'number' OR z.value::text !~ '^[0-9]+$')) THEN RAISE EXCEPTION 'CLOCK_POLICY_INVALID'; END IF;
 -- Fresh native BOOTTIME read occurs AFTER SQL row locks, every guard call.
 -- A remote producer whose boot/host differs cannot authorize this DB-local path.
 obs=company_private.r55_cp_clock_observe_local();
 IF obs->>'profile' IS DISTINCT FROM 'LINUX_ADJTIMEX_DB_LOCAL_V1' OR obs->>'source_sync_state' IS DISTINCT FROM 'SYNC'
 OR (obs->>'host_boot_id')::uuid IS DISTINCT FROM e.host_boot_id OR (obs->>'backend_pid')::integer IS DISTINCT FROM pg_backend_pid()
 THEN RAISE EXCEPTION 'BLOCKED_LOCAL_CLOCK_SOURCE'; END IF;
 age_ns=(obs->>'boottime_after_ns')::numeric-s.boottime_ns;
 age_lower_ns=(obs->>'boottime_before_ns')::numeric-s.boottime_ns;
 capture_ns=(obs->>'boottime_after_ns')::numeric-(obs->>'boottime_before_ns')::numeric;
 IF age_lower_ns<0 OR capture_ns<0 OR age_ns>(e.r55_policy->>'max_sample_age_ms')::numeric*1000000 THEN RAISE EXCEPTION 'CLOCK_SAMPLE_STALE'; END IF;
 drift_ns=ceil(age_ns*s.r55_frequency_error_ppm_bound/1000000)+s.r55_sampling_error_margin_ns;
 IF drift_ns>(e.r55_policy->>'max_drift_ms')::numeric*1000000 THEN RAISE EXCEPTION 'CLOCK_DRIFT_EXCEEDED'; END IF;
 uncertainty_ns=greatest(s.uncertainty_ms::numeric*1000000+drift_ns+capture_ns,(obs->>'maxerror_us')::numeric*1000,(obs->>'esterror_us')::numeric*1000);
 IF uncertainty_ns>(e.r55_policy->>'max_uncertainty_ms')::numeric*1000000 THEN RAISE EXCEPTION 'CLOCK_UNCERTAINTY_EXCEEDED'; END IF;
 IF greatest(abs((obs->>'utc_ns')::numeric-extract(epoch FROM s.utc_lower_bound)*1000000000-age_ns),
             abs((obs->>'utc_ns')::numeric-extract(epoch FROM s.utc_upper_bound)*1000000000-age_lower_ns))
 >(e.r55_policy->>'max_clock_jump_ms')::numeric*1000000 THEN RAISE EXCEPTION 'CLOCK_JUMP'; END IF;
 -- Trusted current UTC is projected from the signed source interval and fresh
 -- BOOTTIME; local realtime is only a jump rejection, not an expiry authority.
 utc_lo=s.utc_lower_bound+floor((age_lower_ns-drift_ns)/1000)*interval '1 microsecond';
 utc_hi=s.utc_upper_bound+ceil((age_ns+drift_ns)/1000)*interval '1 microsecond';
 IF NOT EXISTS(SELECT 1 FROM company.signer_enrollments k WHERE k.tenant_id=p_tenant AND k.issuer_id=s.r55_source_issuer
 AND k.key_id=s.r55_source_key AND k.enrollment_revision=s.r55_source_enrollment_revision AND k.purpose='CLOCK_OBSERVATION'
 AND k.profile_id='R55_CLOCK_V1_RAW_JSON' AND k.revoked_at IS NULL AND k.compromised_since IS NULL
 AND k.r55_project_id=p_project AND k.r55_host_id=e.r55_host_registration_id AND k.r55_host_revision=e.r55_host_registration_revision
 AND k.r55_host_generation=e.r55_host_generation AND k.r55_host_boot_id=e.host_boot_id
 AND k.valid_from<=utc_lo AND k.valid_until>utc_hi)
 THEN RAISE EXCEPTION 'CLOCK_SAMPLE_ENROLLMENT_REVOKED_OR_AMBIGUOUS'; END IF;
 RETURN jsonb_build_object('utc_lower_bound',utc_lo,'utc_upper_bound',utc_hi,'epoch_id',p_epoch,'sample_id',p_sample,
 'host_boot_id',e.host_boot_id,'host_registration_id',e.r55_host_registration_id,'host_registration_revision',e.r55_host_registration_revision,
 'host_generation',e.r55_host_generation,'writer_generation',e.writer_generation,'boottime_after_ns',obs->'boottime_after_ns');
END $$;

-- SOURCE sql/034_R58_EXECUTION_SCHEMA.sql
-- Inert r58 extension of selected r53/r54/r55/r56/r57 ABI. Not a migration.
CREATE ROLE company_execution_functions_r58 NOLOGIN NOSUPERUSER NOBYPASSRLS NOINHERIT;
CREATE ROLE company_attestation_functions_r58 NOLOGIN NOSUPERUSER NOBYPASSRLS NOINHERIT;
CREATE TRIGGER r58_acceptance_immutable BEFORE UPDATE OR DELETE ON company.acceptance_records FOR EACH ROW EXECUTE FUNCTION company.reject_audit_mutation();
-- No role membership, LOGIN, approval, policy duration or secret is enrolled.
GRANT USAGE ON SCHEMA company,company_private TO company_execution_functions_r58,company_attestation_functions_r58;
CREATE TABLE company_private.r58_key_material (
 key_id uuid PRIMARY KEY, purpose text NOT NULL CHECK(purpose IN ('EXECUTION_ATTESTATION','CLOCK_POLICY')),
 secret bytea NOT NULL CHECK(octet_length(secret)=32),
 fingerprint text NOT NULL CHECK(fingerprint=encode(sha256(secret),'hex')),
 revoked boolean NOT NULL DEFAULT false
);
REVOKE ALL ON company_private.r58_key_material FROM PUBLIC;
ALTER TABLE company_private.r58_key_material ENABLE ROW LEVEL SECURITY;
ALTER TABLE company_private.r58_key_material FORCE ROW LEVEL SECURITY;
GRANT SELECT ON company_private.r58_key_material TO company_attestation_functions_r58;
CREATE POLICY r58_secret_verifier ON company_private.r58_key_material FOR SELECT TO company_attestation_functions_r58 USING(purpose='EXECUTION_ATTESTATION' AND NOT revoked);
GRANT UPDATE(revoked) ON company_private.r58_key_material TO company_attestation_functions_r58;
CREATE POLICY r58_secret_lock ON company_private.r58_key_material FOR UPDATE TO company_attestation_functions_r58 USING(purpose='EXECUTION_ATTESTATION') WITH CHECK(false);

CREATE TABLE company_private.r58_attestations (
 tenant_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,
 issuer_id uuid NOT NULL,key_id uuid NOT NULL,enrollment_revision bigint NOT NULL,
 profile text NOT NULL,raw_digest text NOT NULL CHECK(raw_digest ~ '^[a-f0-9]{64}$'),
 raw_bytes bytea NOT NULL CHECK(octet_length(raw_bytes) BETWEEN 1 AND 65536 AND encode(sha256(raw_bytes),'hex')=raw_digest),
 auth_tag text NOT NULL CHECK(auth_tag ~ '^[a-f0-9]{64}$'),
 payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),
 PRIMARY KEY(tenant_id,project_id,id),
 FOREIGN KEY(tenant_id,project_id) REFERENCES company.projects(tenant_id,id),
 FOREIGN KEY(tenant_id,issuer_id) REFERENCES company.principals(tenant_id,id)
);
CREATE TABLE company_private.r58_lease_policies (
 tenant_id uuid NOT NULL,project_id uuid NOT NULL,revision bigint NOT NULL CHECK(revision>0),
 duration_ms bigint NOT NULL CHECK(duration_ms>0),enabled boolean NOT NULL DEFAULT false,
 allowed_tools text[] NOT NULL,controller_id uuid NOT NULL,
 executable_digest text NOT NULL CHECK(executable_digest ~ '^[a-f0-9]{64}$'),
 verification_profile_digest text NOT NULL CHECK(verification_profile_digest ~ '^[a-f0-9]{64}$'),
 approved_by uuid NOT NULL,consent_digest text NOT NULL CHECK(consent_digest ~ '^[a-f0-9]{64}$'),
 valid_until timestamptz NOT NULL CHECK(isfinite(valid_until)),
 PRIMARY KEY(tenant_id,project_id,revision),
 FOREIGN KEY(tenant_id,project_id) REFERENCES company.projects(tenant_id,id),
 FOREIGN KEY(tenant_id,approved_by) REFERENCES company.principals(tenant_id,id)
);
CREATE TABLE company_private.r58_controller_heads (
 tenant_id uuid NOT NULL,project_id uuid NOT NULL,controller_id uuid NOT NULL,generation bigint NOT NULL CHECK(generation>0),
 host_id uuid NOT NULL,host_revision bigint NOT NULL,host_generation bigint NOT NULL,host_boot_id uuid NOT NULL,
 approved_by uuid NOT NULL,enabled boolean NOT NULL DEFAULT false,
 PRIMARY KEY(tenant_id,project_id,controller_id,generation),
 FOREIGN KEY(tenant_id,project_id,host_id,host_revision,host_generation) REFERENCES company.host_registrations(tenant_id,project_id,id,revision,bound_generation),
 FOREIGN KEY(tenant_id,controller_id) REFERENCES company.principals(tenant_id,id),
 FOREIGN KEY(tenant_id,approved_by) REFERENCES company.principals(tenant_id,id)
);
CREATE UNIQUE INDEX r58_current_controller ON company_private.r58_controller_heads(tenant_id,project_id,controller_id) WHERE enabled;
CREATE UNIQUE INDEX r58_one_lease_policy ON company_private.r58_lease_policies(tenant_id,project_id) WHERE enabled;
CREATE TABLE company_private.r58_workspace_heads (
 tenant_id uuid NOT NULL,project_id uuid NOT NULL,workspace_id uuid NOT NULL,
 revision bigint NOT NULL CHECK(revision>=0),head_digest text NOT NULL CHECK(head_digest ~ '^[a-f0-9]{64}$'),
 attestation_id uuid NOT NULL,
 PRIMARY KEY(tenant_id,project_id),
 FOREIGN KEY(tenant_id,project_id) REFERENCES company.projects(tenant_id,id),
 FOREIGN KEY(tenant_id,workspace_id) REFERENCES company.workspaces(tenant_id,id),
 FOREIGN KEY(tenant_id,project_id,attestation_id) REFERENCES company_private.r58_attestations(tenant_id,project_id,id)
);
ALTER TABLE company.attempts ADD COLUMN r58_binding_digest text CHECK(r58_binding_digest ~ '^[a-f0-9]{64}$');
ALTER TABLE company.attempts ADD COLUMN r58_head_digest text CHECK(r58_head_digest ~ '^[a-f0-9]{64}$');
ALTER TABLE company.attempts ADD COLUMN r58_policy_revision bigint CHECK(r58_policy_revision>0);
ALTER TABLE company.attempts ADD COLUMN r58_verification_profile_digest text CHECK(r58_verification_profile_digest ~ '^[a-f0-9]{64}$');
CREATE TABLE company_private.r58_launch_capabilities (
 tenant_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,
 process_id uuid NOT NULL,tuple jsonb NOT NULL CHECK(jsonb_typeof(tuple)='object'),
 tuple_digest text NOT NULL CHECK(tuple_digest=encode(sha256(convert_to(tuple::text,'UTF8')),'hex')),
 state text NOT NULL CHECK(state IN ('RESERVED','CONSUMED','RUNNING','UNKNOWN_LOCAL')),
 consume_command_id uuid,callback_attestation_id uuid,
 PRIMARY KEY(tenant_id,project_id,id),UNIQUE(tenant_id,project_id,process_id),
 FOREIGN KEY(tenant_id,project_id,process_id) REFERENCES company.process_runs(tenant_id,project_id,id),
 FOREIGN KEY(tenant_id,consume_command_id) REFERENCES company.commands(tenant_id,id),
 FOREIGN KEY(tenant_id,project_id,callback_attestation_id) REFERENCES company_private.r58_attestations(tenant_id,project_id,id)
);
CREATE TABLE company_private.r58_execution_receipts (
 tenant_id uuid NOT NULL,project_id uuid NOT NULL,command_id uuid NOT NULL,
 operation text NOT NULL,target_id uuid NOT NULL,payload jsonb NOT NULL,
 PRIMARY KEY(tenant_id,command_id),
 FOREIGN KEY(tenant_id,command_id) REFERENCES company.commands(tenant_id,id),
 FOREIGN KEY(tenant_id,project_id) REFERENCES company.projects(tenant_id,id)
);
-- Metadata supplements canonical owners; it never replaces Attempt/Process/Evidence.
CREATE TABLE company_private.r58_patch_receipts (
 tenant_id uuid NOT NULL,project_id uuid NOT NULL,task_id uuid NOT NULL,attempt_id uuid NOT NULL,id uuid NOT NULL,
 fence bigint NOT NULL,base_head text NOT NULL,result_head text NOT NULL,patch_digest text NOT NULL,
 tool_request_id uuid NOT NULL,attestation_id uuid NOT NULL,command_id uuid NOT NULL,
 PRIMARY KEY(tenant_id,project_id,id),
 FOREIGN KEY(tenant_id,project_id,task_id,attempt_id) REFERENCES company.attempts(tenant_id,project_id,task_id,id),
 FOREIGN KEY(tenant_id,project_id,attestation_id) REFERENCES company_private.r58_attestations(tenant_id,project_id,id),
 FOREIGN KEY(tenant_id,command_id) REFERENCES company.commands(tenant_id,id)
);
CREATE TABLE company_private.r58_verification_seals (
 tenant_id uuid NOT NULL,project_id uuid NOT NULL,task_id uuid NOT NULL,attempt_id uuid NOT NULL,verification_id uuid NOT NULL,
 patch_id uuid NOT NULL,head_digest text NOT NULL,attestation_id uuid NOT NULL,seal_digest text NOT NULL,command_id uuid NOT NULL,
 PRIMARY KEY(tenant_id,project_id,verification_id),
 FOREIGN KEY(tenant_id,project_id,task_id,attempt_id,verification_id) REFERENCES company.verification_runs(tenant_id,project_id,task_id,attempt_id,id),
 FOREIGN KEY(tenant_id,project_id,patch_id) REFERENCES company_private.r58_patch_receipts(tenant_id,project_id,id),
 FOREIGN KEY(tenant_id,project_id,attestation_id) REFERENCES company_private.r58_attestations(tenant_id,project_id,id),
 FOREIGN KEY(tenant_id,command_id) REFERENCES company.commands(tenant_id,id)
);
-- The exact required oracle manifest is independently HUMAN-enrolled, not caller-selected.
CREATE TABLE company_private.r58_verification_profiles (
 tenant_id uuid NOT NULL,project_id uuid NOT NULL,profile_digest text NOT NULL,
 oracle_ids jsonb NOT NULL CHECK(jsonb_typeof(oracle_ids)='array' AND jsonb_array_length(oracle_ids)>0),
 approved_by uuid NOT NULL,enabled boolean NOT NULL DEFAULT false,
 PRIMARY KEY(tenant_id,project_id,profile_digest),
 FOREIGN KEY(tenant_id,approved_by) REFERENCES company.principals(tenant_id,id)
);
CREATE TABLE company_private.r58_evidence_provenance (
 tenant_id uuid NOT NULL,project_id uuid NOT NULL,task_id uuid NOT NULL,attempt_id uuid NOT NULL,evidence_id uuid NOT NULL,
 attestation_id uuid NOT NULL,head_digest text NOT NULL,seal_digest text NOT NULL,command_id uuid NOT NULL,
 PRIMARY KEY(tenant_id,project_id,evidence_id),
 FOREIGN KEY(tenant_id,project_id,task_id,attempt_id,evidence_id) REFERENCES company.evidence(tenant_id,project_id,task_id,attempt_id,id),
 FOREIGN KEY(tenant_id,project_id,attestation_id) REFERENCES company_private.r58_attestations(tenant_id,project_id,id),
 FOREIGN KEY(tenant_id,command_id) REFERENCES company.commands(tenant_id,id)
);
CREATE FUNCTION company_private.r58_metadata_immutable() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'R58_METADATA_HISTORY_IMMUTABLE'; END IF;
 IF TG_TABLE_NAME='r58_launch_capabilities' THEN
  IF (to_jsonb(OLD)-ARRAY['state','consume_command_id','callback_attestation_id']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','consume_command_id','callback_attestation_id'])
  OR NOT ((OLD.state='RESERVED' AND NEW.state='CONSUMED' AND OLD.consume_command_id IS NULL AND NEW.consume_command_id IS NOT NULL AND NEW.callback_attestation_id IS NULL)
  OR (OLD.state='CONSUMED' AND NEW.state IN ('RUNNING','UNKNOWN_LOCAL') AND NEW.consume_command_id=OLD.consume_command_id AND OLD.callback_attestation_id IS NULL AND NEW.callback_attestation_id IS NOT NULL)) THEN RAISE EXCEPTION 'R58_CAPABILITY_IDENTITY_OR_STATE_IMMUTABLE'; END IF;
 ELSIF TG_TABLE_NAME='r58_workspace_heads' THEN
  IF ROW(NEW.tenant_id,NEW.project_id,NEW.workspace_id) IS DISTINCT FROM ROW(OLD.tenant_id,OLD.project_id,OLD.workspace_id) OR NEW.revision<>OLD.revision+1 OR NEW.attestation_id=OLD.attestation_id THEN RAISE EXCEPTION 'R58_HEAD_REVISION_REQUIRED'; END IF;
 ELSE
  IF (to_jsonb(OLD)-'enabled') IS DISTINCT FROM (to_jsonb(NEW)-'enabled') OR OLD.enabled IS NOT TRUE OR NEW.enabled IS NOT FALSE THEN RAISE EXCEPTION 'R58_POLICY_DISABLE_ONLY_CREATE_NEW_REVISION'; END IF;
 END IF;
 RETURN NEW;
END $$;
DO $immutability$ DECLARE t text;BEGIN
 FOREACH t IN ARRAY ARRAY['r58_launch_capabilities','r58_workspace_heads','r58_lease_policies','r58_controller_heads','r58_verification_profiles'] LOOP
  EXECUTE format('CREATE TRIGGER r58_metadata_immutable BEFORE UPDATE OR DELETE ON company_private.%I FOR EACH ROW EXECUTE FUNCTION company_private.r58_metadata_immutable()',t);
 END LOOP;
END $immutability$;
DO $security$ DECLARE t text;BEGIN
 FOREACH t IN ARRAY ARRAY['r58_attestations','r58_lease_policies','r58_controller_heads','r58_workspace_heads','r58_launch_capabilities','r58_execution_receipts','r58_patch_receipts','r58_verification_seals','r58_verification_profiles','r58_evidence_provenance'] LOOP
  EXECUTE format('ALTER TABLE company_private.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE company_private.%I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('REVOKE ALL ON company_private.%I FROM PUBLIC',t);
  EXECUTE format('GRANT SELECT ON company_private.%I TO company_execution_functions_r58',t);
  EXECUTE format('CREATE POLICY r58_scope_read ON company_private.%I FOR SELECT TO company_execution_functions_r58 USING(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.writer_generation=54 AND x.tenant_id=%I.tenant_id AND x.project_id=%I.project_id))',t,t,t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['r58_workspace_heads','r58_launch_capabilities','r58_execution_receipts','r58_patch_receipts','r58_verification_seals','r58_evidence_provenance'] LOOP
  EXECUTE format('GRANT INSERT ON company_private.%I TO company_execution_functions_r58',t);
  EXECUTE format('CREATE POLICY r58_scope_insert ON company_private.%I FOR INSERT TO company_execution_functions_r58 WITH CHECK(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.writer_generation=54 AND x.tenant_id=%I.tenant_id AND x.project_id=%I.project_id))',t,t,t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['r58_attestations','r58_execution_receipts','r58_patch_receipts','r58_verification_seals','r58_evidence_provenance'] LOOP
  EXECUTE format('CREATE TRIGGER r58_immutable BEFORE UPDATE OR DELETE ON company_private.%I FOR EACH ROW EXECUTE FUNCTION company.reject_audit_mutation()',t);
 END LOOP;
END $security$;
GRANT SELECT ON company_private.request_contexts,company_private.operation_permissions TO company_execution_functions_r58,company_attestation_functions_r58;
CREATE POLICY r58_execution_context ON company_private.request_contexts FOR SELECT TO company_execution_functions_r58,company_attestation_functions_r58 USING(backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54);
CREATE POLICY r58_execution_registry ON company_private.operation_permissions FOR SELECT TO company_execution_functions_r58,company_attestation_functions_r58 USING(true);
GRANT SELECT ON company.principals,company.signer_enrollments TO company_attestation_functions_r58;
GRANT UPDATE(enrollment_revision) ON company.signer_enrollments TO company_attestation_functions_r58;
CREATE POLICY r58_attest_signer ON company.signer_enrollments FOR SELECT TO company_attestation_functions_r58 USING(purpose='TASK_VERIFICATION');
CREATE POLICY r58_attest_signer_lock ON company.signer_enrollments FOR UPDATE TO company_attestation_functions_r58 USING(purpose='TASK_VERIFICATION') WITH CHECK(false);
CREATE POLICY r58_attest_principal ON company.principals FOR SELECT TO company_attestation_functions_r58 USING(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=principals.tenant_id));
GRANT SELECT,INSERT ON company_private.r58_attestations TO company_attestation_functions_r58;
CREATE POLICY r58_attest_scope ON company_private.r58_attestations TO company_attestation_functions_r58
 USING(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=r58_attestations.tenant_id AND x.project_id=r58_attestations.project_id))
 WITH CHECK(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.tenant_id=r58_attestations.tenant_id AND x.project_id=r58_attestations.project_id AND x.principal_id=r58_attestations.issuer_id));

-- SOURCE sql/035_R58_OPERATION_REGISTRY.sql
CREATE OR REPLACE FUNCTION company_private.r55_cp_event_kind(p_operation text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT CASE p_operation
 WHEN 'e0.process_admit' THEN 'E0ProcessAdmitted'
 WHEN 'e0.process_stop_confirm' THEN 'E0ProcessStopConfirmed'
 WHEN 'e0.process_release' THEN 'E0ProcessReleased'
 WHEN 'e0.process_reconcile' THEN 'E0ProcessReconciled'
 WHEN 'e0.evaluation_envelope_persist' THEN 'E0EnvelopePersisted'
 WHEN 'e0.process_proof_persist' THEN 'E0ProcessProofPersisted'
 WHEN 'plans.create' THEN 'PlanCreated'
 WHEN 'tasks.create' THEN 'TaskCreated'
 WHEN 'objectives.create' THEN 'ObjectiveCreated'
 WHEN 'worker.claim' THEN 'WorkerClaimed'
 WHEN 'worker.heartbeat' THEN 'WorkerHeartbeat'
 WHEN 'workspace.current_head' THEN 'WorkspaceHeadUpdated'
 WHEN 'process.launch_reserve' THEN 'LaunchReserved'
 WHEN 'process.launch_consume' THEN 'LaunchConsumed'
 WHEN 'process.launch_callback' THEN 'LaunchCallbackRecorded'
 WHEN 'tool.authorize_final' THEN 'ToolAuthorized'
 WHEN 'patch.receipt' THEN 'PatchReceiptPersisted'
 WHEN 'verification.final_seal' THEN 'VerificationSealed'
 WHEN 'evidence.provenance' THEN 'EvidenceProvenanceRecorded'
 WHEN 'verification.accept' THEN 'TaskAccepted'
 WHEN 'evidence.attestation_ingest' THEN 'ExecutionAttestationIngested'
 WHEN 'process.stop_release' THEN 'ProcessStoppedAndReleased'
 END;
$$;
REVOKE ALL ON FUNCTION company_private.r55_cp_event_kind(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_event_kind(text) TO company_atomic_functions_r55,company_first_run_functions_r53;

