ALTER TABLE company.commands DROP CONSTRAINT r56_command_finality_shape;
ALTER TABLE company.commands ADD CONSTRAINT r58_command_finality_shape CHECK((
 (r55_project_id IS NULL AND r55_result_payload IS NULL AND r55_result_digest IS NULL AND r55_event_sequence IS NULL AND r55_audit_id IS NULL AND r55_source_revision IS NULL)
 OR (state='SUCCEEDED' AND r55_project_id IS NOT NULL AND jsonb_typeof(r55_result_payload)='object'
 AND r55_result_digest ~ '^[a-f0-9]{64}$' AND r55_event_sequence>0 AND r55_audit_id>0 AND r55_source_revision IN ('r55-cp1','r56','r58'))) IS TRUE);
GRANT UPDATE(state,result_ref) ON company.commands TO company_atomic_functions_r55;
CREATE OR REPLACE FUNCTION company.r50_command_identity_immutable() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF OLD.operation='trusted_setup.consume' AND OLD.state='RUNNING' AND OLD.r55_result_digest IS NULL
 AND NEW.state='SUCCEEDED' AND NEW.r55_source_revision='r56' THEN
  IF (to_jsonb(OLD)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
   IS DISTINCT FROM
   (to_jsonb(NEW)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
  OR NOT EXISTS(SELECT 1 FROM company_private.bootstrap_request_contexts x
   JOIN company_private.installation_bootstrap_control b ON b.installation_id=x.installation_id AND b.generation=x.generation
   WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user
   AND x.r56_command_id=OLD.id AND b.expected_tenant_id=OLD.tenant_id AND b.expected_human_id=OLD.principal_id
   AND b.expected_project_id=NEW.r55_project_id AND b.installation_id=NEW.result_ref
   AND b.state='ARMED' AND x.manifest_digest=OLD.payload_digest)
  THEN RAISE EXCEPTION 'IMMUTABLE_COMMAND_RECEIPT'; END IF;
 ELSIF OLD.operation IN ('objectives.create','plans.create','tasks.create','e0.process_proof_persist','e0.evaluation_envelope_persist','e0.process_admit','e0.process_stop_confirm','e0.process_reconcile','e0.process_release','worker.claim','worker.heartbeat','workspace.current_head','process.launch_reserve','process.launch_consume','process.launch_callback','tool.authorize_final','patch.receipt','verification.final_seal','evidence.provenance','verification.accept','evidence.attestation_ingest','process.stop_release')
 AND OLD.state='RUNNING' AND OLD.result_ref IS NULL AND OLD.r55_result_digest IS NULL
 AND NEW.state='SUCCEEDED' AND NEW.r55_source_revision IN ('r55-cp1','r58') THEN
  IF current_user<>'company_atomic_functions_r55'
  OR (to_jsonb(OLD)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
   IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
  OR NOT EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid()
   AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.writer_generation=54
   AND x.tenant_id=OLD.tenant_id AND x.project_id=NEW.r55_project_id AND x.principal_id=OLD.principal_id AND x.operation_id=OLD.operation)
  THEN RAISE EXCEPTION 'IMMUTABLE_COMMAND_RECEIPT'; END IF;
 ELSE
  IF to_jsonb(OLD) IS DISTINCT FROM to_jsonb(NEW)
  OR (OLD.state IN ('SUCCEEDED','FAILED') AND ROW(OLD.state,OLD.result_ref) IS DISTINCT FROM ROW(NEW.state,NEW.result_ref))
  THEN RAISE EXCEPTION 'IMMUTABLE_COMMAND_RECEIPT'; END IF;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION company.r50_command_identity_immutable() FROM PUBLIC;

CREATE OR REPLACE FUNCTION company_private.r55_cp_finalize_command(p_command uuid,p_aggregate uuid,p_revision bigint,p_event_kind text,p_result_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; d text; seq bigint; aid bigint; perm text; event_payload jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 IF p_command IS NULL OR p_aggregate IS NULL OR p_revision IS NULL OR p_revision<0 OR p_result_payload IS NULL OR jsonb_typeof(p_result_payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'INVALID_RESULT_BINDING'; END IF;
 IF p_event_kind IS DISTINCT FROM company_private.r55_cp_event_kind(x.operation_id) OR company_private.r55_cp_event_kind(x.operation_id) IS NULL THEN RAISE EXCEPTION 'UNREGISTERED_FINALIZER_OPERATION'; END IF;
 SELECT permission INTO STRICT perm FROM company_private.operation_permissions WHERE operation_id=x.operation_id AND execution_class NOT IN ('QUERY','STREAM');
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_FINALIZE_COMMAND'; END IF;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=x.tenant_id AND id=p_command AND principal_id=x.principal_id AND operation=x.operation_id FOR UPDATE;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_FINALIZE_AFTER_LOCK_WAIT'; END IF;
 IF c.payload_digest IS NULL OR c.correlation_id IS NULL THEN RAISE EXCEPTION 'COMMAND_IDENTITY_INCOMPLETE'; END IF;
 d=encode(sha256(convert_to(jsonb_build_array(c.id,c.payload_digest,p_aggregate,p_revision,p_event_kind,p_result_payload,coalesce(c.r55_source_revision,'r58'))::text,'UTF8')),'hex');
 IF c.r55_result_digest IS NOT NULL THEN
  IF c.state IS DISTINCT FROM 'SUCCEEDED' OR c.result_ref IS DISTINCT FROM p_aggregate
   OR c.r55_result_digest IS DISTINCT FROM d OR c.r55_project_id IS DISTINCT FROM x.project_id
   OR c.r55_result_payload IS DISTINCT FROM p_result_payload OR c.r55_event_sequence IS NULL OR c.r55_audit_id IS NULL
   OR NOT EXISTS(SELECT 1 FROM company.audit_events a WHERE a.tenant_id=c.tenant_id AND a.id=c.r55_audit_id AND a.actor_id=c.principal_id AND a.correlation_id=c.correlation_id AND a.kind=p_event_kind)
   OR NOT EXISTS(SELECT 1 FROM company.outbox e WHERE e.tenant_id=c.tenant_id AND e.project_id=c.r55_project_id AND e.project_sequence=c.r55_event_sequence AND e.event_instance_id=c.id AND e.event_writer_generation=54 AND e.kind=p_event_kind AND e.payload->>'result_digest'=d AND e.payload->>'request_digest'=c.payload_digest) THEN RAISE EXCEPTION 'CONFLICT_RESULT_DIGEST'; END IF;
  RETURN jsonb_build_object('command_id',c.id,'correlation_id',c.correlation_id,'state',c.state,'result_ref',c.result_ref);
 END IF;
 IF c.state IS DISTINCT FROM 'RUNNING' OR c.result_ref IS NOT NULL THEN RAISE EXCEPTION 'UNSEALED_RUNNING_COMMAND_REQUIRED'; END IF;
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(x.tenant_id,c.correlation_id,x.principal_id,p_event_kind) RETURNING id INTO aid;
 event_payload=jsonb_build_object('command_id',c.id,'request_digest',c.payload_digest,'result_digest',d,'result_ref',p_aggregate,'source_revision','r58');
 seq=company_private.r55_cp_emit_event(x.tenant_id,x.project_id,c.id,p_aggregate,p_revision,p_event_kind,event_payload);
 UPDATE company.commands SET state='SUCCEEDED',result_ref=p_aggregate,r55_project_id=x.project_id,r55_result_payload=p_result_payload,r55_result_digest=d,r55_event_sequence=seq,r55_audit_id=aid,r55_source_revision='r58' WHERE tenant_id=c.tenant_id AND id=c.id AND state='RUNNING' AND result_ref IS NULL AND r55_result_digest IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'CONFLICT_RESULT_FINALIZATION'; END IF;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=x.tenant_id AND id=p_command;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_COMMAND_COMMIT_CUT'; END IF;
 RETURN jsonb_build_object('command_id',c.id,'correlation_id',c.correlation_id,'state',c.state,'result_ref',c.result_ref);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'COMMAND_OR_CONTEXT_UNRESOLVED';
END $$;
ALTER FUNCTION company_private.r55_cp_finalize_command(uuid,uuid,bigint,text,jsonb) OWNER TO company_atomic_functions_r55;
REVOKE ALL ON FUNCTION company_private.r55_cp_finalize_command(uuid,uuid,bigint,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_finalize_command(uuid,uuid,bigint,text,jsonb) TO company_first_run_functions_r53;

CREATE FUNCTION company.r58_command_insert_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF NEW.state IS DISTINCT FROM 'RUNNING' OR NEW.result_ref IS NOT NULL OR NEW.r55_result_digest IS NOT NULL
 OR NEW.r55_project_id IS NOT NULL OR NEW.r55_result_payload IS NOT NULL OR NEW.r55_event_sequence IS NOT NULL OR NEW.r55_audit_id IS NOT NULL OR NEW.r55_source_revision IS NOT NULL THEN RAISE EXCEPTION 'R58_COMMAND_MUST_START_UNSEALED'; END IF;
 IF NEW.operation='trusted_setup.consume' THEN
  IF current_user<>'company_bootstrap_functions_r56' OR NOT EXISTS(SELECT 1 FROM company_private.bootstrap_request_contexts x JOIN company_private.installation_bootstrap_control b ON b.installation_id=x.installation_id AND b.generation=x.generation WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND b.expected_tenant_id=NEW.tenant_id AND b.expected_human_id=NEW.principal_id AND b.state='ARMED') THEN RAISE EXCEPTION 'R58_BOOTSTRAP_INSERT_CONTEXT'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM company_private.operation_permissions op WHERE op.operation_id=NEW.operation AND op.approved_policy_digest IS NOT NULL)
  OR NOT EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.writer_generation=54 AND x.tenant_id=NEW.tenant_id AND x.principal_id=NEW.principal_id AND x.operation_id=NEW.operation)
  OR NEW.operation NOT IN ('worker.claim','worker.heartbeat','workspace.current_head','process.launch_reserve','process.launch_consume','process.launch_callback','tool.authorize_final','patch.receipt','verification.final_seal','evidence.provenance','verification.accept','evidence.attestation_ingest','process.stop_release','objectives.create','plans.create','tasks.create','e0.process_proof_persist','e0.evaluation_envelope_persist','e0.process_admit','e0.process_stop_confirm','e0.process_reconcile','e0.process_release') THEN RAISE EXCEPTION 'R58_LEGACY_OR_UNKNOWN_COMMAND_INSERT_BLOCKED'; END IF;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION company.r58_command_insert_guard() FROM PUBLIC;
CREATE TRIGGER r58_command_insert_guard BEFORE INSERT ON company.commands FOR EACH ROW EXECUTE FUNCTION company.r58_command_insert_guard();

-- SOURCE sql/037_R58_EXECUTION_HELPERS.sql
CREATE FUNCTION company_private.r58_context(p_operation text) RETURNS company_private.request_contexts
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;perm text;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54 AND operation_id=p_operation;
 SELECT permission INTO STRICT perm FROM company_private.operation_permissions WHERE operation_id=p_operation AND execution_class='COMMAND' AND approved_policy_digest IS NOT NULL AND policy_revision=x.policy_revision;
 IF x.project_id IS NULL OR company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'R58_CURRENT_AUTHORITY_REQUIRED'; END IF;
 RETURN x;
END $$;
CREATE FUNCTION company_private.r58_shape(v jsonb,fields text[]) RETURNS void
LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR NOT ((v ?& fields) IS TRUE)
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(v) k WHERE k<>ALL(fields))
 OR EXISTS(SELECT 1 FROM jsonb_each(v) z WHERE z.value='null'::jsonb) THEN RAISE EXCEPTION 'R58_EXACT_NON_NULL_FIELDS'; END IF;
END $$;
CREATE FUNCTION company_private.r58_unique_json(v json) RETURNS void
LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE item json;
BEGIN
 IF json_typeof(v)='object' THEN
  IF EXISTS(SELECT key FROM json_each(v) GROUP BY key HAVING count(*)>1) THEN RAISE EXCEPTION 'R58_DUPLICATE_JSON_KEYS'; END IF;
  FOR item IN SELECT value FROM json_each(v) LOOP PERFORM company_private.r58_unique_json(item); END LOOP;
 ELSIF json_typeof(v)='array' THEN
  FOR item IN SELECT value FROM json_array_elements(v) LOOP PERFORM company_private.r58_unique_json(item); END LOOP;
 END IF;
END $$;
CREATE FUNCTION company_private.r58_begin_command(p_key text,p_correlation uuid,p_request jsonb) RETURNS company.commands
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;c company.commands%ROWTYPE;d text;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 x=company_private.r58_context(x.operation_id);
 IF p_key IS NULL OR p_key !~ '^[A-Za-z0-9_.:-]{16,128}$' OR p_correlation IS NULL OR jsonb_typeof(p_request) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'R58_COMMAND_BINDING'; END IF;
 d=encode(sha256(convert_to(p_request::text,'UTF8')),'hex');
 SELECT * INTO c FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation=x.operation_id AND idempotency_key=p_key FOR UPDATE;
 IF FOUND THEN
  IF c.payload_digest IS DISTINCT FROM d OR c.state IS DISTINCT FROM 'SUCCEEDED' OR c.r55_result_digest IS NULL THEN RAISE EXCEPTION 'R58_IDEMPOTENCY_CONFLICT_OR_INCOMPLETE'; END IF;
  RETURN c;
 END IF;
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,gen_random_uuid(),x.principal_id,x.operation_id,p_key,d,p_correlation,'RUNNING',NULL) RETURNING * INTO c;
 RETURN c;
END $$;
CREATE FUNCTION company_private.r58_finish(p_command uuid,p_target uuid,p_result jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;c company.commands%ROWTYPE;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 x=company_private.r58_context(x.operation_id);
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=x.tenant_id AND id=p_command AND principal_id=x.principal_id AND operation=x.operation_id;
 IF c.state='SUCCEEDED' THEN RETURN company_private.r57_replay_command(c.id); END IF;
 INSERT INTO company_private.r58_execution_receipts(tenant_id,project_id,command_id,operation,target_id,payload) VALUES(x.tenant_id,x.project_id,c.id,x.operation_id,p_target,p_result);
 RETURN company_private.r55_cp_finalize_command(c.id,p_target,0,company_private.r55_cp_event_kind(x.operation_id),p_result);
END $$;
CREATE FUNCTION company_private.r58_qualification(p_q uuid,p_subject uuid,p_binding text) RETURNS company.agent_qualifications
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;q company.agent_qualifications%ROWTYPE;h company.governance_decision_heads%ROWTYPE;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 SELECT * INTO STRICT q FROM company.agent_qualifications WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_q FOR SHARE;
 IF p_binding IS NULL OR q.subject_principal_id IS DISTINCT FROM p_subject OR q.execution_binding_digest IS DISTINCT FROM p_binding
 OR encode(sha256(convert_to(q.version_binding::text,'UTF8')),'hex') IS DISTINCT FROM p_binding
 THEN RAISE EXCEPTION 'R58_EXACT_QUALIFICATION_BINDING'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,q.valid_until);
 SELECT * INTO STRICT h FROM company.governance_decision_heads WHERE tenant_id=x.tenant_id AND scope_kind='PROJECT' AND scope_ref=x.project_id AND decision_kind='QUALIFICATION' AND operation='qualification.activate' AND logical_target_digest=encode(sha256(convert_to(q.id::text,'UTF8')),'hex') FOR SHARE;
 IF h.decision_state IS DISTINCT FROM 'APPROVED' OR NOT EXISTS(SELECT 1 FROM company.artifacts a JOIN company.principals p ON p.tenant_id=a.tenant_id AND p.id=(a.r54_human_decision->>'human_id')::uuid
 WHERE a.tenant_id=x.tenant_id AND a.project_id=h.decision_project_id AND a.task_id=h.decision_task_id AND a.attempt_id=h.decision_attempt_id AND a.id=h.decision_artifact_id AND a.state='AVAILABLE' AND p.kind='HUMAN'
 AND a.r54_human_decision->>'kind'='QUALIFICATION_ACTIVATE' AND a.r54_human_decision->>'qualification_id'=q.id::text AND a.r54_human_decision->>'binding_digest'=p_binding
 AND company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,'-infinity'::timestamptz,(a.r54_human_decision->>'valid_until')::timestamptz)) THEN RAISE EXCEPTION 'R58_CURRENT_HUMAN_QUALIFICATION_HEAD'; END IF;
 RETURN q;
END $$;
CREATE FUNCTION company_private.r58_attempt(p_task uuid,p_attempt uuid,p_fence bigint) RETURNS company.attempts
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;a company.attempts%ROWTYPE;t company.tasks%ROWTYPE;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 SELECT * INTO STRICT t FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_task FOR UPDATE;
 SELECT * INTO STRICT a FROM company.attempts WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_task AND id=p_attempt FOR UPDATE;
 IF t.execution_kind IS DISTINCT FROM 'ORDINARY' OR a.e0_evaluation_run_id IS NOT NULL OR t.active_attempt_id IS DISTINCT FROM a.id OR t.fencing_epoch IS DISTINCT FROM p_fence OR a.fencing_epoch IS DISTINCT FROM p_fence
 OR x.task_id IS DISTINCT FROM p_task OR x.attempt_id IS DISTINCT FROM p_attempt OR x.fencing_epoch IS DISTINCT FROM p_fence
 OR a.state NOT IN ('CLAIMED','RUNNING','PRODUCED') THEN RAISE EXCEPTION 'R58_STALE_ORDINARY_ATTEMPT'; END IF;
 PERFORM 1 FROM company_private.r58_lease_policies lp WHERE lp.tenant_id=x.tenant_id AND lp.project_id=x.project_id AND lp.revision=a.r58_policy_revision AND lp.enabled AND lp.verification_profile_digest=a.r58_verification_profile_digest AND company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,'-infinity'::timestamptz,lp.valid_until) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_ATTEMPT_LEASE_POLICY_REVOKED'; END IF;
 PERFORM 1 FROM company_private.r58_verification_profiles vp WHERE vp.tenant_id=x.tenant_id AND vp.project_id=x.project_id AND vp.profile_digest=a.r58_verification_profile_digest AND vp.enabled FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_ATTEMPT_VERIFICATION_PROFILE_REVOKED'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,a.lease_expires_at);
 PERFORM company_private.r58_qualification(a.admission_qualification_id,a.worker_id,a.r58_binding_digest);
 RETURN a;
END $$;

CREATE FUNCTION company_private.r58_key_current(p_key uuid,p_fingerprint text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM 1 FROM company_private.r58_key_material WHERE key_id=p_key AND fingerprint=p_fingerprint AND purpose='EXECUTION_ATTESTATION' AND NOT revoked FOR SHARE;
 RETURN FOUND;
END $$;
CREATE FUNCTION company_private.r58_attestation(p_id uuid,p_profile text) RETURNS company_private.r58_attestations
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;a company_private.r58_attestations%ROWTYPE;e company.signer_enrollments%ROWTYPE;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 SELECT * INTO STRICT a FROM company_private.r58_attestations WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_id AND profile=p_profile;
 SELECT * INTO STRICT e FROM company.signer_enrollments WHERE tenant_id=x.tenant_id AND issuer_id=a.issuer_id AND key_id=a.key_id AND enrollment_revision=a.enrollment_revision AND purpose='TASK_VERIFICATION' FOR SHARE;
 IF e.revoked_at IS NOT NULL OR e.compromised_since IS NOT NULL OR e.profile_id IS DISTINCT FROM a.profile OR company_private.r58_key_current(a.key_id,e.key_fingerprint) IS NOT TRUE OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,e.valid_from,e.valid_until) IS NOT TRUE THEN RAISE EXCEPTION 'R58_ATTESTATION_SIGNER_NOT_CURRENT'; END IF;
 RETURN a;
END $$;
CREATE FUNCTION company_private.r58_process_current(p_process uuid) RETURNS company.process_runs
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;r company.process_runs%ROWTYPE;ch company_private.r58_controller_heads%ROWTYPE;b jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process FOR SHARE;
 SELECT * INTO STRICT ch FROM company_private.r58_controller_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND controller_id=r.controller_id AND generation=r.controller_generation AND enabled FOR SHARE;
 b=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 IF r.r55_host_boot_id IS DISTINCT FROM ch.host_boot_id OR b->>'host_boot_id' IS DISTINCT FROM ch.host_boot_id::text
 OR r.host_registration_id IS DISTINCT FROM ch.host_id OR r.host_registration_revision IS DISTINCT FROM ch.host_revision OR r.host_generation IS DISTINCT FROM ch.host_generation
 OR r.e0_evaluation_run_id IS NOT NULL OR r.kind IS DISTINCT FROM 'TASK_EXECUTION'
 OR NOT EXISTS(SELECT 1 FROM company.projects p JOIN company.host_registrations h ON h.tenant_id=p.tenant_id AND h.project_id=p.id AND h.id=p.host_registration_id AND h.revision=p.host_registration_revision AND h.bound_generation=p.instance_generation WHERE p.tenant_id=x.tenant_id AND p.id=x.project_id AND h.id=r.host_registration_id AND h.revision=r.host_registration_revision AND h.bound_generation=r.host_generation AND h.state='BOUND_NOT_LEASED')
 OR NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=ch.approved_by AND kind='HUMAN') THEN RAISE EXCEPTION 'R58_PROCESS_HOST_CONTROLLER_FENCED'; END IF;
 IF ch.controller_id=ch.approved_by OR NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=ch.controller_id AND kind IN ('WORKER','VERIFIER')) THEN RAISE EXCEPTION 'R58_TECHNICAL_CONTROLLER_REQUIRED'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,r.lease_expires_at);
 RETURN r;
END $$;
CREATE FUNCTION company_private.r58_attestation_ingest(p_id uuid,p_issuer uuid,p_key_id uuid,p_revision bigint,p_profile text,p_raw bytea,p_tag bytea,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;e company.signer_enrollments%ROWTYPE;k company_private.r58_key_material%ROWTYPE;c company.commands%ROWTYPE;j jsonb;msg bytea;part bytea;d text;
BEGIN
 x=company_private.r58_context('evidence.attestation_ingest');
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=x.principal_id AND kind IN ('WORKER','VERIFIER')) THEN RAISE EXCEPTION 'R58_TECHNICAL_SIGNER_REQUIRED'; END IF;
 IF p_id IS NULL OR p_issuer IS DISTINCT FROM x.principal_id OR p_key_id IS NULL OR p_revision IS NULL OR p_revision<0 OR p_raw IS NULL OR octet_length(p_raw) NOT BETWEEN 1 AND 65536 OR p_tag IS NULL OR octet_length(p_tag)<>32
 OR p_profile NOT IN ('r58.workspace.v1','r58.launch-manifest.v1','r58.launch-callback.v1','r58.patch.v1','r58.verification.v1','r58.evidence.v1','r58.quiescence.v1') THEN RAISE EXCEPTION 'R58_ATTESTATION_WIRE'; END IF;
 SELECT * INTO STRICT e FROM company.signer_enrollments WHERE tenant_id=x.tenant_id AND issuer_id=p_issuer AND key_id=p_key_id AND enrollment_revision=p_revision AND purpose='TASK_VERIFICATION' FOR SHARE;
 SELECT * INTO STRICT k FROM company_private.r58_key_material WHERE key_id=p_key_id AND purpose='EXECUTION_ATTESTATION' AND NOT revoked FOR SHARE;
 IF e.profile_id IS DISTINCT FROM p_profile OR e.revoked_at IS NOT NULL OR e.compromised_since IS NOT NULL OR e.key_fingerprint IS DISTINCT FROM k.fingerprint
 OR NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=e.approved_by AND kind='HUMAN') OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,e.valid_from,e.valid_until) IS NOT TRUE THEN RAISE EXCEPTION 'R58_SIGNER_ENROLLMENT'; END IF;
 PERFORM company_private.r58_unique_json(convert_from(p_raw,'UTF8')::json);
 j=convert_from(p_raw,'UTF8')::jsonb;
 PERFORM company_private.r58_shape(j,ARRAY['tenant_id','project_id','receipt_id','profile','binding']);
 IF j->>'tenant_id' IS DISTINCT FROM x.tenant_id::text OR j->>'project_id' IS DISTINCT FROM x.project_id::text OR j->>'receipt_id' IS DISTINCT FROM p_id::text OR j->>'profile' IS DISTINCT FROM p_profile OR jsonb_typeof(j->'binding') IS DISTINCT FROM 'object'
 OR EXISTS(SELECT key FROM json_each(convert_from(p_raw,'UTF8')::json) GROUP BY key HAVING count(*)>1) THEN RAISE EXCEPTION 'R58_ATTESTATION_SCOPE'; END IF;
 msg=convert_to('R58-EXECUTION-ATTESTATION-v1','UTF8')||decode('00','hex');
 FOREACH part IN ARRAY ARRAY[convert_to(p_issuer::text,'UTF8'),convert_to(p_key_id::text,'UTF8'),convert_to(p_revision::text,'UTF8'),convert_to(p_profile,'UTF8'),p_raw] LOOP msg=msg||convert_to(octet_length(part)::text||':','UTF8')||part; END LOOP;
 IF company_private.r55_cp_tag_equal(company_private.r55_cp_hmac_sha256(k.secret,msg),p_tag) IS NOT TRUE THEN RAISE EXCEPTION 'R58_INVALID_ATTESTATION_HMAC'; END IF;
 d=encode(sha256(p_raw),'hex');
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('receipt_id',p_id,'issuer',p_issuer,'key',p_key_id,'revision',p_revision,'profile',p_profile,'raw_digest',d));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 INSERT INTO company_private.r58_attestations(tenant_id,project_id,id,issuer_id,key_id,enrollment_revision,profile,raw_digest,raw_bytes,auth_tag,payload) VALUES(x.tenant_id,x.project_id,p_id,p_issuer,p_key_id,p_revision,p_profile,d,p_raw,encode(p_tag,'hex'),j->'binding');
 PERFORM company_private.r58_store_signed_artifact(p_id);
 RETURN company_private.r58_finish(c.id,p_id,jsonb_build_object('receipt_id',p_id,'raw_digest',d,'profile',p_profile));
END $$;
CREATE FUNCTION company_private.r58_store_signed_artifact(p_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;m company_private.r58_attestations%ROWTYPE;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54 AND operation_id='evidence.attestation_ingest';
 SELECT * INTO STRICT m FROM company_private.r58_attestations WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_id AND issuer_id=x.principal_id;
 IF x.task_id IS NOT NULL AND x.attempt_id IS NOT NULL THEN
  -- These are real DB-resident signed-statement bytes, not an invented file.
  INSERT INTO company.artifacts(tenant_id,project_id,task_id,attempt_id,id,storage_key,sha256,size_bytes,state)
  VALUES(x.tenant_id,x.project_id,x.task_id,x.attempt_id,m.id,gen_random_uuid(),m.raw_digest,octet_length(m.raw_bytes),'AVAILABLE');
  INSERT INTO company.verifier_receipts(tenant_id,project_id,task_id,attempt_id,id,purpose,signer_id,key_id,receipt_digest,signature) VALUES(x.tenant_id,x.project_id,x.task_id,x.attempt_id,m.id,'TASK_VERIFICATION',m.issuer_id,m.key_id,m.raw_digest,m.auth_tag);
 END IF;
END $$;
CREATE FUNCTION company_private.r58_signed_artifact_read(p_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;art company.artifacts%ROWTYPE;m company_private.r58_attestations%ROWTYPE;correlation uuid;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54 AND operation_id='candidate.r58.artifacts.read';
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'artifacts.read',x.task_id,false) IS NOT TRUE THEN RAISE EXCEPTION 'R58_ARTIFACT_READ_DENIED'; END IF;
 SELECT * INTO STRICT art FROM company.artifacts WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=x.task_id AND attempt_id=x.attempt_id AND id=p_id AND state='AVAILABLE';
 SELECT * INTO STRICT m FROM company_private.r58_attestations WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=art.id AND raw_digest=art.sha256;
 correlation=gen_random_uuid();
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(x.tenant_id,correlation,x.principal_id,'Readback:SignedStatementArtifact');
 RETURN jsonb_build_object('artifact_id',art.id,'sha256',art.sha256,'size_bytes',art.size_bytes,'content_base64',encode(m.raw_bytes,'base64'),'kind','SIGNED_STATEMENT_ONLY','access_audit_correlation',correlation);
END $$;

-- SOURCE sql/038_R58_WORKER_NATIVE.sql
CREATE FUNCTION company_private.r58_workspace_current_head(p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;a company_private.r58_attestations%ROWTYPE;h company_private.r58_workspace_heads%ROWTYPE;c company.commands%ROWTYPE;v jsonb;ws uuid;
BEGIN
 x=company_private.r58_context('workspace.current_head');a=company_private.r58_attestation(p_attestation,'r58.workspace.v1');v=a.payload;
 PERFORM company_private.r58_shape(v,ARRAY['workspace_id','expected_revision','previous_head','head_digest','host_id','host_revision','host_generation','host_boot_id','supervisor_id']);
 SELECT workspace_id INTO STRICT ws FROM company.projects WHERE tenant_id=x.tenant_id AND id=x.project_id FOR UPDATE;
 IF a.issuer_id::text IS DISTINCT FROM v->>'supervisor_id' OR a.issuer_id IS DISTINCT FROM x.principal_id
 OR v->>'workspace_id' IS DISTINCT FROM ws::text OR v->>'head_digest' !~ '^[a-f0-9]{64}$'
 OR v->>'host_boot_id' IS DISTINCT FROM (company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id)->>'host_boot_id')
 OR NOT EXISTS(SELECT 1 FROM company.projects p JOIN company.host_registrations h ON h.tenant_id=p.tenant_id AND h.project_id=p.id AND h.id=p.host_registration_id AND h.revision=p.host_registration_revision AND h.bound_generation=p.instance_generation
 WHERE p.tenant_id=x.tenant_id AND p.id=x.project_id AND h.state='BOUND_NOT_LEASED' AND h.id::text=v->>'host_id' AND h.revision::text=v->>'host_revision' AND h.bound_generation::text=v->>'host_generation') THEN RAISE EXCEPTION 'R58_WORKSPACE_HOST_BINDING'; END IF;
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('attestation',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO h FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id FOR UPDATE;
 IF FOUND THEN
  IF h.revision::text IS DISTINCT FROM v->>'expected_revision' OR h.head_digest IS DISTINCT FROM v->>'previous_head' THEN RAISE EXCEPTION 'R58_WORKSPACE_HEAD_CAS'; END IF;
  UPDATE company_private.r58_workspace_heads SET revision=revision+1,head_digest=v->>'head_digest',attestation_id=a.id WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND revision=h.revision;
 ELSE
  IF v->>'expected_revision' IS DISTINCT FROM '0' OR v->>'previous_head' IS DISTINCT FROM 'INITIAL' THEN RAISE EXCEPTION 'R58_WORKSPACE_INITIAL_HEAD'; END IF;
  INSERT INTO company_private.r58_workspace_heads VALUES(x.tenant_id,x.project_id,ws,1,v->>'head_digest',a.id);
 END IF;
 RETURN company_private.r58_finish(c.id,ws,jsonb_build_object('head_digest',v->>'head_digest','attestation_id',a.id));
END $$;

CREATE FUNCTION company_private.r58_worker_claim(p_task uuid,p_revision bigint,p_qualification uuid,p_binding text,p_policy_revision bigint,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;t company.tasks%ROWTYPE;q company.agent_qualifications%ROWTYPE;
 h company_private.r58_workspace_heads%ROWTYPE;lp company_private.r58_lease_policies%ROWTYPE;c company.commands%ROWTYPE;b jsonb;until_at timestamptz;aid uuid;n integer;
BEGIN
 x=company_private.r58_context('worker.claim');
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=x.principal_id AND kind IN ('WORKER','VERIFIER')) THEN RAISE EXCEPTION 'R58_TECHNICAL_WORKER_REQUIRED'; END IF;
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('task_id',p_task,'revision',p_revision,'qualification',p_qualification,'binding',p_binding,'lease_policy_revision',p_policy_revision));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT lp FROM company_private.r58_lease_policies WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND revision=p_policy_revision AND enabled FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=lp.approved_by AND kind='HUMAN') THEN RAISE EXCEPTION 'R58_HUMAN_LEASE_POLICY_REQUIRED'; END IF;
 q=company_private.r58_qualification(p_qualification,x.principal_id,p_binding);
 SELECT * INTO STRICT h FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id FOR SHARE;
 SELECT * INTO STRICT t FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_task FOR UPDATE;
 IF x.task_id IS DISTINCT FROM p_task OR x.attempt_id IS NOT NULL OR t.execution_kind IS DISTINCT FROM 'ORDINARY' OR t.state IS DISTINCT FROM 'READY' OR t.revision IS DISTINCT FROM p_revision OR t.active_attempt_id IS NOT NULL OR t.role_id IS DISTINCT FROM q.role_id
 OR EXISTS(SELECT 1 FROM company.task_dependencies d JOIN company.tasks parent ON parent.tenant_id=d.tenant_id AND parent.project_id=d.project_id AND parent.id=d.depends_on_task_id WHERE d.tenant_id=t.tenant_id AND d.project_id=t.project_id AND d.task_id=t.id AND parent.state<>'ACCEPTED') THEN RAISE EXCEPTION 'R58_TASK_NOT_CLAIMABLE'; END IF;
 b=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 until_at=least((b->>'utc_lower_bound')::timestamptz+(lp.duration_ms::numeric*interval '1 millisecond'),q.valid_until,lp.valid_until);
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,until_at);
 SELECT coalesce(max(attempt_no),0)+1 INTO n FROM company.attempts WHERE tenant_id=t.tenant_id AND project_id=t.project_id AND task_id=t.id;
 aid=gen_random_uuid();
 INSERT INTO company.attempts(tenant_id,project_id,task_id,id,attempt_no,fencing_epoch,worker_id,state,lease_expires_at,admission_qualification_id,r58_binding_digest,r58_head_digest,r58_policy_revision,r58_verification_profile_digest)
 VALUES(t.tenant_id,t.project_id,t.id,aid,n,t.fencing_epoch+1,x.principal_id,'CLAIMED',until_at,q.id,p_binding,h.head_digest,lp.revision,lp.verification_profile_digest);
 UPDATE company.tasks SET state='RUNNING',revision=revision+1,fencing_epoch=fencing_epoch+1,active_attempt_id=aid WHERE tenant_id=t.tenant_id AND project_id=t.project_id AND id=t.id AND revision=p_revision AND state='READY';
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_TASK_CLAIM_CAS'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,until_at);
 RETURN company_private.r58_finish(c.id,aid,jsonb_build_object('attempt_id',aid,'task_id',t.id,'fencing_epoch',t.fencing_epoch+1,'lease_expires_at',until_at,'qualification_id',q.id,'head_digest',h.head_digest,'lease_policy_revision',lp.revision));
END $$;

CREATE FUNCTION company_private.r58_worker_heartbeat(p_task uuid,p_attempt uuid,p_fence bigint,p_policy_revision bigint,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;a company.attempts%ROWTYPE;lp company_private.r58_lease_policies%ROWTYPE;q company.agent_qualifications%ROWTYPE;c company.commands%ROWTYPE;r company.process_runs%ROWTYPE;b jsonb;until_at timestamptz;
BEGIN
 x=company_private.r58_context('worker.heartbeat');
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('task_id',p_task,'attempt_id',p_attempt,'fencing_epoch',p_fence,'lease_policy_revision',p_policy_revision));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT lp FROM company_private.r58_lease_policies WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND revision=p_policy_revision AND enabled FOR SHARE;
 a=company_private.r58_attempt(p_task,p_attempt,p_fence);
 IF a.worker_id IS DISTINCT FROM x.principal_id OR a.r58_policy_revision IS DISTINCT FROM lp.revision OR a.state NOT IN ('CLAIMED','RUNNING') THEN RAISE EXCEPTION 'R58_STALE_WORKER_HEARTBEAT'; END IF;
 q=company_private.r58_qualification(a.admission_qualification_id,a.worker_id,a.r58_binding_digest);
 b=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 until_at=least((b->>'utc_lower_bound')::timestamptz+(lp.duration_ms::numeric*interval '1 millisecond'),q.valid_until,lp.valid_until);
 IF until_at<a.lease_expires_at THEN RAISE EXCEPTION 'R58_LEASE_POLICY_SHRANK_REQUIRES_FENCE'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,until_at);
 FOR r IN SELECT * FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_task AND attempt_id=p_attempt ORDER BY id FOR UPDATE LOOP
  PERFORM company_private.r58_process_current(r.id);
  -- A running controller must first support a separately accepted OS lease
  -- extension handshake. DB timestamps alone never extend an active OS lease.
  IF r.worker_id IS DISTINCT FROM a.worker_id OR r.attempt_fencing_epoch IS DISTINCT FROM p_fence OR r.state IS DISTINCT FROM 'REQUESTED' OR r.release_command_id IS NOT NULL THEN RAISE EXCEPTION 'R58_LIVE_OS_RENEWAL_NOT_ACCEPTED'; END IF;
  PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,r.lease_expires_at);
  UPDATE company.process_runs SET lease_expires_at=until_at,revision=revision+1 WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=r.revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'R58_PROCESS_LEASE_CAS'; END IF;
 END LOOP;
 UPDATE company.attempts SET lease_expires_at=until_at WHERE tenant_id=a.tenant_id AND project_id=a.project_id AND task_id=a.task_id AND id=a.id AND fencing_epoch=p_fence AND lease_expires_at=a.lease_expires_at;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_ATTEMPT_LEASE_CAS'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,until_at);
 RETURN company_private.r58_finish(c.id,a.id,jsonb_build_object('attempt_id',a.id,'fencing_epoch',p_fence,'lease_expires_at',until_at,'lease_policy_revision',lp.revision));
END $$;

-- SOURCE sql/039_R58_LAUNCH_NATIVE.sql
CREATE FUNCTION company_private.r58_launch_reserve(p_task uuid,p_attempt uuid,p_fence bigint,p_manifest uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;a company.attempts%ROWTYPE;m company_private.r58_attestations%ROWTYPE;lp company_private.r58_lease_policies%ROWTYPE;
 h company_private.r58_workspace_heads%ROWTYPE;host company.host_registrations%ROWTYPE;v company.budget_versions%ROWTYPE;c company.commands%ROWTYPE;
 j jsonb;cl jsonb;cap uuid;process uuid;reservation uuid;tuple jsonb;now_bounds jsonb;remaining_ns numeric;
BEGIN
 x=company_private.r58_context('process.launch_reserve');
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('task_id',p_task,'attempt_id',p_attempt,'fence',p_fence,'manifest',p_manifest));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 a=company_private.r58_attempt(p_task,p_attempt,p_fence);
 m=company_private.r58_attestation(p_manifest,'r58.launch-manifest.v1');j=m.payload;
 PERFORM company_private.r58_shape(j,ARRAY['task_id','attempt_id','fencing_epoch','workspace_id','head_digest','host_id','host_revision','host_generation','host_boot_id','controller_id','controller_generation','executable_digest','argv','budget_id','budget_revision','admission_artifact_id','claims']);
 SELECT * INTO STRICT lp FROM company_private.r58_lease_policies WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND revision=a.r58_policy_revision AND enabled FOR SHARE;
 SELECT * INTO STRICT h FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id FOR SHARE;
 SELECT hr.* INTO STRICT host FROM company.host_registrations hr JOIN company.projects p ON p.tenant_id=hr.tenant_id AND p.id=hr.project_id AND p.host_registration_id=hr.id AND p.host_registration_revision=hr.revision AND p.instance_generation=hr.bound_generation
 WHERE p.tenant_id=x.tenant_id AND p.id=x.project_id AND hr.state='BOUND_NOT_LEASED' FOR SHARE OF hr;
 IF a.worker_id IS DISTINCT FROM x.principal_id OR m.issuer_id IS DISTINCT FROM lp.controller_id OR m.issuer_id=a.worker_id
 OR j->>'task_id' IS DISTINCT FROM p_task::text OR j->>'attempt_id' IS DISTINCT FROM p_attempt::text OR j->>'fencing_epoch' IS DISTINCT FROM p_fence::text
 OR j->>'head_digest' IS DISTINCT FROM h.head_digest OR j->>'head_digest' IS DISTINCT FROM a.r58_head_digest OR j->>'workspace_id' IS DISTINCT FROM h.workspace_id::text
 OR j->>'host_id' IS DISTINCT FROM host.id::text OR j->>'host_revision' IS DISTINCT FROM host.revision::text OR j->>'host_generation' IS DISTINCT FROM host.bound_generation::text
 OR j->>'controller_id' IS DISTINCT FROM lp.controller_id::text OR j->>'executable_digest' IS DISTINCT FROM lp.executable_digest
 OR (j->>'controller_generation')::bigint<1 OR jsonb_typeof(j->'argv') IS DISTINCT FROM 'array' OR jsonb_array_length(j->'argv') NOT BETWEEN 1 AND 64
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(j->'argv') z WHERE jsonb_typeof(z) IS DISTINCT FROM 'string' OR length(z#>>'{}')>4096)
 OR jsonb_typeof(j->'claims') IS DISTINCT FROM 'array' OR jsonb_array_length(j->'claims') NOT BETWEEN 1 AND 16
 OR EXISTS(SELECT 1 FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_task AND attempt_id=p_attempt) THEN RAISE EXCEPTION 'R58_LAUNCH_EXACT_BINDING_OR_NO_RESPAWN'; END IF;
 now_bounds=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 IF j->>'host_boot_id' IS DISTINCT FROM now_bounds->>'host_boot_id' THEN RAISE EXCEPTION 'R58_DB_LOCAL_BOOT_REQUIRED'; END IF;
 remaining_ns=floor(extract(epoch FROM (least(a.lease_expires_at,lp.valid_until)-(now_bounds->>'utc_upper_bound')::timestamptz))*1000000000);
 IF remaining_ns<=0 THEN RAISE EXCEPTION 'R58_LAUNCH_LEASE_EXPIRED'; END IF;
 SELECT * INTO STRICT v FROM company.budget_versions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND budget_id=(j->>'budget_id')::uuid AND revision=(j->>'budget_revision')::bigint FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM company.artifacts art WHERE art.tenant_id=x.tenant_id AND art.project_id=x.project_id AND art.task_id=p_task AND art.attempt_id=p_attempt AND art.id=(j->>'admission_artifact_id')::uuid AND art.state='AVAILABLE' AND art.sha256=m.raw_digest) THEN RAISE EXCEPTION 'R58_MANIFEST_ARTIFACT_DIGEST'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=v.approved_by AND kind='HUMAN') THEN RAISE EXCEPTION 'R58_HUMAN_LOCAL_ZERO_BUDGET_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(j->'claims') z GROUP BY z->>'slot_id' HAVING count(*)>1) THEN RAISE EXCEPTION 'R58_DUPLICATE_SLOT'; END IF;
 cap=gen_random_uuid();process=gen_random_uuid();reservation=gen_random_uuid();
 INSERT INTO company.budget_reservations(tenant_id,project_id,id,budget_id,budget_revision,task_id,attempt_id,attempt_fencing_epoch,semantic_key,payload_digest,admission_artifact_id,amount_minor,state,command_id)
 VALUES(x.tenant_id,x.project_id,reservation,v.budget_id,v.revision,p_task,p_attempt,p_fence,'r58:'||p_attempt::text,m.raw_digest,(j->>'admission_artifact_id')::uuid,0,'RESERVED',c.id);
 INSERT INTO company.process_runs(tenant_id,project_id,id,task_id,attempt_id,attempt_fencing_epoch,worker_lease_id,worker_id,qualification_id,lease_expires_at,workspace_id,host_registration_id,host_registration_revision,host_generation,controller_id,controller_generation,kind,state,reservation_id,manifest_artifact_id,manifest_digest,semantic_run_digest,start_command_id,r55_host_boot_id)
 VALUES(x.tenant_id,x.project_id,process,p_task,p_attempt,p_fence,gen_random_uuid(),a.worker_id,a.admission_qualification_id,a.lease_expires_at,h.workspace_id,host.id,host.revision,host.bound_generation,lp.controller_id,(j->>'controller_generation')::bigint,'TASK_EXECUTION','REQUESTED',reservation,(j->>'admission_artifact_id')::uuid,m.raw_digest,encode(sha256(convert_to(jsonb_build_array(p_task,p_attempt,p_fence,m.raw_digest)::text,'UTF8')),'hex'),c.id,(j->>'host_boot_id')::uuid);
 FOR cl IN SELECT value FROM jsonb_array_elements(j->'claims') ORDER BY value->>'slot_id' LOOP
  PERFORM company_private.r58_shape(cl,ARRAY['slot_id','units']);
  IF jsonb_typeof(cl->'units') IS DISTINCT FROM 'number' OR cl->>'units' !~ '^[1-9][0-9]*$' THEN RAISE EXCEPTION 'R58_FINITE_RESOURCE_UNITS'; END IF;
  UPDATE company.resource_slots SET reserved=reserved+(cl->>'units')::integer WHERE tenant_id=x.tenant_id AND id=(cl->>'slot_id')::uuid AND capacity-reserved>=(cl->>'units')::integer;
  IF NOT FOUND THEN RAISE EXCEPTION 'R58_RESOURCE_CAPACITY'; END IF;
  INSERT INTO company.resource_claims(tenant_id,project_id,process_run_id,slot_id,units,state) VALUES(x.tenant_id,x.project_id,process,(cl->>'slot_id')::uuid,(cl->>'units')::integer,'HELD');
 END LOOP;
 tuple=jsonb_build_object('capability_id',cap,'tenant_id',x.tenant_id,'project_id',x.project_id,'task_id',p_task,'attempt_id',p_attempt,'fencing_epoch',p_fence,'worker_id',a.worker_id,'qualification_id',a.admission_qualification_id,'binding_digest',a.r58_binding_digest,'workspace_id',h.workspace_id,'head_digest',h.head_digest,'host_id',host.id,'host_revision',host.revision,'host_generation',host.bound_generation,'host_boot_id',j->>'host_boot_id','controller_id',lp.controller_id,'controller_generation',j->'controller_generation','process_id',process,'executable_digest',lp.executable_digest,'argv',j->'argv','reservation_id',reservation,'claims',j->'claims','lease_policy_revision',lp.revision,'not_after_boottime_ns',(now_bounds->>'boottime_after_ns')::numeric+remaining_ns);
 INSERT INTO company_private.r58_launch_capabilities(tenant_id,project_id,id,process_id,tuple,tuple_digest,state) VALUES(x.tenant_id,x.project_id,cap,process,tuple,encode(sha256(convert_to(tuple::text,'UTF8')),'hex'),'RESERVED');
 PERFORM company_private.r58_process_current(process);
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,a.lease_expires_at);
 RETURN company_private.r58_finish(c.id,cap,jsonb_build_object('capability_id',cap,'process_id',process,'tuple',tuple,'spawned',false));
END $$;

CREATE FUNCTION company_private.r58_launch_consume(p_capability uuid,p_digest text,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;cap company_private.r58_launch_capabilities%ROWTYPE;r company.process_runs%ROWTYPE;a company.attempts%ROWTYPE;c company.commands%ROWTYPE;b jsonb;
BEGIN
 x=company_private.r58_context('process.launch_consume');
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('capability',p_capability,'tuple_digest',p_digest));
 -- Even an exact replay may not return a second OS launch instruction.
 IF c.state='SUCCEEDED' THEN RETURN jsonb_build_object('outcome','REPLAY_RECONCILE_ONLY','command_id',c.id,'spawn_permitted',false); END IF;
 SELECT * INTO STRICT cap FROM company_private.r58_launch_capabilities WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_capability FOR UPDATE;
 a=company_private.r58_attempt((cap.tuple->>'task_id')::uuid,(cap.tuple->>'attempt_id')::uuid,(cap.tuple->>'fencing_epoch')::bigint);
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=cap.process_id FOR UPDATE;
 PERFORM company_private.r58_process_current(r.id);
 b=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 IF cap.state IS DISTINCT FROM 'RESERVED' OR cap.tuple_digest IS DISTINCT FROM p_digest OR r.controller_id IS DISTINCT FROM x.principal_id OR r.state IS DISTINCT FROM 'REQUESTED'
 OR b->>'host_boot_id' IS DISTINCT FROM cap.tuple->>'host_boot_id' OR (b->>'boottime_after_ns')::numeric>=(cap.tuple->>'not_after_boottime_ns')::numeric
 OR NOT EXISTS(SELECT 1 FROM company_private.r58_workspace_heads h WHERE h.tenant_id=x.tenant_id AND h.project_id=x.project_id AND h.head_digest=cap.tuple->>'head_digest') THEN RAISE EXCEPTION 'R58_CAPABILITY_NOT_CURRENT_OR_ALREADY_USED'; END IF;
 UPDATE company_private.r58_launch_capabilities SET state='CONSUMED',consume_command_id=c.id WHERE tenant_id=cap.tenant_id AND project_id=cap.project_id AND id=cap.id AND state='RESERVED';
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_CAPABILITY_CONSUME_CAS'; END IF;
 UPDATE company.process_runs SET state='STARTING',revision=revision+1 WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=r.revision AND state='REQUESTED';
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_PROCESS_START_CAS'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,a.lease_expires_at);
 RETURN company_private.r58_finish(c.id,cap.id,jsonb_build_object('capability_id',cap.id,'tuple',cap.tuple,'tuple_raw',cap.tuple::text,'tuple_digest',cap.tuple_digest,'spawn_permitted',true,'release_only_after_commit',true));
END $$;

CREATE FUNCTION company_private.r58_launch_callback(p_capability uuid,p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;cap company_private.r58_launch_capabilities%ROWTYPE;m company_private.r58_attestations%ROWTYPE;r company.process_runs%ROWTYPE;a company.attempts%ROWTYPE;c company.commands%ROWTYPE;j jsonb;b jsonb;
BEGIN
 x=company_private.r58_context('process.launch_callback');m=company_private.r58_attestation(p_attestation,'r58.launch-callback.v1');j=m.payload;
 PERFORM company_private.r58_shape(j,ARRAY['capability_id','tuple_digest','controller_generation','host_boot_id','process_identity_digest','isolation_digest','cgroup_inode','outcome']);
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('capability',p_capability,'attestation',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT cap FROM company_private.r58_launch_capabilities WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_capability FOR UPDATE;
 a=company_private.r58_attempt((cap.tuple->>'task_id')::uuid,(cap.tuple->>'attempt_id')::uuid,(cap.tuple->>'fencing_epoch')::bigint);
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=cap.process_id FOR UPDATE;
 PERFORM company_private.r58_process_current(r.id);
 IF cap.state IS DISTINCT FROM 'CONSUMED' OR m.issuer_id IS DISTINCT FROM r.controller_id OR x.principal_id IS DISTINCT FROM r.controller_id
 OR j->>'capability_id' IS DISTINCT FROM cap.id::text OR j->>'tuple_digest' IS DISTINCT FROM cap.tuple_digest
 OR j->>'host_boot_id' IS DISTINCT FROM cap.tuple->>'host_boot_id' OR j->>'controller_generation' IS DISTINCT FROM r.controller_generation::text
 OR jsonb_typeof(j->'cgroup_inode') IS DISTINCT FROM 'number' OR j->>'cgroup_inode' !~ '^[1-9][0-9]*$'
 OR j->>'process_identity_digest' !~ '^[a-f0-9]{64}$' OR j->>'isolation_digest' !~ '^[a-f0-9]{64}$' OR j->>'outcome' NOT IN ('RUNNING','UNKNOWN_LOCAL') THEN RAISE EXCEPTION 'R58_CALLBACK_BINDING'; END IF;
 b=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 IF b->>'host_boot_id' IS DISTINCT FROM j->>'host_boot_id' OR (b->>'boottime_after_ns')::numeric>=(cap.tuple->>'not_after_boottime_ns')::numeric THEN RAISE EXCEPTION 'R58_STALE_CALLBACK_REQUIRES_RECONCILIATION'; END IF;
 UPDATE company.process_runs SET state=j->>'outcome',revision=revision+1 WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND state='STARTING' AND revision=r.revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_CALLBACK_PROCESS_CAS'; END IF;
 UPDATE company_private.r58_launch_capabilities SET state=j->>'outcome',callback_attestation_id=m.id WHERE tenant_id=cap.tenant_id AND project_id=cap.project_id AND id=cap.id AND state='CONSUMED';
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_CALLBACK_CAPABILITY_CAS'; END IF;
 UPDATE company.attempts SET state=CASE WHEN j->>'outcome'='RUNNING' THEN 'RUNNING' ELSE 'UNKNOWN_RECOVERY' END WHERE tenant_id=a.tenant_id AND project_id=a.project_id AND task_id=a.task_id AND id=a.id;
 RETURN company_private.r58_finish(c.id,cap.id,jsonb_build_object('process_id',r.id,'capability_id',cap.id,'outcome',j->>'outcome','process_identity_digest',j->>'process_identity_digest','isolation_digest',j->>'isolation_digest','callback_attestation_id',m.id,'respawn_permitted',false));
END $$;

-- SOURCE sql/040_R58_PATCH_ACCEPTANCE_NATIVE.sql
CREATE FUNCTION company_private.r58_tool_authorize_final(p_task uuid,p_attempt uuid,p_fence bigint,p_process uuid,p_tool text,p_request_digest text,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;a company.attempts%ROWTYPE;r company.process_runs%ROWTYPE;lp company_private.r58_lease_policies%ROWTYPE;cap company_private.r58_launch_capabilities%ROWTYPE;h company_private.r58_workspace_heads%ROWTYPE;c company.commands%ROWTYPE;rid uuid;
BEGIN
 x=company_private.r58_context('tool.authorize_final');
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('task_id',p_task,'attempt_id',p_attempt,'fence',p_fence,'process_id',p_process,'tool',p_tool,'request_digest',p_request_digest));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 a=company_private.r58_attempt(p_task,p_attempt,p_fence);
 SELECT * INTO STRICT lp FROM company_private.r58_lease_policies WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND revision=a.r58_policy_revision AND enabled FOR SHARE;
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process FOR SHARE;
 PERFORM company_private.r58_process_current(r.id);
 SELECT * INTO STRICT cap FROM company_private.r58_launch_capabilities WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND process_id=r.id AND state='RUNNING';
 SELECT * INTO STRICT h FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id FOR SHARE;
 IF p_tool IS NULL OR NOT ((p_tool=ANY(lp.allowed_tools)) IS TRUE) OR p_request_digest IS NULL OR p_request_digest !~ '^[a-f0-9]{64}$'
 OR a.worker_id IS DISTINCT FROM x.principal_id OR r.state IS DISTINCT FROM 'RUNNING' OR r.attempt_id IS DISTINCT FROM a.id OR r.task_id IS DISTINCT FROM a.task_id OR r.attempt_fencing_epoch IS DISTINCT FROM p_fence OR r.qualification_id IS DISTINCT FROM a.admission_qualification_id
 OR cap.tuple->>'head_digest' IS DISTINCT FROM h.head_digest OR cap.callback_attestation_id IS NULL THEN RAISE EXCEPTION 'R58_TOOL_EXACT_CURRENT_AUTHORITY'; END IF;
 PERFORM company_private.r58_attestation(cap.callback_attestation_id,'r58.launch-callback.v1');
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,r.lease_expires_at);
 rid=gen_random_uuid();
 INSERT INTO company.tool_requests(tenant_id,project_id,task_id,attempt_id,request_id,payload_digest,request_fencing_epoch) VALUES(x.tenant_id,x.project_id,p_task,p_attempt,rid,p_request_digest,p_fence);
 RETURN company_private.r58_finish(c.id,rid,jsonb_build_object('request_id',rid,'process_id',r.id,'head_digest',h.head_digest,'tool',p_tool,'request_digest',p_request_digest,'os_effect_performed',false));
END $$;

CREATE FUNCTION company_private.r58_patch_receipt(p_task uuid,p_attempt uuid,p_fence bigint,p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;a company.attempts%ROWTYPE;m company_private.r58_attestations%ROWTYPE;h company_private.r58_workspace_heads%ROWTYPE;tr company.tool_requests%ROWTYPE;cap company_private.r58_launch_capabilities%ROWTYPE;c company.commands%ROWTYPE;j jsonb;rid uuid;
BEGIN
 x=company_private.r58_context('patch.receipt');m=company_private.r58_attestation(p_attestation,'r58.patch.v1');j=m.payload;
 PERFORM company_private.r58_shape(j,ARRAY['task_id','attempt_id','fencing_epoch','base_head','result_head','patch_digest','tool_request_id','process_id','request_digest','receipt_artifact_id']);
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('task_id',p_task,'attempt_id',p_attempt,'fence',p_fence,'attestation',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 a=company_private.r58_attempt(p_task,p_attempt,p_fence);
 SELECT * INTO STRICT h FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id FOR UPDATE;
 SELECT * INTO STRICT tr FROM company.tool_requests WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_task AND attempt_id=p_attempt AND request_id=(j->>'tool_request_id')::uuid FOR UPDATE;
 SELECT * INTO STRICT cap FROM company_private.r58_launch_capabilities WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND process_id=(j->>'process_id')::uuid AND state='RUNNING';
 PERFORM company_private.r58_process_current(cap.process_id);
 IF j->>'task_id' IS DISTINCT FROM p_task::text OR j->>'attempt_id' IS DISTINCT FROM p_attempt::text OR j->>'fencing_epoch' IS DISTINCT FROM p_fence::text
 OR j->>'base_head' IS DISTINCT FROM h.head_digest OR j->>'base_head' IS DISTINCT FROM cap.tuple->>'head_digest' OR j->>'result_head' !~ '^[a-f0-9]{64}$' OR j->>'patch_digest' !~ '^[a-f0-9]{64}$'
 OR tr.receipt_id IS NOT NULL OR tr.payload_digest IS DISTINCT FROM j->>'request_digest' OR tr.request_fencing_epoch IS DISTINCT FROM p_fence
 OR j->>'receipt_artifact_id' IS DISTINCT FROM m.id::text OR NOT EXISTS(SELECT 1 FROM company.artifacts ar WHERE ar.tenant_id=x.tenant_id AND ar.project_id=x.project_id AND ar.task_id=p_task AND ar.attempt_id=p_attempt AND ar.id=m.id AND ar.state='AVAILABLE' AND ar.sha256=m.raw_digest)
 OR m.issuer_id::text IS DISTINCT FROM cap.tuple->>'controller_id' OR m.issuer_id=a.worker_id
 OR NOT EXISTS(SELECT 1 FROM company_private.r58_execution_receipts rr WHERE rr.tenant_id=x.tenant_id AND rr.project_id=x.project_id AND rr.operation='tool.authorize_final' AND rr.target_id=tr.request_id AND rr.payload->>'tool'='patch.apply' AND rr.payload->>'head_digest'=h.head_digest AND rr.payload->>'process_id'=j->>'process_id') THEN RAISE EXCEPTION 'R58_PATCH_PROVENANCE'; END IF;
 rid=m.id;
 INSERT INTO company_private.r58_patch_receipts VALUES(x.tenant_id,x.project_id,p_task,p_attempt,rid,p_fence,h.head_digest,j->>'result_head',j->>'patch_digest',tr.request_id,m.id,c.id);
 UPDATE company_private.r58_workspace_heads SET revision=revision+1,head_digest=j->>'result_head',attestation_id=m.id WHERE tenant_id=h.tenant_id AND project_id=h.project_id AND revision=h.revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_PATCH_HEAD_CAS'; END IF;
 UPDATE company.tool_requests SET receipt_id=rid WHERE tenant_id=tr.tenant_id AND attempt_id=tr.attempt_id AND request_id=tr.request_id AND receipt_id IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_PATCH_TOOL_RECEIPT_CAS'; END IF;
 UPDATE company.attempts SET state='PRODUCED' WHERE tenant_id=a.tenant_id AND project_id=a.project_id AND task_id=a.task_id AND id=a.id;
 UPDATE company.tasks SET state='VERIFYING',revision=revision+1 WHERE tenant_id=a.tenant_id AND project_id=a.project_id AND id=a.task_id AND active_attempt_id=a.id AND fencing_epoch=p_fence AND state='RUNNING';
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_PATCH_TASK_CAS'; END IF;
 RETURN company_private.r58_finish(c.id,rid,jsonb_build_object('patch_id',rid,'result_head',j->>'result_head','patch_digest',j->>'patch_digest','attestation',m.id));
END $$;

CREATE FUNCTION company_private.r58_verification_final_seal(p_task uuid,p_attempt uuid,p_fence bigint,p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;a company.attempts%ROWTYPE;m company_private.r58_attestations%ROWTYPE;pm company_private.r58_attestations%ROWTYPE;patch company_private.r58_patch_receipts%ROWTYPE;profile company_private.r58_verification_profiles%ROWTYPE;h company_private.r58_workspace_heads%ROWTYPE;c company.commands%ROWTYPE;j jsonb;vid uuid;sd text;
BEGIN
 x=company_private.r58_context('verification.final_seal');m=company_private.r58_attestation(p_attestation,'r58.verification.v1');j=m.payload;
 PERFORM company_private.r58_shape(j,ARRAY['patch_id','head_digest','profile_digest','build_digest','results','report_artifact_id','kind','acceptance_criteria_digest']);
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('task_id',p_task,'attempt_id',p_attempt,'fence',p_fence,'attestation',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 a=company_private.r58_attempt(p_task,p_attempt,p_fence);
 SELECT * INTO STRICT patch FROM company_private.r58_patch_receipts WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=(j->>'patch_id')::uuid;
 SELECT * INTO STRICT h FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id FOR SHARE;
 SELECT * INTO STRICT profile FROM company_private.r58_verification_profiles WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND profile_digest=a.r58_verification_profile_digest AND enabled FOR SHARE;
 pm=company_private.r58_attestation(patch.attestation_id,'r58.patch.v1');
 IF j->>'kind' IS DISTINCT FROM 'ORDINARY' OR j->>'profile_digest' IS DISTINCT FROM profile.profile_digest OR j->>'head_digest' IS DISTINCT FROM h.head_digest OR patch.result_head IS DISTINCT FROM h.head_digest OR patch.task_id IS DISTINCT FROM p_task OR patch.attempt_id IS DISTINCT FROM p_attempt OR patch.fence IS DISTINCT FROM p_fence
 OR m.issuer_id=a.worker_id OR m.issuer_id=pm.issuer_id OR m.issuer_id IS DISTINCT FROM x.principal_id OR j->>'build_digest' !~ '^[a-f0-9]{64}$' OR jsonb_typeof(j->'results') IS DISTINCT FROM 'array'
 OR NOT EXISTS(SELECT 1 FROM company.tasks t WHERE t.tenant_id=x.tenant_id AND t.project_id=x.project_id AND t.id=p_task AND j->>'acceptance_criteria_digest'=encode(sha256(convert_to(t.acceptance_criteria::text,'UTF8')),'hex'))
 OR NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=profile.approved_by AND kind='HUMAN') THEN RAISE EXCEPTION 'R58_ORDINARY_SEAL_CURRENT_BINDING'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(j->'results') z WHERE jsonb_typeof(z) IS DISTINCT FROM 'object' OR NOT ((z ?& ARRAY['oracle_id','outcome','artifact_digest']) IS TRUE) OR (SELECT count(*) FROM jsonb_object_keys(z))<>3 OR z->>'outcome' IS DISTINCT FROM 'PASS' OR jsonb_typeof(z->'oracle_id') IS DISTINCT FROM 'string' OR jsonb_typeof(z->'artifact_digest') IS DISTINCT FROM 'string' OR z->>'artifact_digest' !~ '^[a-f0-9]{64}$')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(profile.oracle_ids) z WHERE jsonb_typeof(z) IS DISTINCT FROM 'string' OR length(z#>>'{}')=0)
 OR (SELECT count(*)<>count(DISTINCT value) FROM jsonb_array_elements_text(profile.oracle_ids))
 OR (SELECT count(*)<>count(DISTINCT value->>'oracle_id') FROM jsonb_array_elements(j->'results'))
 OR EXISTS((SELECT value FROM jsonb_array_elements_text(profile.oracle_ids)) EXCEPT (SELECT value->>'oracle_id' FROM jsonb_array_elements(j->'results')))
 OR EXISTS((SELECT value->>'oracle_id' FROM jsonb_array_elements(j->'results')) EXCEPT (SELECT value FROM jsonb_array_elements_text(profile.oracle_ids)))
 OR NOT EXISTS(SELECT 1 FROM company.artifacts art WHERE art.tenant_id=x.tenant_id AND art.project_id=x.project_id AND art.task_id=p_task AND art.attempt_id=p_attempt AND art.id=(j->>'report_artifact_id')::uuid AND art.state='AVAILABLE' AND art.sha256=m.raw_digest) THEN RAISE EXCEPTION 'R58_EXACT_REQUIRED_ORACLE_MANIFEST'; END IF;
 vid=gen_random_uuid();sd=encode(sha256(convert_to(jsonb_build_array(patch.id,h.head_digest,profile.profile_digest,m.raw_digest,j->'results')::text,'UTF8')),'hex');
 INSERT INTO company.verification_runs(tenant_id,project_id,task_id,attempt_id,id,producer_id,verifier_id,profile_version,build_digest,dirty_digest,result,exit_code,source_report_artifact_id)
 VALUES(x.tenant_id,x.project_id,p_task,p_attempt,vid,a.worker_id,m.issuer_id,profile.profile_digest,j->>'build_digest',patch.patch_digest,'PASS',0,(j->>'report_artifact_id')::uuid);
 INSERT INTO company_private.r58_verification_seals VALUES(x.tenant_id,x.project_id,p_task,p_attempt,vid,patch.id,h.head_digest,m.id,sd,c.id);
 RETURN company_private.r58_finish(c.id,vid,jsonb_build_object('verification_id',vid,'seal_digest',sd,'head_digest',h.head_digest,'patch_id',patch.id));
END $$;

CREATE FUNCTION company_private.r58_evidence_provenance(p_task uuid,p_attempt uuid,p_fence bigint,p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;a company.attempts%ROWTYPE;m company_private.r58_attestations%ROWTYPE;s company_private.r58_verification_seals%ROWTYPE;v company.verification_runs%ROWTYPE;c company.commands%ROWTYPE;j jsonb;eid uuid;
BEGIN
 x=company_private.r58_context('evidence.provenance');m=company_private.r58_attestation(p_attestation,'r58.evidence.v1');j=m.payload;
 PERFORM company_private.r58_shape(j,ARRAY['verification_id','seal_digest','artifact_id','artifact_digest','head_digest']);
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('task_id',p_task,'attempt_id',p_attempt,'fence',p_fence,'attestation',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 a=company_private.r58_attempt(p_task,p_attempt,p_fence);
 SELECT * INTO STRICT s FROM company_private.r58_verification_seals WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_task AND attempt_id=p_attempt AND verification_id=(j->>'verification_id')::uuid;
 SELECT * INTO STRICT v FROM company.verification_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_task AND attempt_id=p_attempt AND id=s.verification_id AND result='PASS';
 IF m.issuer_id=a.worker_id OR m.issuer_id=v.verifier_id OR m.issuer_id IS DISTINCT FROM x.principal_id OR j->>'seal_digest' IS DISTINCT FROM s.seal_digest OR j->>'head_digest' IS DISTINCT FROM s.head_digest
 OR EXISTS(SELECT 1 FROM company_private.r58_patch_receipts p JOIN company_private.r58_attestations pm ON pm.tenant_id=p.tenant_id AND pm.project_id=p.project_id AND pm.id=p.attestation_id WHERE p.tenant_id=x.tenant_id AND p.project_id=x.project_id AND p.id=s.patch_id AND pm.issuer_id=m.issuer_id)
 OR NOT EXISTS(SELECT 1 FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND head_digest=s.head_digest)
 OR NOT EXISTS(SELECT 1 FROM company.artifacts art WHERE art.tenant_id=x.tenant_id AND art.project_id=x.project_id AND art.task_id=p_task AND art.attempt_id=p_attempt AND art.id=(j->>'artifact_id')::uuid AND art.state='AVAILABLE' AND art.sha256=j->>'artifact_digest') THEN RAISE EXCEPTION 'R58_EVIDENCE_EXACT_PROVENANCE'; END IF;
 PERFORM company_private.r58_attestation(s.attestation_id,'r58.verification.v1');eid=gen_random_uuid();
 INSERT INTO company.evidence(tenant_id,project_id,task_id,attempt_id,id,verification_run_id,artifact_id,command_receipt) VALUES(x.tenant_id,x.project_id,p_task,p_attempt,eid,s.verification_id,(j->>'artifact_id')::uuid,c.id);
 INSERT INTO company_private.r58_evidence_provenance VALUES(x.tenant_id,x.project_id,p_task,p_attempt,eid,m.id,s.head_digest,s.seal_digest,c.id);
 RETURN company_private.r58_finish(c.id,eid,jsonb_build_object('evidence_id',eid,'verification_id',s.verification_id,'seal_digest',s.seal_digest,'head_digest',s.head_digest));
END $$;

CREATE FUNCTION company_private.r58_verification_accept(p_task uuid,p_attempt uuid,p_fence bigint,p_revision bigint,p_evidence uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;a company.attempts%ROWTYPE;t company.tasks%ROWTYPE;e company.evidence%ROWTYPE;ep company_private.r58_evidence_provenance%ROWTYPE;s company_private.r58_verification_seals%ROWTYPE;v company.verification_runs%ROWTYPE;m company_private.r58_attestations%ROWTYPE;patch company_private.r58_patch_receipts%ROWTYPE;pm company_private.r58_attestations%ROWTYPE;h company_private.r58_workspace_heads%ROWTYPE;c company.commands%ROWTYPE;acceptance_id uuid;
BEGIN
 x=company_private.r58_context('verification.accept');
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('task_id',p_task,'attempt_id',p_attempt,'fence',p_fence,'expected_revision',p_revision,'evidence_id',p_evidence));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 a=company_private.r58_attempt(p_task,p_attempt,p_fence);
 SELECT * INTO STRICT h FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id FOR SHARE;
 SELECT * INTO STRICT t FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_task FOR UPDATE;
 SELECT * INTO STRICT e FROM company.evidence WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_task AND attempt_id=p_attempt AND id=p_evidence;
 SELECT * INTO STRICT ep FROM company_private.r58_evidence_provenance WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND evidence_id=e.id;
 SELECT * INTO STRICT s FROM company_private.r58_verification_seals WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND verification_id=e.verification_run_id;
 SELECT * INTO STRICT v FROM company.verification_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_task AND attempt_id=p_attempt AND id=s.verification_id;
 SELECT * INTO STRICT patch FROM company_private.r58_patch_receipts WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=s.patch_id;
 m=company_private.r58_attestation(ep.attestation_id,'r58.evidence.v1');pm=company_private.r58_attestation(patch.attestation_id,'r58.patch.v1');
 PERFORM company_private.r58_attestation(s.attestation_id,'r58.verification.v1');
 IF t.state IS DISTINCT FROM 'VERIFYING' OR t.revision IS DISTINCT FROM p_revision OR v.result IS DISTINCT FROM 'PASS' OR v.exit_code IS DISTINCT FROM 0
 OR x.principal_id IN (a.worker_id,v.verifier_id,m.issuer_id,pm.issuer_id)
 OR ep.head_digest IS DISTINCT FROM h.head_digest OR s.head_digest IS DISTINCT FROM h.head_digest OR patch.result_head IS DISTINCT FROM h.head_digest OR ep.seal_digest IS DISTINCT FROM s.seal_digest
 OR NOT EXISTS(SELECT 1 FROM company.artifacts art WHERE art.tenant_id=e.tenant_id AND art.project_id=e.project_id AND art.task_id=e.task_id AND art.attempt_id=e.attempt_id AND art.id=e.artifact_id AND art.state='AVAILABLE' AND art.sha256=m.payload->>'artifact_digest') THEN RAISE EXCEPTION 'R58_INDEPENDENT_ACCEPTANCE_CURRENT_EVIDENCE'; END IF;
 acceptance_id=gen_random_uuid();
 INSERT INTO company.acceptance_records(tenant_id,project_id,task_id,attempt_id,id,verification_run_id,evidence_id,accepted_by,build_digest,dirty_digest) VALUES(x.tenant_id,x.project_id,p_task,p_attempt,acceptance_id,v.id,e.id,x.principal_id,v.build_digest,v.dirty_digest);
 UPDATE company.tasks SET state='ACCEPTED',revision=revision+1 WHERE tenant_id=t.tenant_id AND project_id=t.project_id AND id=t.id AND revision=p_revision AND active_attempt_id=a.id AND fencing_epoch=p_fence AND state='VERIFYING';
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_ACCEPTANCE_CAS'; END IF;
 RETURN company_private.r58_finish(c.id,t.id,jsonb_build_object('task_id',t.id,'attempt_id',a.id,'acceptance_id',acceptance_id,'state','ACCEPTED','task_revision',p_revision+1,'head_digest',h.head_digest,'evidence_id',e.id,'seal_digest',s.seal_digest,'acceptor_id',x.principal_id));
END $$;

-- SOURCE sql/041_R58_STOP_RELEASE_NATIVE.sql
CREATE FUNCTION company_private.r58_process_stop_release(p_process uuid,p_revision bigint,p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;r company.process_runs%ROWTYPE;m company_private.r58_attestations%ROWTYPE;b company.budget_reservations%ROWTYPE;cl company.resource_claims%ROWTYPE;ch company_private.r58_controller_heads%ROWTYPE;c company.commands%ROWTYPE;j jsonb;
BEGIN
 -- Cleanup uses current PROJECT authority, not an expired worker lease. It
 -- grants no new execution and cannot authorize another spawn or new spend.
 x=company_private.r58_context('process.stop_release');m=company_private.r58_attestation(p_attestation,'r58.quiescence.v1');j=m.payload;
 PERFORM company_private.r58_shape(j,ARRAY['process_id','task_id','attempt_id','fencing_epoch','host_boot_id','controller_generation','cgroup_inode','process_identity_digest','cgroup_populated','workspace_fenced','no_post_fence_spawn','settled_minor','outcome']);
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('process_id',p_process,'expected_revision',p_revision,'attestation',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process FOR UPDATE;
 SELECT * INTO STRICT ch FROM company_private.r58_controller_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND controller_id=r.controller_id AND generation=r.controller_generation AND enabled FOR SHARE;
 IF r.e0_evaluation_run_id IS NOT NULL OR r.kind IS DISTINCT FROM 'TASK_EXECUTION' OR r.revision IS DISTINCT FROM p_revision OR r.release_command_id IS NOT NULL OR m.issuer_id IS DISTINCT FROM r.controller_id OR m.issuer_id IS DISTINCT FROM x.principal_id
 OR j->>'process_id' IS DISTINCT FROM r.id::text OR j->>'task_id' IS DISTINCT FROM r.task_id::text OR j->>'attempt_id' IS DISTINCT FROM r.attempt_id::text OR j->>'fencing_epoch' IS DISTINCT FROM r.attempt_fencing_epoch::text
 OR j->>'host_boot_id' IS DISTINCT FROM r.r55_host_boot_id::text OR ch.host_boot_id IS DISTINCT FROM r.r55_host_boot_id OR j->>'controller_generation' IS DISTINCT FROM r.controller_generation::text
 OR j->>'process_identity_digest' !~ '^[a-f0-9]{64}$' OR jsonb_typeof(j->'cgroup_inode') IS DISTINCT FROM 'number'
 OR j->'cgroup_populated' IS DISTINCT FROM '0'::jsonb OR j->'workspace_fenced' IS DISTINCT FROM 'true'::jsonb OR j->'no_post_fence_spawn' IS DISTINCT FROM 'true'::jsonb
 OR j->'settled_minor' IS DISTINCT FROM '0'::jsonb OR j->>'outcome' NOT IN ('STOPPED','FAILED_NOT_STARTED') THEN RAISE EXCEPTION 'R58_ACTUAL_QUIESCENCE_REQUIRED_NO_TTL_RELEASE'; END IF;
 -- The signed identity must agree with the immutable launch callback. For an
 -- uncertain spawn without callback, reconciliation remains blocked rather
 -- than fabricating a process identity or freeing resources by TTL.
 IF NOT EXISTS(SELECT 1 FROM company_private.r58_launch_capabilities cap JOIN company_private.r58_attestations cb ON cb.tenant_id=cap.tenant_id AND cb.project_id=cap.project_id AND cb.id=cap.callback_attestation_id WHERE cap.tenant_id=x.tenant_id AND cap.project_id=x.project_id AND cap.process_id=r.id AND cb.payload->>'process_identity_digest'=j->>'process_identity_digest' AND cb.payload->'cgroup_inode'=j->'cgroup_inode') THEN RAISE EXCEPTION 'R58_STOP_IDENTITY_RECONCILIATION_REQUIRED'; END IF;
 SELECT * INTO STRICT b FROM company.budget_reservations WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.reservation_id FOR UPDATE;
 IF b.amount_minor<>0 OR b.state IS DISTINCT FROM 'RESERVED' OR b.task_id IS DISTINCT FROM r.task_id OR b.attempt_id IS DISTINCT FROM r.attempt_id OR b.attempt_fencing_epoch IS DISTINCT FROM r.attempt_fencing_epoch THEN RAISE EXCEPTION 'R58_ZERO_LOCAL_RESERVATION_ONLY'; END IF;
 FOR cl IN SELECT * FROM company.resource_claims WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND process_run_id=r.id ORDER BY slot_id FOR UPDATE LOOP
  IF cl.state IS DISTINCT FROM 'HELD' THEN RAISE EXCEPTION 'R58_RESOURCE_ALREADY_RELEASED'; END IF;
  UPDATE company.resource_slots SET reserved=reserved-cl.units WHERE tenant_id=cl.tenant_id AND id=cl.slot_id AND reserved>=cl.units;
  IF NOT FOUND THEN RAISE EXCEPTION 'R58_RESOURCE_ACCOUNTING'; END IF;
  UPDATE company.resource_claims SET state='RELEASED',revision=revision+1,release_command_id=c.id WHERE tenant_id=cl.tenant_id AND project_id=cl.project_id AND process_run_id=cl.process_run_id AND slot_id=cl.slot_id AND state='HELD' AND revision=cl.revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'R58_CLAIM_RELEASE_CAS'; END IF;
 END LOOP;
 IF r.state NOT IN ('STOPPED','COMPLETED','FAILED_NOT_STARTED') THEN
  IF j->>'outcome'='FAILED_NOT_STARTED' AND r.state NOT IN ('LEASED','REQUESTED','STARTING','UNKNOWN_LOCAL') THEN RAISE EXCEPTION 'R58_RUNNING_PROCESS_CANNOT_BECOME_NOT_STARTED'; END IF;
  IF j->>'outcome'='STOPPED' AND r.state NOT IN ('STOP_REQUESTED','UNKNOWN_LOCAL') THEN
   UPDATE company.process_runs SET state='STOP_REQUESTED',revision=revision+1 WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=r.revision;
   IF NOT FOUND THEN RAISE EXCEPTION 'R58_STOP_REQUEST_CAS'; END IF;
   r.revision=r.revision+1;
  END IF;
  UPDATE company.process_runs SET state=j->>'outcome',revision=revision+1,stop_command_id=c.id WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=r.revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'R58_STOP_CONFIRM_CAS'; END IF;
  r.revision=r.revision+1;
 END IF;
 UPDATE company.budget_reservations SET state='SETTLED',revision=revision+1,settled_minor=0,settlement_command_id=c.id WHERE tenant_id=b.tenant_id AND project_id=b.project_id AND id=b.id AND state='RESERVED' AND revision=b.revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_RESERVATION_SETTLEMENT_CAS'; END IF;
 UPDATE company.budget_reservations SET state='RELEASED',revision=revision+1,released_minor=0,release_command_id=c.id,release_op_id=gen_random_uuid() WHERE tenant_id=b.tenant_id AND project_id=b.project_id AND id=b.id AND state='SETTLED' AND revision=b.revision+1;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_RESERVATION_RELEASE_CAS'; END IF;
 UPDATE company.process_runs SET release_command_id=c.id,revision=revision+1 WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=r.revision AND release_command_id IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_PROCESS_RELEASE_CAS'; END IF;
 RETURN company_private.r58_finish(c.id,r.id,jsonb_build_object('process_id',r.id,'resources_released',true,'quiescence_attestation',m.id,'settled_minor',0,'respawn_permitted',false));
END $$;

-- SOURCE sql/042_R58_EMISSION_NATIVE.sql
CREATE FUNCTION company_private.r58_emission_snapshot() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;h text;perm text;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 SELECT permission INTO STRICT perm FROM company_private.operation_permissions WHERE operation_id=x.operation_id;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,false) IS NOT TRUE THEN RAISE EXCEPTION 'R58_EMISSION_CURRENT_AUTHORITY'; END IF;
 SELECT head_digest INTO h FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id;
 RETURN jsonb_build_object('tenant_id',x.tenant_id,'project_id',x.project_id,'principal_id',x.principal_id,'session_id',x.session_id,'operation',x.operation_id,'tenant_epoch',x.tenant_epoch,'project_epoch',x.project_epoch,'session_epoch',x.session_epoch,'policy_revision',x.policy_revision,'head_digest',h);
END $$;
CREATE FUNCTION company_private.r58_emission_check(p_snapshot jsonb) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 -- Native context_enter reacquires the same rank-ordered scope locks used by
 -- revoke. The socket host holds this transaction during bounded synchronous
 -- sendall; every chunk refreshes trusted time/current grant before emission.
 RETURN p_snapshot IS NOT NULL AND p_snapshot=company_private.r58_emission_snapshot();
END $$;

-- SOURCE sql/043_R58_CLOCK_KEY_BOUNDARY.sql
GRANT SELECT,UPDATE(revoked) ON company_private.r58_key_material TO company_clock_policy_owner_r57;
CREATE POLICY r58_clock_secret ON company_private.r58_key_material FOR SELECT TO company_clock_policy_owner_r57 USING(purpose='CLOCK_POLICY' AND NOT revoked);
CREATE POLICY r58_clock_secret_lock ON company_private.r58_key_material FOR UPDATE TO company_clock_policy_owner_r57 USING(purpose='CLOCK_POLICY') WITH CHECK(false);
REVOKE EXECUTE ON FUNCTION company_private.r57_clock_policy_write(uuid,bytea,bytea,bytea) FROM company_clock_policy_transport_r57;
CREATE FUNCTION company_private.r58_clock_policy_write(p_consent uuid,p_raw bytea,p_tag bytea,p_key_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE p_key bytea; a company_private.r57_clock_policy_authority%ROWTYPE;
 c company_private.r57_clock_policy_consents%ROWTYPE;e company_private.r55_setup_root_enrollments%ROWTYPE;
 ctl company_private.installation_bootstrap_control%ROWTYPE;r company_private.r57_clock_policy_receipts%ROWTYPE;
 op company_private.operation_permissions%ROWTYPE;j jsonb;s jsonb;v jsonb;bounds jsonb;d text;pd text;rd text;aid bigint;
 msg bytea;item bytea;policy_key text;revision bigint;
BEGIN
 SELECT secret INTO STRICT p_key FROM company_private.r58_key_material WHERE key_id=p_key_id AND purpose='CLOCK_POLICY' AND NOT revoked FOR SHARE;
 IF NOT pg_has_role(session_user,'company_clock_policy_transport_r57','MEMBER') THEN RAISE EXCEPTION 'CLOCK_POLICY_TRANSPORT_REQUIRED'; END IF;
 IF p_consent IS NULL OR p_raw IS NULL OR octet_length(p_raw) NOT BETWEEN 1 AND 65536
 OR p_tag IS NULL OR octet_length(p_tag)<>32 OR p_key IS NULL OR octet_length(p_key)<>32 THEN RAISE EXCEPTION 'INVALID_CLOCK_POLICY_WIRE'; END IF;
 SELECT * INTO STRICT a FROM company_private.r57_clock_policy_authority WHERE singleton;
 SELECT * INTO STRICT ctl FROM company_private.installation_bootstrap_control WHERE installation_id=a.installation_id;
 -- Same installation lock as bootstrap. All policy writers take this first,
 -- then consent, then registry. Root rows stay SHARE-locked through COMMIT.
 PERFORM pg_advisory_xact_lock(ctl.lock_id);
 SELECT * INTO STRICT c FROM company_private.r57_clock_policy_consents WHERE consent_id=p_consent FOR SHARE;
 SELECT * INTO STRICT e FROM company_private.r55_setup_root_enrollments WHERE installation_id=a.installation_id AND generation=c.root_generation FOR SHARE;
 IF e.key_id IS DISTINCT FROM p_key_id OR c.installation_id IS DISTINCT FROM a.installation_id OR c.root_generation IS DISTINCT FROM ctl.generation
 OR ctl.state IS DISTINCT FROM 'CONSUMED' OR a.human_id IS DISTINCT FROM ctl.expected_human_id
 OR a.tenant_id IS DISTINCT FROM ctl.expected_tenant_id OR e.actual_human_id IS DISTINCT FROM a.human_id
 OR c.revoked_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=a.tenant_id AND id=a.human_id AND kind='HUMAN')
 OR e.key_fingerprint IS DISTINCT FROM encode(sha256(p_key),'hex') THEN RAISE EXCEPTION 'CLOCK_POLICY_HUMAN_ENROLLMENT_REQUIRED'; END IF;
 bounds=company_private.r56_root_bounds(a.installation_id);
 IF NOT ((c.valid_from<=(bounds->>'utc_lower')::timestamptz AND (bounds->>'utc_upper')::timestamptz<c.valid_until) IS TRUE)
 THEN RAISE EXCEPTION 'CLOCK_POLICY_CONSENT_EXPIRED_OR_AMBIGUOUS'; END IF;
 j=convert_from(p_raw,'UTF8')::jsonb;
 IF jsonb_typeof(j) IS DISTINCT FROM 'object'
 OR EXISTS(SELECT key FROM json_each(convert_from(p_raw,'UTF8')::json) GROUP BY key HAVING count(*)>1)
 OR NOT ((j ?& ARRAY['statement','backend_pid','transaction_id','db_login']) IS TRUE)
 OR (SELECT count(*) FROM jsonb_object_keys(j))<>4
 OR jsonb_typeof(j->'backend_pid') IS DISTINCT FROM 'number'
 OR j->>'backend_pid' !~ '^[1-9][0-9]*$'
 OR jsonb_typeof(j->'transaction_id') IS DISTINCT FROM 'string'
 OR jsonb_typeof(j->'db_login') IS DISTINCT FROM 'string'
 OR j->>'backend_pid' IS DISTINCT FROM pg_backend_pid()::text OR j->>'transaction_id' IS DISTINCT FROM pg_current_xact_id()::text
 OR j->>'db_login' IS DISTINCT FROM session_user::text THEN RAISE EXCEPTION 'CLOCK_POLICY_CONTEXT_MISMATCH'; END IF;
 s=j->'statement';
 IF jsonb_typeof(s) IS DISTINCT FROM 'object' OR NOT ((s ?& ARRAY['consent_id','installation_id','action','expected_revision','policy']) IS TRUE)
 OR (SELECT count(*) FROM jsonb_object_keys(s))<>5
 OR jsonb_typeof(s->'expected_revision') IS DISTINCT FROM 'number' OR s->>'expected_revision' !~ '^(0|[1-9][0-9]*)$'
 OR EXISTS(SELECT 1 FROM jsonb_each(s) z WHERE z.key IN ('consent_id','installation_id','action') AND jsonb_typeof(z.value) IS DISTINCT FROM 'string')
 THEN RAISE EXCEPTION 'CLOCK_POLICY_STATEMENT_SHAPE'; END IF;
 -- PG JSONB bytes, not a caller-supplied digest or Python JSON hash.
 d=encode(sha256(convert_to(s::text,'UTF8')),'hex');
 IF d IS DISTINCT FROM c.approved_statement_digest OR s->>'consent_id' IS DISTINCT FROM c.consent_id::text
 OR s->>'installation_id' IS DISTINCT FROM a.installation_id::text OR s->>'action' IS DISTINCT FROM c.action
 OR s->>'expected_revision' IS DISTINCT FROM c.expected_revision::text
 THEN RAISE EXCEPTION 'EXACT_HUMAN_POLICY_CONSENT_REQUIRED'; END IF;
 msg=convert_to('R57-CLOCK-POLICY-v1','UTF8')||decode('00','hex');
 FOREACH item IN ARRAY ARRAY[convert_to(c.consent_id::text,'UTF8'),convert_to(e.issuer_id::text,'UTF8'),convert_to(e.key_id::text,'UTF8'),convert_to(e.enrollment_revision::text,'UTF8'),p_raw] LOOP
  msg=msg||convert_to(octet_length(item)::text||':','UTF8')||item;
 END LOOP;
 IF company_private.r55_cp_tag_equal(company_private.r55_cp_hmac_sha256(p_key,msg),p_tag) IS NOT TRUE THEN RAISE EXCEPTION 'INVALID_CLOCK_POLICY_HMAC'; END IF;
 v=s->'policy';
 IF c.action='ACTIVATE' THEN
  IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR NOT ((v ?& ARRAY['bounded_handoff_duration_ms','max_uncertainty_ms','max_sample_age_ms','max_clock_jump_ms','first_alert_ms','owner_ack_ms','manual_reconcile_ms','poll_ms','max_drift_ms']) IS TRUE)
  OR (SELECT count(*) FROM jsonb_object_keys(v))<>9 THEN RAISE EXCEPTION 'NINE_EXPLICIT_CLOCK_DECISIONS_REQUIRED'; END IF;
  FOR policy_key IN SELECT jsonb_object_keys(v) LOOP
   IF jsonb_typeof(v->policy_key) IS DISTINCT FROM 'number' OR v->>policy_key !~ '^[1-9][0-9]*$' THEN RAISE EXCEPTION 'POSITIVE_INTEGER_CLOCK_DECISION_REQUIRED'; END IF;
   PERFORM (v->>policy_key)::bigint;
  END LOOP;
  IF (v->>'first_alert_ms')::bigint>(v->>'owner_ack_ms')::bigint OR (v->>'owner_ack_ms')::bigint>(v->>'manual_reconcile_ms')::bigint
  THEN RAISE EXCEPTION 'CLOCK_ESCALATION_ORDER'; END IF;
  pd=encode(sha256(convert_to(v::text,'UTF8')),'hex');
 ELSE
  IF v IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'REVOKE_POLICY_MUST_BE_NULL'; END IF;
  pd=NULL;v=NULL;
 END IF;
 SELECT * INTO STRICT op FROM company_private.operation_permissions WHERE operation_id='clock.policy.activate' FOR UPDATE;
 -- Recheck after registry lock wait, including the replay path.
 bounds=company_private.r56_root_bounds(a.installation_id);
 IF NOT ((c.valid_from<=(bounds->>'utc_lower')::timestamptz AND (bounds->>'utc_upper')::timestamptz<c.valid_until) IS TRUE)
 THEN RAISE EXCEPTION 'CLOCK_POLICY_FINAL_CONSENT_EXPIRED'; END IF;
 SELECT * INTO r FROM company_private.r57_clock_policy_receipts WHERE consent_id=c.consent_id;
 IF FOUND THEN
  IF r.statement_digest IS DISTINCT FROM d OR r.revision IS DISTINCT FROM op.policy_revision OR r.policy_digest IS DISTINCT FROM op.approved_policy_digest
  OR r.action IS DISTINCT FROM c.action
  OR r.receipt_digest IS DISTINCT FROM encode(sha256(convert_to(jsonb_build_array(r.consent_id,r.installation_id,r.human_id,r.revision,r.action,r.statement_digest,r.policy_digest,r.final_proof)::text,'UTF8')),'hex')
  OR NOT EXISTS(SELECT 1 FROM company.audit_events z WHERE z.tenant_id=r.tenant_id AND z.id=r.audit_id AND z.actor_id=r.human_id AND z.correlation_id=r.consent_id AND z.kind='ClockPolicy'||initcap(lower(r.action)))
  THEN RAISE EXCEPTION 'CLOCK_POLICY_REPLAY_STALE_OR_WITNESS_MISSING'; END IF;
  RETURN jsonb_build_object('consent_id',r.consent_id,'revision',r.revision,'receipt_digest',r.receipt_digest,'outcome','REPLAY_NO_NEW_REVISION');
 END IF;
 IF op.policy_revision IS DISTINCT FROM c.expected_revision THEN RAISE EXCEPTION 'CLOCK_POLICY_REVISION_CONFLICT'; END IF;
 revision=op.policy_revision+1;
 bounds=company_private.r56_root_bounds(a.installation_id);
 IF NOT ((c.valid_from<=(bounds->>'utc_lower')::timestamptz AND (bounds->>'utc_upper')::timestamptz<c.valid_until) IS TRUE)
 THEN RAISE EXCEPTION 'CLOCK_POLICY_FINAL_CONSENT_EXPIRED'; END IF;
 rd=encode(sha256(convert_to(jsonb_build_array(c.consent_id,a.installation_id,a.human_id,revision,c.action,d,pd,bounds)::text,'UTF8')),'hex');
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(a.tenant_id,c.consent_id,a.human_id,'ClockPolicy'||initcap(lower(c.action))) RETURNING id INTO aid;
 INSERT INTO company_private.r57_clock_policy_receipts(consent_id,installation_id,tenant_id,human_id,revision,action,statement_digest,policy_digest,policy,final_proof,receipt_digest,audit_id)
 VALUES(c.consent_id,a.installation_id,a.tenant_id,a.human_id,revision,c.action,d,pd,v,bounds,rd,aid);
 -- Registry lock precedes epoch locks in writer and every selected consumer.
 -- Retire current epochs atomically, freeing the one-current-epoch unique key.
 UPDATE company.clock_epochs SET invalidated_at=(bounds->>'utc_upper')::timestamptz
 WHERE tenant_id=a.tenant_id AND invalidated_at IS NULL;
 UPDATE company_private.operation_permissions SET policy_revision=revision,approved_policy_digest=pd
 WHERE operation_id='clock.policy.activate' AND policy_revision=c.expected_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'CLOCK_POLICY_CAS_CONFLICT'; END IF;
 -- Immutable epoch identity is preserved; only one-way invalidation changes.
 RETURN jsonb_build_object('consent_id',c.consent_id,'revision',revision,'receipt_digest',rd,'outcome',c.action);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'CLOCK_POLICY_NOT_ENROLLED';
END $$;
ALTER FUNCTION company_private.r58_clock_policy_write(uuid,bytea,bytea,uuid) OWNER TO company_clock_policy_owner_r57;
REVOKE ALL ON FUNCTION company_private.r58_clock_policy_write(uuid,bytea,bytea,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r58_clock_policy_write(uuid,bytea,bytea,uuid) TO company_clock_policy_transport_r57;

