-- SOURCE sql/049_R60_BEGIN_COMMAND_OVERLAY.sql
CREATE OR REPLACE FUNCTION company_private.r58_begin_command(p_key text,p_correlation uuid,p_request jsonb) RETURNS company.commands
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;c company.commands%ROWTYPE;d text;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 x=company_private.r58_context(x.operation_id);
 IF p_key IS NULL OR p_key !~ '^[A-Za-z0-9_.:-]{16,128}$' OR p_correlation IS NULL OR jsonb_typeof(p_request) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'R58_COMMAND_BINDING'; END IF;
 d=encode(sha256(convert_to(p_request::text,'UTF8')),'hex');
 c=company_private.r60_find_command(p_key);
 IF c.id IS NOT NULL THEN
  IF c.payload_digest IS DISTINCT FROM d OR c.state IS DISTINCT FROM 'SUCCEEDED' OR c.r55_result_digest IS NULL THEN RAISE EXCEPTION 'R58_IDEMPOTENCY_CONFLICT_OR_INCOMPLETE'; END IF;
  RETURN c;
 END IF;
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,gen_random_uuid(),x.principal_id,x.operation_id,p_key,d,p_correlation,'RUNNING',NULL) RETURNING * INTO c;
 RETURN c;
END $$;

-- SOURCE sql/050_R62_LEGACY_REPLAY_ASSEMBLY.sql
CREATE OR REPLACE FUNCTION company_private.r53_objectives_create(p_request jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; v_project uuid; v_correlation uuid;
 v_key text; v_digest text; v_id uuid; v_command uuid; v_revision bigint; element jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND operation_id='objectives.create';
 IF p_request IS NULL OR jsonb_typeof(p_request)<>'object' OR NOT (p_request ?& ARRAY['idempotency_key','correlation_id','project_id','goal','constraints','expected_outputs'])
 OR (SELECT count(*) FROM jsonb_object_keys(p_request))<>6 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 IF jsonb_typeof(p_request->'idempotency_key')<>'string' OR jsonb_typeof(p_request->'correlation_id')<>'string' OR jsonb_typeof(p_request->'project_id')<>'string'
 OR jsonb_typeof(p_request->'goal')<>'string' OR jsonb_typeof(p_request->'constraints')<>'array' OR jsonb_typeof(p_request->'expected_outputs')<>'array' THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 v_project=(p_request->>'project_id')::uuid; v_correlation=(p_request->>'correlation_id')::uuid; v_key=p_request->>'idempotency_key';
 IF v_project IS DISTINCT FROM x.project_id OR x.resource_kind<>'PROJECT' OR NOT company_private.r54_allowed(x.tenant_id,v_project,'objectives.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_CURRENT_AUTHORITY'; END IF;
 IF length(v_key) NOT BETWEEN 16 AND 128 OR v_key !~ '^[A-Za-z0-9_.:-]+$' OR length(p_request->>'goal') NOT BETWEEN 10 AND 4000
 OR jsonb_array_length(p_request->'constraints') NOT BETWEEN 1 AND 20 OR jsonb_array_length(p_request->'expected_outputs') NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 FOR element IN SELECT value FROM jsonb_array_elements((p_request->'constraints')||(p_request->'expected_outputs')) LOOP
  IF jsonb_typeof(element)<>'string' OR length(element#>>'{}') NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING'; END IF;
 END LOOP;
 -- Server-owned profile PG_JSONB_TEXT_UTF8_R53; JCS veya caller digest iddiası yok.
 -- correlation_id semantik payload dışıdır: replay ilk correlation id'yi döndürür.
 v_digest=encode(sha256(convert_to((p_request-'correlation_id'-'idempotency_key')::text,'UTF8')),'hex');
 -- Project authority advisory lock context enter'da alınmıştır; row lock bundan sonra.
 SELECT revision INTO STRICT v_revision FROM company.projects WHERE tenant_id=x.tenant_id AND id=v_project FOR UPDATE;
 c=company_private.r60_find_command(v_key);
 IF c.id IS NOT NULL THEN
  IF c.payload_digest<>v_digest THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  IF c.r55_result_payload IS NULL OR c.r55_result_payload->>'project_revision' IS NULL THEN RAISE EXCEPTION 'BLOCKED_LEGACY_UNFINALIZED_COMMAND'; END IF;
  RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,(c.r55_result_payload->>'project_revision')::bigint,'ObjectiveCreated',c.r55_result_payload);
 END IF;
 v_id=gen_random_uuid(); v_command=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,v_command,x.principal_id,'objectives.create',v_key,v_digest,v_correlation,'RUNNING',NULL);
 INSERT INTO company.objectives(tenant_id,project_id,id,goal,constraints,expected_outputs,created_by)
 VALUES(x.tenant_id,v_project,v_id,p_request->>'goal',p_request->'constraints',p_request->'expected_outputs',x.principal_id);
 UPDATE company.projects SET revision=revision+1 WHERE tenant_id=x.tenant_id AND id=v_project AND revision=v_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_PROJECT'; END IF;
 PERFORM company_private.r55_cp_finalize_command(v_command,v_id,v_revision+1,'ObjectiveCreated',jsonb_build_object('objective_id',v_id,'project_revision',v_revision+1));
 IF NOT company_private.r54_allowed(x.tenant_id,v_project,'objectives.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_COMMIT_CUT'; END IF;
 RETURN jsonb_build_object('command_id',v_command,'correlation_id',v_correlation,'state','SUCCEEDED','result_ref',v_id);
EXCEPTION WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST';
WHEN INVALID_TEXT_REPRESENTATION THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING';
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_plans_create(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; pid uuid; parent_id uuid; rid uuid; cid uuid; correlation uuid; k text; d text; rev bigint; dep uuid;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND operation_id='plans.create';
 IF q IS NULL OR jsonb_typeof(q)<>'object' OR NOT(q ?& ARRAY['idempotency_key','correlation_id','project_id','objective_id','expected_revision','assumptions','acceptance_criteria']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(q) key WHERE key<>ALL(ARRAY['idempotency_key','correlation_id','project_id','objective_id','expected_revision','assumptions','acceptance_criteria'])) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 pid=(q->>'project_id')::uuid; parent_id=(q->>'objective_id')::uuid; correlation=(q->>'correlation_id')::uuid; k=q->>'idempotency_key';
 IF pid IS DISTINCT FROM x.project_id OR x.task_id IS NOT NULL OR k IS NULL OR k !~ '^[A-Za-z0-9_.:-]{16,128}$' OR NOT company_private.r54_allowed(x.tenant_id,pid,'plans.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_CURRENT_AUTHORITY'; END IF;
 IF jsonb_typeof(q->'acceptance_criteria') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF jsonb_array_length(q->'acceptance_criteria') NOT BETWEEN 1 AND 20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'acceptance_criteria') e WHERE jsonb_typeof(e)<>'string' OR length(e#>>'{}') NOT BETWEEN 1 AND 2000) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 d=encode(sha256(convert_to((q-'correlation_id'-'idempotency_key')::text,'UTF8')),'hex');
 SELECT revision INTO STRICT rev FROM company.projects WHERE tenant_id=x.tenant_id AND id=pid FOR UPDATE;
 c=company_private.r60_find_command(k);
 IF c.id IS NOT NULL THEN
  IF c.payload_digest<>d THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  IF c.r55_result_payload IS NULL THEN RAISE EXCEPTION 'BLOCKED_LEGACY_UNFINALIZED_COMMAND'; END IF;
  RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,0,'PlanCreated',c.r55_result_payload);
 END IF;
 PERFORM 1 FROM company.objectives WHERE tenant_id=x.tenant_id AND project_id=pid AND id=parent_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PARENT_NOT_FOUND_OR_DENIED'; END IF;
 IF jsonb_typeof(q->'expected_revision') IS DISTINCT FROM 'number' OR (q->>'expected_revision') !~ '^[0-9]+$' OR (q->>'expected_revision')::bigint<>rev THEN RAISE EXCEPTION 'STALE_PROJECT_REVISION'; END IF;
 IF jsonb_typeof(q->'assumptions') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF jsonb_array_length(q->'assumptions')>20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'assumptions') e WHERE jsonb_typeof(e)<>'string' OR length(e#>>'{}') NOT BETWEEN 1 AND 2000) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 rid=gen_random_uuid(); cid=gen_random_uuid();
 INSERT INTO company.plans(tenant_id,project_id,id,objective_id,revision,assumptions,acceptance_criteria) VALUES(x.tenant_id,pid,rid,parent_id,0,q->'assumptions',q->'acceptance_criteria');
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref) VALUES(x.tenant_id,cid,x.principal_id,'plans.create',k,d,correlation,'RUNNING',NULL);
 UPDATE company.projects SET revision=revision+1 WHERE tenant_id=x.tenant_id AND id=pid AND revision=rev;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_PROJECT_REVISION'; END IF;
 PERFORM company_private.r55_cp_finalize_command(cid,rid,0,'PlanCreated',jsonb_build_object('resource_id',rid,'project_revision',rev+1));
 IF NOT company_private.r54_allowed(x.tenant_id,pid,'plans.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_COMMIT_CUT'; END IF;
 RETURN jsonb_build_object('command_id',cid,'correlation_id',correlation,'state','SUCCEEDED','result_ref',rid);
EXCEPTION WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING';
 WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST';
END $$;

CREATE OR REPLACE FUNCTION company_private.r54_tasks_create(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; pid uuid; parent_id uuid; rid uuid; cid uuid; correlation uuid; k text; d text; rev bigint; dep uuid;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND operation_id='tasks.create';
 IF q IS NULL OR jsonb_typeof(q)<>'object' OR NOT(q ?& ARRAY['idempotency_key','correlation_id','project_id','plan_id','title','role_id','acceptance_criteria']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(q) key WHERE key<>ALL(ARRAY['idempotency_key','correlation_id','project_id','plan_id','title','role_id','acceptance_criteria','depends_on'])) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 pid=(q->>'project_id')::uuid; parent_id=(q->>'plan_id')::uuid; correlation=(q->>'correlation_id')::uuid; k=q->>'idempotency_key';
 IF pid IS DISTINCT FROM x.project_id OR x.task_id IS NOT NULL OR k IS NULL OR k !~ '^[A-Za-z0-9_.:-]{16,128}$' OR NOT company_private.r54_allowed(x.tenant_id,pid,'tasks.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_CURRENT_AUTHORITY'; END IF;
 IF jsonb_typeof(q->'acceptance_criteria') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF jsonb_array_length(q->'acceptance_criteria') NOT BETWEEN 1 AND 20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'acceptance_criteria') e WHERE jsonb_typeof(e)<>'string' OR length(e#>>'{}') NOT BETWEEN 1 AND 2000) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 d=encode(sha256(convert_to((q-'correlation_id'-'idempotency_key')::text,'UTF8')),'hex');
 SELECT revision INTO STRICT rev FROM company.projects WHERE tenant_id=x.tenant_id AND id=pid FOR UPDATE;
 c=company_private.r60_find_command(k);
 IF c.id IS NOT NULL THEN
  IF c.payload_digest<>d THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST'; END IF;
  IF c.r55_result_payload IS NULL THEN RAISE EXCEPTION 'BLOCKED_LEGACY_UNFINALIZED_COMMAND'; END IF;
  RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,0,'TaskCreated',c.r55_result_payload);
 END IF;
 PERFORM 1 FROM company.plans WHERE tenant_id=x.tenant_id AND project_id=pid AND id=parent_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PARENT_NOT_FOUND_OR_DENIED'; END IF;
 IF jsonb_typeof(q->'title') IS DISTINCT FROM 'string' OR length(q->>'title') NOT BETWEEN 3 AND 200 OR jsonb_typeof(q->'role_id') IS DISTINCT FROM 'string' OR (q->>'role_id') !~ '^(MGR|EXP)-[0-9]{2,3}$' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 IF q ? 'depends_on' THEN
  IF jsonb_typeof(q->'depends_on') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
  IF jsonb_array_length(q->'depends_on')>32 OR EXISTS(SELECT 1 FROM jsonb_array_elements(q->'depends_on') e WHERE jsonb_typeof(e)<>'string') OR (SELECT count(*)<>count(DISTINCT value) FROM jsonb_array_elements_text(q->'depends_on')) THEN RAISE EXCEPTION 'INVALID_TYPED_REQUEST'; END IF;
 END IF;
 rid=gen_random_uuid(); cid=gen_random_uuid();
 INSERT INTO company.tasks(tenant_id,project_id,id,plan_id,title,role_id,state,revision,fencing_epoch,acceptance_criteria) VALUES(x.tenant_id,pid,rid,parent_id,q->>'title',q->>'role_id','DRAFT',0,0,q->'acceptance_criteria');
 -- Existing dependency rows cannot point to a not-yet-created rid; only outgoing edges added => no cycle introduced.
 FOR dep IN SELECT value::uuid FROM jsonb_array_elements_text(COALESCE(q->'depends_on','[]'::jsonb)) ORDER BY value LOOP
  PERFORM 1 FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=pid AND id=dep;
  IF NOT FOUND THEN RAISE EXCEPTION 'DEPENDENCY_NOT_FOUND_OR_DENIED'; END IF;
  INSERT INTO company.task_dependencies(tenant_id,project_id,task_id,depends_on_task_id) VALUES(x.tenant_id,pid,rid,dep);
 END LOOP;
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref) VALUES(x.tenant_id,cid,x.principal_id,'tasks.create',k,d,correlation,'RUNNING',NULL);
 UPDATE company.projects SET revision=revision+1 WHERE tenant_id=x.tenant_id AND id=pid AND revision=rev;
 IF NOT FOUND THEN RAISE EXCEPTION 'STALE_PROJECT_REVISION'; END IF;
 PERFORM company_private.r55_cp_finalize_command(cid,rid,0,'TaskCreated',jsonb_build_object('resource_id',rid,'project_revision',rev+1));
 IF NOT company_private.r54_allowed(x.tenant_id,pid,'tasks.create',NULL,true) THEN RAISE EXCEPTION 'DENIED_COMMIT_CUT'; END IF;
 RETURN jsonb_build_object('command_id',cid,'correlation_id',correlation,'state','SUCCEEDED','result_ref',rid);
EXCEPTION WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_TYPED_BINDING';
 WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_IDEMPOTENCY_DIGEST';
END $$;

CREATE OR REPLACE FUNCTION company_private.r55_cp_persist_process_proof(p_artifact uuid,p_raw jsonb,p_envelope jsonb,p_key_material bytea,p_idempotency text,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; e company.evaluation_runs%ROWTYPE; pr company.process_runs%ROWTYPE; en company.signer_enrollments%ROWTYPE; b company_private.bootstrap_receipts%ROWTYPE; c company.commands%ROWTYPE;
 profile text; fields text[]; issuer uuid; task_id uuid; attempt_id uuid; rid uuid; cmd uuid; digest text; binding text; envelope_digest text; request_digest text; raw bytea; tag bytea; item text; n bigint; verified company.artifacts%ROWTYPE;
BEGIN
 IF NOT pg_has_role(session_user,'company_receipt_ingest_r55','MEMBER') THEN RAISE EXCEPTION 'TRUSTED_RECEIPT_INGEST_REQUIRED'; END IF;
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54 AND operation_id='e0.process_proof_persist';
 IF p_artifact IS NULL OR p_raw IS NULL OR jsonb_typeof(p_raw) IS DISTINCT FROM 'object' OR p_envelope IS NULL OR jsonb_typeof(p_envelope) IS DISTINCT FROM 'object'
 OR p_key_material IS NULL OR octet_length(p_key_material)<>32 OR p_idempotency IS NULL OR p_idempotency !~ '^[A-Za-z0-9_.:-]{16,128}$' OR p_correlation IS NULL THEN RAISE EXCEPTION 'INVALID_PROCESS_PROOF_INPUT'; END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'e0.process_proof_persist',x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_PROCESS_PROOF_AUTHORITY'; END IF;
 profile=p_raw->>'profile';
 IF profile IS NULL OR profile NOT IN ('r55.e0-process-admission.pg-jsonb.v1','r55.e0-process-observation.pg-jsonb.v1') THEN RAISE EXCEPTION 'PROCESS_PROOF_PROFILE_NOT_ALLOWED'; END IF;
 fields=ARRAY['tenant_id','issuer_id','key_id','purpose','profile_id','enrollment_revision','receipt_id','canonical_artifact_digest','expected_binding_digest','envelope_digest','auth_tag'];
 IF NOT(p_envelope ?& fields) OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_envelope) k WHERE k<>ALL(fields)) OR NOT((p_envelope->>'tenant_id'=x.tenant_id::text
 AND p_envelope->>'issuer_id'=x.principal_id::text AND p_envelope->>'purpose'='EVALUATION' AND p_envelope->>'profile_id'=profile
 AND jsonb_typeof(p_envelope->'enrollment_revision')='number' AND p_envelope->>'enrollment_revision' ~ '^[0-9]+$' AND p_envelope->>'auth_tag' ~ '^[A-Za-z0-9_-]{43}$') IS TRUE)
 THEN RAISE EXCEPTION 'PROCESS_PROOF_ENROLLMENT_BINDING_INVALID'; END IF;
 rid=(p_envelope->>'receipt_id')::uuid;
 PERFORM 1 FROM company.projects WHERE tenant_id=x.tenant_id AND id=x.project_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PROCESS_PROOF_PROJECT_UNRESOLVED'; END IF;
 IF profile='r55.e0-process-admission.pg-jsonb.v1' THEN
  SELECT * INTO STRICT e FROM company.evaluation_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=(p_raw->>'evaluation_run_id')::uuid FOR SHARE;
  SELECT * INTO STRICT b FROM company_private.bootstrap_receipts WHERE installation_id=e.e0_installation_id AND tenant_id=e.tenant_id AND project_id=e.project_id;
  issuer=b.accepted_human_id; task_id=e.evaluation_task_id; attempt_id=e.evaluation_attempt_id;
  binding=encode(sha256(convert_to(jsonb_build_array(x.tenant_id,x.project_id,e.id,e.evaluation_task_id,e.evaluation_attempt_id,p_artifact)::text,'UTF8')),'hex');
 ELSE
  SELECT * INTO STRICT pr FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=(p_raw->>'process_run_id')::uuid FOR SHARE;
  IF pr.e0_evaluation_run_id IS NULL OR pr.qualification_id IS NOT NULL THEN RAISE EXCEPTION 'E0_PROCESS_PROOF_ONLY'; END IF;
  issuer=pr.controller_id;task_id=pr.task_id;attempt_id=pr.attempt_id;
  binding=encode(sha256(convert_to(jsonb_build_array(pr.tenant_id,pr.project_id,pr.id,pr.task_id,pr.attempt_id,pr.attempt_fencing_epoch,pr.host_registration_id,pr.host_registration_revision,pr.host_generation,pr.r55_host_boot_id,pr.controller_id,pr.controller_generation,pr.manifest_digest)::text,'UTF8')),'hex');
 END IF;
 IF issuer IS NULL OR issuer IS DISTINCT FROM x.principal_id OR p_raw->>'tenant_id' IS DISTINCT FROM x.tenant_id::text OR p_raw->>'project_id' IS DISTINCT FROM x.project_id::text
 OR p_raw->>'task_id' IS DISTINCT FROM task_id::text OR p_raw->>'attempt_id' IS DISTINCT FROM attempt_id::text THEN RAISE EXCEPTION 'PROCESS_PROOF_ISSUER_OR_SCOPE_INVALID'; END IF;
 SELECT * INTO STRICT en FROM company.signer_enrollments WHERE tenant_id=x.tenant_id AND issuer_id=issuer AND key_id=(p_envelope->>'key_id')::uuid AND purpose='EVALUATION' AND profile_id=profile AND enrollment_revision=(p_envelope->>'enrollment_revision')::bigint FOR SHARE;
 IF en.revoked_at IS NOT NULL OR en.compromised_since IS NOT NULL OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,en.valid_from,en.valid_until) IS NOT TRUE OR en.key_fingerprint IS DISTINCT FROM encode(sha256(p_key_material),'hex')
 OR NOT EXISTS(SELECT 1 FROM company.principals hp WHERE hp.tenant_id=en.tenant_id AND hp.id=en.approved_by AND hp.kind='HUMAN') THEN RAISE EXCEPTION 'DENIED_PROCESS_PROOF_CURRENT_ENROLLMENT'; END IF;
 digest=encode(sha256(convert_to(p_raw::text,'UTF8')),'hex'); n=octet_length(convert_to(p_raw::text,'UTF8'));
 IF n>52428800 OR digest IS DISTINCT FROM p_envelope->>'canonical_artifact_digest' OR binding IS DISTINCT FROM p_envelope->>'expected_binding_digest' THEN RAISE EXCEPTION 'PROCESS_PROOF_DIGEST_BINDING_INVALID'; END IF;
 raw=convert_to('R54-EVALUATION-v1','UTF8')||decode('00','hex');
 FOREACH item IN ARRAY ARRAY[x.tenant_id::text,issuer::text,en.key_id::text,'EVALUATION',profile,en.enrollment_revision::text,rid::text,digest,binding] LOOP
  raw=raw||convert_to(octet_length(convert_to(item,'UTF8'))::text||':'||item,'UTF8');
 END LOOP;
 envelope_digest=encode(sha256(raw),'hex');tag=decode(translate(p_envelope->>'auth_tag','-_','+/')||'=','base64');
 IF envelope_digest IS DISTINCT FROM p_envelope->>'envelope_digest' OR company_private.r55_cp_tag_equal(company_private.r55_cp_hmac_sha256(p_key_material,raw),tag) IS DISTINCT FROM true THEN RAISE EXCEPTION 'INVALID_PROCESS_PROOF_HMAC'; END IF;
 request_digest=encode(sha256(convert_to(jsonb_build_array(p_artifact,p_raw,p_envelope)::text,'UTF8')),'hex');
 c=company_private.r60_find_command(p_idempotency);
 IF c.id IS NOT NULL THEN
  IF c.payload_digest IS DISTINCT FROM request_digest OR c.r55_project_id IS DISTINCT FROM x.project_id OR c.r55_result_payload IS NULL THEN RAISE EXCEPTION 'CONFLICT_PROCESS_PROOF_IDEMPOTENCY'; END IF;
  RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,0,'E0ProcessProofPersisted',c.r55_result_payload);
 END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'e0.process_proof_persist',x.task_id,true) IS DISTINCT FROM true OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,en.valid_from,en.valid_until) IS NOT TRUE THEN RAISE EXCEPTION 'DENIED_PROCESS_PROOF_INSERT_CUT'; END IF;
 INSERT INTO company.artifacts(tenant_id,project_id,task_id,attempt_id,id,storage_key,sha256,size_bytes,state,r55_e0_process_manifest,r55_e0_process_observation)
 VALUES(x.tenant_id,x.project_id,task_id,attempt_id,p_artifact,gen_random_uuid(),digest,n,'AVAILABLE',CASE WHEN profile='r55.e0-process-admission.pg-jsonb.v1' THEN p_raw ELSE NULL END,CASE WHEN profile='r55.e0-process-observation.pg-jsonb.v1' THEN p_raw ELSE NULL END);
 INSERT INTO company.internal_receipt_envelopes(tenant_id,issuer_id,key_id,purpose,enrollment_revision,receipt_id,profile_id,envelope_digest,expected_binding_digest,canonical_artifact_digest,auth_tag,verified_at)
 VALUES(x.tenant_id,issuer,en.key_id,'EVALUATION',en.enrollment_revision,rid,profile,envelope_digest,binding,digest,p_envelope->>'auth_tag',clock_timestamp());
 verified=company_private.r55_cp_e0_verified_artifact(x.tenant_id,x.project_id,task_id,attempt_id,p_artifact,rid,profile,issuer,binding);
 cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,cmd,x.principal_id,x.operation_id,p_idempotency,request_digest,p_correlation,'RUNNING',NULL);
 RETURN company_private.r55_cp_finalize_command(cmd,p_artifact,0,'E0ProcessProofPersisted',jsonb_build_object('artifact_id',p_artifact,'receipt_id',rid,'profile',profile,'sha256',digest));
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'PROCESS_PROOF_CANONICAL_SOURCE_UNRESOLVED';
 WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_PROCESS_PROOF_TYPED_BINDING';
 WHEN UNIQUE_VIOLATION THEN RAISE EXCEPTION 'CONFLICT_PROCESS_PROOF_IDENTITY';
END $$;

CREATE OR REPLACE FUNCTION company_private.r55_cp_persist_evaluation_envelope(p_evaluation uuid,p_binding jsonb,p_envelope jsonb,p_key_material bytea,p_idempotency text,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; e company.evaluation_runs%ROWTYPE; ev company.evidence%ROWTYPE; v company.verification_runs%ROWTYPE; a company.artifacts%ROWTYPE; en company.signer_enrollments%ROWTYPE; old company.internal_receipt_envelopes%ROWTYPE; cmd company.commands%ROWTYPE;
 raw bytea; tag bytea; item text; binding_digest text; artifact_digest text; envelope_digest text; request_digest text; rid uuid; cid uuid; revision bigint; fields text[]; now_at timestamptz;
BEGIN
 IF NOT pg_has_role(session_user,'company_receipt_ingest_r55','MEMBER') THEN RAISE EXCEPTION 'TRUSTED_RECEIPT_INGEST_REQUIRED'; END IF;
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54 AND operation_id='e0.evaluation_envelope_persist';
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'e0.evaluation_envelope_persist',x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_RECEIPT_AUTHORITY'; END IF;
 fields=ARRAY['tenant_id','issuer_id','key_id','purpose','profile_id','enrollment_revision','receipt_id','canonical_artifact_digest','expected_binding_digest','envelope_digest','auth_tag'];
 IF p_binding IS NULL OR jsonb_typeof(p_binding) IS DISTINCT FROM 'object' OR p_envelope IS NULL OR jsonb_typeof(p_envelope) IS DISTINCT FROM 'object' OR NOT(p_envelope ?& fields) OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_envelope) k WHERE k<>ALL(fields))
 OR p_key_material IS NULL OR octet_length(p_key_material)<>32 OR p_idempotency IS NULL OR p_idempotency !~ '^[A-Za-z0-9_.:-]{16,128}$' OR p_correlation IS NULL THEN RAISE EXCEPTION 'INVALID_RECEIPT_INPUT'; END IF;
 IF NOT ((p_envelope->>'tenant_id'=x.tenant_id::text AND p_envelope->>'issuer_id'=x.principal_id::text AND p_envelope->>'purpose'='EVALUATION' AND p_envelope->>'profile_id'='r54.evaluation-report.pg-jsonb.v1'
 AND jsonb_typeof(p_envelope->'enrollment_revision')='number' AND p_envelope->>'enrollment_revision' ~ '^[0-9]+$' AND p_envelope->>'auth_tag' ~ '^[A-Za-z0-9_-]{43}$') IS TRUE) THEN RAISE EXCEPTION 'WRONG_ENROLLMENT_BINDING'; END IF;
 PERFORM company_private.r54_schema_check(p_binding,'{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"schema_version":{"const":"r53.execution-binding.v1"},"subject_principal_id":{"type":"string","format":"uuid"},"role_definition":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"agent_profile":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"model":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"engine":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"tools":{"type":"array","items":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"minItems":1,"uniqueItems":true},"suite":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"policy":{"type":"object","properties":{"identity":{"type":"string","minLength":1},"revision":{"type":"integer","minimum":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["identity","revision","sha256"],"additionalProperties":false},"resource_scope":{"type":"object","properties":{"tenant_id":{"type":"string","format":"uuid"},"project_id":{"type":"string","format":"uuid"},"workspace_id":{"type":"string","format":"uuid"}},"required":["tenant_id","project_id","workspace_id"],"additionalProperties":false},"independent_evidence":{"type":"object","properties":{"task_id":{"type":"string","format":"uuid"},"attempt_id":{"type":"string","format":"uuid"},"evidence_id":{"type":"string","format":"uuid"},"verification_run_id":{"type":"string","format":"uuid"},"producer_id":{"type":"string","format":"uuid"},"verifier_id":{"type":"string","format":"uuid"},"artifact_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["task_id","attempt_id","evidence_id","verification_run_id","producer_id","verifier_id","artifact_sha256"],"additionalProperties":false},"source_revision":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["schema_version","subject_principal_id","role_definition","agent_profile","model","engine","tools","suite","policy","resource_scope","independent_evidence","source_revision"],"additionalProperties":false}'::jsonb);
 revision=(p_envelope->>'enrollment_revision')::bigint; rid=(p_envelope->>'receipt_id')::uuid;
 -- Domain project row precedes enrollment locks, command and event-head locks.
 PERFORM 1 FROM company.projects WHERE tenant_id=x.tenant_id AND id=x.project_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RECEIPT_PROJECT_UNRESOLVED'; END IF;
 -- Lock enrollment through commit so revoke/rotation cannot race verified INSERT.
 SELECT * INTO STRICT en FROM company.signer_enrollments WHERE tenant_id=x.tenant_id AND issuer_id=x.principal_id AND key_id=(p_envelope->>'key_id')::uuid AND purpose='EVALUATION' AND enrollment_revision=revision AND profile_id='r54.evaluation-report.pg-jsonb.v1' FOR SHARE;
 now_at=clock_timestamp();
 IF en.revoked_at IS NOT NULL OR en.compromised_since IS NOT NULL OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,en.valid_from,en.valid_until) IS NOT TRUE
 OR en.key_fingerprint IS DISTINCT FROM encode(sha256(p_key_material),'hex') OR NOT EXISTS(SELECT 1 FROM company.principals hp WHERE hp.tenant_id=en.tenant_id AND hp.id=en.approved_by AND hp.kind='HUMAN') THEN RAISE EXCEPTION 'DENIED_CURRENT_SIGNER_ENROLLMENT'; END IF;
 SELECT * INTO STRICT e FROM company.evaluation_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_evaluation FOR SHARE;
 SELECT * INTO STRICT ev FROM company.evidence WHERE tenant_id=e.tenant_id AND project_id=e.project_id AND task_id=e.evaluation_task_id AND attempt_id=e.evaluation_attempt_id AND id=(p_binding#>>'{independent_evidence,evidence_id}')::uuid FOR SHARE;
 SELECT * INTO STRICT v FROM company.verification_runs WHERE tenant_id=ev.tenant_id AND project_id=ev.project_id AND task_id=ev.task_id AND attempt_id=ev.attempt_id AND id=ev.verification_run_id FOR SHARE;
 SELECT * INTO STRICT a FROM company.artifacts WHERE tenant_id=ev.tenant_id AND project_id=ev.project_id AND task_id=ev.task_id AND attempt_id=ev.attempt_id AND id=ev.artifact_id FOR SHARE;
 IF NOT((v.producer_id=e.subject_principal_id AND v.verifier_id=x.principal_id AND v.producer_id<>v.verifier_id AND a.state='AVAILABLE' AND a.r54_evaluation_report IS NOT NULL AND a.r54_evaluation_report->>'receipt_id'=rid::text AND ev.command_receipt IS NOT NULL) IS TRUE) THEN RAISE EXCEPTION 'DENIED_CANONICAL_REPORT_BINDING'; END IF;
 artifact_digest=encode(sha256(convert_to(a.r54_evaluation_report::text,'UTF8')),'hex');
 binding_digest=encode(sha256(convert_to(p_binding::text,'UTF8')),'hex');
 IF artifact_digest IS DISTINCT FROM a.sha256 OR artifact_digest IS DISTINCT FROM p_envelope->>'canonical_artifact_digest' OR binding_digest IS DISTINCT FROM p_envelope->>'expected_binding_digest' THEN RAISE EXCEPTION 'WRONG_REPORT_BINDING'; END IF;
 raw=convert_to('R54-EVALUATION-v1','UTF8')||decode('00','hex');
 FOREACH item IN ARRAY ARRAY[x.tenant_id::text,x.principal_id::text,en.key_id::text,'EVALUATION',en.profile_id,revision::text,rid::text,artifact_digest,binding_digest] LOOP
  raw=raw||convert_to(octet_length(convert_to(item,'UTF8'))::text||':'||item,'UTF8');
 END LOOP;
 envelope_digest=encode(sha256(raw),'hex');
 tag=decode(translate(p_envelope->>'auth_tag','-_','+/')||'=','base64');
 IF envelope_digest IS DISTINCT FROM p_envelope->>'envelope_digest' OR company_private.r55_cp_tag_equal(company_private.r55_cp_hmac_sha256(p_key_material,raw),tag) IS DISTINCT FROM true THEN RAISE EXCEPTION 'INVALID_ENVELOPE_HMAC'; END IF;
 request_digest=encode(sha256(convert_to(jsonb_build_array(p_evaluation,p_envelope,p_binding)::text,'UTF8')),'hex');
 -- Shared project row serializes idempotency before INSERT, not global outbox IDs.
 SELECT * INTO cmd FROM company.commands WHERE tenant_id=x.tenant_id AND principal_id=x.principal_id AND operation=x.operation_id AND idempotency_key=p_idempotency;
 IF FOUND THEN
  IF cmd.payload_digest IS DISTINCT FROM request_digest OR cmd.r55_project_id IS DISTINCT FROM x.project_id OR cmd.r55_result_digest IS NULL THEN RAISE EXCEPTION 'CONFLICT_RECEIPT_COMMAND'; END IF;
  IF company_private.r54_allowed(x.tenant_id,x.project_id,'e0.evaluation_envelope_persist',x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_RECEIPT_REPLAY_CUT'; END IF;
  RETURN jsonb_build_object('command_id',cmd.id,'correlation_id',cmd.correlation_id,'state',cmd.state,'result_ref',cmd.result_ref);
 END IF;
 SELECT * INTO old FROM company.internal_receipt_envelopes WHERE tenant_id=x.tenant_id AND receipt_id=rid;
 IF FOUND THEN RAISE EXCEPTION 'RECEIPT_ID_ALREADY_PERSISTED_DIFFERENT_COMMAND'; END IF;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'e0.evaluation_envelope_persist',x.task_id,true) IS DISTINCT FROM true OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,en.valid_from,en.valid_until) IS NOT TRUE THEN RAISE EXCEPTION 'DENIED_RECEIPT_AFTER_LOCK_WAIT'; END IF;
 INSERT INTO company.internal_receipt_envelopes(tenant_id,issuer_id,key_id,purpose,enrollment_revision,receipt_id,profile_id,envelope_digest,expected_binding_digest,canonical_artifact_digest,auth_tag,verified_at)
 VALUES(x.tenant_id,x.principal_id,en.key_id,'EVALUATION',revision,rid,en.profile_id,envelope_digest,binding_digest,artifact_digest,p_envelope->>'auth_tag',clock_timestamp());
 INSERT INTO company.verifier_receipts(tenant_id,project_id,task_id,attempt_id,id,purpose,signer_id,key_id,receipt_digest,signature)
 VALUES(x.tenant_id,x.project_id,e.evaluation_task_id,e.evaluation_attempt_id,rid,'EVALUATION',x.principal_id,en.key_id,envelope_digest,p_envelope->>'auth_tag');
 cid=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,cid,x.principal_id,x.operation_id,p_idempotency,request_digest,p_correlation,'RUNNING',NULL);
 RETURN company_private.r55_cp_finalize_command(cid,rid,0,'E0EnvelopePersisted',jsonb_build_object('receipt_id',rid,'envelope_digest',envelope_digest,'verified_profile',en.profile_id));
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'RECEIPT_CANONICAL_SOURCE_UNRESOLVED';
 WHEN INVALID_TEXT_REPRESENTATION OR NUMERIC_VALUE_OUT_OF_RANGE THEN RAISE EXCEPTION 'INVALID_RECEIPT_TYPED_BINDING';
END $$;



CREATE OR REPLACE FUNCTION company_private.r57_replay_command(p_command uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;c company.commands%ROWTYPE;e company.outbox%ROWTYPE;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=x.tenant_id AND id=p_command AND principal_id=x.principal_id AND operation=x.operation_id;
 SELECT * INTO STRICT e FROM company.outbox WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND event_instance_id=c.id AND project_sequence=c.r55_event_sequence;
 RETURN company_private.r55_cp_finalize_command(c.id,c.result_ref,e.aggregate_revision,e.kind,c.r55_result_payload);
END $$;
ALTER FUNCTION company_private.r57_replay_command(uuid) OWNER TO company_atomic_functions_r55;
REVOKE ALL ON FUNCTION company_private.r57_replay_command(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r57_replay_command(uuid) TO company_e0_process_functions_r55;
CREATE OR REPLACE FUNCTION company_private.r55_cp_e0_process_admit(
 p_evaluation uuid,p_manifest uuid,p_receipt uuid,p_key text,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE final_result jsonb; x company_private.request_contexts%ROWTYPE; e company.evaluation_runs%ROWTYPE;
 b company_private.bootstrap_receipts%ROWTYPE; t company.tasks%ROWTYPE; at company.attempts%ROWTYPE;
 art company.artifacts%ROWTYPE; v company.budget_versions%ROWTYPE; h company.host_registrations%ROWTYPE;
 c company.commands%ROWTYPE; sl company.resource_slots%ROWTYPE; m jsonb; item jsonb;
 d text; bind text; exposure numeric; process uuid; reservation uuid; cmd uuid; n integer;
BEGIN
 x=company_private.r54_b_context('e0.process_admit',true,true);
 IF p_evaluation IS NULL OR p_manifest IS NULL OR p_receipt IS NULL OR p_correlation IS NULL
 OR p_key IS NULL OR length(p_key) NOT BETWEEN 16 AND 128 THEN RAISE EXCEPTION 'INVALID_PROCESS_ADMISSION'; END IF;
 SELECT * INTO STRICT e FROM company.evaluation_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_evaluation;
 SELECT * INTO STRICT b FROM company_private.bootstrap_receipts WHERE installation_id=e.e0_installation_id;
 bind=encode(sha256(convert_to(jsonb_build_array(x.tenant_id,x.project_id,e.id,e.evaluation_task_id,e.evaluation_attempt_id,p_manifest)::text,'UTF8')),'hex');
 art=company_private.r55_cp_e0_verified_artifact(x.tenant_id,x.project_id,e.evaluation_task_id,e.evaluation_attempt_id,
 p_manifest,p_receipt,'r55.e0-process-admission.pg-jsonb.v1',b.accepted_human_id,bind);
 m=art.r55_e0_process_manifest;
 IF NOT ((m->>'tenant_id'=x.tenant_id::text AND m->>'project_id'=x.project_id::text
 AND m->>'evaluation_run_id'=e.id::text AND m->>'task_id'=e.evaluation_task_id::text
 AND m->>'attempt_id'=e.evaluation_attempt_id::text AND m->>'worker_id'=e.subject_principal_id::text
 AND m->>'model_digest'=e.model_digest AND m->>'fixture_digest'=e.fixture_digest
 AND m->>'profile_digest'=b.e0_mandate->>'profile_digest' AND m->>'workspace_id'=b.e0_mandate->>'workspace_id'
 AND m->>'network'='DENY' AND m->>'external_effects'='DENY' AND m->>'credentials'='NONE'
 AND m->>'live_paths'='DENY' AND m->>'kind' IN ('CHECK_SUITE','MUTANT_SUITE')
 AND (m->>'amount_minor')::bigint=0 AND jsonb_typeof(m->'claims')='array'
 AND jsonb_array_length(m->'claims')>0) IS TRUE) THEN RAISE EXCEPTION 'INVALID_FINITE_E0_MANIFEST'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(m->'claims') z GROUP BY (z->>'slot_id')::uuid HAVING count(*)>1)
 THEN RAISE EXCEPTION 'DUPLICATE_RESOURCE_SLOT'; END IF;
 d=encode(sha256(convert_to(jsonb_build_array(p_evaluation,p_manifest,p_receipt,m)::text,'UTF8')),'hex');
 c=company_private.r60_find_command(p_key);
 IF c.id IS NOT NULL THEN
  IF c.payload_digest IS DISTINCT FROM d OR c.state<>'SUCCEEDED' THEN RAISE EXCEPTION 'CONFLICT_PROCESS_COMMAND'; END IF;
  PERFORM company_private.r54_b_context('e0.process_admit',true,true);
  PERFORM company_private.r57_replay_command(c.id);
  RETURN jsonb_build_object('process_run_id',c.result_ref,'command_id',c.id,'outcome','REPLAY_NO_SPAWN');
 END IF;
 -- Current project authority locks already serialize this budget across revisions.
 SELECT * INTO STRICT v FROM company.budget_versions WHERE tenant_id=x.tenant_id AND project_id=x.project_id
 AND budget_id=(m->>'budget_id')::uuid AND revision=(m->>'budget_revision')::bigint FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=v.tenant_id AND id=v.approved_by AND kind='HUMAN')
 OR v.environment_policy_digest IS DISTINCT FROM m->>'environment_policy_digest'
 THEN RAISE EXCEPTION 'BUDGET_HUMAN_POLICY_REQUIRED'; END IF;
 SELECT COALESCE(sum(greatest(amount_minor,settled_minor)-released_minor),0) INTO exposure
 FROM company.budget_reservations WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND budget_id=v.budget_id;
 IF exposure>v.limit_minor THEN RAISE EXCEPTION 'BUDGET_EXPOSURE_EXCEEDED'; END IF;
 SELECT * INTO STRICT e FROM company.evaluation_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_evaluation FOR UPDATE;
 SELECT * INTO STRICT t FROM company.tasks WHERE tenant_id=e.tenant_id AND project_id=e.project_id AND id=e.evaluation_task_id FOR UPDATE;
 SELECT * INTO STRICT at FROM company.attempts WHERE tenant_id=e.tenant_id AND project_id=e.project_id AND task_id=t.id AND id=e.evaluation_attempt_id FOR UPDATE;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,b.e0_valid_until);
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,at.lease_expires_at);
 IF b.accepted_human_id IS DISTINCT FROM x.principal_id OR b.e0_valid_until IS NULL
 OR e.state<>'AUTHORIZED' OR t.execution_kind<>'EVALUATION' OR t.state NOT IN ('READY','RUNNING','VERIFYING')
 OR t.active_attempt_id IS DISTINCT FROM at.id OR t.fencing_epoch IS DISTINCT FROM at.fencing_epoch
 OR at.worker_id IS DISTINCT FROM e.subject_principal_id OR at.e0_evaluation_run_id IS DISTINCT FROM e.id
 OR at.admission_qualification_id IS NOT NULL OR at.state NOT IN ('CLAIMED','RUNNING') OR at.ended_at IS NOT NULL
 OR at.lease_expires_at>b.e0_valid_until
 OR at.fencing_epoch IS DISTINCT FROM (m->>'fencing_epoch')::bigint
 OR NOT isfinite((m->>'valid_until')::timestamptz) OR (m->>'valid_until')::timestamptz<at.lease_expires_at
 OR (m->>'valid_until')::timestamptz>b.e0_valid_until THEN RAISE EXCEPTION 'STALE_E0_ADMISSION_TUPLE'; END IF;
 PERFORM company_private.r55_cp_clock_assert_current(x.tenant_id,x.project_id,(m->>'clock_epoch_id')::uuid,(m->>'clock_sample_id')::uuid);
 IF NOT EXISTS(SELECT 1 FROM company.clock_epochs ce WHERE ce.tenant_id=x.tenant_id AND ce.epoch_id=(m->>'clock_epoch_id')::uuid
 AND ce.host_boot_id=(m->>'host_boot_id')::uuid AND ce.r55_host_registration_id=(m->>'host_registration_id')::uuid
 AND ce.r55_host_registration_revision=(m->>'host_registration_revision')::bigint
 AND ce.r55_host_generation=(m->>'host_generation')::bigint) THEN RAISE EXCEPTION 'PROCESS_CLOCK_BOOT_BINDING_MISMATCH'; END IF;
 SELECT * INTO STRICT h FROM company.host_registrations WHERE tenant_id=x.tenant_id AND project_id=x.project_id
 AND id=(m->>'host_registration_id')::uuid AND revision=(m->>'host_registration_revision')::bigint FOR SHARE;
 IF h.state<>'BOUND_NOT_LEASED' OR h.bound_generation IS DISTINCT FROM (m->>'host_generation')::bigint
 OR NOT EXISTS(SELECT 1 FROM company.projects pr JOIN company.workspaces ws ON ws.tenant_id=pr.tenant_id AND ws.id=pr.workspace_id
 WHERE pr.tenant_id=x.tenant_id AND pr.id=x.project_id AND pr.workspace_id=(m->>'workspace_id')::uuid
 AND ws.trust_class='DISPOSABLE_TEST' AND pr.host_registration_id=h.id AND pr.host_registration_revision=h.revision
 AND pr.instance_generation=h.bound_generation) THEN RAISE EXCEPTION 'E0_HOST_OR_ISOLATION_BINDING_STALE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=(m->>'controller_id')::uuid AND kind IN ('WORKER','VERIFIER'))
 OR (m->>'controller_generation')::bigint<=0 OR (m->>'controller_id')::uuid=e.subject_principal_id
 THEN RAISE EXCEPTION 'E0_INDEPENDENT_CONTROLLER_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id
 AND e0_evaluation_run_id=e.id) THEN RAISE EXCEPTION 'E0_RUN_ALREADY_RESERVED_NO_RESPAWN'; END IF;
 process=gen_random_uuid();reservation=gen_random_uuid();cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,cmd,x.principal_id,x.operation_id,p_key,d,p_correlation,'RUNNING',NULL);
 INSERT INTO company.budget_reservations(tenant_id,project_id,id,budget_id,budget_revision,task_id,attempt_id,attempt_fencing_epoch,
 semantic_key,payload_digest,admission_artifact_id,amount_minor,state,command_id)
 VALUES(x.tenant_id,x.project_id,reservation,v.budget_id,v.revision,t.id,at.id,at.fencing_epoch,
 'e0:'||e.id::text,d,p_manifest,0,'RESERVED',cmd);
 INSERT INTO company.process_runs(tenant_id,project_id,id,task_id,attempt_id,attempt_fencing_epoch,worker_lease_id,worker_id,
 qualification_id,e0_evaluation_run_id,lease_expires_at,workspace_id,host_registration_id,host_registration_revision,host_generation,
 controller_id,controller_generation,kind,state,reservation_id,manifest_artifact_id,manifest_digest,semantic_run_digest,start_command_id,
 r55_host_boot_id,r55_admission_receipt_id)
 VALUES(x.tenant_id,x.project_id,process,t.id,at.id,at.fencing_epoch,gen_random_uuid(),at.worker_id,NULL,e.id,at.lease_expires_at,
 (m->>'workspace_id')::uuid,h.id,h.revision,h.bound_generation,(m->>'controller_id')::uuid,(m->>'controller_generation')::bigint,
 m->>'kind','REQUESTED',reservation,p_manifest,art.sha256,d,cmd,(m->>'host_boot_id')::uuid,p_receipt);
 FOR item IN SELECT value FROM jsonb_array_elements(m->'claims') ORDER BY (value->>'slot_id')::uuid LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR jsonb_typeof(item->'units') IS DISTINCT FROM 'number'
  OR jsonb_typeof(item->'slot_id') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'INVALID_RESOURCE_CLAIM_SHAPE'; END IF;
  n=(item->>'units')::integer;
  IF n IS NULL OR n<=0 OR item->>'slot_id' IS NULL THEN RAISE EXCEPTION 'INVALID_RESOURCE_UNITS'; END IF;
  SELECT * INTO STRICT sl FROM company.resource_slots WHERE tenant_id=x.tenant_id AND id=(item->>'slot_id')::uuid FOR UPDATE;
  UPDATE company.resource_slots SET reserved=reserved+n WHERE tenant_id=x.tenant_id AND id=sl.id AND reserved=sl.reserved AND capacity-reserved>=n;
  IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_CAPACITY_EXCEEDED'; END IF;
  INSERT INTO company.resource_claims(tenant_id,project_id,process_run_id,slot_id,units,state)
  VALUES(x.tenant_id,x.project_id,process,sl.id,n,'HELD');
 END LOOP;
 final_result=company_private.r55_cp_finalize_command(cmd,process,0,'E0ProcessAdmitted',
 jsonb_build_object('process_run_id',process,'reservation_id',reservation,'state','REQUESTED','spawned',false,'ordinary_admission',false));
 -- R55_POST_ALL_LOCKS_CUT: finalizer can wait too; rollback all rows on expiry.
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,b.e0_valid_until);
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,at.lease_expires_at);
 PERFORM company_private.r54_b_context('e0.process_admit',true,true);
 RETURN final_result;
END $$;

CREATE OR REPLACE FUNCTION company_private.r55_cp_e0_process_observe(
 p_operation text,p_process uuid,p_expected_revision bigint,p_artifact uuid,p_receipt uuid,
 p_key text,p_correlation uuid,p_require_stop boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE final_result jsonb; x company_private.request_contexts%ROWTYPE;r company.process_runs%ROWTYPE;
 a company.artifacts%ROWTYPE;c company.commands%ROWTYPE;m jsonb;d text;bind text;cmd uuid;next_state text;
BEGIN
 IF p_operation IS NULL OR p_operation NOT IN ('e0.process_stop_confirm','e0.process_reconcile') OR p_require_stop IS NULL
 OR (p_operation='e0.process_stop_confirm') IS DISTINCT FROM p_require_stop
 OR p_process IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_artifact IS NULL OR p_receipt IS NULL
 OR p_correlation IS NULL OR p_key IS NULL OR length(p_key) NOT BETWEEN 16 AND 128 THEN RAISE EXCEPTION 'INVALID_PROCESS_OBSERVATION'; END IF;
 x=company_private.r54_b_context(p_operation,false,true);
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process FOR UPDATE;
 IF r.e0_evaluation_run_id IS NULL OR r.qualification_id IS NOT NULL OR r.controller_id IS DISTINCT FROM x.principal_id
 THEN RAISE EXCEPTION 'E0_CONTROLLER_TUPLE_REQUIRED'; END IF;
 bind=encode(sha256(convert_to(jsonb_build_array(r.tenant_id,r.project_id,r.id,r.task_id,r.attempt_id,r.attempt_fencing_epoch,
 r.host_registration_id,r.host_registration_revision,r.host_generation,r.r55_host_boot_id,r.controller_id,r.controller_generation,r.manifest_digest)::text,'UTF8')),'hex');
 a=company_private.r55_cp_e0_verified_artifact(r.tenant_id,r.project_id,r.task_id,r.attempt_id,p_artifact,p_receipt,
 'r55.e0-process-observation.pg-jsonb.v1',r.controller_id,bind);
 m=a.r55_e0_process_observation;
 d=encode(sha256(convert_to(jsonb_build_array(p_process,p_expected_revision,p_artifact,p_receipt,p_operation)::text,'UTF8')),'hex');
 c=company_private.r60_find_command(p_key);
 IF c.id IS NOT NULL THEN
  IF c.payload_digest IS DISTINCT FROM d OR c.state<>'SUCCEEDED' THEN RAISE EXCEPTION 'CONFLICT_PROCESS_COMMAND'; END IF;
  PERFORM company_private.r54_b_context(p_operation,false,true);
  PERFORM company_private.r57_replay_command(c.id);
  RETURN jsonb_build_object('process_run_id',r.id,'command_id',c.id,'outcome','REPLAY_ORIGINAL_FACT_NO_RESPAWN');
 END IF;
 IF r.revision IS DISTINCT FROM p_expected_revision OR r.state IN ('STOPPED','COMPLETED','FAILED_NOT_STARTED')
 OR r.release_command_id IS NOT NULL THEN RAISE EXCEPTION 'STALE_OR_TERMINAL_PROCESS'; END IF;
 IF NOT ((m->>'process_run_id'=r.id::text AND m->>'task_id'=r.task_id::text AND m->>'attempt_id'=r.attempt_id::text
 AND (m->>'fencing_epoch')::bigint=r.attempt_fencing_epoch AND (m->>'host_generation')::bigint=r.host_generation
 AND m->>'host_boot_id'=r.r55_host_boot_id::text AND (m->>'controller_generation')::bigint=r.controller_generation
 AND m->>'manifest_digest'=r.manifest_digest AND m->>'network'='DENY'
 AND m->>'external_effects'='DENY' AND ((m->>'observed_state'='UNKNOWN_LOCAL' AND m->>'process_identity_digest' IS NULL)
 OR m->>'process_identity_digest' ~ '^[a-f0-9]{64}$')) IS TRUE)
 THEN RAISE EXCEPTION 'PROCESS_OBSERVATION_TUPLE_MISMATCH'; END IF;
 IF r.r55_process_identity_digest IS NOT NULL AND r.r55_process_identity_digest IS DISTINCT FROM m->>'process_identity_digest'
 THEN RAISE EXCEPTION 'ORIGINAL_PROCESS_IDENTITY_CHANGED'; END IF;
 next_state=m->>'observed_state';
 IF next_state NOT IN ('RUNNING','STOPPED','UNKNOWN_LOCAL','FAILED_NOT_STARTED') OR next_state IS NULL
 OR (p_require_stop AND next_state<>'STOPPED') THEN RAISE EXCEPTION 'INVALID_PROCESS_OBSERVATION_STATE'; END IF;
 IF next_state='RUNNING' AND r.state='STOP_REQUESTED' THEN RAISE EXCEPTION 'STALE_RUN_CANNOT_RESUME'; END IF;
 IF next_state='RUNNING' THEN
  PERFORM company_private.r55_cp_require_not_expired(r.tenant_id,r.project_id,r.lease_expires_at);
  PERFORM company_private.r55_cp_clock_assert_current(r.tenant_id,r.project_id,(m->>'clock_epoch_id')::uuid,(m->>'clock_sample_id')::uuid);
  IF NOT EXISTS(SELECT 1 FROM company.clock_epochs ce WHERE ce.tenant_id=r.tenant_id AND ce.epoch_id=(m->>'clock_epoch_id')::uuid
   AND ce.host_boot_id=r.r55_host_boot_id AND ce.r55_host_registration_id=r.host_registration_id
   AND ce.r55_host_registration_revision=r.host_registration_revision AND ce.r55_host_generation=r.host_generation)
  THEN RAISE EXCEPTION 'REBOOTED_HOST_CANNOT_RESUME_ORIGINAL_PROCESS'; END IF;
 END IF;
 IF next_state='RUNNING' AND NOT EXISTS(SELECT 1 FROM company.tasks t JOIN company.attempts at
 ON at.tenant_id=t.tenant_id AND at.project_id=t.project_id AND at.task_id=t.id AND at.id=t.active_attempt_id
 JOIN company.host_registrations h ON h.tenant_id=t.tenant_id AND h.project_id=t.project_id
 JOIN company.projects pr ON pr.tenant_id=t.tenant_id AND pr.id=t.project_id
 WHERE t.tenant_id=r.tenant_id AND t.project_id=r.project_id AND t.id=r.task_id AND t.execution_kind='EVALUATION'
 AND t.state IN ('READY','RUNNING','VERIFYING') AND at.id=r.attempt_id AND at.fencing_epoch=r.attempt_fencing_epoch
 AND t.fencing_epoch=at.fencing_epoch AND at.worker_id=r.worker_id AND at.state IN ('CLAIMED','RUNNING')
 AND at.ended_at IS NULL AND at.lease_expires_at=r.lease_expires_at
 AND h.id=r.host_registration_id AND h.revision=r.host_registration_revision AND h.bound_generation=r.host_generation
 AND h.state='BOUND_NOT_LEASED' AND pr.instance_generation=r.host_generation
 AND pr.host_registration_id=h.id AND pr.host_registration_revision=h.revision)
 THEN RAISE EXCEPTION 'STALE_OR_REVOKED_RUN_BINDING'; END IF;
 IF next_state='STOPPED' AND NOT ((m->'all_descendants_gone'='true'::jsonb AND m->'cgroup_quiescent'='true'::jsonb
 AND m->'workspace_fenced'='true'::jsonb AND m->'no_post_fence_spawn'='true'::jsonb
 AND m->>'usage_state'='VERIFIED_ZERO_LOCAL' AND (m->>'settled_minor')::bigint=0) IS TRUE)
 THEN RAISE EXCEPTION 'PROCESS_STOP_QUIESCENCE_PROOF_REQUIRED'; END IF;
 IF next_state='FAILED_NOT_STARTED' AND NOT ((m->'never_spawned'='true'::jsonb AND m->'all_descendants_gone'='true'::jsonb
 AND m->'cgroup_quiescent'='true'::jsonb AND m->'workspace_fenced'='true'::jsonb
 AND m->'no_post_fence_spawn'='true'::jsonb AND m->>'usage_state'='VERIFIED_ZERO_LOCAL'
 AND (m->>'settled_minor')::bigint=0) IS TRUE) THEN RAISE EXCEPTION 'NO_SPAWN_PROOF_REQUIRED'; END IF;
 IF next_state='RUNNING' AND NOT EXISTS(SELECT 1 FROM company.artifacts ia WHERE ia.tenant_id=r.tenant_id AND ia.project_id=r.project_id
 AND ia.task_id=r.task_id AND ia.attempt_id=r.attempt_id AND ia.id=(m->>'isolation_artifact_id')::uuid AND ia.state='AVAILABLE'
 AND ia.sha256=m->>'isolation_digest') THEN RAISE EXCEPTION 'ISOLATION_PROOF_REQUIRED'; END IF;
 cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,cmd,x.principal_id,x.operation_id,p_key,d,p_correlation,'RUNNING',NULL);
 UPDATE company.process_runs SET state=next_state,revision=revision+1,
 r55_process_identity_digest=m->>'process_identity_digest',
 stop_command_id=CASE WHEN next_state IN ('STOPPED','FAILED_NOT_STARTED') THEN cmd ELSE stop_command_id END,
 stop_artifact_id=CASE WHEN next_state IN ('STOPPED','FAILED_NOT_STARTED') THEN a.id ELSE stop_artifact_id END,
 r55_stop_receipt_id=CASE WHEN next_state IN ('STOPPED','FAILED_NOT_STARTED') THEN p_receipt ELSE r55_stop_receipt_id END,
 r55_isolation_artifact_id=CASE WHEN next_state='RUNNING' THEN (m->>'isolation_artifact_id')::uuid ELSE r55_isolation_artifact_id END
 WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=p_expected_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'PROCESS_REVISION_CONFLICT'; END IF;
 final_result=company_private.r55_cp_finalize_command(cmd,r.id,p_expected_revision+1,
 CASE WHEN p_require_stop THEN 'E0ProcessStopConfirmed' ELSE 'E0ProcessReconciled' END,
 jsonb_build_object('process_run_id',r.id,'state',next_state,'spawned',false,'resources_released',false));
 -- R55_POST_ALL_LOCKS_CUT: finalizer can wait too; rollback all rows on expiry.
 IF next_state='RUNNING' THEN
  PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,r.lease_expires_at);
 END IF;
 PERFORM company_private.r54_b_context(p_operation,false,true);
 RETURN final_result;
END $$;

CREATE OR REPLACE FUNCTION company_private.r55_cp_e0_process_release(p_process uuid,p_expected_revision bigint,p_key text,p_correlation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE final_result jsonb; x company_private.request_contexts%ROWTYPE;r company.process_runs%ROWTYPE;b company.budget_reservations%ROWTYPE;
 cl company.resource_claims%ROWTYPE;v company.budget_versions%ROWTYPE;art company.artifacts%ROWTYPE;
 c company.commands%ROWTYPE;cmd uuid;d text;bind text;
BEGIN
 x=company_private.r54_b_context('e0.process_release',false,true);
 IF p_process IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_key IS NULL
 OR length(p_key) NOT BETWEEN 16 AND 128 OR p_correlation IS NULL THEN RAISE EXCEPTION 'INVALID_PROCESS_RELEASE'; END IF;
 -- Read immutable identity first, lock budget before process and slots.
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process;
 SELECT * INTO STRICT b FROM company.budget_reservations WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.reservation_id;
 SELECT * INTO STRICT v FROM company.budget_versions WHERE tenant_id=b.tenant_id AND project_id=b.project_id AND budget_id=b.budget_id AND revision=b.budget_revision FOR UPDATE;
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process FOR UPDATE;
 d=encode(sha256(convert_to(jsonb_build_array(p_process,p_expected_revision,r.stop_artifact_id,r.r55_stop_receipt_id)::text,'UTF8')),'hex');
 c=company_private.r60_find_command(p_key);
 IF c.id IS NOT NULL THEN
  IF c.payload_digest IS DISTINCT FROM d OR c.state<>'SUCCEEDED' THEN RAISE EXCEPTION 'CONFLICT_PROCESS_COMMAND'; END IF;
  PERFORM company_private.r54_b_context('e0.process_release',false,true);
  PERFORM company_private.r57_replay_command(c.id);
  RETURN jsonb_build_object('process_run_id',r.id,'command_id',c.id,'outcome','REPLAY_NO_SECOND_RELEASE');
 END IF;
 IF r.e0_evaluation_run_id IS NULL OR r.qualification_id IS NOT NULL OR r.revision IS DISTINCT FROM p_expected_revision
 OR r.state NOT IN ('STOPPED','FAILED_NOT_STARTED') OR r.stop_artifact_id IS NULL OR r.r55_stop_receipt_id IS NULL
 OR r.release_command_id IS NOT NULL THEN RAISE EXCEPTION 'STOP_PROOF_REQUIRED_NO_TTL_RELEASE'; END IF;
 bind=encode(sha256(convert_to(jsonb_build_array(r.tenant_id,r.project_id,r.id,r.task_id,r.attempt_id,r.attempt_fencing_epoch,
 r.host_registration_id,r.host_registration_revision,r.host_generation,r.r55_host_boot_id,r.controller_id,r.controller_generation,r.manifest_digest)::text,'UTF8')),'hex');
 art=company_private.r55_cp_e0_verified_artifact(r.tenant_id,r.project_id,r.task_id,r.attempt_id,r.stop_artifact_id,r.r55_stop_receipt_id,
 'r55.e0-process-observation.pg-jsonb.v1',r.controller_id,bind);
 IF NOT ((art.r55_e0_process_observation->>'usage_state'='VERIFIED_ZERO_LOCAL'
 AND (art.r55_e0_process_observation->>'settled_minor')::bigint=0) IS TRUE) THEN RAISE EXCEPTION 'UNKNOWN_USAGE_NO_RELEASE'; END IF;
 SELECT * INTO STRICT b FROM company.budget_reservations WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.reservation_id FOR UPDATE;
 IF b.task_id IS DISTINCT FROM r.task_id OR b.attempt_id IS DISTINCT FROM r.attempt_id OR b.attempt_fencing_epoch IS DISTINCT FROM r.attempt_fencing_epoch
 OR b.state<>'RESERVED' OR b.amount_minor<>0 OR b.settled_minor<>0 OR b.released_minor<>0 THEN RAISE EXCEPTION 'RESERVATION_NOT_RELEASABLE'; END IF;
 cmd=gen_random_uuid();
 INSERT INTO company.commands(tenant_id,id,principal_id,operation,idempotency_key,payload_digest,correlation_id,state,result_ref)
 VALUES(x.tenant_id,cmd,x.principal_id,x.operation_id,p_key,d,p_correlation,'RUNNING',NULL);
 FOR cl IN SELECT * FROM company.resource_claims WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND process_run_id=r.id ORDER BY slot_id FOR UPDATE LOOP
  IF cl.state<>'HELD' THEN RAISE EXCEPTION 'CLAIM_ALREADY_RELEASED'; END IF;
  UPDATE company.resource_slots SET reserved=reserved-cl.units WHERE tenant_id=cl.tenant_id AND id=cl.slot_id AND reserved>=cl.units;
  IF NOT FOUND THEN RAISE EXCEPTION 'CLAIM_CAPACITY_ACCOUNTING_CONFLICT'; END IF;
  UPDATE company.resource_claims SET state='RELEASED',revision=revision+1,release_command_id=cmd
  WHERE tenant_id=cl.tenant_id AND project_id=cl.project_id AND process_run_id=cl.process_run_id AND slot_id=cl.slot_id AND revision=cl.revision AND state='HELD';
  IF NOT FOUND THEN RAISE EXCEPTION 'CLAIM_REVISION_CONFLICT'; END IF;
 END LOOP;
 UPDATE company.budget_reservations SET state='RELEASED',revision=revision+1,released_minor=0,
 settlement_command_id=cmd,release_command_id=cmd,release_op_id=cmd
 WHERE tenant_id=b.tenant_id AND project_id=b.project_id AND id=b.id AND revision=b.revision AND state='RESERVED';
 IF NOT FOUND THEN RAISE EXCEPTION 'RESERVATION_REVISION_CONFLICT'; END IF;
 UPDATE company.process_runs SET release_command_id=cmd,revision=revision+1
 WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=p_expected_revision AND release_command_id IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'PROCESS_REVISION_CONFLICT'; END IF;
 final_result=company_private.r55_cp_finalize_command(cmd,r.id,p_expected_revision+1,'E0ProcessReleased',
 jsonb_build_object('process_run_id',r.id,'state',r.state,'released',true,'ordinary_admission',false));
 -- R55_POST_ALL_LOCKS_CUT: finalizer can wait too; rollback all rows on expiry.
 PERFORM company_private.r55_cp_e0_verified_artifact(r.tenant_id,r.project_id,r.task_id,r.attempt_id,r.stop_artifact_id,r.r55_stop_receipt_id,
 'r55.e0-process-observation.pg-jsonb.v1',r.controller_id,bind);
 PERFORM company_private.r54_b_context('e0.process_release',false,true);
 RETURN final_result;
END $$;


-- SOURCE sql/051_R60_WRITER_FENCE.sql
CREATE OR REPLACE FUNCTION company.r50_command_identity_immutable() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF OLD.operation='trusted_setup.consume' AND OLD.state='RUNNING' AND OLD.r55_result_digest IS NULL
 AND NEW.state='SUCCEEDED' AND NEW.r55_source_revision='r56' THEN
  IF (to_jsonb(OLD)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
   IS DISTINCT FROM
   (to_jsonb(NEW)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
  OR NOT EXISTS(SELECT 1 FROM company_private.bootstrap_request_contexts x
   JOIN company_private.installation_bootstrap_control b ON b.installation_id=x.installation_id AND b.generation=x.generation
   WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user
   AND x.r56_command_id=OLD.id AND b.expected_tenant_id=OLD.tenant_id AND b.expected_human_id=OLD.principal_id
   AND b.expected_project_id=NEW.r55_project_id AND b.installation_id=NEW.result_ref
   AND b.state='ARMED' AND x.manifest_digest=OLD.payload_digest)
  THEN RAISE EXCEPTION 'IMMUTABLE_COMMAND_RECEIPT'; END IF;
 ELSIF OLD.operation IN ('objectives.create','plans.create','tasks.create','e0.process_proof_persist','e0.evaluation_envelope_persist','e0.process_admit','e0.process_stop_confirm','e0.process_reconcile','e0.process_release','worker.claim','worker.heartbeat','workspace.current_head','process.launch_reserve','process.launch_consume','process.launch_callback','tool.authorize_final','patch.receipt','verification.final_seal','evidence.provenance','verification.accept','evidence.attestation_ingest','process.stop_release','tasks.ready','engine.bind','tool.consume','tool.effect','process.lease_prepare','process.lease_commit','process.lease_activate','process.reconcile')
 AND OLD.state='RUNNING' AND OLD.result_ref IS NULL AND OLD.r55_result_digest IS NULL
 AND NEW.state='SUCCEEDED' AND NEW.r55_source_revision IN ('r55-cp1','r58') THEN
  IF current_user<>'company_atomic_functions_r55'
  OR (to_jsonb(OLD)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
   IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','result_ref','r55_project_id','r55_result_payload','r55_result_digest','r55_event_sequence','r55_audit_id','r55_source_revision'])
  OR NOT EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid()
   AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.writer_generation=54
   AND x.tenant_id=OLD.tenant_id AND x.project_id=NEW.r55_project_id AND x.principal_id=OLD.principal_id AND x.operation_id=OLD.operation)
  THEN RAISE EXCEPTION 'IMMUTABLE_COMMAND_RECEIPT'; END IF;
 ELSE
  IF to_jsonb(OLD) IS DISTINCT FROM to_jsonb(NEW)
  OR (OLD.state IN ('SUCCEEDED','FAILED') AND ROW(OLD.state,OLD.result_ref) IS DISTINCT FROM ROW(NEW.state,NEW.result_ref))
  THEN RAISE EXCEPTION 'IMMUTABLE_COMMAND_RECEIPT'; END IF;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION company.r50_command_identity_immutable() FROM PUBLIC;

CREATE OR REPLACE FUNCTION company_private.r55_cp_finalize_command(p_command uuid,p_aggregate uuid,p_revision bigint,p_event_kind text,p_result_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE; c company.commands%ROWTYPE; d text; seq bigint; aid bigint; perm text; event_payload jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 IF p_command IS NULL OR p_aggregate IS NULL OR p_revision IS NULL OR p_revision<0 OR p_result_payload IS NULL OR jsonb_typeof(p_result_payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'INVALID_RESULT_BINDING'; END IF;
 IF p_event_kind IS DISTINCT FROM company_private.r55_cp_event_kind(x.operation_id) OR company_private.r55_cp_event_kind(x.operation_id) IS NULL THEN RAISE EXCEPTION 'UNREGISTERED_FINALIZER_OPERATION'; END IF;
 SELECT permission INTO STRICT perm FROM company_private.operation_permissions WHERE operation_id=x.operation_id AND execution_class NOT IN ('QUERY','STREAM');
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_FINALIZE_COMMAND'; END IF;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=x.tenant_id AND id=p_command AND principal_id=x.principal_id AND operation=x.operation_id AND (r55_project_id=x.project_id OR EXISTS(SELECT 1 FROM company_private.r60_command_scopes s WHERE s.tenant_id=x.tenant_id AND s.project_id=x.project_id AND s.command_id=p_command)) FOR UPDATE;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_FINALIZE_AFTER_LOCK_WAIT'; END IF;
 IF c.payload_digest IS NULL OR c.correlation_id IS NULL THEN RAISE EXCEPTION 'COMMAND_IDENTITY_INCOMPLETE'; END IF;
 d=encode(sha256(convert_to(jsonb_build_array(c.id,c.payload_digest,p_aggregate,p_revision,p_event_kind,p_result_payload,coalesce(c.r55_source_revision,'r58'))::text,'UTF8')),'hex');
 IF c.r55_result_digest IS NOT NULL THEN
  IF c.state IS DISTINCT FROM 'SUCCEEDED' OR c.result_ref IS DISTINCT FROM p_aggregate
   OR c.r55_result_digest IS DISTINCT FROM d OR c.r55_project_id IS DISTINCT FROM x.project_id
   OR c.r55_result_payload IS DISTINCT FROM p_result_payload OR c.r55_event_sequence IS NULL OR c.r55_audit_id IS NULL
   OR NOT EXISTS(SELECT 1 FROM company.audit_events a WHERE a.tenant_id=c.tenant_id AND a.id=c.r55_audit_id AND a.actor_id=c.principal_id AND a.correlation_id=c.correlation_id AND a.kind=p_event_kind)
   OR NOT EXISTS(SELECT 1 FROM company.outbox e WHERE e.tenant_id=c.tenant_id AND e.project_id=c.r55_project_id AND e.project_sequence=c.r55_event_sequence AND e.event_instance_id=c.id AND e.event_writer_generation=54 AND e.kind=p_event_kind AND e.payload->>'result_digest'=d AND e.payload->>'request_digest'=c.payload_digest) THEN RAISE EXCEPTION 'CONFLICT_RESULT_DIGEST'; END IF;
  RETURN jsonb_build_object('command_id',c.id,'correlation_id',c.correlation_id,'state',c.state,'result_ref',c.result_ref);
 END IF;
 IF c.state IS DISTINCT FROM 'RUNNING' OR c.result_ref IS NOT NULL THEN RAISE EXCEPTION 'UNSEALED_RUNNING_COMMAND_REQUIRED'; END IF;
 INSERT INTO company.audit_events(tenant_id,correlation_id,actor_id,kind) VALUES(x.tenant_id,c.correlation_id,x.principal_id,p_event_kind) RETURNING id INTO aid;
 event_payload=jsonb_build_object('command_id',c.id,'request_digest',c.payload_digest,'result_digest',d,'result_ref',p_aggregate,'source_revision','r58');
 seq=company_private.r55_cp_emit_event(x.tenant_id,x.project_id,c.id,p_aggregate,p_revision,p_event_kind,event_payload);
 UPDATE company.commands SET state='SUCCEEDED',result_ref=p_aggregate,r55_project_id=x.project_id,r55_result_payload=p_result_payload,r55_result_digest=d,r55_event_sequence=seq,r55_audit_id=aid,r55_source_revision='r58' WHERE tenant_id=c.tenant_id AND id=c.id AND state='RUNNING' AND result_ref IS NULL AND r55_result_digest IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'CONFLICT_RESULT_FINALIZATION'; END IF;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=x.tenant_id AND id=p_command;
 IF company_private.r54_allowed(x.tenant_id,x.project_id,perm,x.task_id,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DENIED_COMMAND_COMMIT_CUT'; END IF;
 RETURN jsonb_build_object('command_id',c.id,'correlation_id',c.correlation_id,'state',c.state,'result_ref',c.result_ref);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'COMMAND_OR_CONTEXT_UNRESOLVED';
END $$;
ALTER FUNCTION company_private.r55_cp_finalize_command(uuid,uuid,bigint,text,jsonb) OWNER TO company_atomic_functions_r55;
REVOKE ALL ON FUNCTION company_private.r55_cp_finalize_command(uuid,uuid,bigint,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_finalize_command(uuid,uuid,bigint,text,jsonb) TO company_first_run_functions_r53;

CREATE OR REPLACE FUNCTION company.r58_command_insert_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF NEW.state IS DISTINCT FROM 'RUNNING' OR NEW.result_ref IS NOT NULL OR NEW.r55_result_digest IS NOT NULL
 OR NEW.r55_project_id IS NOT NULL OR NEW.r55_result_payload IS NOT NULL OR NEW.r55_event_sequence IS NOT NULL OR NEW.r55_audit_id IS NOT NULL OR NEW.r55_source_revision IS NOT NULL THEN RAISE EXCEPTION 'R58_COMMAND_MUST_START_UNSEALED'; END IF;
 IF NEW.operation='trusted_setup.consume' THEN
  IF current_user<>'company_bootstrap_functions_r56' OR NOT EXISTS(SELECT 1 FROM company_private.bootstrap_request_contexts x JOIN company_private.installation_bootstrap_control b ON b.installation_id=x.installation_id AND b.generation=x.generation WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND b.expected_tenant_id=NEW.tenant_id AND b.expected_human_id=NEW.principal_id AND b.state='ARMED') THEN RAISE EXCEPTION 'R58_BOOTSTRAP_INSERT_CONTEXT'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM company_private.operation_permissions op WHERE op.operation_id=NEW.operation AND op.approved_policy_digest IS NOT NULL)
  OR NOT EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.writer_generation=54 AND x.tenant_id=NEW.tenant_id AND x.principal_id=NEW.principal_id AND x.operation_id=NEW.operation)
  OR NEW.operation NOT IN ('worker.claim','worker.heartbeat','workspace.current_head','process.launch_reserve','process.launch_consume','process.launch_callback','tool.authorize_final','patch.receipt','verification.final_seal','evidence.provenance','verification.accept','evidence.attestation_ingest','process.stop_release','tasks.ready','engine.bind','tool.consume','tool.effect','process.lease_prepare','process.lease_commit','process.lease_activate','process.reconcile','objectives.create','plans.create','tasks.create','e0.process_proof_persist','e0.evaluation_envelope_persist','e0.process_admit','e0.process_stop_confirm','e0.process_reconcile','e0.process_release') THEN RAISE EXCEPTION 'R58_LEGACY_OR_UNKNOWN_COMMAND_INSERT_BLOCKED'; END IF;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION company.r58_command_insert_guard() FROM PUBLIC;



-- SOURCE sql/052_R60_READY_NATIVE.sql
CREATE FUNCTION company_private.r60_ready_binding(p_task uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;t company.tasks%ROWTYPE;p company.plans%ROWTYPE;h text;deps jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 PERFORM 1 FROM company.projects WHERE tenant_id=x.tenant_id AND id=x.project_id FOR UPDATE;
 SELECT * INTO STRICT t FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_task;
 SELECT * INTO STRICT p FROM company.plans WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=t.plan_id FOR SHARE;
 SELECT head_digest INTO STRICT h FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id FOR SHARE;
 PERFORM 1 FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND (id=p_task OR id IN(SELECT depends_on_task_id FROM company.task_dependencies WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_task)) ORDER BY id FOR UPDATE;
 SELECT * INTO STRICT t FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_task;
 IF jsonb_array_length(t.acceptance_criteria)=0 OR jsonb_array_length(p.acceptance_criteria)=0
 OR NOT EXISTS(SELECT 1 FROM company.objectives WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p.objective_id)
 OR EXISTS(SELECT 1 FROM company.task_dependencies d LEFT JOIN company.tasks parent ON parent.tenant_id=d.tenant_id AND parent.project_id=d.project_id AND parent.id=d.depends_on_task_id WHERE d.tenant_id=x.tenant_id AND d.project_id=x.project_id AND d.task_id=p_task AND (parent.id IS NULL OR parent.state<>'ACCEPTED')) THEN RAISE EXCEPTION 'R60_READINESS_DEPENDENCIES'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',parent.id,'revision',parent.revision,'state',parent.state) ORDER BY parent.id),'[]'::jsonb) INTO deps FROM company.task_dependencies d JOIN company.tasks parent ON parent.tenant_id=d.tenant_id AND parent.project_id=d.project_id AND parent.id=d.depends_on_task_id WHERE d.tenant_id=x.tenant_id AND d.project_id=x.project_id AND d.task_id=p_task;
 RETURN jsonb_build_object('task_id',t.id,'task_revision',t.revision,'plan_id',p.id,'plan_revision',p.revision,'role_id',t.role_id,'task_criteria',t.acceptance_criteria,'plan_criteria',p.acceptance_criteria,'dependencies',deps,'head_digest',h);
END $$;
CREATE FUNCTION company_private.r60_finish_revision(p_command uuid,p_target uuid,p_revision bigint,p_result jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;c company.commands%ROWTYPE;receipt jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 x=company_private.r58_context(x.operation_id);
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=x.tenant_id AND id=p_command AND principal_id=x.principal_id AND operation=x.operation_id;
 INSERT INTO company_private.r58_execution_receipts VALUES(x.tenant_id,x.project_id,c.id,x.operation_id,p_target,p_result);
 receipt=company_private.r55_cp_finalize_command(c.id,p_target,p_revision,company_private.r55_cp_event_kind(x.operation_id),p_result);
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=x.tenant_id AND id=p_command AND r55_project_id=x.project_id AND state='SUCCEEDED';
 RETURN receipt||jsonb_build_object('result_payload',c.r55_result_payload);
END $$;
CREATE FUNCTION company_private.r60_tasks_ready(p_task uuid,p_plan_revision bigint,p_head text,q jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;t company.tasks%ROWTYPE;c company.commands%ROWTYPE;b jsonb;
BEGIN
 x=company_private.r58_context('tasks.ready');
 PERFORM company_private.r58_shape(q-'approval_ref',ARRAY['idempotency_key','correlation_id','expected_revision','action','reason']);
 IF x.task_id IS DISTINCT FROM p_task OR x.attempt_id IS NOT NULL OR q->>'action' IS DISTINCT FROM 'ready' OR length(q->>'reason') NOT BETWEEN 1 AND 2000 OR jsonb_typeof(q->'reason') IS DISTINCT FROM 'string'
 OR (q ? 'approval_ref' AND q->'approval_ref'<>'null'::jsonb) OR jsonb_typeof(q->'expected_revision') IS DISTINCT FROM 'number' OR (q->>'expected_revision') !~ '^[0-9]+$' THEN RAISE EXCEPTION 'R60_READY_TYPED_SCOPE'; END IF;
 c=company_private.r58_begin_command(q->>'idempotency_key',(q->>'correlation_id')::uuid,jsonb_build_object('task_id',p_task,'plan_revision',p_plan_revision,'head',p_head,'action',q-'idempotency_key'-'correlation_id'));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 b=company_private.r60_ready_binding(p_task);
 SELECT * INTO STRICT t FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_task;
 IF t.state IS DISTINCT FROM 'DRAFT' OR t.execution_kind IS DISTINCT FROM 'ORDINARY' OR t.active_attempt_id IS NOT NULL OR t.revision IS DISTINCT FROM (q->>'expected_revision')::bigint OR b->>'plan_revision' IS DISTINCT FROM p_plan_revision::text OR b->>'head_digest' IS DISTINCT FROM p_head THEN RAISE EXCEPTION 'R60_READY_CAS'; END IF;
 UPDATE company.tasks SET state='READY',revision=revision+1 WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_task AND state='DRAFT' AND revision=t.revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'R60_READY_UPDATE_CAS'; END IF;
 b=jsonb_set(b,'{task_revision}',to_jsonb(t.revision+1));
 INSERT INTO company_private.r60_ready_bindings VALUES(x.tenant_id,x.project_id,p_task,t.revision+1,p_plan_revision,p_head,b,encode(sha256(convert_to(b::text,'UTF8')),'hex'),c.id);
 RETURN company_private.r60_finish_revision(c.id,p_task,t.revision+1,jsonb_build_object('task_id',p_task,'state','READY','revision',t.revision+1,'binding_digest',encode(sha256(convert_to(b::text,'UTF8')),'hex')));
END $$;
CREATE FUNCTION company_private.r60_assert_ready(p_task uuid,p_revision bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;b jsonb;saved jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 b=company_private.r60_ready_binding(p_task);
 SELECT binding INTO STRICT saved FROM company_private.r60_ready_bindings WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_task AND task_revision=p_revision;
 IF saved IS DISTINCT FROM b THEN RAISE EXCEPTION 'R60_READINESS_CHANGED_REISSUE_REQUIRED'; END IF;
END $$;

-- SOURCE sql/053_R60_WORKER_CLAIM_OVERLAY.sql
CREATE OR REPLACE FUNCTION company_private.r58_worker_claim(p_task uuid,p_revision bigint,p_qualification uuid,p_binding text,p_policy_revision bigint,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;t company.tasks%ROWTYPE;q company.agent_qualifications%ROWTYPE;
 h company_private.r58_workspace_heads%ROWTYPE;lp company_private.r58_lease_policies%ROWTYPE;c company.commands%ROWTYPE;b jsonb;until_at timestamptz;aid uuid;n integer;
BEGIN
 x=company_private.r58_context('worker.claim');
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=x.principal_id AND kind IN ('WORKER','VERIFIER')) THEN RAISE EXCEPTION 'R58_TECHNICAL_WORKER_REQUIRED'; END IF;
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('task_id',p_task,'revision',p_revision,'qualification',p_qualification,'binding',p_binding,'lease_policy_revision',p_policy_revision));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT lp FROM company_private.r58_lease_policies WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND revision=p_policy_revision AND enabled FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=lp.approved_by AND kind='HUMAN') THEN RAISE EXCEPTION 'R58_HUMAN_LEASE_POLICY_REQUIRED'; END IF;
 PERFORM company_private.r60_assert_ready(p_task,p_revision);
 q=company_private.r58_qualification(p_qualification,x.principal_id,p_binding);
 SELECT * INTO STRICT h FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id FOR SHARE;
 SELECT * INTO STRICT t FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_task FOR UPDATE;
 IF x.task_id IS DISTINCT FROM p_task OR x.attempt_id IS NOT NULL OR t.execution_kind IS DISTINCT FROM 'ORDINARY' OR t.state IS DISTINCT FROM 'READY' OR t.revision IS DISTINCT FROM p_revision OR t.active_attempt_id IS NOT NULL OR t.role_id IS DISTINCT FROM q.role_id
 OR EXISTS(SELECT 1 FROM company.task_dependencies d JOIN company.tasks parent ON parent.tenant_id=d.tenant_id AND parent.project_id=d.project_id AND parent.id=d.depends_on_task_id WHERE d.tenant_id=t.tenant_id AND d.project_id=t.project_id AND d.task_id=t.id AND parent.state<>'ACCEPTED') THEN RAISE EXCEPTION 'R58_TASK_NOT_CLAIMABLE'; END IF;
 b=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 until_at=least((b->>'utc_lower_bound')::timestamptz+(lp.duration_ms::numeric*interval '1 millisecond'),q.valid_until,lp.valid_until);
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,until_at);
 SELECT coalesce(max(attempt_no),0)+1 INTO n FROM company.attempts WHERE tenant_id=t.tenant_id AND project_id=t.project_id AND task_id=t.id;
 aid=gen_random_uuid();
 INSERT INTO company.attempts(tenant_id,project_id,task_id,id,attempt_no,fencing_epoch,worker_id,state,lease_expires_at,admission_qualification_id,r58_binding_digest,r58_head_digest,r58_policy_revision,r58_verification_profile_digest)
 VALUES(t.tenant_id,t.project_id,t.id,aid,n,t.fencing_epoch+1,x.principal_id,'CLAIMED',until_at,q.id,p_binding,h.head_digest,lp.revision,lp.verification_profile_digest);
 UPDATE company.tasks SET state='RUNNING',revision=revision+1,fencing_epoch=fencing_epoch+1,active_attempt_id=aid WHERE tenant_id=t.tenant_id AND project_id=t.project_id AND id=t.id AND revision=p_revision AND state='READY';
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_TASK_CLAIM_CAS'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,until_at);
 RETURN company_private.r58_finish(c.id,aid,jsonb_build_object('attempt_id',aid,'task_id',t.id,'fencing_epoch',t.fencing_epoch+1,'lease_expires_at',until_at,'qualification_id',q.id,'head_digest',h.head_digest,'lease_policy_revision',lp.revision));
END $$;

-- SOURCE sql/054_R60_CONTEXT_ACTOR_OVERLAY.sql
CREATE FUNCTION company_private.r60_attempt_actor_allowed(p_tenant uuid,p_project uuid,p_task uuid,p_attempt uuid,p_actor uuid,p_operation text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM company.attempts a WHERE a.tenant_id=p_tenant AND a.project_id=p_project AND a.task_id=p_task AND a.id=p_attempt AND
 (a.worker_id=p_actor OR
 (p_operation IN ('process.launch_consume','process.launch_callback','process.launch_delivery','engine.bind','tool.effect','process.lease_prepare','process.lease_commit','process.lease_activate','process.lease_read','evidence.attestation_ingest','candidate.r58.artifacts.read')
 AND EXISTS(SELECT 1 FROM company.process_runs r JOIN company_private.r58_controller_heads ch ON ch.tenant_id=r.tenant_id AND ch.project_id=r.project_id AND ch.controller_id=r.controller_id AND ch.generation=r.controller_generation AND ch.host_boot_id=r.r55_host_boot_id AND ch.enabled WHERE r.tenant_id=a.tenant_id AND r.project_id=a.project_id AND r.task_id=a.task_id AND r.attempt_id=a.id AND r.attempt_fencing_epoch=a.fencing_epoch AND r.controller_id=p_actor)) OR
 (p_operation IN ('verification.final_seal','evidence.provenance','verification.accept','candidate.r58.artifacts.read','evidence.attestation_ingest') AND p_actor<>a.worker_id
 AND EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=p_tenant AND id=p_actor AND kind='VERIFIER')
 AND NOT EXISTS(SELECT 1 FROM company.process_runs WHERE tenant_id=a.tenant_id AND project_id=a.project_id AND task_id=a.task_id AND attempt_id=a.id AND controller_id=p_actor))))
$$;
CREATE OR REPLACE FUNCTION company_private.r54_context_enter(p_token text,p_operation text,p_project uuid,p_kind text,p_resource uuid,p_task uuid,p_attempt uuid,p_fence bigint,p_grant uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE s company.sessions%ROWTYPE; op company_private.operation_permissions%ROWTYPE;
 t company.tasks%ROWTYPE; a company.attempts%ROWTYPE; h record; ids uuid[]; nonce uuid; pk text; te bigint; pe bigint; se bigint;
BEGIN
 IF NOT pg_has_role(session_user,'company_transport_r54','MEMBER') THEN RAISE EXCEPTION 'TRANSPORT_REQUIRED'; END IF;
 IF p_token IS NULL OR octet_length(p_token)<32 OR octet_length(p_token)>4096 THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id()) THEN RAISE EXCEPTION 'CONTEXT_ALREADY_BOUND'; END IF;
 SELECT * INTO STRICT s FROM company.sessions WHERE token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex');
 -- Tek authority lock sırası: rank,lock_id. Revoke da aynı üç scope kilidini alır.
 FOR h IN SELECT l.lock_id,l.rank FROM company.authority_scope_heads ah JOIN company_private.scope_lock_registry l ON l.lock_id=ah.lock_id
 WHERE ah.tenant_id=s.tenant_id AND ((ah.scope_kind='TENANT' AND ah.scope_ref=s.tenant_id)
 OR (ah.scope_kind='PROJECT' AND ah.scope_ref=p_project) OR (ah.scope_kind='SESSION' AND ah.scope_ref=s.id)) ORDER BY l.rank,l.lock_id LOOP
  PERFORM pg_advisory_xact_lock(h.lock_id);
 END LOOP;
 SELECT * INTO STRICT s FROM company.sessions WHERE tenant_id=s.tenant_id AND id=s.id AND token_hash=s.token_hash;
 IF s.revoked_at IS NOT NULL OR s.expires_at<=((company_private.r55_cp_clock_current_bounds(s.tenant_id,p_project)->>'utc_upper_bound')::timestamptz) THEN RAISE EXCEPTION 'AUTH_REVOKED'; END IF;
 SELECT pr.kind INTO STRICT pk FROM company.principals pr JOIN company.memberships m ON m.tenant_id=pr.tenant_id AND m.principal_id=pr.id
 WHERE pr.tenant_id=s.tenant_id AND pr.id=s.principal_id;
 SELECT * INTO STRICT op FROM company_private.operation_permissions WHERE operation_id=p_operation;
 -- Yeni DIRECT/TASK/RESOURCE scope enum yaratılmaz. Bunlar PROJECT altındaki exact binding biçimleridir.
 IF op.scope_kind<>'PROJECT' THEN RAISE EXCEPTION 'SEPARATE_SCOPE_RESOLVER_REQUIRED'; END IF;
 IF op.approved_policy_digest IS NULL AND op.execution_class NOT IN ('QUERY','STREAM') THEN RAISE EXCEPTION 'POLICY_NOT_APPROVED'; END IF;
 IF p_project IS NULL OR p_kind IS NULL OR p_resource IS NULL OR p_kind NOT IN ('PROJECT','TASK','ATTEMPT') THEN RAISE EXCEPTION 'RESOURCE_RESOLVER_UNSUPPORTED'; END IF;
 IF p_kind='PROJECT' THEN
  IF p_resource IS DISTINCT FROM p_project OR p_task IS NOT NULL OR p_attempt IS NOT NULL OR p_fence IS NOT NULL THEN RAISE EXCEPTION 'PROJECT_BINDING_INVALID'; END IF;
  PERFORM 1 FROM company.projects WHERE tenant_id=s.tenant_id AND id=p_project;
  IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 ELSE
  SELECT * INTO STRICT t FROM company.tasks WHERE tenant_id=s.tenant_id AND project_id=p_project AND id=p_task;
  IF p_kind='TASK' AND (p_resource IS DISTINCT FROM p_task OR p_attempt IS NOT NULL OR p_fence IS NOT NULL) THEN RAISE EXCEPTION 'TASK_BINDING_INVALID'; END IF;
  IF p_kind='ATTEMPT' THEN
   IF p_task IS NULL OR p_attempt IS NULL OR p_fence IS NULL OR p_fence<=0 THEN RAISE EXCEPTION 'ATTEMPT_BINDING_INVALID'; END IF;
   SELECT * INTO STRICT a FROM company.attempts WHERE tenant_id=s.tenant_id AND project_id=p_project AND task_id=p_task AND id=p_attempt;
   IF p_resource IS DISTINCT FROM p_attempt OR t.active_attempt_id IS DISTINCT FROM a.id OR t.fencing_epoch<>p_fence
      OR a.fencing_epoch<>p_fence OR company_private.r60_attempt_actor_allowed(s.tenant_id,p_project,p_task,p_attempt,s.principal_id,p_operation) IS NOT TRUE OR a.lease_expires_at<=((company_private.r55_cp_clock_current_bounds(s.tenant_id,p_project)->>'utc_upper_bound')::timestamptz)
      OR (a.state NOT IN ('CLAIMED','RUNNING') AND NOT (a.state='PRODUCED' AND p_operation IN ('verification.final_seal','evidence.provenance','verification.accept','candidate.r58.artifacts.read','evidence.attestation_ingest'))) OR a.ended_at IS NOT NULL THEN RAISE EXCEPTION 'STALE_ATTEMPT'; END IF;
  END IF;
 END IF;
 ids=company_private.r54_grant_chain(s.tenant_id,p_project,s.principal_id,op.permission,p_task,p_grant);
 SELECT epoch INTO STRICT te FROM company.authority_scope_heads WHERE tenant_id=s.tenant_id AND scope_kind='TENANT' AND scope_ref=s.tenant_id;
 SELECT epoch INTO STRICT pe FROM company.authority_scope_heads WHERE tenant_id=s.tenant_id AND scope_kind='PROJECT' AND scope_ref=p_project;
 SELECT epoch INTO STRICT se FROM company.authority_scope_heads WHERE tenant_id=s.tenant_id AND scope_kind='SESSION' AND scope_ref=s.id;
 PERFORM company_private.r54_require_clock_health(s.tenant_id,p_project);
 nonce=gen_random_uuid();
 INSERT INTO company_private.request_contexts(backend_pid,transaction_id,request_nonce,db_login,tenant_id,project_id,principal_id,session_id,operation_id,tenant_epoch,project_epoch,session_epoch,writer_generation,authenticated_at,expires_at,grant_id,grant_chain_ids,principal_kind,resource_kind,resource_id,task_id,attempt_id,fencing_epoch,policy_revision)
 VALUES(pg_backend_pid(),pg_current_xact_id(),nonce,session_user,s.tenant_id,p_project,s.principal_id,s.id,p_operation,te,pe,se,54,clock_timestamp(),s.expires_at,p_grant,ids,pk,p_kind,p_resource,p_task,p_attempt,p_fence,op.policy_revision);
 RETURN nonce;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'AUTH_OR_RESOURCE_UNRESOLVED';
END $$;

-- SOURCE sql/055_R60_PROOF_OVERLAY.sql
CREATE OR REPLACE FUNCTION company_private.r60_store_effect_proof(p_id uuid,p_issuer uuid,p_key_id uuid,p_revision bigint,p_profile text,p_raw bytea,p_tag bytea) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;e company.signer_enrollments%ROWTYPE;k company_private.r58_key_material%ROWTYPE;c company.commands%ROWTYPE;j jsonb;msg bytea;part bytea;d text;
BEGIN
 x=company_private.r58_context('tool.effect');
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=x.principal_id AND kind IN ('WORKER','VERIFIER')) THEN RAISE EXCEPTION 'R58_TECHNICAL_SIGNER_REQUIRED'; END IF;
 IF p_id IS NULL OR p_issuer IS DISTINCT FROM x.principal_id OR p_key_id IS NULL OR p_revision IS NULL OR p_revision<0 OR p_raw IS NULL OR octet_length(p_raw) NOT BETWEEN 1 AND 65536 OR p_tag IS NULL OR octet_length(p_tag)<>32
 OR p_profile IS DISTINCT FROM 'r60.tool-effect.v1' THEN RAISE EXCEPTION 'R58_ATTESTATION_WIRE'; END IF;
 SELECT * INTO STRICT e FROM company.signer_enrollments WHERE tenant_id=x.tenant_id AND issuer_id=p_issuer AND key_id=p_key_id AND enrollment_revision=p_revision AND purpose='TASK_VERIFICATION' FOR SHARE;
 SELECT * INTO STRICT k FROM company_private.r58_key_material WHERE key_id=p_key_id AND purpose='EXECUTION_ATTESTATION' AND NOT revoked FOR SHARE;
 IF e.profile_id IS DISTINCT FROM p_profile OR e.revoked_at IS NOT NULL OR e.compromised_since IS NOT NULL OR e.key_fingerprint IS DISTINCT FROM k.fingerprint
 OR NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=e.approved_by AND kind='HUMAN') OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,e.valid_from,e.valid_until) IS NOT TRUE THEN RAISE EXCEPTION 'R58_SIGNER_ENROLLMENT'; END IF;
 PERFORM company_private.r58_unique_json(convert_from(p_raw,'UTF8')::json);
 j=convert_from(p_raw,'UTF8')::jsonb;
 PERFORM company_private.r58_shape(j,ARRAY['tenant_id','project_id','receipt_id','profile','binding']);
 IF j->>'tenant_id' IS DISTINCT FROM x.tenant_id::text OR j->>'project_id' IS DISTINCT FROM x.project_id::text OR j->>'receipt_id' IS DISTINCT FROM p_id::text OR j->>'profile' IS DISTINCT FROM p_profile OR jsonb_typeof(j->'binding') IS DISTINCT FROM 'object'
 OR EXISTS(SELECT key FROM json_each(convert_from(p_raw,'UTF8')::json) GROUP BY key HAVING count(*)>1) THEN RAISE EXCEPTION 'R58_ATTESTATION_SCOPE'; END IF;
 msg=convert_to('R58-EXECUTION-ATTESTATION-v1','UTF8')||decode('00','hex');
 FOREACH part IN ARRAY ARRAY[convert_to(p_issuer::text,'UTF8'),convert_to(p_key_id::text,'UTF8'),convert_to(p_revision::text,'UTF8'),convert_to(p_profile,'UTF8'),p_raw] LOOP msg=msg||convert_to(octet_length(part)::text||':','UTF8')||part; END LOOP;
 IF company_private.r55_cp_tag_equal(company_private.r55_cp_hmac_sha256(k.secret,msg),p_tag) IS NOT TRUE THEN RAISE EXCEPTION 'R58_INVALID_ATTESTATION_HMAC'; END IF;
 d=encode(sha256(p_raw),'hex');
 INSERT INTO company_private.r58_attestations(tenant_id,project_id,id,issuer_id,key_id,enrollment_revision,profile,raw_digest,raw_bytes,auth_tag,payload) VALUES(x.tenant_id,x.project_id,p_id,p_issuer,p_key_id,p_revision,p_profile,d,p_raw,encode(p_tag,'hex'),j->'binding');
 PERFORM company_private.r58_store_signed_artifact(p_id);
 RETURN jsonb_build_object('receipt_id',p_id,'raw_digest',d,'profile',p_profile);
END $$;
CREATE OR REPLACE FUNCTION company_private.r58_store_signed_artifact(p_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;m company_private.r58_attestations%ROWTYPE;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54 AND operation_id IN ('evidence.attestation_ingest','tool.effect');
 SELECT * INTO STRICT m FROM company_private.r58_attestations WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_id AND issuer_id=x.principal_id;
 IF x.task_id IS NOT NULL AND x.attempt_id IS NOT NULL THEN
  -- These are real DB-resident signed-statement bytes, not an invented file.
  INSERT INTO company.artifacts(tenant_id,project_id,task_id,attempt_id,id,storage_key,sha256,size_bytes,state)
  VALUES(x.tenant_id,x.project_id,x.task_id,x.attempt_id,m.id,gen_random_uuid(),m.raw_digest,octet_length(m.raw_bytes),'AVAILABLE');
  INSERT INTO company.verifier_receipts(tenant_id,project_id,task_id,attempt_id,id,purpose,signer_id,key_id,receipt_digest,signature) VALUES(x.tenant_id,x.project_id,x.task_id,x.attempt_id,m.id,'TASK_VERIFICATION',m.issuer_id,m.key_id,m.raw_digest,m.auth_tag);
 END IF;
END $$;
CREATE OR REPLACE FUNCTION company_private.r58_attestation_ingest(p_id uuid,p_issuer uuid,p_key_id uuid,p_revision bigint,p_profile text,p_raw bytea,p_tag bytea,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;e company.signer_enrollments%ROWTYPE;k company_private.r58_key_material%ROWTYPE;c company.commands%ROWTYPE;j jsonb;msg bytea;part bytea;d text;
BEGIN
 x=company_private.r58_context('evidence.attestation_ingest');
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=x.principal_id AND kind IN ('WORKER','VERIFIER')) THEN RAISE EXCEPTION 'R58_TECHNICAL_SIGNER_REQUIRED'; END IF;
 IF p_id IS NULL OR p_issuer IS DISTINCT FROM x.principal_id OR p_key_id IS NULL OR p_revision IS NULL OR p_revision<0 OR p_raw IS NULL OR octet_length(p_raw) NOT BETWEEN 1 AND 65536 OR p_tag IS NULL OR octet_length(p_tag)<>32
 OR p_profile NOT IN ('r58.workspace.v1','r58.launch-manifest.v1','r58.launch-callback.v1','r58.patch.v1','r58.verification.v1','r58.evidence.v1','r58.quiescence.v1','r60.engine-binding.v1','r60.lease-prepared.v1','r60.lease-active.v1','r60.process-observation.v1','r60.patch-proposal.v1') THEN RAISE EXCEPTION 'R58_ATTESTATION_WIRE'; END IF;
 SELECT * INTO STRICT e FROM company.signer_enrollments WHERE tenant_id=x.tenant_id AND issuer_id=p_issuer AND key_id=p_key_id AND enrollment_revision=p_revision AND purpose='TASK_VERIFICATION' FOR SHARE;
 SELECT * INTO STRICT k FROM company_private.r58_key_material WHERE key_id=p_key_id AND purpose='EXECUTION_ATTESTATION' AND NOT revoked FOR SHARE;
 IF e.profile_id IS DISTINCT FROM p_profile OR e.revoked_at IS NOT NULL OR e.compromised_since IS NOT NULL OR e.key_fingerprint IS DISTINCT FROM k.fingerprint
 OR NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=e.approved_by AND kind='HUMAN') OR company_private.r55_cp_time_window_current(x.tenant_id,x.project_id,e.valid_from,e.valid_until) IS NOT TRUE THEN RAISE EXCEPTION 'R58_SIGNER_ENROLLMENT'; END IF;
 PERFORM company_private.r58_unique_json(convert_from(p_raw,'UTF8')::json);
 j=convert_from(p_raw,'UTF8')::jsonb;
 PERFORM company_private.r58_shape(j,ARRAY['tenant_id','project_id','receipt_id','profile','binding']);
 IF j->>'tenant_id' IS DISTINCT FROM x.tenant_id::text OR j->>'project_id' IS DISTINCT FROM x.project_id::text OR j->>'receipt_id' IS DISTINCT FROM p_id::text OR j->>'profile' IS DISTINCT FROM p_profile OR jsonb_typeof(j->'binding') IS DISTINCT FROM 'object'
 OR EXISTS(SELECT key FROM json_each(convert_from(p_raw,'UTF8')::json) GROUP BY key HAVING count(*)>1) THEN RAISE EXCEPTION 'R58_ATTESTATION_SCOPE'; END IF;
 msg=convert_to('R58-EXECUTION-ATTESTATION-v1','UTF8')||decode('00','hex');
 FOREACH part IN ARRAY ARRAY[convert_to(p_issuer::text,'UTF8'),convert_to(p_key_id::text,'UTF8'),convert_to(p_revision::text,'UTF8'),convert_to(p_profile,'UTF8'),p_raw] LOOP msg=msg||convert_to(octet_length(part)::text||':','UTF8')||part; END LOOP;
 IF company_private.r55_cp_tag_equal(company_private.r55_cp_hmac_sha256(k.secret,msg),p_tag) IS NOT TRUE THEN RAISE EXCEPTION 'R58_INVALID_ATTESTATION_HMAC'; END IF;
 d=encode(sha256(p_raw),'hex');
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('receipt_id',p_id,'issuer',p_issuer,'key',p_key_id,'revision',p_revision,'profile',p_profile,'raw_digest',d));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 INSERT INTO company_private.r58_attestations(tenant_id,project_id,id,issuer_id,key_id,enrollment_revision,profile,raw_digest,raw_bytes,auth_tag,payload) VALUES(x.tenant_id,x.project_id,p_id,p_issuer,p_key_id,p_revision,p_profile,d,p_raw,encode(p_tag,'hex'),j->'binding');
 PERFORM company_private.r58_store_signed_artifact(p_id);
 RETURN company_private.r58_finish(c.id,p_id,jsonb_build_object('receipt_id',p_id,'raw_digest',d,'profile',p_profile));
END $$;

-- SOURCE sql/056_R60_DELIVERY_NATIVE.sql
CREATE FUNCTION company_private.r60_delivery_guard(p_capability uuid,p_command uuid,p_snapshot jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;c company.commands%ROWTYPE;cap company_private.r58_launch_capabilities%ROWTYPE;r company.process_runs%ROWTYPE;current_snapshot jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54 AND operation_id='process.launch_delivery';
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'process.launch_delivery',x.task_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'R60_DELIVERY_DENIED'; END IF;
 PERFORM 1 FROM company.projects WHERE tenant_id=x.tenant_id AND id=x.project_id FOR UPDATE;
 SELECT * INTO STRICT c FROM company.commands WHERE tenant_id=x.tenant_id AND id=p_command AND principal_id=x.principal_id AND operation='process.launch_consume' AND r55_project_id=x.project_id AND state='SUCCEEDED' FOR SHARE;
 SELECT * INTO STRICT cap FROM company_private.r58_launch_capabilities WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_capability AND consume_command_id=c.id AND state='CONSUMED' FOR SHARE;
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=cap.process_id FOR SHARE;
 PERFORM company_private.r58_attempt(r.task_id,r.attempt_id,r.attempt_fencing_epoch);
 PERFORM company_private.r58_process_current(r.id);
 current_snapshot=company_private.r58_emission_snapshot();
 IF r.controller_id IS DISTINCT FROM x.principal_id OR r.state IS DISTINCT FROM 'STARTING' OR x.task_id IS DISTINCT FROM r.task_id OR x.attempt_id IS DISTINCT FROM r.attempt_id
 OR (current_snapshot-'operation') IS DISTINCT FROM (p_snapshot-'operation') OR p_snapshot->>'operation' IS DISTINCT FROM 'process.launch_consume'
 OR c.r55_result_payload->>'capability_id' IS DISTINCT FROM cap.id::text OR c.r55_result_payload->>'tuple_digest' IS DISTINCT FROM cap.tuple_digest OR c.r55_result_payload->>'spawn_permitted' IS DISTINCT FROM 'true'
 OR c.r55_result_payload->>'tuple_raw' IS DISTINCT FROM cap.tuple::text
 OR NOT EXISTS(SELECT 1 FROM company.audit_events WHERE tenant_id=x.tenant_id AND id=c.r55_audit_id AND actor_id=c.principal_id AND correlation_id=c.correlation_id AND kind='LaunchConsumed')
 OR NOT EXISTS(SELECT 1 FROM company.outbox WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND event_instance_id=c.id AND project_sequence=c.r55_event_sequence AND kind='LaunchConsumed' AND payload->>'result_digest'=c.r55_result_digest)
 OR NOT EXISTS(SELECT 1 FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND head_digest=cap.tuple->>'head_digest')
 THEN RAISE EXCEPTION 'R60_COMMITTED_CAPABILITY_NOT_CURRENT'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,r.lease_expires_at);
 RETURN jsonb_build_object('command_receipt',jsonb_build_object('command_id',c.id,'correlation_id',c.correlation_id,'state',c.state,'result_ref',c.result_ref),'result',c.r55_result_payload,'snapshot',p_snapshot);
 -- Caller holds this transaction and original scope revoke locks across spawn.
END $$;

-- SOURCE sql/057_R60_TOOL_NATIVE.sql
CREATE FUNCTION company_private.r60_engine_bind(p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;m company_private.r58_attestations%ROWTYPE;r company.process_runs%ROWTYPE;a company.attempts%ROWTYPE;c company.commands%ROWTYPE;j jsonb;
BEGIN
 x=company_private.r58_context('engine.bind');m=company_private.r58_attestation(p_attestation,'r60.engine-binding.v1');j=m.payload;
 PERFORM company_private.r58_shape(j,ARRAY['engine_session_id','process_id','task_revision','tool_manifest_digest']);
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('attestation_id',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 r=company_private.r58_process_current((j->>'process_id')::uuid);a=company_private.r58_attempt(r.task_id,r.attempt_id,r.attempt_fencing_epoch);
 IF r.state IS DISTINCT FROM 'RUNNING' OR m.issuer_id IS DISTINCT FROM r.controller_id OR x.principal_id IS DISTINCT FROM r.controller_id OR j->>'tool_manifest_digest' !~ '^[a-f0-9]{64}$'
 OR NOT EXISTS(SELECT 1 FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=r.task_id AND revision::text=j->>'task_revision')
 OR NOT EXISTS(SELECT 1 FROM company_private.r60_tool_manifests tm JOIN company.principals p ON p.tenant_id=tm.tenant_id AND p.id=tm.approved_by AND p.kind='HUMAN' WHERE tm.tenant_id=x.tenant_id AND tm.project_id=x.project_id AND tm.manifest_digest=j->>'tool_manifest_digest' AND tm.enabled) THEN RAISE EXCEPTION 'R60_ENGINE_BINDING_CURRENT'; END IF;
 INSERT INTO company_private.r60_engine_streams VALUES(x.tenant_id,x.project_id,(j->>'engine_session_id')::uuid,r.task_id,r.attempt_id,r.attempt_fencing_epoch,r.id,j->>'tool_manifest_digest',(j->>'task_revision')::bigint,1);
 RETURN company_private.r58_finish(c.id,r.id,jsonb_build_object('engine_session_id',j->>'engine_session_id','next_sequence',1));
END $$;
CREATE FUNCTION company_private.r60_tool_consume(p_kernel_request uuid,p_frame bytea,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;s company_private.r60_engine_streams%ROWTYPE;tr company.tool_requests%ROWTYPE;r company.process_runs%ROWTYPE;a company.attempts%ROWTYPE;c company.commands%ROWTYPE;j jsonb;raw text;fd text;id uuid;auth jsonb;
BEGIN
 x=company_private.r58_context('tool.consume');
 IF p_frame IS NULL OR octet_length(p_frame) NOT BETWEEN 1 AND 65536 THEN RAISE EXCEPTION 'R60_FRAME_SIZE'; END IF;
 raw=convert_from(p_frame,'UTF8');
 IF right(raw,1)<>chr(10) OR position(chr(10) in left(raw,length(raw)-1))>0 THEN RAISE EXCEPTION 'R60_SINGLE_FRAME'; END IF;
 PERFORM company_private.r58_unique_json(raw::json);j=raw::jsonb;
 PERFORM company_private.r58_shape(j,ARRAY['protocol','request_id','engine_session_id','attempt_id','fencing_epoch','expected_revision','sequence','tool_manifest_digest','call']);
 IF jsonb_typeof(j->'fencing_epoch') IS DISTINCT FROM 'number' OR jsonb_typeof(j->'expected_revision') IS DISTINCT FROM 'number' OR jsonb_typeof(j->'sequence') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'R60_TYPED_FRAME_INTEGERS'; END IF;
 fd=encode(sha256(p_frame),'hex');
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('kernel_request',p_kernel_request,'frame_digest',fd));
 IF c.state='SUCCEEDED' THEN RETURN jsonb_build_object('effect_permitted',false,'outcome','REPLAY_RECONCILE_ONLY'); END IF;
 SELECT * INTO STRICT s FROM company_private.r60_engine_streams WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND engine_session_id=(j->>'engine_session_id')::uuid FOR UPDATE;
 a=company_private.r58_attempt(s.task_id,s.attempt_id,s.fence);r=company_private.r58_process_current(s.process_id);
 SELECT * INTO STRICT tr FROM company.tool_requests WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=s.task_id AND attempt_id=s.attempt_id AND request_id=p_kernel_request FOR UPDATE;
 SELECT payload INTO STRICT auth FROM company_private.r58_execution_receipts WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND operation='tool.authorize_final' AND target_id=tr.request_id;
 IF j->>'protocol' IS DISTINCT FROM 'company-tool/1' OR j->>'attempt_id' IS DISTINCT FROM s.attempt_id::text OR j->>'fencing_epoch' IS DISTINCT FROM s.fence::text OR j->>'expected_revision' IS DISTINCT FROM s.task_revision::text OR j->>'sequence' IS DISTINCT FROM s.next_sequence::text OR j->>'tool_manifest_digest' IS DISTINCT FROM s.manifest_digest
 OR a.worker_id IS DISTINCT FROM x.principal_id OR r.state IS DISTINCT FROM 'RUNNING' OR tr.payload_digest IS DISTINCT FROM fd OR tr.request_fencing_epoch IS DISTINCT FROM s.fence OR tr.receipt_id IS NOT NULL
 OR auth->>'tool' IS DISTINCT FROM j->'call'->>'tool_id' OR auth->>'process_id' IS DISTINCT FROM r.id::text
 OR NOT EXISTS(SELECT 1 FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND head_digest=auth->>'head_digest')
 OR EXISTS(SELECT 1 FROM company_private.r60_tool_consumptions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND engine_session_id=s.engine_session_id AND state IN ('CONSUMED','UNKNOWN'))
 OR NOT EXISTS(SELECT 1 FROM company_private.r60_tool_manifests WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND manifest_digest=s.manifest_digest AND enabled)
 OR EXISTS(SELECT 1 FROM company_private.r60_lease_extensions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND process_id=r.id AND state IN ('PREPARED','COMMITTED')) THEN RAISE EXCEPTION 'R60_TOOL_BINDING_OR_PENDING'; END IF;
 IF j->'call'->>'tool_id'='workspace.read' THEN
  PERFORM company_private.r58_shape(j->'call',ARRAY['tool_id','arguments']);PERFORM company_private.r58_shape(j->'call'->'arguments',ARRAY['relative_path','max_bytes']);
  IF j->'call'->'arguments'->>'relative_path' IS DISTINCT FROM 'task_title.py' OR jsonb_typeof(j->'call'->'arguments'->'max_bytes') IS DISTINCT FROM 'number' OR (j->'call'->'arguments'->>'max_bytes') !~ '^[0-9]+$' OR (j->'call'->'arguments'->>'max_bytes')::bigint NOT BETWEEN 1 AND 16384 THEN RAISE EXCEPTION 'R60_PILOT_READ_SCOPE'; END IF;
 ELSIF j->'call'->>'tool_id'='patch.apply' THEN
  PERFORM company_private.r58_shape(j->'call',ARRAY['tool_id','patch_artifact_id','expected_source_digest']);
  PERFORM (j->'call'->>'patch_artifact_id')::uuid;
  IF j->'call'->>'expected_source_digest' IS DISTINCT FROM auth->>'head_digest' THEN RAISE EXCEPTION 'R60_PATCH_SOURCE_CAS'; END IF;
 ELSE RAISE EXCEPTION 'R60_INDEPENDENT_VERIFIER_OR_UNKNOWN_TOOL'; END IF;
 id=gen_random_uuid();
 INSERT INTO company_private.r60_tool_consumptions VALUES(x.tenant_id,x.project_id,id,s.engine_session_id,(j->>'request_id')::uuid,tr.request_id,s.next_sequence,r.id,fd,p_frame,'CONSUMED',NULL,c.id);
 RETURN company_private.r58_finish(c.id,id,jsonb_build_object('consume_id',id,'effect_permitted',true,'frame_digest',fd));
END $$;
CREATE FUNCTION company_private.r60_effect_guard(p_consume uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;u company_private.r60_tool_consumptions%ROWTYPE;s company_private.r60_engine_streams%ROWTYPE;r company.process_runs%ROWTYPE;auth jsonb;
BEGIN
 x=company_private.r58_context('tool.effect');
 PERFORM 1 FROM company.projects WHERE tenant_id=x.tenant_id AND id=x.project_id FOR UPDATE;
 SELECT * INTO STRICT u FROM company_private.r60_tool_consumptions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_consume FOR UPDATE;
 SELECT * INTO STRICT s FROM company_private.r60_engine_streams WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND engine_session_id=u.engine_session_id FOR UPDATE;
 r=company_private.r58_process_current(u.process_id);PERFORM company_private.r58_attempt(s.task_id,s.attempt_id,s.fence);
 SELECT payload INTO STRICT auth FROM company_private.r58_execution_receipts WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND operation='tool.authorize_final' AND target_id=u.kernel_request_id;
 IF u.state IS DISTINCT FROM 'CONSUMED' OR x.principal_id IS DISTINCT FROM r.controller_id OR r.state IS DISTINCT FROM 'RUNNING' OR x.task_id IS DISTINCT FROM s.task_id OR x.attempt_id IS DISTINCT FROM s.attempt_id OR s.next_sequence IS DISTINCT FROM u.sequence
 OR NOT EXISTS(SELECT 1 FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND head_digest=auth->>'head_digest')
 OR EXISTS(SELECT 1 FROM company_private.r60_lease_extensions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND process_id=r.id AND state IN ('PREPARED','COMMITTED')) THEN RAISE EXCEPTION 'R60_EFFECT_NOT_CURRENT'; END IF;
 RETURN jsonb_build_object('consume_id',u.id,'frame_digest',u.frame_digest,'frame_base64',encode(u.frame_bytes,'base64'),'process_id',r.id,'base_head',auth->>'head_digest');
END $$;
CREATE FUNCTION company_private.r60_effect_complete(p_consume uuid,p_proof uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;u company_private.r60_tool_consumptions%ROWTYPE;m company_private.r58_attestations%ROWTYPE;c company.commands%ROWTYPE;g jsonb;j jsonb;
BEGIN
 x=company_private.r58_context('tool.effect');g=company_private.r60_effect_guard(p_consume);
 m=company_private.r58_attestation(p_proof,'r60.tool-effect.v1');j=m.payload;
 PERFORM company_private.r58_shape(j,ARRAY['consume_id','frame_digest','process_id','base_head','result_head','effect_digest','outcome','effect']);
 IF m.issuer_id IS DISTINCT FROM x.principal_id OR j->>'consume_id' IS DISTINCT FROM p_consume::text OR j->>'frame_digest' IS DISTINCT FROM g->>'frame_digest' OR j->>'process_id' IS DISTINCT FROM g->>'process_id' OR j->>'base_head' IS DISTINCT FROM g->>'base_head' OR j->>'result_head' !~ '^[a-f0-9]{64}$' OR j->>'effect_digest' !~ '^[a-f0-9]{64}$' OR j->>'outcome' IS DISTINCT FROM 'SUCCEEDED' THEN RAISE EXCEPTION 'R60_EFFECT_PROOF_BINDING'; END IF;
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('consume_id',p_consume,'proof_id',p_proof));
 SELECT * INTO STRICT u FROM company_private.r60_tool_consumptions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_consume;
 UPDATE company_private.r60_tool_consumptions SET state='SUCCEEDED',effect_attestation_id=m.id WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_consume AND state='CONSUMED';
 IF NOT FOUND THEN RAISE EXCEPTION 'R60_EFFECT_CAS'; END IF;
 UPDATE company_private.r60_engine_streams SET next_sequence=next_sequence+1 WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND engine_session_id=u.engine_session_id AND next_sequence=u.sequence;
 IF NOT FOUND THEN RAISE EXCEPTION 'R60_SEQUENCE_CAS'; END IF;
 RETURN company_private.r58_finish(c.id,m.id,jsonb_build_object('consume_id',u.id,'frame_digest',u.frame_digest,'receipt_id',m.id,'status','SUCCEEDED','artifact_ids',jsonb_build_array(m.id)));
END $$;
CREATE FUNCTION company_private.r60_effect_finish(p_consume uuid,p_proof uuid,p_key_id uuid,p_key_revision bigint,p_raw bytea,p_tag bytea,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;
BEGIN
 x=company_private.r58_context('tool.effect');
 PERFORM company_private.r60_effect_guard(p_consume);
 PERFORM company_private.r60_store_effect_proof(p_proof,x.principal_id,p_key_id,p_key_revision,'r60.tool-effect.v1',p_raw,p_tag);
 RETURN company_private.r60_effect_complete(p_consume,p_proof,p_key,p_correlation);
END $$;

-- SOURCE sql/058_R60_PATCH_EFFECT_OVERLAY.sql
CREATE OR REPLACE FUNCTION company_private.r58_patch_receipt(p_task uuid,p_attempt uuid,p_fence bigint,p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;a company.attempts%ROWTYPE;m company_private.r58_attestations%ROWTYPE;h company_private.r58_workspace_heads%ROWTYPE;tr company.tool_requests%ROWTYPE;cap company_private.r58_launch_capabilities%ROWTYPE;c company.commands%ROWTYPE;j jsonb;rid uuid;
BEGIN
 x=company_private.r58_context('patch.receipt');m=company_private.r58_attestation(p_attestation,'r58.patch.v1');j=m.payload;
 PERFORM company_private.r58_shape(j,ARRAY['task_id','attempt_id','fencing_epoch','base_head','result_head','patch_digest','tool_request_id','process_id','request_digest','receipt_artifact_id']);
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('task_id',p_task,'attempt_id',p_attempt,'fence',p_fence,'attestation',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 a=company_private.r58_attempt(p_task,p_attempt,p_fence);
 IF NOT EXISTS(SELECT 1 FROM company_private.r60_tool_consumptions u JOIN company_private.r58_attestations m ON m.tenant_id=u.tenant_id AND m.project_id=u.project_id AND m.id=u.effect_attestation_id WHERE u.tenant_id=x.tenant_id AND u.project_id=x.project_id AND u.kernel_request_id=(j->>'tool_request_id')::uuid AND u.process_id=(j->>'process_id')::uuid AND u.frame_digest=j->>'request_digest' AND u.state='SUCCEEDED' AND m.profile='r60.tool-effect.v1' AND m.payload->>'base_head'=j->>'base_head' AND m.payload->>'result_head'=j->>'result_head' AND m.payload->>'effect_digest'=j->>'patch_digest') THEN RAISE EXCEPTION 'R60_COMPLETED_PATCH_EFFECT_REQUIRED'; END IF;
 SELECT * INTO STRICT h FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id FOR UPDATE;
 SELECT * INTO STRICT tr FROM company.tool_requests WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_task AND attempt_id=p_attempt AND request_id=(j->>'tool_request_id')::uuid FOR UPDATE;
 SELECT * INTO STRICT cap FROM company_private.r58_launch_capabilities WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND process_id=(j->>'process_id')::uuid AND state='RUNNING';
 PERFORM company_private.r58_process_current(cap.process_id);
 IF j->>'task_id' IS DISTINCT FROM p_task::text OR j->>'attempt_id' IS DISTINCT FROM p_attempt::text OR j->>'fencing_epoch' IS DISTINCT FROM p_fence::text
 OR j->>'base_head' IS DISTINCT FROM h.head_digest OR j->>'base_head' IS DISTINCT FROM cap.tuple->>'head_digest' OR j->>'result_head' !~ '^[a-f0-9]{64}$' OR j->>'patch_digest' !~ '^[a-f0-9]{64}$'
 OR tr.receipt_id IS NOT NULL OR tr.payload_digest IS DISTINCT FROM j->>'request_digest' OR tr.request_fencing_epoch IS DISTINCT FROM p_fence
 OR j->>'receipt_artifact_id' IS DISTINCT FROM m.id::text OR NOT EXISTS(SELECT 1 FROM company.artifacts ar WHERE ar.tenant_id=x.tenant_id AND ar.project_id=x.project_id AND ar.task_id=p_task AND ar.attempt_id=p_attempt AND ar.id=m.id AND ar.state='AVAILABLE' AND ar.sha256=m.raw_digest)
 OR m.issuer_id::text IS DISTINCT FROM cap.tuple->>'controller_id' OR m.issuer_id=a.worker_id
 OR NOT EXISTS(SELECT 1 FROM company_private.r58_execution_receipts rr WHERE rr.tenant_id=x.tenant_id AND rr.project_id=x.project_id AND rr.operation='tool.authorize_final' AND rr.target_id=tr.request_id AND rr.payload->>'tool'='patch.apply' AND rr.payload->>'head_digest'=h.head_digest AND rr.payload->>'process_id'=j->>'process_id') THEN RAISE EXCEPTION 'R58_PATCH_PROVENANCE'; END IF;
 rid=m.id;
 INSERT INTO company_private.r58_patch_receipts VALUES(x.tenant_id,x.project_id,p_task,p_attempt,rid,p_fence,h.head_digest,j->>'result_head',j->>'patch_digest',tr.request_id,m.id,c.id);
 UPDATE company_private.r58_workspace_heads SET revision=revision+1,head_digest=j->>'result_head',attestation_id=m.id WHERE tenant_id=h.tenant_id AND project_id=h.project_id AND revision=h.revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_PATCH_HEAD_CAS'; END IF;
 UPDATE company.tool_requests SET receipt_id=rid WHERE tenant_id=tr.tenant_id AND attempt_id=tr.attempt_id AND request_id=tr.request_id AND receipt_id IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_PATCH_TOOL_RECEIPT_CAS'; END IF;
 UPDATE company.attempts SET state='PRODUCED' WHERE tenant_id=a.tenant_id AND project_id=a.project_id AND task_id=a.task_id AND id=a.id;
 UPDATE company.tasks SET state='VERIFYING',revision=revision+1 WHERE tenant_id=a.tenant_id AND project_id=a.project_id AND id=a.task_id AND active_attempt_id=a.id AND fencing_epoch=p_fence AND state='RUNNING';
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_PATCH_TASK_CAS'; END IF;
 RETURN company_private.r58_finish(c.id,rid,jsonb_build_object('patch_id',rid,'result_head',j->>'result_head','patch_digest',j->>'patch_digest','attestation',m.id));
END $$;

-- SOURCE sql/059_R60_LEASE_RECOVERY_NATIVE.sql
CREATE FUNCTION company_private.r60_lease_prepare(p_process uuid,p_revision bigint,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;r company.process_runs%ROWTYPE;a company.attempts%ROWTYPE;q company.agent_qualifications%ROWTYPE;lp company_private.r58_lease_policies%ROWTYPE;cap company_private.r58_launch_capabilities%ROWTYPE;cb company_private.r58_attestations%ROWTYPE;c company.commands%ROWTYPE;b jsonb;oldns bigint;newns bigint;until_at timestamptz;identity jsonb;proposal jsonb;id uuid;
BEGIN
 x=company_private.r58_context('process.lease_prepare');
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('process_id',p_process,'revision',p_revision));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process FOR UPDATE;
 PERFORM company_private.r58_process_current(r.id);a=company_private.r58_attempt(r.task_id,r.attempt_id,r.attempt_fencing_epoch);
 IF r.state IS DISTINCT FROM 'RUNNING' OR r.revision IS DISTINCT FROM p_revision OR x.principal_id IS DISTINCT FROM r.controller_id OR x.task_id IS DISTINCT FROM r.task_id OR x.attempt_id IS DISTINCT FROM r.attempt_id
 OR EXISTS(SELECT 1 FROM company_private.r60_tool_consumptions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND process_id=r.id AND state IN ('CONSUMED','UNKNOWN')) THEN RAISE EXCEPTION 'R60_ONLY_KNOWN_IDLE_RUNNING_PROCESS_RENEWABLE'; END IF;
 SELECT * INTO STRICT lp FROM company_private.r58_lease_policies WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND revision=a.r58_policy_revision AND enabled FOR SHARE;
 q=company_private.r58_qualification(a.admission_qualification_id,a.worker_id,a.r58_binding_digest);
 SELECT * INTO STRICT cap FROM company_private.r58_launch_capabilities WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND process_id=r.id AND state='RUNNING';
 cb=company_private.r58_attestation(cap.callback_attestation_id,'r58.launch-callback.v1');b=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 SELECT new_deadline_ns INTO oldns FROM company_private.r60_lease_extensions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND process_id=r.id AND state='ACTIVE' ORDER BY new_deadline_ns DESC LIMIT 1;
 oldns=coalesce(oldns,(cap.tuple->>'not_after_boottime_ns')::bigint);
 until_at=least((b->>'utc_lower_bound')::timestamptz+lp.duration_ms*interval '1 millisecond',q.valid_until,lp.valid_until,x.expires_at);
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,until_at);
 -- Convert conservatively using upper UTC bound; never add uncertainty to lease.
 newns=(b->>'boottime_after_ns')::bigint+floor(extract(epoch FROM (until_at-(b->>'utc_upper_bound')::timestamptz))*1000000000)::bigint;
 IF (b->>'boottime_after_ns')::bigint>=oldns OR newns<=oldns OR until_at<=r.lease_expires_at THEN RAISE EXCEPTION 'R60_NO_EXPIRED_OR_NONINCREASING_EXTENSION'; END IF;
 id=gen_random_uuid();identity=jsonb_build_object('process_id',r.id,'attempt_id',r.attempt_id,'fence',r.attempt_fencing_epoch,'host_boot_id',r.r55_host_boot_id,'controller_generation',r.controller_generation,'process_identity_digest',cb.payload->>'process_identity_digest','cgroup_inode',cb.payload->'cgroup_inode');
 proposal=jsonb_build_object('extension_id',id,'identity',identity,'old_deadline',oldns,'new_deadline',newns,'process_revision',r.revision,'policy_revision',lp.revision,'new_expires_at',until_at);
 INSERT INTO company_private.r60_lease_extensions VALUES(x.tenant_id,x.project_id,id,r.id,oldns,newns,r.lease_expires_at,until_at,identity,encode(sha256(convert_to(proposal::text,'UTF8')),'hex'),lp.revision,'PREPARED',NULL,NULL,c.id);
 RETURN company_private.r58_finish(c.id,id,jsonb_build_object('extension_id',id,'proposal',proposal,'proposal_raw',proposal::text,'proposal_digest',encode(sha256(convert_to(proposal::text,'UTF8')),'hex'),'os_extended',false));
END $$;
CREATE FUNCTION company_private.r60_lease_commit(p_extension uuid,p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;e company_private.r60_lease_extensions%ROWTYPE;m company_private.r58_attestations%ROWTYPE;r company.process_runs%ROWTYPE;a company.attempts%ROWTYPE;c company.commands%ROWTYPE;b jsonb;
BEGIN
 x=company_private.r58_context('process.lease_commit');m=company_private.r58_attestation(p_attestation,'r60.lease-prepared.v1');
 PERFORM company_private.r58_shape(m.payload,ARRAY['extension_id','proposal_digest','identity','old_deadline','new_deadline','state']);
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('extension',p_extension,'attestation',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT e FROM company_private.r60_lease_extensions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_extension FOR UPDATE;
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=e.process_id FOR UPDATE;
 PERFORM company_private.r58_process_current(r.id);a=company_private.r58_attempt(r.task_id,r.attempt_id,r.attempt_fencing_epoch);b=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 IF e.state IS DISTINCT FROM 'PREPARED' OR r.state IS DISTINCT FROM 'RUNNING' OR m.issuer_id IS DISTINCT FROM r.controller_id OR x.principal_id IS DISTINCT FROM r.controller_id OR m.payload->>'state' IS DISTINCT FROM 'PREPARED'
 OR m.payload->>'extension_id' IS DISTINCT FROM e.id::text OR m.payload->>'proposal_digest' IS DISTINCT FROM e.proposal_digest OR m.payload->'identity' IS DISTINCT FROM e.identity OR m.payload->>'old_deadline' IS DISTINCT FROM e.old_deadline_ns::text OR m.payload->>'new_deadline' IS DISTINCT FROM e.new_deadline_ns::text
 OR r.lease_expires_at IS DISTINCT FROM e.old_expires_at OR (b->>'boottime_after_ns')::bigint>=e.old_deadline_ns
 OR NOT EXISTS(SELECT 1 FROM company_private.r58_lease_policies WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND revision=e.policy_revision AND enabled AND valid_until>=e.new_expires_at)
 OR NOT EXISTS(SELECT 1 FROM company.agent_qualifications WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=a.admission_qualification_id AND valid_until>=e.new_expires_at) THEN RAISE EXCEPTION 'R60_LEASE_PREPARED_ACK_BINDING'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,e.new_expires_at);
 UPDATE company.process_runs SET lease_expires_at=e.new_expires_at,revision=revision+1 WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=r.id AND revision=r.revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'R60_LEASE_PROCESS_CAS'; END IF;
 UPDATE company.attempts SET lease_expires_at=e.new_expires_at WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=r.task_id AND id=r.attempt_id AND fencing_epoch=r.attempt_fencing_epoch;
 UPDATE company_private.r60_lease_extensions SET state='COMMITTED',prepared_attestation_id=m.id WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=e.id AND state='PREPARED';
 RETURN company_private.r58_finish(c.id,e.id,jsonb_build_object('state','COMMITTED','extension_id',e.id,'proposal_digest',e.proposal_digest,'new_deadline',e.new_deadline_ns,'tool_use_allowed',false));
END $$;
CREATE FUNCTION company_private.r60_lease_activate(p_extension uuid,p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;e company_private.r60_lease_extensions%ROWTYPE;m company_private.r58_attestations%ROWTYPE;r company.process_runs%ROWTYPE;c company.commands%ROWTYPE;
BEGIN
 x=company_private.r58_context('process.lease_activate');m=company_private.r58_attestation(p_attestation,'r60.lease-active.v1');
 PERFORM company_private.r58_shape(m.payload,ARRAY['extension_id','proposal_digest','identity','active_deadline','activated_at_boottime_ns','state']);
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('extension',p_extension,'attestation',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT e FROM company_private.r60_lease_extensions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_extension FOR UPDATE;
 r=company_private.r58_process_current(e.process_id);PERFORM company_private.r58_attempt(r.task_id,r.attempt_id,r.attempt_fencing_epoch);
 IF e.state IS DISTINCT FROM 'COMMITTED' OR m.issuer_id IS DISTINCT FROM r.controller_id OR x.principal_id IS DISTINCT FROM r.controller_id OR m.payload->>'state' IS DISTINCT FROM 'ACTIVE' OR m.payload->>'extension_id' IS DISTINCT FROM e.id::text OR m.payload->>'proposal_digest' IS DISTINCT FROM e.proposal_digest OR m.payload->'identity' IS DISTINCT FROM e.identity OR m.payload->>'active_deadline' IS DISTINCT FROM e.new_deadline_ns::text
 OR (m.payload->>'activated_at_boottime_ns')::bigint NOT BETWEEN 0 AND e.old_deadline_ns-1 THEN RAISE EXCEPTION 'R60_ACTIVE_WATCHDOG_PROOF_REQUIRED'; END IF;
 UPDATE company_private.r60_lease_extensions SET state='ACTIVE',active_attestation_id=m.id WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=e.id AND state='COMMITTED';
 RETURN company_private.r58_finish(c.id,e.id,jsonb_build_object('state','ACTIVE','extension_id',e.id,'new_deadline',e.new_deadline_ns));
END $$;
CREATE FUNCTION company_private.r60_lease_read(p_extension uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;e company_private.r60_lease_extensions%ROWTYPE;r company.process_runs%ROWTYPE;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54 AND operation_id='process.lease_read';
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'process.lease_read',x.task_id,false) IS NOT TRUE THEN RAISE EXCEPTION 'R60_LEASE_READ_DENIED'; END IF;
 PERFORM 1 FROM company.projects WHERE tenant_id=x.tenant_id AND id=x.project_id FOR UPDATE;
 SELECT * INTO STRICT e FROM company_private.r60_lease_extensions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_extension AND state='COMMITTED' FOR SHARE;
 r=company_private.r58_process_current(e.process_id);PERFORM company_private.r58_attempt(r.task_id,r.attempt_id,r.attempt_fencing_epoch);
 IF x.principal_id IS DISTINCT FROM r.controller_id OR r.state IS DISTINCT FROM 'RUNNING' THEN RAISE EXCEPTION 'R60_LEASE_CONTROLLER_READBACK'; END IF;
 RETURN jsonb_build_object('state',e.state,'extension_id',e.id,'proposal_digest',e.proposal_digest,'new_deadline',e.new_deadline_ns,'identity',e.identity);
END $$;
CREATE FUNCTION company_private.r60_process_reconcile(p_process uuid,p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;m company_private.r58_attestations%ROWTYPE;r company.process_runs%ROWTYPE;cap company_private.r58_launch_capabilities%ROWTYPE;c company.commands%ROWTYPE;j jsonb;id uuid;
BEGIN
 x=company_private.r58_context('process.reconcile');m=company_private.r58_attestation(p_attestation,'r60.process-observation.v1');j=m.payload;
 PERFORM company_private.r58_shape(j,ARRAY['process_id','capability_id','tuple_digest','host_boot_id','controller_generation','process_identity_digest','cgroup_inode','observer_id','outcome','cgroup_populated','workspace_fenced','no_respawn_intent','usage_zero']);
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('process',p_process,'attestation',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process FOR UPDATE;
 SELECT * INTO STRICT cap FROM company_private.r58_launch_capabilities WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND process_id=r.id;
 -- Deliberately does not call r58_process_current: an expired lease may be stopped.
 IF r.state NOT IN ('STARTING','RUNNING','UNKNOWN_LOCAL','STOP_REQUESTED') OR m.issuer_id IS DISTINCT FROM x.principal_id OR m.issuer_id IN (r.worker_id,r.controller_id) OR j->>'observer_id' IS DISTINCT FROM m.issuer_id::text
 OR NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=m.issuer_id AND kind='VERIFIER')
 OR j->>'process_id' IS DISTINCT FROM r.id::text OR j->>'capability_id' IS DISTINCT FROM cap.id::text OR j->>'tuple_digest' IS DISTINCT FROM cap.tuple_digest OR j->>'host_boot_id' IS DISTINCT FROM r.r55_host_boot_id::text OR j->>'controller_generation' IS DISTINCT FROM r.controller_generation::text
 OR j->>'process_identity_digest' !~ '^[a-f0-9]{64}$' OR jsonb_typeof(j->'cgroup_inode') IS DISTINCT FROM 'number' OR (j->>'cgroup_inode')::bigint<=0 OR j->>'outcome' NOT IN ('RUNNING','EXITED','NOT_STARTED') THEN RAISE EXCEPTION 'R60_INDEPENDENT_EXACT_OBSERVATION_REQUIRED'; END IF;
 IF cap.callback_attestation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM company_private.r58_attestations cb WHERE cb.tenant_id=x.tenant_id AND cb.project_id=x.project_id AND cb.id=cap.callback_attestation_id AND cb.payload->>'process_identity_digest'=j->>'process_identity_digest' AND cb.payload->'cgroup_inode'=j->'cgroup_inode') THEN RAISE EXCEPTION 'R60_CALLBACK_OBSERVATION_IDENTITY_MISMATCH'; END IF;
 IF j->>'outcome'='NOT_STARTED' AND (cap.callback_attestation_id IS NOT NULL OR r.state='RUNNING') THEN RAISE EXCEPTION 'R60_KNOWN_STARTED_PROCESS_CANNOT_BECOME_NOT_STARTED'; END IF;
 IF j->>'outcome'<>'RUNNING' AND (j->'cgroup_populated' IS DISTINCT FROM '0'::jsonb OR j->'workspace_fenced' IS DISTINCT FROM 'true'::jsonb OR j->'no_respawn_intent' IS DISTINCT FROM 'true'::jsonb OR j->'usage_zero' IS DISTINCT FROM 'true'::jsonb) THEN RAISE EXCEPTION 'R60_ACTUAL_QUIESCENCE_REQUIRED'; END IF;
 id=gen_random_uuid();INSERT INTO company_private.r60_process_reconciliations VALUES(x.tenant_id,x.project_id,id,r.id,m.id,j->>'outcome',c.id);
 UPDATE company.process_runs SET state=CASE WHEN j->>'outcome'='RUNNING' THEN 'UNKNOWN_LOCAL' ELSE 'STOPPED' END,revision=revision+1 WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=r.id AND revision=r.revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'R60_RECONCILIATION_CAS'; END IF;
 -- No acceptance, respawn, root issuance, budget or slot release here.
 RETURN company_private.r58_finish(c.id,id,jsonb_build_object('process_id',r.id,'observation',j->>'outcome','respawn_permitted',false,'release_performed',false));
END $$;

-- SOURCE sql/060_R60_STOP_RECONCILIATION_OVERLAY.sql
CREATE OR REPLACE FUNCTION company_private.r58_process_stop_release(p_process uuid,p_revision bigint,p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;r company.process_runs%ROWTYPE;m company_private.r58_attestations%ROWTYPE;b company.budget_reservations%ROWTYPE;cl company.resource_claims%ROWTYPE;ch company_private.r58_controller_heads%ROWTYPE;c company.commands%ROWTYPE;j jsonb;
BEGIN
 -- Cleanup uses current PROJECT authority, not an expired worker lease. It
 -- grants no new execution and cannot authorize another spawn or new spend.
 x=company_private.r58_context('process.stop_release');m=company_private.r58_attestation(p_attestation,'r58.quiescence.v1');j=m.payload;
 PERFORM company_private.r58_shape(j,ARRAY['process_id','task_id','attempt_id','fencing_epoch','host_boot_id','controller_generation','cgroup_inode','process_identity_digest','cgroup_populated','workspace_fenced','no_post_fence_spawn','settled_minor','outcome']);
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('process_id',p_process,'expected_revision',p_revision,'attestation',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process FOR UPDATE;
 SELECT * INTO STRICT ch FROM company_private.r58_controller_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND controller_id=r.controller_id AND generation=r.controller_generation FOR SHARE;
 IF r.e0_evaluation_run_id IS NOT NULL OR r.kind IS DISTINCT FROM 'TASK_EXECUTION' OR r.revision IS DISTINCT FROM p_revision OR r.release_command_id IS NOT NULL OR (m.issuer_id IS DISTINCT FROM r.controller_id AND NOT (EXISTS(SELECT 1 FROM company_private.r60_process_reconciliations z JOIN company_private.r58_attestations ob ON ob.tenant_id=z.tenant_id AND ob.project_id=z.project_id AND ob.id=z.attestation_id WHERE z.tenant_id=x.tenant_id AND z.project_id=x.project_id AND z.process_id=r.id AND z.outcome IN ('EXITED','NOT_STARTED') AND ob.issuer_id NOT IN (r.worker_id,r.controller_id) AND ob.payload->>'process_identity_digest'=j->>'process_identity_digest' AND ob.payload->'cgroup_inode'=j->'cgroup_inode'))) OR m.issuer_id IS DISTINCT FROM x.principal_id
 OR j->>'process_id' IS DISTINCT FROM r.id::text OR j->>'task_id' IS DISTINCT FROM r.task_id::text OR j->>'attempt_id' IS DISTINCT FROM r.attempt_id::text OR j->>'fencing_epoch' IS DISTINCT FROM r.attempt_fencing_epoch::text
 OR j->>'host_boot_id' IS DISTINCT FROM r.r55_host_boot_id::text OR ch.host_boot_id IS DISTINCT FROM r.r55_host_boot_id OR j->>'controller_generation' IS DISTINCT FROM r.controller_generation::text
 OR j->>'process_identity_digest' !~ '^[a-f0-9]{64}$' OR jsonb_typeof(j->'cgroup_inode') IS DISTINCT FROM 'number'
 OR j->'cgroup_populated' IS DISTINCT FROM '0'::jsonb OR j->'workspace_fenced' IS DISTINCT FROM 'true'::jsonb OR j->'no_post_fence_spawn' IS DISTINCT FROM 'true'::jsonb
 OR j->'settled_minor' IS DISTINCT FROM '0'::jsonb OR j->>'outcome' NOT IN ('STOPPED','FAILED_NOT_STARTED') THEN RAISE EXCEPTION 'R58_ACTUAL_QUIESCENCE_REQUIRED_NO_TTL_RELEASE'; END IF;
 -- The signed identity must agree with the immutable launch callback. For an
 -- uncertain spawn without callback, reconciliation remains blocked rather
 -- than fabricating a process identity or freeing resources by TTL.
 IF NOT EXISTS(SELECT 1 FROM company_private.r58_launch_capabilities cap JOIN company_private.r58_attestations cb ON cb.tenant_id=cap.tenant_id AND cb.project_id=cap.project_id AND cb.id=cap.callback_attestation_id WHERE cap.tenant_id=x.tenant_id AND cap.project_id=x.project_id AND cap.process_id=r.id AND cb.payload->>'process_identity_digest'=j->>'process_identity_digest' AND cb.payload->'cgroup_inode'=j->'cgroup_inode') AND NOT (EXISTS(SELECT 1 FROM company_private.r60_process_reconciliations z JOIN company_private.r58_attestations ob ON ob.tenant_id=z.tenant_id AND ob.project_id=z.project_id AND ob.id=z.attestation_id WHERE z.tenant_id=x.tenant_id AND z.project_id=x.project_id AND z.process_id=r.id AND z.outcome IN ('EXITED','NOT_STARTED') AND ob.issuer_id NOT IN (r.worker_id,r.controller_id) AND ob.payload->>'process_identity_digest'=j->>'process_identity_digest' AND ob.payload->'cgroup_inode'=j->'cgroup_inode')) THEN RAISE EXCEPTION 'R58_STOP_IDENTITY_RECONCILIATION_REQUIRED'; END IF;
 SELECT * INTO STRICT b FROM company.budget_reservations WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.reservation_id FOR UPDATE;
 IF b.amount_minor<>0 OR b.state IS DISTINCT FROM 'RESERVED' OR b.task_id IS DISTINCT FROM r.task_id OR b.attempt_id IS DISTINCT FROM r.attempt_id OR b.attempt_fencing_epoch IS DISTINCT FROM r.attempt_fencing_epoch THEN RAISE EXCEPTION 'R58_ZERO_LOCAL_RESERVATION_ONLY'; END IF;
 FOR cl IN SELECT * FROM company.resource_claims WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND process_run_id=r.id ORDER BY slot_id FOR UPDATE LOOP
  IF cl.state IS DISTINCT FROM 'HELD' THEN RAISE EXCEPTION 'R58_RESOURCE_ALREADY_RELEASED'; END IF;
  UPDATE company.resource_slots SET reserved=reserved-cl.units WHERE tenant_id=cl.tenant_id AND id=cl.slot_id AND reserved>=cl.units;
  IF NOT FOUND THEN RAISE EXCEPTION 'R58_RESOURCE_ACCOUNTING'; END IF;
  UPDATE company.resource_claims SET state='RELEASED',revision=revision+1,release_command_id=c.id WHERE tenant_id=cl.tenant_id AND project_id=cl.project_id AND process_run_id=cl.process_run_id AND slot_id=cl.slot_id AND state='HELD' AND revision=cl.revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'R58_CLAIM_RELEASE_CAS'; END IF;
 END LOOP;
 IF r.state NOT IN ('STOPPED','COMPLETED','FAILED_NOT_STARTED') THEN
  IF j->>'outcome'='FAILED_NOT_STARTED' AND r.state NOT IN ('LEASED','REQUESTED','STARTING','UNKNOWN_LOCAL') THEN RAISE EXCEPTION 'R58_RUNNING_PROCESS_CANNOT_BECOME_NOT_STARTED'; END IF;
  IF j->>'outcome'='STOPPED' AND r.state NOT IN ('STOP_REQUESTED','UNKNOWN_LOCAL') THEN
   UPDATE company.process_runs SET state='STOP_REQUESTED',revision=revision+1 WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=r.revision;
   IF NOT FOUND THEN RAISE EXCEPTION 'R58_STOP_REQUEST_CAS'; END IF;
   r.revision=r.revision+1;
  END IF;
  UPDATE company.process_runs SET state=j->>'outcome',revision=revision+1,stop_command_id=c.id WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=r.revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'R58_STOP_CONFIRM_CAS'; END IF;
  r.revision=r.revision+1;
 END IF;
 UPDATE company.budget_reservations SET state='SETTLED',revision=revision+1,settled_minor=0,settlement_command_id=c.id WHERE tenant_id=b.tenant_id AND project_id=b.project_id AND id=b.id AND state='RESERVED' AND revision=b.revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_RESERVATION_SETTLEMENT_CAS'; END IF;
 UPDATE company.budget_reservations SET state='RELEASED',revision=revision+1,released_minor=0,release_command_id=c.id,release_op_id=gen_random_uuid() WHERE tenant_id=b.tenant_id AND project_id=b.project_id AND id=b.id AND state='SETTLED' AND revision=b.revision+1;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_RESERVATION_RELEASE_CAS'; END IF;
 UPDATE company.process_runs SET release_command_id=c.id,revision=revision+1 WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=r.revision AND release_command_id IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_PROCESS_RELEASE_CAS'; END IF;
 RETURN company_private.r58_finish(c.id,r.id,jsonb_build_object('process_id',r.id,'resources_released',true,'quiescence_attestation',m.id,'settled_minor',0,'respawn_permitted',false));
END $$;

