-- SOURCE sql/062_R61_AUTHORITY_BOUNDS.sql
CREATE TABLE company_private.r61_attempt_authorities (
 tenant_id uuid NOT NULL,project_id uuid NOT NULL,task_id uuid NOT NULL,attempt_id uuid NOT NULL,
 worker_id uuid NOT NULL,grant_chain_ids uuid[] NOT NULL CHECK(cardinality(grant_chain_ids)>0),
 admitted_until timestamptz NOT NULL CHECK(isfinite(admitted_until)),command_id uuid NOT NULL,
 PRIMARY KEY(tenant_id,project_id,task_id,attempt_id),
 FOREIGN KEY(tenant_id,project_id,task_id,attempt_id) REFERENCES company.attempts(tenant_id,project_id,task_id,id),
 FOREIGN KEY(tenant_id,command_id) REFERENCES company.commands(tenant_id,id)
);
CREATE TABLE company_private.r61_extension_authorities (
 tenant_id uuid NOT NULL,project_id uuid NOT NULL,extension_id uuid NOT NULL,controller_id uuid NOT NULL,
 phase text NOT NULL CHECK(phase IN ('PREPARED','COMMITTED')),grant_chain_ids uuid[] NOT NULL CHECK(cardinality(grant_chain_ids)>0),
 PRIMARY KEY(tenant_id,project_id,extension_id,phase),
 FOREIGN KEY(tenant_id,project_id,extension_id) REFERENCES company_private.r60_lease_extensions(tenant_id,project_id,id)
);
CREATE FUNCTION company_private.r61_grant_deadline(p_chain uuid[],p_actor uuid,p_permission text,p_task uuid) RETURNS timestamptz
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;current_chain uuid[];until_at timestamptz;n integer;finite_chain boolean;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 IF p_actor IS NULL OR p_permission IS NULL OR p_task IS NULL OR p_chain IS NULL OR cardinality(p_chain)=0 OR cardinality(p_chain)<>(SELECT count(DISTINCT id) FROM unnest(p_chain) id) THEN RAISE EXCEPTION 'R61_COMPLETE_UNIQUE_CHAIN_REQUIRED'; END IF;
 current_chain=company_private.r54_grant_chain(x.tenant_id,x.project_id,p_actor,p_permission,p_task,p_chain[1]);
 IF current_chain IS DISTINCT FROM p_chain THEN RAISE EXCEPTION 'R61_ANCESTOR_CHAIN_CHANGED'; END IF;
 SELECT count(*),least(min(g.valid_until),x.expires_at),bool_and(isfinite(g.valid_until)) INTO n,until_at,finite_chain FROM company.project_grants g WHERE g.tenant_id=x.tenant_id AND g.project_id=x.project_id AND g.grant_id=ANY(p_chain) AND g.revoked_at IS NULL;
 IF n<>cardinality(p_chain) OR finite_chain IS NOT TRUE OR until_at IS NULL OR NOT isfinite(until_at) THEN RAISE EXCEPTION 'R61_CURRENT_FINITE_AUTHORITY_REQUIRED'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,until_at);
 RETURN until_at;
END $$;
CREATE FUNCTION company_private.r61_worker_deadline(p_task uuid,p_attempt uuid) RETURNS timestamptz
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;a company_private.r61_attempt_authorities%ROWTYPE;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 SELECT * INTO STRICT a FROM company_private.r61_attempt_authorities WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_task AND attempt_id=p_attempt;
 RETURN company_private.r61_grant_deadline(a.grant_chain_ids,a.worker_id,'worker.claim',p_task);
END $$;
CREATE FUNCTION company_private.r61_extension_deadline(p_extension uuid) RETURNS timestamptz
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;pr company_private.r61_extension_authorities%ROWTYPE;co company_private.r61_extension_authorities%ROWTYPE;e company_private.r60_lease_extensions%ROWTYPE;r company.process_runs%ROWTYPE;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54;
 SELECT * INTO STRICT e FROM company_private.r60_lease_extensions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_extension;
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=e.process_id;
 SELECT * INTO STRICT pr FROM company_private.r61_extension_authorities WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND extension_id=e.id AND phase='PREPARED';
 SELECT * INTO STRICT co FROM company_private.r61_extension_authorities WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND extension_id=e.id AND phase='COMMITTED';
 IF pr.controller_id IS DISTINCT FROM r.controller_id OR co.controller_id IS DISTINCT FROM r.controller_id OR x.principal_id IS DISTINCT FROM r.controller_id THEN RAISE EXCEPTION 'R61_EXACT_CONTROLLER_CHAINS_REQUIRED'; END IF;
 RETURN least(company_private.r61_worker_deadline(r.task_id,r.attempt_id),company_private.r61_grant_deadline(pr.grant_chain_ids,r.controller_id,'process.lease_prepare',r.task_id),company_private.r61_grant_deadline(co.grant_chain_ids,r.controller_id,'process.lease_commit',r.task_id));
END $$;

-- SOURCE sql/063_R61_WORKER_AUTHORITY_OVERLAY.sql
CREATE OR REPLACE FUNCTION company_private.r58_worker_claim(p_task uuid,p_revision bigint,p_qualification uuid,p_binding text,p_policy_revision bigint,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;t company.tasks%ROWTYPE;q company.agent_qualifications%ROWTYPE;
 h company_private.r58_workspace_heads%ROWTYPE;lp company_private.r58_lease_policies%ROWTYPE;c company.commands%ROWTYPE;b jsonb;until_at timestamptz;aid uuid;n integer;
BEGIN
 x=company_private.r58_context('worker.claim');
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=x.principal_id AND kind IN ('WORKER','VERIFIER')) THEN RAISE EXCEPTION 'R58_TECHNICAL_WORKER_REQUIRED'; END IF;
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('task_id',p_task,'revision',p_revision,'qualification',p_qualification,'binding',p_binding,'lease_policy_revision',p_policy_revision));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT lp FROM company_private.r58_lease_policies WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND revision=p_policy_revision AND enabled FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM company.principals WHERE tenant_id=x.tenant_id AND id=lp.approved_by AND kind='HUMAN') THEN RAISE EXCEPTION 'R58_HUMAN_LEASE_POLICY_REQUIRED'; END IF;
 PERFORM company_private.r60_assert_ready(p_task,p_revision);
 q=company_private.r58_qualification(p_qualification,x.principal_id,p_binding);
 SELECT * INTO STRICT h FROM company_private.r58_workspace_heads WHERE tenant_id=x.tenant_id AND project_id=x.project_id FOR SHARE;
 SELECT * INTO STRICT t FROM company.tasks WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_task FOR UPDATE;
 IF x.task_id IS DISTINCT FROM p_task OR x.attempt_id IS NOT NULL OR t.execution_kind IS DISTINCT FROM 'ORDINARY' OR t.state IS DISTINCT FROM 'READY' OR t.revision IS DISTINCT FROM p_revision OR t.active_attempt_id IS NOT NULL OR t.role_id IS DISTINCT FROM q.role_id
 OR EXISTS(SELECT 1 FROM company.task_dependencies d JOIN company.tasks parent ON parent.tenant_id=d.tenant_id AND parent.project_id=d.project_id AND parent.id=d.depends_on_task_id WHERE d.tenant_id=t.tenant_id AND d.project_id=t.project_id AND d.task_id=t.id AND parent.state<>'ACCEPTED') THEN RAISE EXCEPTION 'R58_TASK_NOT_CLAIMABLE'; END IF;
 b=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 until_at=least((b->>'utc_lower_bound')::timestamptz+(lp.duration_ms::numeric*interval '1 millisecond'),q.valid_until,lp.valid_until,company_private.r61_grant_deadline(x.grant_chain_ids,x.principal_id,'worker.claim',p_task));
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,until_at);
 SELECT coalesce(max(attempt_no),0)+1 INTO n FROM company.attempts WHERE tenant_id=t.tenant_id AND project_id=t.project_id AND task_id=t.id;
 aid=gen_random_uuid();
 INSERT INTO company.attempts(tenant_id,project_id,task_id,id,attempt_no,fencing_epoch,worker_id,state,lease_expires_at,admission_qualification_id,r58_binding_digest,r58_head_digest,r58_policy_revision,r58_verification_profile_digest)
 VALUES(t.tenant_id,t.project_id,t.id,aid,n,t.fencing_epoch+1,x.principal_id,'CLAIMED',until_at,q.id,p_binding,h.head_digest,lp.revision,lp.verification_profile_digest);
 INSERT INTO company_private.r61_attempt_authorities VALUES(x.tenant_id,x.project_id,p_task,aid,x.principal_id,x.grant_chain_ids,until_at,c.id);
 UPDATE company.tasks SET state='RUNNING',revision=revision+1,fencing_epoch=fencing_epoch+1,active_attempt_id=aid WHERE tenant_id=t.tenant_id AND project_id=t.project_id AND id=t.id AND revision=p_revision AND state='READY';
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_TASK_CLAIM_CAS'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,until_at);
 RETURN company_private.r58_finish(c.id,aid,jsonb_build_object('attempt_id',aid,'task_id',t.id,'fencing_epoch',t.fencing_epoch+1,'lease_expires_at',until_at,'qualification_id',q.id,'head_digest',h.head_digest,'lease_policy_revision',lp.revision));
END $$;
CREATE OR REPLACE FUNCTION company_private.r58_worker_heartbeat(p_task uuid,p_attempt uuid,p_fence bigint,p_policy_revision bigint,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;a company.attempts%ROWTYPE;lp company_private.r58_lease_policies%ROWTYPE;q company.agent_qualifications%ROWTYPE;c company.commands%ROWTYPE;r company.process_runs%ROWTYPE;b jsonb;until_at timestamptz;
BEGIN
 x=company_private.r58_context('worker.heartbeat');
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('task_id',p_task,'attempt_id',p_attempt,'fencing_epoch',p_fence,'lease_policy_revision',p_policy_revision));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT lp FROM company_private.r58_lease_policies WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND revision=p_policy_revision AND enabled FOR SHARE;
 a=company_private.r58_attempt(p_task,p_attempt,p_fence);
 IF a.worker_id IS DISTINCT FROM x.principal_id OR a.r58_policy_revision IS DISTINCT FROM lp.revision OR a.state NOT IN ('CLAIMED','RUNNING') THEN RAISE EXCEPTION 'R58_STALE_WORKER_HEARTBEAT'; END IF;
 q=company_private.r58_qualification(a.admission_qualification_id,a.worker_id,a.r58_binding_digest);
 b=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 until_at=least((b->>'utc_lower_bound')::timestamptz+(lp.duration_ms::numeric*interval '1 millisecond'),q.valid_until,lp.valid_until,company_private.r61_grant_deadline(x.grant_chain_ids,x.principal_id,'worker.heartbeat',p_task),company_private.r61_worker_deadline(p_task,p_attempt));
 IF until_at<a.lease_expires_at THEN RAISE EXCEPTION 'R58_LEASE_POLICY_SHRANK_REQUIRES_FENCE'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,until_at);
 FOR r IN SELECT * FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=p_task AND attempt_id=p_attempt ORDER BY id FOR UPDATE LOOP
  PERFORM company_private.r58_process_current(r.id);
  -- A running controller must first support a separately accepted OS lease
  -- extension handshake. DB timestamps alone never extend an active OS lease.
  IF r.worker_id IS DISTINCT FROM a.worker_id OR r.attempt_fencing_epoch IS DISTINCT FROM p_fence OR r.state IS DISTINCT FROM 'REQUESTED' OR r.release_command_id IS NOT NULL THEN RAISE EXCEPTION 'R58_LIVE_OS_RENEWAL_NOT_ACCEPTED'; END IF;
  PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,r.lease_expires_at);
  UPDATE company.process_runs SET lease_expires_at=until_at,revision=revision+1 WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=r.revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'R58_PROCESS_LEASE_CAS'; END IF;
 END LOOP;
 UPDATE company.attempts SET lease_expires_at=until_at WHERE tenant_id=a.tenant_id AND project_id=a.project_id AND task_id=a.task_id AND id=a.id AND fencing_epoch=p_fence AND lease_expires_at=a.lease_expires_at;
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_ATTEMPT_LEASE_CAS'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,until_at);
 RETURN company_private.r58_finish(c.id,a.id,jsonb_build_object('attempt_id',a.id,'fencing_epoch',p_fence,'lease_expires_at',until_at,'lease_policy_revision',lp.revision));
END $$;

-- SOURCE sql/064_R61_LEASE_AUTHORITY_OVERLAY.sql
CREATE OR REPLACE FUNCTION company_private.r60_lease_prepare(p_process uuid,p_revision bigint,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;r company.process_runs%ROWTYPE;a company.attempts%ROWTYPE;q company.agent_qualifications%ROWTYPE;lp company_private.r58_lease_policies%ROWTYPE;cap company_private.r58_launch_capabilities%ROWTYPE;cb company_private.r58_attestations%ROWTYPE;c company.commands%ROWTYPE;b jsonb;oldns bigint;newns bigint;until_at timestamptz;identity jsonb;proposal jsonb;id uuid;
BEGIN
 x=company_private.r58_context('process.lease_prepare');
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('process_id',p_process,'revision',p_revision));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_process FOR UPDATE;
 PERFORM company_private.r58_process_current(r.id);a=company_private.r58_attempt(r.task_id,r.attempt_id,r.attempt_fencing_epoch);
 IF r.state IS DISTINCT FROM 'RUNNING' OR r.revision IS DISTINCT FROM p_revision OR x.principal_id IS DISTINCT FROM r.controller_id OR x.task_id IS DISTINCT FROM r.task_id OR x.attempt_id IS DISTINCT FROM r.attempt_id
 OR EXISTS(SELECT 1 FROM company_private.r60_tool_consumptions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND process_id=r.id AND state IN ('CONSUMED','UNKNOWN')) THEN RAISE EXCEPTION 'R60_ONLY_KNOWN_IDLE_RUNNING_PROCESS_RENEWABLE'; END IF;
 SELECT * INTO STRICT lp FROM company_private.r58_lease_policies WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND revision=a.r58_policy_revision AND enabled FOR SHARE;
 q=company_private.r58_qualification(a.admission_qualification_id,a.worker_id,a.r58_binding_digest);
 SELECT * INTO STRICT cap FROM company_private.r58_launch_capabilities WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND process_id=r.id AND state='RUNNING';
 cb=company_private.r58_attestation(cap.callback_attestation_id,'r58.launch-callback.v1');b=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 SELECT new_deadline_ns INTO oldns FROM company_private.r60_lease_extensions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND process_id=r.id AND state='ACTIVE' ORDER BY new_deadline_ns DESC LIMIT 1;
 oldns=coalesce(oldns,(cap.tuple->>'not_after_boottime_ns')::bigint);
 until_at=least((b->>'utc_lower_bound')::timestamptz+lp.duration_ms*interval '1 millisecond',q.valid_until,lp.valid_until,company_private.r61_grant_deadline(x.grant_chain_ids,x.principal_id,'process.lease_prepare',r.task_id),company_private.r61_worker_deadline(r.task_id,r.attempt_id));
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,until_at);
 -- Convert conservatively using upper UTC bound; never add uncertainty to lease.
 newns=(b->>'boottime_after_ns')::bigint+floor(extract(epoch FROM (until_at-(b->>'utc_upper_bound')::timestamptz))*1000000000)::bigint;
 IF (b->>'boottime_after_ns')::bigint>=oldns OR newns<=oldns OR until_at<=r.lease_expires_at THEN RAISE EXCEPTION 'R60_NO_EXPIRED_OR_NONINCREASING_EXTENSION'; END IF;
 id=gen_random_uuid();identity=jsonb_build_object('process_id',r.id,'attempt_id',r.attempt_id,'fence',r.attempt_fencing_epoch,'host_boot_id',r.r55_host_boot_id,'controller_generation',r.controller_generation,'process_identity_digest',cb.payload->>'process_identity_digest','cgroup_inode',cb.payload->'cgroup_inode');
 proposal=jsonb_build_object('extension_id',id,'identity',identity,'old_deadline',oldns,'new_deadline',newns,'process_revision',r.revision,'policy_revision',lp.revision,'new_expires_at',until_at);
 INSERT INTO company_private.r60_lease_extensions VALUES(x.tenant_id,x.project_id,id,r.id,oldns,newns,r.lease_expires_at,until_at,identity,encode(sha256(convert_to(proposal::text,'UTF8')),'hex'),lp.revision,'PREPARED',NULL,NULL,c.id);
 INSERT INTO company_private.r61_extension_authorities VALUES(x.tenant_id,x.project_id,id,x.principal_id,'PREPARED',x.grant_chain_ids);
 RETURN company_private.r58_finish(c.id,id,jsonb_build_object('extension_id',id,'proposal',proposal,'proposal_raw',proposal::text,'proposal_digest',encode(sha256(convert_to(proposal::text,'UTF8')),'hex'),'os_extended',false));
END $$;
CREATE OR REPLACE FUNCTION company_private.r60_lease_commit(p_extension uuid,p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;e company_private.r60_lease_extensions%ROWTYPE;m company_private.r58_attestations%ROWTYPE;r company.process_runs%ROWTYPE;a company.attempts%ROWTYPE;c company.commands%ROWTYPE;b jsonb;
BEGIN
 x=company_private.r58_context('process.lease_commit');m=company_private.r58_attestation(p_attestation,'r60.lease-prepared.v1');
 PERFORM company_private.r58_shape(m.payload,ARRAY['extension_id','proposal_digest','identity','old_deadline','new_deadline','state']);
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('extension',p_extension,'attestation',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT e FROM company_private.r60_lease_extensions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_extension FOR UPDATE;
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=e.process_id FOR UPDATE;
 PERFORM company_private.r58_process_current(r.id);a=company_private.r58_attempt(r.task_id,r.attempt_id,r.attempt_fencing_epoch);b=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 IF e.state IS DISTINCT FROM 'PREPARED' OR r.state IS DISTINCT FROM 'RUNNING' OR m.issuer_id IS DISTINCT FROM r.controller_id OR x.principal_id IS DISTINCT FROM r.controller_id OR m.payload->>'state' IS DISTINCT FROM 'PREPARED'
 OR m.payload->>'extension_id' IS DISTINCT FROM e.id::text OR m.payload->>'proposal_digest' IS DISTINCT FROM e.proposal_digest OR m.payload->'identity' IS DISTINCT FROM e.identity OR m.payload->>'old_deadline' IS DISTINCT FROM e.old_deadline_ns::text OR m.payload->>'new_deadline' IS DISTINCT FROM e.new_deadline_ns::text
 OR r.lease_expires_at IS DISTINCT FROM e.old_expires_at OR (b->>'boottime_after_ns')::bigint>=e.old_deadline_ns
 OR NOT EXISTS(SELECT 1 FROM company_private.r58_lease_policies WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND revision=e.policy_revision AND enabled AND valid_until>=e.new_expires_at)
 OR NOT EXISTS(SELECT 1 FROM company.agent_qualifications WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=a.admission_qualification_id AND valid_until>=e.new_expires_at) THEN RAISE EXCEPTION 'R60_LEASE_PREPARED_ACK_BINDING'; END IF;
 IF e.new_expires_at>least(company_private.r61_grant_deadline(x.grant_chain_ids,x.principal_id,'process.lease_commit',r.task_id),company_private.r61_worker_deadline(r.task_id,r.attempt_id)) THEN RAISE EXCEPTION 'R61_EXTENSION_EXCEEDS_CURRENT_AUTHORITY'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,e.new_expires_at);
 UPDATE company.process_runs SET lease_expires_at=e.new_expires_at,revision=revision+1 WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=r.id AND revision=r.revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'R60_LEASE_PROCESS_CAS'; END IF;
 UPDATE company.attempts SET lease_expires_at=e.new_expires_at WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND task_id=r.task_id AND id=r.attempt_id AND fencing_epoch=r.attempt_fencing_epoch;
 UPDATE company_private.r60_lease_extensions SET state='COMMITTED',prepared_attestation_id=m.id WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=e.id AND state='PREPARED';
 INSERT INTO company_private.r61_extension_authorities VALUES(x.tenant_id,x.project_id,e.id,x.principal_id,'COMMITTED',x.grant_chain_ids);
 RETURN company_private.r58_finish(c.id,e.id,jsonb_build_object('state','COMMITTED','extension_id',e.id,'proposal_digest',e.proposal_digest,'new_deadline',e.new_deadline_ns,'tool_use_allowed',false));
END $$;
CREATE OR REPLACE FUNCTION company_private.r60_lease_read(p_extension uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;e company_private.r60_lease_extensions%ROWTYPE;r company.process_runs%ROWTYPE;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54 AND operation_id='process.lease_read';
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'process.lease_read',x.task_id,false) IS NOT TRUE THEN RAISE EXCEPTION 'R60_LEASE_READ_DENIED'; END IF;
 PERFORM 1 FROM company.projects WHERE tenant_id=x.tenant_id AND id=x.project_id FOR UPDATE;
 SELECT * INTO STRICT e FROM company_private.r60_lease_extensions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_extension AND state='COMMITTED' FOR SHARE;
 r=company_private.r58_process_current(e.process_id);PERFORM company_private.r58_attempt(r.task_id,r.attempt_id,r.attempt_fencing_epoch);
 IF x.principal_id IS DISTINCT FROM r.controller_id OR r.state IS DISTINCT FROM 'RUNNING' THEN RAISE EXCEPTION 'R60_LEASE_CONTROLLER_READBACK'; END IF;
 IF e.new_expires_at>company_private.r61_extension_deadline(e.id) THEN RAISE EXCEPTION 'R61_COMMITTED_AUTHORITY_REVOKED_OR_SHORTENED'; END IF;
 RETURN jsonb_build_object('state',e.state,'extension_id',e.id,'proposal_digest',e.proposal_digest,'new_deadline',e.new_deadline_ns,'identity',e.identity);
END $$;
CREATE OR REPLACE FUNCTION company_private.r60_lease_activate(p_extension uuid,p_attestation uuid,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;e company_private.r60_lease_extensions%ROWTYPE;m company_private.r58_attestations%ROWTYPE;r company.process_runs%ROWTYPE;c company.commands%ROWTYPE;
BEGIN
 x=company_private.r58_context('process.lease_activate');m=company_private.r58_attestation(p_attestation,'r60.lease-active.v1');
 PERFORM company_private.r58_shape(m.payload,ARRAY['extension_id','proposal_digest','identity','active_deadline','activated_at_boottime_ns','state']);
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('extension',p_extension,'attestation',p_attestation));
 IF c.state='SUCCEEDED' THEN RETURN company_private.r58_finish(c.id,c.result_ref,c.r55_result_payload); END IF;
 SELECT * INTO STRICT e FROM company_private.r60_lease_extensions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_extension FOR UPDATE;
 r=company_private.r58_process_current(e.process_id);PERFORM company_private.r58_attempt(r.task_id,r.attempt_id,r.attempt_fencing_epoch);
 IF e.state IS DISTINCT FROM 'COMMITTED' OR m.issuer_id IS DISTINCT FROM r.controller_id OR x.principal_id IS DISTINCT FROM r.controller_id OR m.payload->>'state' IS DISTINCT FROM 'ACTIVE' OR m.payload->>'extension_id' IS DISTINCT FROM e.id::text OR m.payload->>'proposal_digest' IS DISTINCT FROM e.proposal_digest OR m.payload->'identity' IS DISTINCT FROM e.identity OR m.payload->>'active_deadline' IS DISTINCT FROM e.new_deadline_ns::text
 OR (m.payload->>'activated_at_boottime_ns')::bigint NOT BETWEEN 0 AND e.old_deadline_ns-1 THEN RAISE EXCEPTION 'R60_ACTIVE_WATCHDOG_PROOF_REQUIRED'; END IF;
 IF e.new_expires_at>company_private.r61_extension_deadline(e.id) THEN RAISE EXCEPTION 'R61_ACTIVE_AUTHORITY_REVOKED_OR_SHORTENED'; END IF;
 UPDATE company_private.r60_lease_extensions SET state='ACTIVE',active_attestation_id=m.id WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=e.id AND state='COMMITTED';
 RETURN company_private.r58_finish(c.id,e.id,jsonb_build_object('state','ACTIVE','extension_id',e.id,'new_deadline',e.new_deadline_ns));
END $$;

-- SOURCE sql/065_R61_LAUNCH_AUTHORITY_OVERLAY.sql
CREATE OR REPLACE FUNCTION company_private.r58_launch_consume(p_capability uuid,p_digest text,p_key text,p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;cap company_private.r58_launch_capabilities%ROWTYPE;r company.process_runs%ROWTYPE;a company.attempts%ROWTYPE;c company.commands%ROWTYPE;b jsonb;
BEGIN
 x=company_private.r58_context('process.launch_consume');
 c=company_private.r58_begin_command(p_key,p_correlation,jsonb_build_object('capability',p_capability,'tuple_digest',p_digest));
 -- Even an exact replay may not return a second OS launch instruction.
 IF c.state='SUCCEEDED' THEN RETURN jsonb_build_object('outcome','REPLAY_RECONCILE_ONLY','command_id',c.id,'spawn_permitted',false); END IF;
 SELECT * INTO STRICT cap FROM company_private.r58_launch_capabilities WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=p_capability FOR UPDATE;
 a=company_private.r58_attempt((cap.tuple->>'task_id')::uuid,(cap.tuple->>'attempt_id')::uuid,(cap.tuple->>'fencing_epoch')::bigint);
 SELECT * INTO STRICT r FROM company.process_runs WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND id=cap.process_id FOR UPDATE;
 PERFORM company_private.r58_process_current(r.id);
 b=company_private.r55_cp_clock_current_bounds(x.tenant_id,x.project_id);
 IF cap.state IS DISTINCT FROM 'RESERVED' OR cap.tuple_digest IS DISTINCT FROM p_digest OR r.controller_id IS DISTINCT FROM x.principal_id OR r.state IS DISTINCT FROM 'REQUESTED'
 OR b->>'host_boot_id' IS DISTINCT FROM cap.tuple->>'host_boot_id' OR (b->>'boottime_after_ns')::numeric>=(cap.tuple->>'not_after_boottime_ns')::numeric
 OR NOT EXISTS(SELECT 1 FROM company_private.r58_workspace_heads h WHERE h.tenant_id=x.tenant_id AND h.project_id=x.project_id AND h.head_digest=cap.tuple->>'head_digest') THEN RAISE EXCEPTION 'R58_CAPABILITY_NOT_CURRENT_OR_ALREADY_USED'; END IF;
 IF r.lease_expires_at>least(company_private.r61_grant_deadline(x.grant_chain_ids,x.principal_id,'process.launch_consume',r.task_id),company_private.r61_worker_deadline(r.task_id,r.attempt_id)) THEN RAISE EXCEPTION 'R61_LAUNCH_LEASE_EXCEEDS_AUTHORITY'; END IF;
 UPDATE company_private.r58_launch_capabilities SET state='CONSUMED',consume_command_id=c.id WHERE tenant_id=cap.tenant_id AND project_id=cap.project_id AND id=cap.id AND state='RESERVED';
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_CAPABILITY_CONSUME_CAS'; END IF;
 UPDATE company.process_runs SET state='STARTING',revision=revision+1 WHERE tenant_id=r.tenant_id AND project_id=r.project_id AND id=r.id AND revision=r.revision AND state='REQUESTED';
 IF NOT FOUND THEN RAISE EXCEPTION 'R58_PROCESS_START_CAS'; END IF;
 PERFORM company_private.r55_cp_require_not_expired(x.tenant_id,x.project_id,a.lease_expires_at);
 RETURN company_private.r58_finish(c.id,cap.id,jsonb_build_object('capability_id',cap.id,'tuple',cap.tuple,'tuple_raw',cap.tuple::text,'tuple_digest',cap.tuple_digest,'spawn_permitted',true,'release_only_after_commit',true));
END $$;

