GRANT SELECT ON company.audit_events,company.outbox TO company_execution_functions_r58;
CREATE POLICY r65_reply_audit_read ON company.audit_events FOR SELECT TO company_execution_functions_r58
USING(EXISTS(SELECT 1 FROM company_private.request_contexts x JOIN company.commands c ON c.tenant_id=x.tenant_id AND c.r55_project_id=x.project_id AND c.principal_id=x.principal_id AND c.operation='tool.effect' AND c.r55_audit_id=audit_events.id
 WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.writer_generation=54 AND x.operation_id='candidate.r58.artifacts.read' AND audit_events.tenant_id=x.tenant_id));
CREATE POLICY r65_reply_outbox_read ON company.outbox FOR SELECT TO company_execution_functions_r58
USING(EXISTS(SELECT 1 FROM company_private.request_contexts x JOIN company.commands c ON c.tenant_id=x.tenant_id AND c.r55_project_id=x.project_id AND c.principal_id=x.principal_id AND c.operation='tool.effect' AND c.id=outbox.event_instance_id AND c.r55_event_sequence=outbox.project_sequence
 WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.writer_generation=54 AND x.operation_id='candidate.r58.artifacts.read' AND outbox.tenant_id=x.tenant_id AND outbox.project_id=x.project_id));
CREATE FUNCTION company_private.r65_engine_reply_guard(p_receipt uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x company_private.request_contexts%ROWTYPE;m company_private.r58_attestations%ROWTYPE;u company_private.r60_tool_consumptions%ROWTYPE;s company_private.r60_engine_streams%ROWTYPE;r company.process_runs%ROWTYPE;snapshot jsonb;
BEGIN
 SELECT * INTO STRICT x FROM company_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54 AND operation_id='candidate.r58.artifacts.read';
 IF company_private.r54_allowed(x.tenant_id,x.project_id,'artifacts.read',x.task_id,false) IS NOT TRUE THEN RAISE EXCEPTION 'R65_REPLY_CURRENT_AUTHORITY_REQUIRED'; END IF;
 m=company_private.r58_attestation(p_receipt,'r60.tool-effect.v1');
 SELECT * INTO STRICT u FROM company_private.r60_tool_consumptions WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND effect_attestation_id=m.id AND state='SUCCEEDED';
 SELECT * INTO STRICT s FROM company_private.r60_engine_streams WHERE tenant_id=x.tenant_id AND project_id=x.project_id AND engine_session_id=u.engine_session_id;
 r=company_private.r58_process_current(u.process_id);
 IF m.issuer_id IS DISTINCT FROM x.principal_id OR r.controller_id IS DISTINCT FROM x.principal_id
 OR s.task_id IS DISTINCT FROM x.task_id OR s.attempt_id IS DISTINCT FROM x.attempt_id OR s.fence IS DISTINCT FROM x.fencing_epoch
 OR s.next_sequence IS DISTINCT FROM u.sequence+1 OR r.state IS DISTINCT FROM 'RUNNING'
 OR m.payload->>'consume_id' IS DISTINCT FROM u.id::text OR m.payload->>'frame_digest' IS DISTINCT FROM u.frame_digest
 OR NOT EXISTS(SELECT 1 FROM company_private.r58_execution_receipts e JOIN company.commands c ON c.tenant_id=e.tenant_id AND c.id=e.command_id
 JOIN company.audit_events a ON a.tenant_id=c.tenant_id AND a.id=c.r55_audit_id AND a.actor_id=c.principal_id AND a.correlation_id=c.correlation_id AND a.kind=company_private.r55_cp_event_kind(c.operation)
 JOIN company.outbox ev ON ev.tenant_id=c.tenant_id AND ev.project_id=c.r55_project_id AND ev.event_instance_id=c.id AND ev.project_sequence=c.r55_event_sequence AND ev.event_writer_generation=54 AND ev.aggregate_revision=0 AND ev.aggregate_id=m.id AND ev.kind=a.kind
 WHERE e.tenant_id=x.tenant_id AND e.project_id=x.project_id AND e.operation='tool.effect' AND e.target_id=m.id AND e.payload=c.r55_result_payload AND c.principal_id=x.principal_id AND c.operation=e.operation AND c.state='SUCCEEDED' AND c.r55_project_id=x.project_id AND c.result_ref=m.id AND c.r55_source_revision='r58'
 AND c.r55_result_digest=encode(sha256(convert_to(jsonb_build_array(c.id,c.payload_digest,c.result_ref,ev.aggregate_revision,ev.kind,c.r55_result_payload,c.r55_source_revision)::text,'UTF8')),'hex') AND ev.payload->>'result_digest'=c.r55_result_digest AND ev.payload->>'request_digest'=c.payload_digest)
 THEN RAISE EXCEPTION 'R65_REPLY_EXACT_COMMITTED_EFFECT_REQUIRED'; END IF;
 snapshot=company_private.r58_emission_snapshot();
 IF company_private.r58_emission_check(snapshot) IS NOT TRUE THEN RAISE EXCEPTION 'R65_REPLY_EMISSION_REVOKED'; END IF;
 RETURN jsonb_build_object('receipt_id',m.id,'engine_session_id',s.engine_session_id,'request_id',u.engine_request_id,'snapshot',snapshot);
END $$;
ALTER FUNCTION company_private.r65_engine_reply_guard(uuid) OWNER TO company_execution_functions_r58;
REVOKE ALL ON FUNCTION company_private.r65_engine_reply_guard(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r65_engine_reply_guard(uuid) TO company_transport_r54,company_execution_functions_r58;

SELECT json_build_object('registry_count',(SELECT count(*) FROM company_private.operation_permissions),'inactive_required',(SELECT count(*) FROM company_private.operation_permissions WHERE operation_id IN ('CAP-017.revoke','e0.setup_mandate_consume','e0.qualification_candidate_issue','e0.evaluation_artifact_record','qualification.activate','qualification.revoke','objectives.create','plans.create','tasks.create') AND policy_revision=0 AND approved_policy_digest IS NULL),'public_clock_execute',(SELECT EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x WHERE x.grantee=0 AND x.privilege_type='EXECUTE') FROM pg_proc p WHERE p.oid='company_private.r55_cp_clock_epoch_immutable()'::regprocedure));
SELECT json_build_object('bootstrap_roots',(SELECT count(*) FROM company_private.r55_setup_root_enrollments),'installation_controls',(SELECT count(*) FROM company_private.installation_bootstrap_control),'principals',(SELECT count(*) FROM company.principals),'sessions',(SELECT count(*) FROM company.sessions),'grants',(SELECT count(*) FROM company.project_grants));

-- SYNTHETIC_ROOT_SHAPE_TEST: NOT actual human or authority enrollment.
INSERT INTO company_private.scope_lock_registry(rank,identity_key) VALUES(0,jsonb_build_object('kind','INSTALLATION_BOOTSTRAP','installation_id','00000000-0000-4000-8000-000000000001'::uuid));
INSERT INTO company_private.r55_setup_root_enrollments(installation_id,generation,enrollment_revision,issuer_id,key_id,key_fingerprint,actual_human_id,custodian_id,verified_identity_evidence_digest,release_digest,enrollment_digest,allowed_operations,host_boot_id,clock_policy_digest,not_before,not_after,not_after_boottime_ns,lock_id,r56_anchor_boottime_ns,r56_anchor_utc_lower,r56_anchor_utc_upper,r56_issuer_class,r56_approved_manifest_digest,r56_approved_nonce_hash,r56_human_consent_evidence_digest) VALUES('00000000-0000-4000-8000-000000000001',1,1,'00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000003','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','00000000-0000-4000-8000-000000000004','00000000-0000-4000-8000-000000000004','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',ARRAY['e0.setup_mandate_consume'],'00000000-0000-4000-8000-000000000005','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','2026-11-08T00:00:00Z','2026-11-08T00:05:00Z',10000000000,(SELECT lock_id FROM company_private.scope_lock_registry WHERE identity_key=jsonb_build_object('kind','INSTALLATION_BOOTSTRAP','installation_id','00000000-0000-4000-8000-000000000001'::uuid)),1,'2026-11-08T00:00:01Z','2026-11-08T00:00:02Z','PROVISIONING_SERVICE','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa');
DO $$ BEGIN BEGIN INSERT INTO company_private.r55_setup_root_enrollments(installation_id,generation,enrollment_revision,issuer_id,key_id,key_fingerprint,actual_human_id,custodian_id,verified_identity_evidence_digest,release_digest,enrollment_digest,allowed_operations,host_boot_id,clock_policy_digest,not_before,not_after,not_after_boottime_ns,lock_id,r56_anchor_boottime_ns,r56_anchor_utc_lower,r56_anchor_utc_upper,r56_issuer_class,r56_approved_manifest_digest,r56_approved_nonce_hash,r56_human_consent_evidence_digest) VALUES('00000000-0000-4000-8000-000000000001',1,1,'00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000003','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','00000000-0000-4000-8000-000000000004','00000000-0000-4000-8000-000000000004','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',ARRAY['e0.setup_mandate_consume'],'00000000-0000-4000-8000-000000000005','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','2026-11-08T00:00:00Z','2026-11-08T00:05:00Z',10000000000,(SELECT lock_id FROM company_private.scope_lock_registry WHERE identity_key=jsonb_build_object('kind','INSTALLATION_BOOTSTRAP','installation_id','00000000-0000-4000-8000-000000000001'::uuid)),1,'2026-11-08T00:00:01Z','2026-11-08T00:00:02Z','PROVISIONING_SERVICE','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'); RAISE EXCEPTION 'DUPLICATE_ROOT_ACCEPTED'; EXCEPTION WHEN unique_violation THEN NULL; END; END $$;
SELECT json_build_object('scope','SYNTHETIC_ROOT_SHAPE_ONLY','root_rows',(SELECT count(*) FROM company_private.r55_setup_root_enrollments),'duplicate_rejected',true);

DO $probe$ DECLARE item bytea; message bytea; BEGIN message=convert_to('R55-CP-PROOF-v1','UTF8')||decode('00','hex'); FOREACH item IN ARRAY ARRAY[convert_to('SETUP','UTF8'),convert_to('00000000-0000-4000-8000-000000000001','UTF8'),convert_to('00000000-0000-4000-8000-000000000001','UTF8'),convert_to('1','UTF8'),decode('7b2266697874757265223a747275657d','hex')] LOOP message=message||convert_to(octet_length(item)::text||':','UTF8')||item; END LOOP; IF encode(company_private.r55_cp_hmac_sha256(decode('7878787878787878787878787878787878787878787878787878787878787878','hex'),message),'hex')<>'1bab5154179e986669cba1bcb5b4165ade3e960d40896b15bd131b0e9250989b' THEN RAISE EXCEPTION 'SETUP_CODEC_MISMATCH'; END IF; message=convert_to('R56-BOOTSTRAP-v1','UTF8')||decode('00','hex'); FOREACH item IN ARRAY ARRAY[convert_to('00000000-0000-4000-8000-000000000001','UTF8'),convert_to('1','UTF8'),convert_to('00000000-0000-4000-8000-000000000001','UTF8'),convert_to('00000000-0000-4000-8000-000000000001','UTF8'),convert_to('1','UTF8'),decode('7b2266697874757265223a747275657d','hex')] LOOP message=message||convert_to(octet_length(item)::text||':','UTF8')||item; END LOOP; IF encode(company_private.r55_cp_hmac_sha256(decode('7878787878787878787878787878787878787878787878787878787878787878','hex'),message),'hex')<>'3620cf33f85543af43c75651eb9d27c3f68a7cf678a8e50a5cca248c7871ce10' THEN RAISE EXCEPTION 'ENTER_CODEC_MISMATCH'; END IF; END $probe$;
SELECT json_build_object('setup_hmac_abi','MATCH','enter_hmac_abi','MATCH','scope','PUBLIC_SYNTHETIC_TEST_VECTOR_NOT_ENROLLED_SECRET');

-- SYNTHETIC_ARM_FLOW: conditional test transport, not real enrollment.
CREATE ROLE company_provisioning_runtime_r55 NOLOGIN NOSUPERUSER NOBYPASSRLS;
GRANT USAGE ON SCHEMA company_private TO company_provisioning_runtime_r55;
GRANT company_bootstrap_transport_r56 TO company_provisioning_runtime_r55;
GRANT EXECUTE ON FUNCTION company_private.r55_cp_setup_control_arm(uuid,bigint,bytea,bytea,bytea) TO company_provisioning_runtime_r55;
DO $arm$ DECLARE e company_private.r55_setup_root_enrollments%ROWTYPE;m jsonb;j jsonb;raw bytea;message bytea;item bytea;tag bytea;o jsonb;nonce bytea=convert_to(repeat('n',32),'UTF8');result jsonb;worker uuid=gen_random_uuid();objective uuid=gen_random_uuid();plan uuid=gen_random_uuid();k bytea=convert_to(repeat('x',32),'UTF8');b uuid;BEGIN
 o=company_private.r55_cp_clock_observe_local();
 SELECT * INTO STRICT e FROM company_private.r55_setup_root_enrollments;
 UPDATE company_private.r55_setup_root_enrollments SET key_fingerprint=encode(sha256(k),'hex'),not_before=clock_timestamp()-interval '1 minute',not_after=clock_timestamp()+interval '5 minutes' WHERE installation_id=e.installation_id;
 m=jsonb_build_object('tenant_id',gen_random_uuid(),'project_id',gen_random_uuid(),'workspace_id',gen_random_uuid(),'verified_human_id',e.actual_human_id,'nonce_hash',repeat('b',64),'setup_manifest_digest',repeat('c',64),'finite_initial_operations',jsonb_build_array('e0.setup_mandate_consume'),'valid_until',clock_timestamp()+interval '1 minute');

 m=m||jsonb_build_object('nonce_hash',encode(sha256(nonce),'hex'),'tenant_name','Synthetic tenant','human_name','Synthetic human','project_name','Synthetic project','initial_principals',jsonb_build_array(jsonb_build_object('id',worker,'name','Synthetic worker','kind','WORKER')),'evaluation_objective',jsonb_build_object('id',objective,'goal','Synthetic evaluation','constraints',jsonb_build_array('No external effects'),'expected_outputs',jsonb_build_array('fixture')),'evaluation_plan',jsonb_build_object('id',plan,'objective_id',objective,'assumptions',jsonb_build_array(),'acceptance_criteria',jsonb_build_array('Synthetic case')),'e0_mandate',jsonb_build_object('kind','EVALUATION_ONLY','network','DENY','external_effects','DENY','workspace_id',m->>'workspace_id','plan_id',plan,'subject_principal_id',worker,'model_digest',repeat('a',64),'fixture_digest',repeat('a',64),'profile_digest',repeat('a',64),'negative_suite_digest',repeat('a',64),'role_id','fixture','required_positive_oracle_ids',jsonb_build_array('positive-fixture'),'required_negative_oracle_ids',jsonb_build_array('negative-fixture')));
 m=m||jsonb_build_object('setup_manifest_digest',encode(sha256(convert_to((m-'setup_manifest_digest')::text,'UTF8')),'hex'));
 UPDATE company_private.r55_setup_root_enrollments SET host_boot_id=(o->>'host_boot_id')::uuid,r56_anchor_boottime_ns=(o->>'boottime_after_ns')::numeric,not_after_boottime_ns=(o->>'boottime_after_ns')::numeric+60000000000,r56_anchor_utc_lower=clock_timestamp()-interval '1 second',r56_anchor_utc_upper=clock_timestamp()+interval '1 second',r56_approved_manifest_digest=encode(sha256(convert_to(m::text,'UTF8')),'hex'),r56_approved_nonce_hash=encode(sha256(nonce),'hex') WHERE installation_id=e.installation_id;
 SELECT * INTO STRICT e FROM company_private.r55_setup_root_enrollments;
 j=jsonb_build_object('installation_id',e.installation_id,'generation',1,'backend_pid',pg_backend_pid(),'transaction_id',pg_current_xact_id()::text,'db_login','company_provisioning_runtime_r55','host_boot_id',e.host_boot_id,'utc_lower_bound',clock_timestamp()-interval '1 second','utc_upper_bound',clock_timestamp()+interval '1 second','manifest',m);
 raw=convert_to(j::text,'UTF8');message=convert_to('R55-CP-PROOF-v1','UTF8')||decode('00','hex');
 FOREACH item IN ARRAY ARRAY[convert_to('SETUP','UTF8'),convert_to(e.issuer_id::text,'UTF8'),convert_to(e.key_id::text,'UTF8'),convert_to('1','UTF8'),raw] LOOP message=message||convert_to(octet_length(item)::text||':','UTF8')||item; END LOOP;
 tag=company_private.r55_cp_hmac_sha256(k,message);
 SET SESSION AUTHORIZATION company_provisioning_runtime_r55;
 SELECT company_private.r55_cp_setup_control_arm(e.installation_id,1,raw,tag,k) INTO b;

 j=jsonb_build_object('profile','r56.bootstrap-enter.v1','phase','BOOTSTRAP_ENTER','installation_id',e.installation_id,'generation',1,'backend_pid',pg_backend_pid(),'transaction_id',pg_current_xact_id()::text,'db_login',session_user,'human_id',e.actual_human_id,'host_boot_id',e.host_boot_id,'nonce_hash',encode(sha256(nonce),'hex'),'manifest_digest',encode(sha256(convert_to(m::text,'UTF8')),'hex'),'root_proof_digest',encode(sha256(raw),'hex'),'release_digest',e.release_digest);
 raw=convert_to(j::text,'UTF8');message=convert_to('R56-BOOTSTRAP-v1','UTF8')||decode('00','hex');
 FOREACH item IN ARRAY ARRAY[convert_to(e.installation_id::text,'UTF8'),convert_to('1','UTF8'),convert_to(e.issuer_id::text,'UTF8'),convert_to(e.key_id::text,'UTF8'),convert_to('1','UTF8'),raw] LOOP message=message||convert_to(octet_length(item)::text||':','UTF8')||item; END LOOP;
 RESET SESSION AUTHORIZATION;
 tag=company_private.r55_cp_hmac_sha256(k,message);
 SET SESSION AUTHORIZATION company_provisioning_runtime_r55;

 BEGIN
  PERFORM company_private.r56_bootstrap_consume(e.installation_id,1,nonce,raw,decode(repeat('00',32),'hex'),k,gen_random_uuid());
  RAISE EXCEPTION 'INVALID_TAG_ACCEPTED';
 EXCEPTION WHEN OTHERS THEN
  IF SQLERRM <> 'INVALID_BOOTSTRAP_HMAC' THEN RAISE; END IF;
 END;
 SELECT company_private.r56_bootstrap_consume(e.installation_id,1,nonce,raw,tag,k,gen_random_uuid()) INTO result;
 IF result->>'state' IS DISTINCT FROM 'SUCCEEDED' THEN RAISE EXCEPTION 'SYNTHETIC_BOOTSTRAP_NOT_SEALED'; END IF;
 SELECT company_private.r56_bootstrap_consume(e.installation_id,1,nonce,raw,tag,k,gen_random_uuid()) INTO result;
 IF result->>'outcome' IS DISTINCT FROM 'REPLAY_NO_NEW_GRANT' THEN RAISE EXCEPTION 'REPLAY_NOT_READ_ONLY'; END IF;

 RESET SESSION AUTHORIZATION;
 IF b IS DISTINCT FROM e.installation_id THEN RAISE EXCEPTION 'ARM_ID_MISMATCH'; END IF;
END $arm$;
SELECT json_build_object('synthetic_bootstrap_receipts',(SELECT count(*) FROM company_private.bootstrap_receipts),'synthetic_objectives',(SELECT count(*) FROM company.objectives),'synthetic_plans',(SELECT count(*) FROM company.plans),'synthetic_arm_rows',(SELECT count(*) FROM company_private.installation_bootstrap_control WHERE state='ARMED'),'scope','CONDITIONAL_TRANSPORT_SYNTHETIC_NOT_REAL_INSTALLATION');
COMMIT;
